P.entries["item:a-letter-to-grelin-whitebeard"] = {n="Лист до Греліна Вайтбірда",s="Це запечатане послання адресоване Ґреліну Вайтбірду, досвідченому дворфу, що несе службу серед засніжених пустищ Долини Холодного Хребта. Надіслане з гірської столиці, Айронфорджа, воно є рідкісною звісткою з новинами та вказівками, що дісталася далекого прикордоння.",h="Це запечатане послання адресоване Ґреліну Вайтбірду, досвідченому дворфу, що несе службу серед засніжених...",kw={"лист","ґрелін вайтбірд","долина холодного хребта","айронфордж","дун мороґ","депеша","анвілмар"},ang={["race:Dwarf"]="Носити депеші крижаними перевалами Дун Мороґу — основний обов'язок молодих дворфійських горян і новобранців, які лише починають здобувати собі ім'я."},sec={{t="Послання з гори",b="Життя в засніженій улоговині Долини Холодного Хребта може бути самотнім, особливо для тих, хто служить далеко від безпечних стін Анвілмара. Такі листи — життєво важлива ланка, що з'єднує розвідників і вчених у полі із залами Айронфорджа. Пронесене на південь гірськими стежками, послання приносить звістку зі столиці до табору Ґреліна Вайтбірда посеред дикої пустки."}},fp="29,270,28.367.0,25.210.0,32.165.0,26.286.0"}
P.entries["item:a-stack-of-letters"] = {n="Стос Листів",s="Стос Листів — невеликий згорток кореспонденції, що потрапив через гірський перевал до Долини Холодного Хребта. Хоча спершу вважали, що весь він належить Таліну Кінаю, у згортку лежать листи для кількох розвідників, які служать серед крижаної пустки.",h="Стос Листів — невеликий згорток кореспонденції, що потрапив через гірський перевал до Долини Холодного Хребта.",kw={"стос листів","пошта","талін кінай","ґрелін вайтбірд","долина холодного хребта","анвілмар","дун мороґ"},ang={["race:Dwarf"]="Для молодих горян, що починають свій шлях у Долині Холодного Хребта, розносити пошту між засніженими таборами — перше знайомство з суворими дорогами та розкиданими вартовими, які стережуть Дун Мороґ."},sec={{t="Через перевал",b="Діставатися віддалених таборів у суворих горах Дун Мороґу — виснажлива праця, тож поштарі часто покладаються на випадкових подорожніх, аби винести пошту з Анвілмара. Цей згорток листів прибув через перевал для розвідників, що стоять глибше в Долині Холодного Хребта. Хоча його вважали призначеним лише Таліну Кінаю в його таборі біля озера, розбираючи пакунок, знаходиш послання й для інших застав серед снігів, зокрема для горянина Ґреліна Вайтбірда."}},fp="18,270,16.459.0,36.251.0,44.162.0,25.187.0"}
P.entries["item:admiral-proudmoore-s-orders"] = {n="Накази Адмірала Праудмура",s="Накази Адмірала Праудмура — письмові бойові плани, здобуті у військ Кул Тірасу, що окопалися на узбережжі Дуротару. Написані ще до поразки Великого адмірала під Терамором, документи окреслюють далекосяжні військові задуми, які й досі загрожують молодій батьківщині орків.",h="Накази Адмірала Праудмура — письмові бойові плани, здобуті у військ Кул Тірасу, що окопалися на узбережжі...",kw={"накази","праудмур","кул тірас","дуротар","тіраґард","вол'джин","орда"},ang={["faction:Horde"]="Ці документи виправдовують тих в Орді, хто твердив, що перемир'я з людьми ніколи не триватиме довго: сили Кул Тірасу мали намір вести війну на винищення з миті висадки.",["race:Troll"]="Для тролів Темного Списа ці накази потрапляють просто до рук їхнього ватажка Вол'джина і підтверджують його давню пораду Траллу: присутність людей на узбережжі лишається безпосередньою небезпекою."},sec={{t="Спадщина ненависті",b="Навіть після загибелі Великого адмірала Дейліна Праудмура під Терамором його експедиційні сили відмовляються здаватися. Здобуті в гарнізоні Лейтенанта Бенедикта у Фортеці Тіраґард, ці тактичні вказівки описують довгострокові маневри та укріплення, покликані підірвати Орду. Накази доводять: наступ Великого адмірала у Дуроторі був не поспішним набігом, а організованою кампанією, розрахованою пережити самого полководця. Для Орди здобуті документи — важливе джерело відомостей про дії Кул Тірасу та можливі підкріплення, що загрожують її кордонам."},{t="Доставка до Фортеці Ґроммаш",b="Усвідомивши стратегічну небезпеку, окреслену в планах, розвідники Орди відправляють здобуті папери просто до Фортеці Ґроммаш в Оргріммарі. Передані ватажкові Вол'джину, який служить радником Вождя Тралла, накази підтверджують давню підозру провідника Темного Списа: людська агресія лишається живою небезпекою. Відомості спонукають провідників Орди готуватися до нових вторгнень уздовж узбережжя."}},fp="27,299,18.577.0,25.419.1,37.219.0,34.150.0,30.144.0,53.286.0"}
P.entries["item:agamand-family-axe"] = {n="Сокира Родини Аґаманд",s="Сокира Родини Аґаманд — родова реліквія, збережена у склепі родини Аґамандів на півночі Галявин Тірісфалю. Колись бойовий символ заможної династії власників млинів, тепер вона потрібна Коулменові Фартінґу, щоб позбавити родину-нежить решток гідності.",h="Сокира Родини Аґаманд — родова реліквія, збережена у склепі родини Аґамандів на півночі Галявин Тірісфалю.",kw={"сокира родини аґаманд","аґаманди","склеп","коулмен фартінґ","реліквія","галявини тірісфалю"},ang={["class:Warrior"]="Родова зброя, збережена у склепі, показує, що рід Аґамандів мав бойові традиції поряд із багатством і зерносховищами.",["race:Undead"]="Для Відступників пограбування реліквій Аґамандів — нутряне зведення рахунків із колишньою аристократією Лордерону, яка впала перед чумою так само легко."},sec={{t="Зброя Аґамандів",b="До Третьої війни династія Аґамандів панувала як заможні землевласники на північних пагорбах Галявин Тірісфалю, утримуючи великі млини й приватний родинний склеп. Сокира Родини Аґаманд спочивала серед родової зброї, похованої разом із покійними патріархами й воїнами, і лишалася цілою на підземних стійках навіть тоді, коли Погибель захопила маєток і вирізала його мешканців."},{t="Злостива відплата",b="Коли Погибель підняла полеглих Аґамандів як безтямних рабів, якими володіє Король-Ліч, їхній колишній слуга Коулмен Фартінґ вижив — у нежитті — з гіркою ненавистю до старих господарів. Фартінґ звинувачує родину у власній загибелі й доручає мандрівникам із Відступників увійти до склепу, зняти зі стійок сокиру, меч, булаву й кинджал і стерти останні сліди спадщини Аґамандів."}},fp="18,264,24.391.0,20.398.0,40.143.0,33.155.0,50.211.0,42.119.0"}
P.entries["item:agamand-family-dagger"] = {n="Кинджал Родини Аґаманд",s="Кинджал Родини Аґаманд — родова реліквія занепалої династії Аґамандів, що лежить на стійках для зброї в їхньому родовому склепі на півночі Галявин Тірісфалю. Коулмен Фартінґ хоче здобути цей клинок разом із рештою родинного арсеналу, щоб позбавити колишніх господарів останків спадщини й честі.",h="Кинджал Родини Аґаманд — родова реліквія занепалої династії Аґамандів, що лежить на стійках для зброї в...",kw={"кинджал родини аґаманд","аґаманди","склеп","коулмен фартінґ","брілл","млини аґаманда"},ang={["class:Rogue"]="Прослизнути повз піднятих мерців у склепі й поцупити зі стійок цінні родинні клинки — класична крадіжка зі світу злочинців, обернена на акт холодної помсти.",["race:Undead"]="Реліквії Аґамандів утілюють гірку прірву між уцілілими Відступниками Лордерону та їхніми колишніми господарями, що впали в безтямне рабство Погибелі."},sec={{t="Спадщина у склепі",b="До Третьої війни родина Аґамандів тримала великі маєтки й зернові млини на пагорбистих луках Галявин Тірісфалю. Як і решта зброї їхнього роду, Кинджал Родини Аґаманд пережив спустошення, яке принесла Погибель, замкнений у родинному склепі на північ від Млинів Аґаманда. Під охороною неспокійних решток-нежиті з домочадців і безтямних прислужників, якими командує Король-Ліч, кинджал уособлює престиж і бойову спадщину, що колись підносили родину над слугами й орендарями."},{t="Злостива вимога",b="Для Коулмена Фартінґа — одного з Відступників, що мешкає у Бріллі й загинув на службі в Аґамандів, — клинок означає гірку образу, а не шляхетний родовід. Вважаючи родину прямо винною у своїй смерті, Фартінґ посилає шукачів пригод до Родинного Склепу Аґамандів забрати кинджал разом із родинним мечем, сокирою й булавою. Виносячи цю родову зброю з гробниці, Фартінґ прагне відібрати в патріархів, що стали Погибеллю, останні крихти гідності й подбати, щоб пам'ять про Аґамандів згасла цілком."}},fp="21,305,21.520.0,22.524.0,34.194.0,41.139.0,43.193.0,47.181.0"}
P.entries["item:agamand-family-mace"] = {n="Булава Родини Аґаманд",s="Булава Родини Аґаманд — родова реліквія, збережена в Родинному Склепі Аґамандів на півночі Галявин Тірісфалю. Колись символ гордості заможної династії північного Лордерону, вона стала предметом злостивої відплати, якої прагне їхній колишній слуга Коулмен Фартінґ.",h="Булава Родини Аґаманд — родова реліквія, збережена в Родинному Склепі Аґамандів на півночі Галявин Тірісфалю.",kw={"булава родини аґаманд","аґаманди","склеп","коулмен фартінґ","помста","галявини тірісфалю"},ang={["race:Undead"]="Осквернення склепів Аґамандів показує, як задавнені смертні образи й кривди часто штовхають Відступників зводити рахунки з часів життя."},sec={{t="Спадщина в руїнах",b="До Третьої війни родина Аґамандів володіла великими угіддями й вітряками на півночі Галявин Тірісфалю. Як і решта місцевої аристократії, вони впали перед чумою нежиті. Аґамандів підняли безтямними рабами, якими володіє Король-Ліч, і тепер вони блукають зруйнованим маєтком, тоді як їхні давні родинні скарби лишилися замкнені в глибинах родового склепу. Серед цієї зброї зберігається й Булава Родини Аґаманд — емблема забутого роду, що перетворився на безтямну Погибель."},{t="Помста слуги",b="Булава — одна з чотирьох бойових реліквій, на які націлився Коулмен Фартінґ, колишній найманий працівник, що звинувачує родину у своїй загибелі під час падіння Лордерону. Воскреслий у лавах Відступників, Фартінґ прагне позбавити безтямних Аґамандів кожної крихти гідності й честі. Здобувши булаву разом із родовими мечем, сокирою й кинджалом, Фартінґ хоче назавжди стерти пам'ять і гордість колишніх господарів із земель, якими вони колись правили."}},fp="19,284,16.528.0,21.482.1,41.137.0,34.153.0,52.186.0,36.205.0"}
P.entries["item:agamand-family-sword"] = {n="Меч Родини Аґаманд",s="Меч Родини Аґаманд — потьмянілий родовий клинок, що зберігається в Родинному Склепі Аґамандів на півночі Галявин Тірісфалю. Колись горда ознака заможної династії власників млинів, тепер він потрібен Коулменові Фартінґу з Відступників, щоб стерти останні сліди спадщини колишніх господарів.",h="Меч Родини Аґаманд — потьмянілий родовий клинок, що зберігається в Родинному Склепі Аґамандів на півночі...",kw={"меч родини аґаманд","аґаманди","склеп","коулмен фартінґ","помста","брілл","тірісфаль"},ang={["class:Warrior"]="Колись начищена емблема аристократії Лордерону, тепер клинок лежить занедбаний у неосвяченій гробниці — пам'ятка зруйнованої бойової гордості.",["race:Undead"]="Для Відступників повернення реліквій колишньої знаті Тірісфалю — зведення рахунків із живим минулим, що не зуміло їх захистити."},sec={{t="Спадщина в гробниці",b="До Третьої війни династія Аґамандів мала величезне багатство й вплив серед млинів на півночі Галявин Тірісфалю. Коли Погибель прокотилася Лордероном, родина загинула страшною смертю, а їхні тіла підняв безтямними рабами Король-Ліч. Їхню родову зброю, зокрема й церемоніальний родинний меч, замкнули в Родинному Склепі Аґамандів на північному краю млинів. Зняти ці клинки з поховальних стійок — не просто грабунок, а свідомий акт, що має зламати будь-яку пам'ять і шляхетне становище, які ще лишилися в полеглого дому."},{t="Помста з-за могили",b="Меча жадає Коулмен Фартінґ — один із Відступників, що мешкає у Бріллі, а за життя працював на Аґамандів. Фартінґ плекає гірку образу на колишніх господарів, звинувачуючи їхні рішення у своїй смерті під час падіння королівства. Посилаючи шукачів пригод по меч разом із родовими сокирою, кинджалом і булавою, Фартінґ прагне відібрати в шкутильгаючих Аґамандів останню крихту честі й подбати, щоб гідність їхнього роду згасла дощенту."}},fp="20,282,20.584.0,31.472.1,33.175.0,27.203.0,42.213.0,36.230.0"}
P.entries["item:alterac-granite"] = {n="Альтеракський Граніт",s="Альтеракський Граніт — цінний міцний камінь, який видобувають у гористій місцевості північного Лордерону, а саме біля Пагорба Дарроу в Передгір'ї Гілсбреда. Майстри-каменярі шанують його за виняткову стійкість і зерно, тож саме його обрав королівський каменяр Короля Маґні Бронзбірда, щоб вирізьбити вічну пам'ятку полеглим воїнам.",h="Альтеракський Граніт — цінний міцний камінь, який видобувають у гористій місцевості північного Лордерону, а...",kw={"альтеракський граніт","пагорб дарроу","передгір'я гілсбреда","саллі баллу","маґні бронзбірд","пам'ятник","марблстен"},ang={["profession:Mining"]="Шахтарі й старателі цінують Альтеракський Граніт за рівний злам і надзвичайну щільність, що вирізняє його з-поміж звичайного скельного каміння.",["race:Dwarf"]="Дворфійські каменярі понад усе ставлять якість матеріалу, тож цей міцний гірський камінь конче потрібен, щоб ушанувати ще одного сина Айронфорджа."},sec={{t="Камінь для пам'ятників",b="Коли Король Маґні Бронзбірд наказав звести пам'ятник Саллі Баллу — хороброму дворфійському захиснику, що загинув у трагедії біля Мосту Тандол, — звичайний камінь із кар'єру не годився. Великий Каменяр Марблстен, якому доручили вирізьбити меморіал в Айронфорджі, наполіг, щоб дістали саме Альтеракський Граніт. Він славиться як один із найкращих каменів у всіх Східних Королівствах, і його легендарна міцність запорука того, що подоба й пам'ять полеглого героя переживуть покоління незаплямованими."},{t="Видобуток серед небезпек",b="Дістати Альтеракський Граніт — зовсім не просте доручення. Камінь залягає біля Пагорба Дарроу в північній частині Передгір'я Гілсбреда, неподалік зруйнованих земель Альтераку. Край кишить ворожими звірами, у засідках чигають розбійники Синдикату, а давні чвари досі не вщухли, тож, щоб принести бездоганні брили цього чистого каменю для ремісників Айронфорджа, потрібні сміливі шукачі пригод, готові заглибитися в спірні землі."}},fp="15,339,18.494.0,17.442.0,33.174.0,35.134.0,60.203.0,21.191.0"}
P.entries["item:ambercorn"] = {n="Бурштинова шишка",s="Бурштинова шишка — священний плід, що падає з високих прадавніх дерев, розкиданих по Малгору. Насичена природною магією, вона слугує важливим реагентом у шаманських варивах тауренів — найчастіше для викликання духовних видінь під час випробувань молоді.",h="Бурштинова шишка — священний плід, що падає з високих прадавніх дерев, розкиданих по Малгору.",kw={"бурштинова шишка","малгор","таурени","обряд видіння","зарлман ту-мунс","вода провидців","шамани"},ang={["class:Shaman"]="Шаманська традиція шанує природні каталізатори на кшталт бурштинової шишки, визнаючи, що Мати-Земля вкладає духовну магію у плоди своїх дерев і ґрунту.",["race:Tauren"]="Кожен молодий таурен, що проходить традиційні Обряди Матері-Землі, вчиться розпізнавати бурштинову шишку як неодмінний складник пошуку видіння, що відкриває його духовний шлях."},sec={{t="Дари крони",b="Зібрані під міцними гілками великих дерев Малгору, бурштинові шишки для тауренів — більше, ніж звичайні горіхи. Багаті на духовну силу землі, вони мають приховані магічні властивості, які містики тауренів розуміють і використовують поколіннями. Молоді мисливці й мандрівники рано вчаться дивитися під ноги в траві під кроною, шануючи дари Матері-Землі, що вільно падають згори."},{t="Вариво провидця",b="У Селі Бладгуф провидець Зарлман Ту-Мунс покладається на бурштинову шишку, готуючи молодих тауренів до Обряду Видіння. Разом із камінням, зібраним у чистих водяних криницях рівнин, бурштинову шишку настоюють на могутню Воду Провидців. Випитий перед вогнями предків церемоніальний еліксир зміщує чуття посвяченого й відкриває духа-провідника у подобі звіра, що має вести його до наступної мети."}},fp="9,241,19.422.0,15.425.0,21.150.0,29.181.0,27.162.0,44.185.0"}
P.entries["item:amethyst-phial"] = {n="Аметистова Фіала",s="Аметистова Фіала — тендітна обрядова посудина, яку Корітрас Мунрейдж у Доланаарі довіряє молодим нічним ельфам — шукачам пригод. Її зроблено саме для того, щоб набрати й зберегти священну воду з найпершого місячного колодязя під Деревом Оракула.",h="Аметистова Фіала — тендітна обрядова посудина, яку Корітрас Мунрейдж у Доланаарі довіряє молодим нічним...",kw={"аметистова фіала","місячний колодязь","дерево оракула","галявина оракула","корітрас мунрейдж","доланаар","тельдрассил","корона землі"},ang={["class:Druid"]="Друїди бачать у цій посудині важливе знаряддя для нагляду за життєвими силами й повзучою скверною, що загрожують живому світові Світового Дерева.",["race:NightElf"]="Для калдореїв наповнити цю фіалу — урочистий обов'язок, що прямо зіштовхує їх із тривожними вадами неблагословенного творення Тельдрассила."},sec={{t="Посудина священних вод",b="Довірена посвяченим на Тельдрассилі, Аметистова Фіала — остання посудина в паломництві Корони Землі. Корітрас Мунрейдж доручає мандрівникам віднести її на далекий північний захід віття, на Галявину Оракула. Там, під прадавнім шатром Дерева Оракула, лежить перший і наймогутніший місячний колодязь острова. Фіалу обережно занурюють у ці сяйливі води, щоб узяти сутність ласки Елуни і дати друїдам та жрицям змогу вивчати й доглядати непередбачуване зростання Світового Дерева."},{t="Тягар неблагословенного зростання",b="Збирання цього зразка — більше ніж звичний обряд відданості. Тельдрассил виростили під проводом Архідруїда Фандрала Стаґгелма без благословення Драконячих Аспектів, які відмовилися схвалити те, що мали за зухвальство. Через це віття потерпає від тривожної скверни, а калдореї лишаються смертними. Наповнення Аметистової Фіали — водночас духовний обряд і безперервне спостереження, що дає дослідникам у Доланаарі змогу прискіпливо перевіряти чистоту священних вод Тельдрассила."}},fp="14,241,23.550.0,28.517.1,36.187.0,35.160.0,52.258.0,32.174.0"}
P.entries["item:barrel-of-barleybrew-scalder"] = {n="Барило Окропу Барліброю",s="Барило Окропу Барліброю — діжка міцного елю, звареного родиною Барліброю, щоб довести свою броварську майстерність перед головними суперниками. Його довіряють таємним кур'єрам, які мають пробратися до Ґуральні Тандербрю в Хараносі та влаштувати хитру дегустаційну диверсію.",h="Барило Окропу Барліброю — діжка міцного елю, звареного родиною Барліброю, щоб довести свою броварську...",kw={"барило","окріп барліброю","ель","тандербрю","харанос","ґуральня","марлет барліб'ю","суперництво"},ang={["class:Rogue"]="Відволікти вартового в льоху й пронести важку контрабанду до охоронюваного сховку — кумедна й безпечна вправа в класичному дворфійському підступі.",["race:Dwarf"]="Для дворфів варіння елю — і мистецтво, і кривавий спорт; узяти участь у льохових інтригах про те, чий рецепт кращий, — чи не улюблена розвага Дун Мороґу."},sec={{t="Запекла ворожнеча в Дун Мороґу",b="Броварство для дворфів Дун Мороґу — справа серйозна, і мало яке суперництво палає гарячіше за ворожнечу між Тандербрю та Барліброю. Поки Тандербрю тішаться широкою славою та почесним місцем у своїй людній ґуральні в Хараносі, Марлет Барліб'ю відмовляється сидіти в їхній тіні. Замість покладатися лише на відкриті шинки, Марлет варить вогняний «Окріп», щоб довести: її рецепти нічим не поступаються. Вона сподівається, що нічого не підозрюючи, відвідувачі скуштують напій і збагнуть: Тандербрю не мають монополії на добрий дворфійський трунок."},{t="Підступ у льоху",b="Барило мають непомітно пронести просто до льохів під Ґуральнею Тандербрю й підмінити ним діжку місцевого улюбленця — Громового Елю. Задум не отруйний і не руйнівний — це зухвалий дворфійський жарт, спрямований на вражену гордість: щоб наступна партія, яку подадуть нагорі, потай виявилася міцним окропом Барліброю."}},fp="28,287,27.543.0,24.337.1,48.135.0,42.215.0,26.155.0,33.171.0"}
P.entries["item:barrel-of-shimmer-stout"] = {n="Барило Мерехтливого Стауту",s="Свіжозварена діжка експериментального дворфійського елю Реджолда Барліброю, створеного в холодних просторах Дун Мороґу. Напій відомий тим, що дає міцного стусана й нібито прояснює зір, і призначений у подарунок вартовим, які чатують на високих гірських перевалах.",h="Свіжозварена діжка експериментального дворфійського елю Реджолда Барліброю, створеного в холодних просторах...",kw={"мерехтливий стаут","барило","реджолд барліброю","ель","лох модан","горянин","дун мороґ"},ang={["profession:Cooking"]="Дворфійські елі раз у раз розсувають межі кулінарних експериментів, поєднуючи міцне бродіння з витривалими гірськими інгредієнтами, щоб витримати лютий холод.",["race:Dwarf"]="Броварство — наріжний камінь культури Айронфорджа, а доправити щойно вдосконалений стаут родичеві на варті — почесна гірська традиція."},sec={{t="Гордість бровара",b="Мерехтливий Стаут, який Реджолд Барліброю зварив, зібравши рідкісні інгредієнти по всьому Дун Мороґу, — найновіший тріумф уславленої родини Барліброю. Дворфійські бровари ставляться до свого ремесла смертельно серйозно й невпинно змагаються, хто зварить ситніше вариво, здатне відігнати крижаний гірський холод. Останній рецепт Реджолда покликаний не лише зігріти нутро, а й загострити чуття тих, хто служить на крижаному вітрі."},{t="Припаси для варти",b="Це барило призначене горянину Велларту Барліброю, який стоїть на варті біля південної вежі на перевалі, що веде до Лох Модану. На самотньому прикордонні горяни терплять пронизливий холод і довгі чергування між сутичками з трогами та звіриною. Свіжа діжка родинного елю — це водночас і жаданий смак дому, і підбадьорливий тонік, достатньо міцний, щоб втомлений вартовий заприсягся, ніби бачить крізь темряву."}},fp="23,272,16.452.0,22.454.0,39.221.0,30.150.0,29.145.0,61.208.0"}
P.entries["item:barrel-of-thunder-ale"] = {n="Барило Грозового Елю",s="Барило Грозового Елю — цінна діжка фірмового трунку Хараноса, винесена просто з льоху Ґуральні Тандербрю. Підмінене на діжку Окропу Барліброю від Марлет, воно слугує незаперечним доказом підступу в броварському суперництві, що дедалі розпалюється.",h="Барило Грозового Елю — цінна діжка фірмового трунку Хараноса, винесена просто з льоху Ґуральні Тандербрю.",kw={"барило","громовий ель","тандербрю","харанос","марлет барліб'ю","село брюнолл","підміна"},ang={["class:Rogue"]="Прослизнути до охоронюваного льоху та підмінити важкі барила елю, не здійнявши тривоги, — класичний і практичний вияв скрадливості та спритності.",["race:Dwarf"]="Для дворфів броварство — серйозна справа й висока політика; підмінити цінну діжку суперницького клану в їхньому ж льоху — зухвала образа."},sec={{t="Гіркий обмін",b="У Дун Мороґу змагання між майстрами-броварами сягає глибоко, і мало яка суперечка запекліша за ворожнечу між Тандербрю з Хараноса та Барліброю із Села Брюнолл. Марлет Барліб'ю задумала підкинути барило власного Окропу Барліброю до льоху суперників, щоб відвідувачі Тандербрю скуштували її вариво замість їхнього. Це важке барило Громового Елю захопили під час обміну й витягли під самим носом у місцевої варти як речовий доказ того, що підміна вдалася."}},fp="21,266,14.510.0,27.154.0,32.140.0,22.181.0,25.158.0"}
P.entries["item:battleboar-flank"] = {n="Бік Бойового Вепра",s="Бік Бойового Вепра — ситний шмат м'яса, здобутий із лютих бойових вепрів, яких вишколюють шипогриви Щетиноспинні в Малгорі. Молоді мисливці збирають його довкола Табору Нарачі: це і доказ знищеної загрози, і поживна їжа для племені тауренів.",h="Бік Бойового Вепра — ситний шмат м'яса, здобутий із лютих бойових вепрів, яких вишколюють шипогриви...",kw={"бойовий вепр","бік","м'ясо","щетиноспинні","табір нарачі","ґрулл гоквінд","малгор"},ang={["profession:Cooking"]="Хоч м'ясо звірів, вирощених для бою, грубе й має присмак дичини, бік дає вдосталь багатого, ситного м'яса, якщо повільно виварити його в спільній табірній юшці.",["race:Tauren"]="Полювання на бойових вепрів, що вдираються в їхні землі, вчить молодих тауренів: захист батьківщини нерозривний зі священним обов'язком шанувати й використовувати щедроти Матері-Землі."},sec={{t="Пожива з загрози Щетиноспинних",b="Шипогриви Щетиноспинні, що причаїлися в Яру Тернистого Клинка, вишколили лютих бойових вепрів, аби ті вдиралися на мисливські угіддя тауренів. Ці агресивні звірі — пряма небезпека для молодих тауренів, що входять у зрілість у Таборі Нарачі, та ніщо, взяте в природи, не марнується. Ґрулл Гоквінд наказує мисливцям-новачкам зрізати з повалених звірів боки разом із рилами. Шматки боків дають багате, поживне м'ясо, яке виварюють на ситну юшку для молоді племені, — так зброя шипогривів стає живленням для племені."}},fp="16,266,38.545.0,36.226.0,34.149.0,51.256.0"}
P.entries["item:battleboar-snout"] = {n="Рило Бойового Вепра",s="Рило Бойового Вепра здобувають з агресивних вепрів, яких вишколюють шипогриви Щетиноспинні в Малгорі. Молоді мисливці-таурени збирають їх і як доказ проріджування загарбницької загрози, і як ситний складник племінної кухні Табору Нарачі.",h="Рило Бойового Вепра здобувають з агресивних вепрів, яких вишколюють шипогриви Щетиноспинні в Малгорі.",kw={"бойовий вепр","рило","щетиноспинні","табір нарачі","ґрулл гоквінд","юшка","малгор"},ang={["profession:Cooking"]="Жорсткі частини на кшталт рил треба довго виварювати на вогні, тож вони стали основними складниками племінних юшок біля багаття.",["race:Tauren"]="Узяти рило разом із м'ясом — означає шанувати рівновагу Матері-Землі: хижака, що вдирається в землі, стримано, а молодь Табору Нарачі нагодовано."},sec={{t="Трофеї та припаси",b="У тіні Плато Червоної Хмари шипогриви Щетиноспинні вишколюють у Яру Тернистого Клинка злісних бойових вепрів, аби ті промацували мисливські угіддя тауренів. Коли Ґрулл Гоквінд посилає молодих сміливців дати відсіч цьому вторгненню, рило стає незаперечним доказом поваленого звіра. Табір Нарачі не марнує жодної частини здобичі: таурени використовують ці рила разом зі шматками боків, щоб готувати багаті, поживні юшки для своєї молоді."}},fp="16,258,23.445.0,36.227.0,32.149.0,51.180.0"}
P.entries["item:bernice-s-necklace"] = {n="Намисто Берніс",s="Намисто Берніс — пам'ятна родинна реліквія «Тітоньки» Берніс Стоунфілд із Ферми Стоунфілдів у Лісі Елвінн. Колись її покійний чоловік носив цю прикрасу як талісман на удачу під час військової служби; дрібничку загубили біля Копальні Фарґодіп, і її поцупив спритний кобольд.",h="Намисто Берніс — пам'ятна родинна реліквія «Тітоньки» Берніс Стоунфілд із Ферми Стоунфілдів у Лісі Елвінн.",kw={"намисто","берніс стоунфілд","золотозуб","кобольд","копальня фарґодіп","реліквія"},ang={["faction:Alliance"]="Намисто — тихе нагадування про важку ціну, яку тривалі військові кампанії Стормвінда стягують із простих фермерських родин по всьому Лісі Елвінн."},sec={{t="Загублений талісман солдата",b="Хоч тутешні знають його як намисто Берніс, спершу воно належало покійному чоловікові Тітоньки Берніс Стоунфілд. Ветеран військових кампаній Стормвінда, він брав талісман із собою в бій як запоруку удачі. За словами Берніс, біда сталася лише раз — під час його останнього походу, єдиної виправи, у яку він забув узяти щасливе намисто. Після його смерті ця пам'ятка лишилася одним із найдорожчих скарбів Берніс на Фермі Стоунфілдів."},{t="Украдене падложерами",b="Реліквія зникла після того, як малого Біллі Маклура застали за грою біля Копальні Фарґодіп, де він упустив блискучу дрібничку, досліджуючи околиці. Блиск привернув око Золотозуба — сумнозвісного кобольда, що чаївся в копальні. Як і всі його родичі, ласий до яскравих і цінних дрібничок, Золотозуб ховав намисто серед своєї підземної здобичі, доки його не повернули згорьованій удові."}},fp="18,294,22.488.0,20.407.1,35.155.0,45.163.0,51.211.0,17.198.0"}
P.entries["item:black-feather-quill"] = {n="Чорне Перо",s="Чорне Перо — священна реліквія нічних ельфів, якою Друїди Кігтя послуговуються в обрядах сплячки й пробудження. Воно зберігається в окремій скрині в Курганному Лігві Бан'етіл і є одним із кількох конче потрібних осередків, щоб безпечно прикликати сплячих друїдів назад зі Смарагдового Сну.",h="Чорне Перо — священна реліквія нічних ельфів, якою Друїди Кігтя послуговуються в обрядах сплячки й...",kw={"чорне перо","реліквія","друїди кігтя","курганне лігво бан'етіл","смарагдовий сон","пробудження","атрідас бермантл"},ang={["class:Druid"]="Для друїдів перо уособлює священні знаряддя, що прив'язують послідовників Кігтя до яви, поки їхні духи єднаються зі Смарагдовим Сном.",["race:NightElf"]="Нічні ельфи бачать у споганенні скринь із реліквіями Бан'етіла фурболгами Вузлошкірів ще одне болісне нагадування про скверну, що насувається на Тельдрассил."},sec={{t="Посудина пробудження",b="Друїдизм нічних ельфів спирається на глибоко настроєні священні предмети, щоб долати поріг між явою і Смарагдовим Сном. Чорне Перо разом із Талісманом Воронячого Пазура, Сапфіром Небес і Руною Гніздування становить основний набір обрядових предметів, потрібних, щоб перервати крихку сплячку Друїдів Кігтя. Без цих осередків сплячий друїд ризикує навіки лишитися в пастці Сну, нездатний повернутися у своє тіло наяву."},{t="Загроза в Бан'етілі",b="Коли споганені фурболги Вузлошкірів заполонили Курганне Лігво Бан'етіл, священні скрині з цими скарбами опинилися в небезпеці. Залишені без охорони в покручених глибинах, реліквії треба було швидко повернути за наказом Атрідаса Бермантла з Доланаара, доки полонених друїдів не втрачено для Сну назавжди."}},fp="19,297,20.476.0,23.306.0,41.144.0,38.117.0,64.227.0,37.144.0"}
P.entries["item:bloodfeather-belt"] = {n="Пояс Кривавого Пера",s="Пояс Кривавого Пера — грубий шкіряний ремінь, який носять гарпії Кривавого Пера, що заполонили північний Тельдрассил. Вартова Аринія Клаудзбрейк збирає ці пояси як доказ, що тутешні гнізда, які зазіхають на Галявину Оракула, розорено.",h="Пояс Кривавого Пера — грубий шкіряний ремінь, який носять гарпії Кривавого Пера, що заполонили північний...",kw={"пояс кривавого пера","гарпії","галявина оракула","аринія клаудзбрейк","вартова","тельдрассил","дарнасус"},ang={["faction:Alliance"]="Допомога Вартовій Аринії Клаудзбрейк гарантує, що важливі звіти від прадавніх дерев Тельдрассила безперешкодно дійдуть до проводу в Дарнасусі.",["race:NightElf"]="Зграя Кривавого Пера споганює природне шатро Тельдрассила, тож відвоювати Галявину Оракула в їхніх верескливих гнізд — неодмінний обов'язок кожного захисника батьківщини калдореїв."},sec={{t="Трофеї з гнізд",b="Гарпії Кривавого Пера напосідливо загніздилися у вітті довкола Галявини Оракула, загрожуючи прадавньому Дереву Оракула й перекриваючи шлях через північний Тельдрассил. Коли зграя підстерегла й убила гінця зі звітами до Дарнасуса, Вартова Аринія Клаудзбрейк закликала мандрівників ударити просто по їхніх гніздах. Пояси, зняті з полеглих гарпій, — відчутний доказ того, що їхню кількість зменшують, а стежки вбезпечують, щоб зв'язок зі столицею відновився."}},fp="17,234,23.505.0,54.329.0,38.237.0,46.263.0"}
P.entries["item:bloodstone-choker"] = {n="Намисто Кровавика",s="Намисто Кровавика — темний магічний талісман із кровавика, яким спершу володів наставник чорнокнижників Ґакін Зв'язувач Темряви. Викрадене зрадливою ученицею, що втекла до Братства Дефіас, воно слугує могутнім осередком ритуалу, здатним пронизати порожнечу, щоб викликати й прив'язати блукача порожнечі.",h="Намисто Кровавика — темний магічний талісман із кровавика, яким спершу володів наставник чорнокнижників Ґакін...",kw={"намисто кровавика","ґакін","сурена каледон","блукач порожнечі","чорнокнижник","зарізане ягня"},ang={["class:Warlock"]="Для чорнокнижників Альянсу повернення Намиста Кровавика — життєво важливий обряд посвяти, що з'єднує основи чаклунства з владою над грізними демонічними слугами.",["faction:Alliance"]="Втеча Сурени Каледон до Братства Дефіас показує, як звичайні розбійники Елвінну завзято шукають небезпечні окультні реліквії, щоб підживити свій бунт проти Стормвінда."},sec={{t="Викрадений провідник",b="Намисто Кровавика, що зберігалося в потаємних покоях під стормвіндським «Зарізаним Ягням», було одним із найцінніших ритуальних знарядь Ґакіна Зв'язувача Темряви. Його спокій розбила Сурена Каледон, чорнокнижниця-початківиця під опікою Ґакіна: вона зрадила наставника й викрала амулет. Сурена втекла в ліси Елвінну, щоб пристати до розбійницького Братства Дефіас, прихопивши зачароване намисто як знак сили й козир для торгу. Щоб повернути його, доведеться вистежити її на Гарбузовій Ділянці Брекуеллів, перш ніж бандити обернуть його небезпечні сили на власні цілі."},{t="Приборкання порожнечі",b="Вирізьблене з кровавика, намисто має приховану містичну владу, потрібну, щоб з'єднати світ смертних із покрученими тінями Викривленого Нижнього Світу. Щойно його повертають Ґакінові, його одразу випробовують у криптах під таверною. Чорнокнижник має спрямувати магію намиста в підземному колі прикликання, щоб вирвати з порожнечі ворожого блукача порожнечі. Лише впокоривши розлючену сутність у прямому бою з талісманом у руках, практик доводить силу волі, потрібну, щоб командувати таким охоронцем."}},fp="17,307,16.598.1,15.530.0,30.192.0,32.165.0,26.211.0,43.226.0"}
P.entries["item:brass-collar"] = {n="Латунний Нашийник",s="Латунний Нашийник — міцна прикраса на шиї Принцеси, призової свині родини Брекуеллів. Він слугує відчутним доказом для Ма Стоунфілд, що ненажерливу тварюку приборкано, перш ніж вона зіпсувала врожай на її фермі.",h="Латунний Нашийник — міцна прикраса на шиї Принцеси, призової свині родини Брекуеллів.",kw={"латунний нашийник","принцеса","свиня","ма стоунфілд","ферма стоунфілдів","брекуелли"},ang={["faction:Alliance"]="Для молодих шукачів пригод, що допомагають сільському люду Елвінну, зняти нашийник із Принцеси — класичний обряд посвяти в залагодженні сварок між фермерами маленьких містечок."},sec={{t="Трофей фермерського суперництва",b="Принцеса — не звичайна свиня: це величезна, гідна призової стрічки льоха родини Брекуеллів, що блукає довкола їхньої гарбузової ділянки на схід від садиби Маклурів. На лихо сусідам, її призові розміри живляться ненаситним апетитом до посівів Ферми Стоунфілдів. Утомлена втрачати цінну городину через мандрівну ненажеру, Ма Стоунфілд шукає когось, хто зважиться зарізати велетенську льоху. Оскільки Принцеса носить на шиї помітний латунний обруч, її нашийник слугує незаперечним доказом, що свиня-мародерка більше ніколи не плюндруватиме поля Стоунфілдів."}},fp="12,230,28.593.0,38.158.0,39.223.0,18.132.0,46.123.0"}
P.entries["item:bristleback-attack-plans"] = {n="Креслення Атаки Щетиноспинних",s="Креслення Атаки Щетиноспинних — грубі мапи й тактичні нотатки, накреслені шипогривами з Яру Тернистого Клинка. Вони описують узгоджену облогу, спрямовану просто на захоплення поселення тауренів — Табору Нарачі.",h="Креслення Атаки Щетиноспинних — грубі мапи й тактичні нотатки, накреслені шипогривами з Яру Тернистого Клинка.",kw={"креслення атаки","щетиноспинні","шипогриви","табір нарачі","вождь гоквінд","яр тернистого клинка","облога"},ang={["faction:Horde"]="Зірваний наступ Щетиноспинних гарантує, що Орда збереже надійну, нічим не загрожену опору на священних рівнинах Малгору.",["race:Tauren"]="Розкрита змова захищає самі тренувальні землі, де молоді таурени проходять перші обряди, і береже ваших старійшин і новачків від жорстокої облоги шипогривів."},sec={{t="Змова проти плато",b="Сховані глибоко в земляній печері Яру Тернистого Клинка, ці накидані тактичні замальовки показують: шипогриви Щетиноспинні вже не просто зчиняють сутички на околицях Плато Червоної Хмари. Їхні ватажки спланували організований, тривалий штурм, щоб увірватися в Табір Нарачі й винищити молодих тауренів, які там навчаються. Доставлена Вождю Гоквінду мапа дає племені змогу послати по підкріплення до Села Бладгуф і притупити навалу, перш ніж вона почнеться."}},fp="24,212,23.494.0,45.200.0,28.143.0,55.171.1,47.208.0"}
P.entries["item:broken-tools"] = {n="Зламані Інструменти",s="Зламані Інструменти — потрощені рештки кайл дворфійських старателів, навмисно знищених на ковадлі. Вони слугують речовим доказом для Бейна Бладгуфа, що загарбницькі дворфійські розкопки, які загрожують землі й звірині Малгору, зірвано.",h="Зламані Інструменти — потрощені рештки кайл дворфійських старателів, навмисно знищених на ковадлі.",kw={"зламані інструменти","бейн бладгуф","дворфи","розкопки","кайла","малгор","кодо"},ang={["profession:Blacksmithing"]="Методично нищити на ковадлі тонку дворфійську ковальську роботу — означає перетворити горно майстра на знаряддя захисту рідної землі.",["race:Tauren"]="Для тауренів принести Бейну зіпсовані інструменти означає захистити Матір-Землю від загарбницького копання, що мучить тутешніх звірів."},sec={{t="Саботаж розкопок",b="На північний захід від Села Бладгуф дворфійські землекопи влаштували розкопки в пагорбах Малгору. Дворфи шукають поховану стародавню історію, а таурени вбачають у їхньому зухвалому копанні пряме осквернення Матері-Землі. Гуркіт і руйнування тривожать місцеву звірину, особливо мандрівні стада кодо. Замість просто прогнати землекопів, молодий Бейн Бладгуф наказує захисникам відібрати в старателів залізні кайла й потрощити їх на горні, щоб експедиція більше не могла шматувати землю."}},fp="12,250,18.570.0,28.152.0,45.239.0,32.165.0,35.218.0"}
P.entries["item:bundle-of-wood"] = {n="Оберемок Дров",s="Оберемки Дров — зв'язані стоси деревини, заготовлені робітниками біля Лісозаготівельного Табору Східної Долини на сході Лісу Елвінн. Нещодавно покинуті через хижу звірину, вони становлять важливі поставки, потрібні, щоб виконати місцеві угоди на деревину.",h="Оберемки Дров — зв'язані стоси деревини, заготовлені робітниками біля Лісозаготівельного Табору Східної...",kw={"оберемок дров","деревина","лісозаготівельний табір","східна долина","лісоруби","ведмеді"},ang={["faction:Alliance"]="Кожен повернутий оберемок напряму підтримує відбудову Стормвінда, дбаючи, щоб важливі поставки деревини вчасно доходили до поселень Елвінну й Вестфолу."},sec={{t="Покинута деревина",b="Лісозаготівельний Табір Східної Долини — головне джерело деревини для Королівства Стормвінд: свіжозрубаний ліс іде на захід, щоб живити міське господарство й будівництво. Нещодавно агресивна тутешня звірина — лісові ведмеді й хижі вовки — вдерлася в гаї на північний захід від табору. Нажахані лісоруби втекли, рятуючи життя, й покинули щойно зібрані Оберемки Дров там, де вони лежали серед дерев. Терміни постачання тиснуть, тож наглядачі табору покладаються на відважних подорожніх, які прослизнуть повз хижаків і повернуть зрубану деревину, перш ніж угоди буде порушено."}},fp="14,238,16.594.0,54.205.0,30.132.0,30.148.0,48.207.0"}
P.entries["item:burning-blade-medallion"] = {n="Медальйон Палаючого Клинка",s="Медальйон Палаючого Клинка — темний талісман, який носять культисти, що причаїлися в Долині Випробувань. Захищений темною магією в глибинах Ковену Палаючого Клинка, він слугує прямим доказом демонічної скверни, що намагається підкорити молодих воїнів Дуротару.",h="Медальйон Палаючого Клинка — темний талісман, який носять культисти, що причаїлися в Долині Випробувань.",kw={"медальйон","палаючий клинок","культ","долина випробувань","скверна","бейншедов"},ang={["class:Warlock"]="Хоч чорнокнижники Орди практикують темну магію під суворою дисципліною, медальйон втілює свавільне, нестримне ремесло Скверни Палаючого Клинка, що загрожує стабільності Дуротару.",["race:Orc"]="Медальйон уособлює тінь демонічної скверни, яка колись поневолила орчий рід, а тепер загрожує молодим посвячуваним ще до того, як вони покинуть Долину Випробувань."},sec={{t="Знак скверни",b="Знайдений глибоко у звивистих печерах Ковену Палаючого Клинка медальйон тримає Ярроґ Бейншедов — агент зловісного культу Палаючого Клинка. Виявлена ворожінням Зуріти Фарґейз, ця дрібничка спрямовує темну силу серед бісівських фамільярів і переслідувачів Скверни культу. Здолати її носія і забрати медальйон — означає урвати підступну спробу підточити тренувальні землі Орди зсередини самого Дуротару."}},fp="23,268,20.452.0,36.208.0,34.171.0,29.192.0,52.215.0"}
P.entries["item:cactus-apple"] = {n="Кактусове Яблуко",s="Кактусові яблука — тверді, соковиті плоди, зібрані з суворої рослинності Долини Випробувань у Дуроторі. Вони розкошують у сухій пустельній спеці, і місцеві орки цінують їх як рідкісне, освіжне джерело харчу.",h="Кактусові яблука — тверді, соковиті плоди, зібрані з суворої рослинності Долини Випробувань у Дуроторі.",kw={"кактусове яблуко","кактус","дуротар","долина випробувань","ґалґар","їжа"},ang={["profession:Cooking"]="Для кухарів, що виживають у нетрях Дуротару, збирання пустельних кактусів — головний урок, як перетворити колючу, негостинну пустельну рослинність на поживну й зволожувальну страву.",["race:Orc"]="Молоді орки, що проходять випробування в Дуроторі, швидко засвоюють: пережити червоний каньйон — означає користатися кожною дрібкою вологи, яку дає природа."},sec={{t="Пустельний урожай",b="Випалена сонцем земля Дуротару не розпещує мешканців, змушуючи їх використовувати будь-які витривалі рослини, що переживають стихію. Кактусові яблука ростуть гронами на товстих кактусах, розкиданих по Долині Випробувань. Їх важко зібрати, не зачепивши кілька колючок, зате плоди дають життєво важливу вологу в задушливому каньйоні. Місцевий орк на ім'я Ґалґар збирає ці плоди для свого фірмового Сюрпризу із Кактусових Яблук — прохолодних ласощів, що приносять жадане полегшення новобранцям на суворому початковому вишколі."}},fp="12,219,14.536.0,28.166.0,30.207.0,26.165.0"}
P.entries["item:candle-of-beckoning"] = {n="Свічка Прикликання",s="Свічка Прикликання — зачарована ритуальна свічка, яку тримає відлюдний некромант Ґунтер Арканус на Озері Світлої Води. Якщо поставити й запалити її на вівтарі на сусідньому острівці, вона прикликає неспокійного духа, відомого як Лілліт Нефара.",h="Свічка Прикликання — зачарована ритуальна свічка, яку тримає відлюдний некромант Ґунтер Арканус на Озері...",kw={"свічка прикликання","ґунтер арканус","лілліт нефара","озеро світлої води","ритуал","некромант"},ang={["class:Mage"]="Уміння Ґунтера прив'язувати духів до ритуальних знарядь, як-от ця свічка, показує його майстерність у некромантії й мистецтві прикликання поза дозволеним ученням Кірін-Тору.",["race:Undead"]="Для посланців Відступників з Андерсіті робота з ритуальною свічкою Ґунтера — необхідний крок, щоб переконати затято незалежного некроманта, що ви не раби Короля-Ліча."},sec={{t="Випробування вірності",b="Свічка Прикликання, що зберігається в ящику біля самотнього мага Ґунтера Аркануса на його острові посеред Озера Світлої Води, — знаряддя темного обряду прикликання. Ґунтер — затято незалежний чаклун-нежить; Король-Ліч утратив над ним владу, бо Ґунтер сам розірвав пута, і тепер він однаково насторожено ставиться і до Погибелі, і до Відступників. Щоб довести, що ваша вірність належить не Королю-Лічу, Ґунтер велить віднести одну з цих свічок на південний захід, до меншого острівця. Там, на старому закривавленому столі, полум'я свічки проймає завісу між світами, щоб розбудити й прикликати сплячу тінь Лілліт Нефари — і дати їй нарешті спочити."}},fp="19,244,20.642.0,41.240.0,41.179.0,30.169.0,44.236.0"}
P.entries["item:canvas-scraps"] = {n="Клапті Парусини",s="Клапті Парусини — рештки міцної тканої тканини, яку носять людські загарбники та племена кентаврів, що вдираються в Дуротар. У Гострому Пагорбі старий ветеран Фурл Скорнброу збирає ці врятовані клапті, щоб пошити корисні дорожні мішки для нових новобранців Орди.",h="Клапті Парусини — рештки міцної тканої тканини, яку носять людські загарбники та племена кентаврів, що...",kw={"парусина","клапті","скорнброу","гострий пагорб","кул тірас","кентаври","торба"},ang={["faction:Horde"]="Кожен клапоть, відібраний у загарбників Кул Тірасу чи нальотчиків Колкар, допомагає спорядити нових захисників, що відгукнулися на заклик Тралла по всьому Дуротару.",["profession:Tailoring"]="Хоч просту ткану парусину здебільшого збирають воїни як сиру здобич, вона слугує міцною основою для пошиття практичних торб у суворій пустелі."},sec={{t="Трофеї з ворогів Дуротару",b="Парусина — тканина не з грубих шкіряних традицій орків, зате її вдосталь у ворогів Дуротару. Морські піхотинці та моряки Кул Тірасу, що окопалися на східному узбережжі, носять важке парусинове спорядження та рештки вітрил зі своїх морських походів. Далі вглиб суходолу кочові кентаври Колкар пристосовують клапті грубої тканини, награбованої з караванів і в минулих сутичках. Перемога над цими ворогами дає міцні рештки, які можна зібрати з їхніх таборів і спорядження."},{t="Ремесло ветерана",b="Умостившись на сторожовій вежі Гострого Пагорба, ветеран Фурл Скорнброу виглядає загарбників і водночас береться за корисну роботу. Хоч бойові роки старого воїна позаду, він перешиває врятовану ворожу тканину на міцні торби для молодших солдатів. Повертаючи матеріали Кул Тірасу й Колкарів проти них самих, Фурл споряджає нове покоління захисників, що б'ються за кордони Орди."}},fp="13,252,29.493.0,17.413.0,33.234.0,42.235.0,53.294.0"}
P.entries["item:cask-of-shimmer-stout"] = {n="Барило Мерехтливого Стауту",s="Барило Мерехтливого Стауту — запечатана діжка міцного нового елю Реджолда Барліброю, звареного на холодних висотах Дун Мороґу. Відомий своїм неабияким ударом і запаморочливою силою, він вирушає на схід через гори як бадьорий гостинець для дворфійських горян.",h="Барило Мерехтливого Стауту — запечатана діжка міцного нового елю Реджолда Барліброю, звареного на холодних...",kw={"мерехтливий стаут","барило","реджолд барліброю","горянин кадрелл","телсамар","лох модан","харанос"},ang={["race:Dwarf"]="Для дворфів поділитися добрим елем між обходами — шанована традиція, що єднає розкиданих горян по суворих вершинах Каз Модану."},sec={{t="Бадьора доставка",b="Зварений у Хараносі Реджолдом Барліброю Мерехтливий Стаут швидко здобув високу оцінку в місцевих відвідувачів і горян, що зносили пронизливі морози Дун Мороґу. Вражений варивом брата, Горянин Барліброу замовив діжку, щоб переправити її східним перевалом до Лох Модану. Дворфи високо цінують міцний трунок і як основу товариства, і як практичний захист від пронизливого гірського холоду, а поділитися свіжим урожаєм із далекими побратимами — давня військова традиція."},{t="Дворфійський підбадьорювач",b="Коли Горянин Кадрелл на своїй варті в Телсамарі відкриває діжку й куштує напій, той цілком виправдовує свою славу. Це не звичайне корчемне пиво: кажуть, один ковток Мерехтливого Стауту робить ноги легкими й лишає воїна з відчуттям, ніби він от-от злетить, — саме таке підбадьорливе зілля потрібне дворфійському розвіднику на довгих самотніх обходах високих доріг."}},fp="21,274,19.512.0,20.395.0,22.190.0,30.138.0,34.223.0,51.169.0"}
P.entries["item:chief-sharptusk-thornmantle-s-head"] = {n="Голова Вождя Гостроікла Терномантія",s="Голову Вождя Гостроікла Терномантія беруть як похмурий доказ перемоги над ватажком шипогривів Щетиноспинних, що загрожують Плато Червоної Хмари. Здобуту з глибин Яру Тернистого Клинка, її подають Сміливцю Віндфезеру на знак того, що невідчепній загрозі для молодих сміливців-тауренів покладено край.",h="Голову Вождя Гостроікла Терномантія беруть як похмурий доказ перемоги над ватажком шипогривів Щетиноспинних...",kw={"гостроікл терномантій","голова","вождь","щетиноспинні","шипогриви","сміливець віндфезер","яр тернистого клинка"},ang={["class:Hunter"]="Для мисливців Гостроікл — найвища здобич: розумний ворог, здатний полювати у відповідь, що перетворює сутичку за виживання на справжнє випробування вистежування й влучності.",["race:Tauren"]="Здобута голова грізного ворога — важлива віха для молодих тауренів: вона доводить, що вони мають рішучість і вміння захистити новий дім свого народу."},sec={{t="Трофей полювання",b="Таурени виборюють свою мирну батьківщину в Малгорі пильністю й силою. Шипогриви Щетиноспинні, що закріпилися в Яру Тернистого Клинка, ведуть агресивний похід проти племен, яким дає прихисток Табір Нарачі, підбурювані своїм лютим вождем Гостроіклом Терномантієм. Відтяти йому голову — не безглузда жорстокість, а остаточний доказ його загибелі й суворе попередження вцілілим кланам шипогривів, що зазіхають на межі плато."},{t="Урок полювання",b="Сміливець Віндфезер вимагає голову вождя як обряд посвяти для мисливців-початківців і захисників племені. Для тауренів зіткнення з ворогом, досить хитрим, щоб відповідати ударом на удар і зібрати цілу бойову ватагу, — важлива перевірка бойової вправності. Подана голова Гостроікла виконує це випробування й здобуває молодому бійцеві міцну репутацію серед сміливців Плато Червоної Хмари."}},fp="34,295,18.458.0,20.398.0,66.288.0,36.232.0,30.161.0"}
P.entries["item:consecrated-rune"] = {n="Освячена Руна",s="Освячена Руна — священний предмет із написом, який вручають новоспеченим дворфійським паладинам, що навчаються в Долині Холодного Хребта. Це вступний виклик від Бромоса Ґруммнера, який велить послушникам з'явитися до Анвілмара й узятися до своїх обов'язків як Лицарі Срібної Длані.",h="Освячена Руна — священний предмет із написом, який вручають новоспеченим дворфійським паладинам, що...",kw={"освячена руна","паладин","бромос ґруммнер","срібна длань","анвілмар","долина холодного хребта","святе світло"},ang={["class:Paladin"]="Для дворфійських паладинів отримати цю руну означає зробити офіційний крок до лав Лицарів Срібної Длані під проводом Бромоса Ґруммнера.",["race:Dwarf"]="Руна відображає, як людські священні традиції вросли в дворфійську бойову культуру — на ґрунті спільного союзу та взаємної поваги між Айронфорджем і людством."},sec={{t="Поклик Срібної Длані",b="Дворфи-паладини, які доводять себе в Долині Холодного Хребта, отримують Освячену Руну, щойно покажуть базову бойову вправність. Руна, вкрита священними словами й благословенна Святим Світлом, походить від Бромоса Ґруммнера — наставника паладинів, що мешкає в Анвілмарі. Дворфи глибоко шанують традиції Святого Світла, які їм передали союзники-люди. Прочитання руни — водночас офіційний виклик і символічний обряд посвяти, що підтверджує місце новачка серед Лицарів Срібної Длані."}},fp="16,275,28.546.0,38.169.0,31.105.0,65.222.0"}
P.entries["item:cougar-claws"] = {n="Кігті Пуми",s="Кігті Пуми здобувають із рівнинних пум, що блукають центральними рівнинами Малгору. Вони слугують важливим матеріалом у ритуальному ремеслі тауренів, уособлюючи неприборкану рівновагу й природну лють диких хижаків.",h="Кігті Пуми здобувають із рівнинних пум, що блукають центральними рівнинами Малгору.",kw={"кігті пуми","пума","малл тандергорн","водяна криниця","тотем","гобліни","малгор"},ang={["class:Shaman"]="Шамани знають, що сутність місцевих хижаків нерозривно пов'язана з духами рівнин, тож вона — неодмінний провідник для очисних оберегів і тотемів.",["race:Tauren"]="Збирання цих кігтів учить молодих тауренів, що полювання вкорінене в рівновазі й духовній потребі — на разючу відміну від безоглядного забруднення, яке несуть підприємства гоблінів."},sec={{t="Посудина природної рівноваги",b="Рівнинна пума — один із найвищих хижаків розлогих лугів Малгору, що переслідує здобич з інстинктивною грацією. У традиції тауренів узяти кігті такого хижака — не легковажне вбивство й не полювання за трофеями, а спосіб приборкати природний дух звіра. Коли підприємства гоблінів починають оскверняти прабатьківські води рівнин, Малл Тандергорн закликає молодих мисливців зібрати ці кігті разом із кігтями степових переслідувачів. Таурени вірять, що чисті, неспотворені хижацькі інстинкти тутешніх звірів можна вплести в ритуальний тотем, здатний вичистити неприродні отрути й лихе чаклунство з отруєної Водяної Криниці Тандергорнів."}},fp="12,218,27.670.0,31.228.0,32.128.0,64.259.0,42.138.0"}
P.entries["item:crate-of-horseshoes"] = {n="Ящик Підків",s="Ящик Підків — важкий пакунок із п'ятдесятьма залізними підковами, викуваними в Лісі Елвінн. Призначений для Лейкширу, він утілює життєво важливий торговий зв'язок між кузнею Ґолдширу й обложеними поселенцями Редріджу.",h="Ящик Підків — важкий пакунок із п'ятдесятьма залізними підковами, викуваними в Лісі Елвінн.",kw={"ящик підків","коваль арґус","вернер осґуд","лейкшир","ґолдшир","ковальство"},ang={["faction:Alliance"]="Гінці, що возять товари між Елвінном і Редріджем, підтримують крихкий торговий хребет королівства, тримаючи віддалені гарнізони спорядженими навіть тоді, коли Стормвінд не шле військового підкріплення.",["profession:Blacksmithing"]="Ця доставка показує сталий попит на ковальські основи оптом уздовж прикордонних доріг королівства, де такі містечка, як Лейкшир, цілком залежать від ковадла Ґолдширу, щоб підтримувати своїх тяглових тварин."},sec={{t="Доставка в Лейкшир",b="Спакований і забитий цвяхами ковалем Арґусом у Ґолдширі, цей важкий ящик містить п'ятдесят щойно викуваних підків на замовлення Вернера Осґуда. Місцеве ремесло Лейкширу знемагає під постійним тиском гнолів і орків з околиць, тож майстри на кшталт Вернера залежать від Лісу Елвінн у постачанні важливих металевих виробів. Ящик задовольняє нагальну потребу Вернера в спорядженні, та Арґус не забуває вкласти суворий рахунок, щоб редріджський майстер пам'ятав: навіть виживання на рубежі має свою високу ціну."}},fp="19,232,23.543.0,39.138.0,23.172.0,29.125.0,44.228.0"}
P.entries["item:crate-of-inn-supplies"] = {n="Ящик із Припасами для Корчми",s="Ящик із Припасами для Корчми — пакунок, зібраний у Долині Холодного Хребта для Ґуральні Тандербрю в Хараносі. Гірський перевал захопили троги, звичні шляхи постачання перерізано, і корчма залежить від випадкових подорожніх, які зголосяться пронести крам.",h="Ящик із Припасами для Корчми — пакунок, зібраний у Долині Холодного Хребта для Ґуральні Тандербрю в Хараносі.",kw={"ящик","припаси","корчма","гендс спрінґспрокет","таннок фростгаммер","харанос","троги","перевал холодного кряжа"},ang={["race:Dwarf"]="Пронести ці припаси — перша служба молодого дворфа за межами Долини Холодного Хребта: кинути виклик забитому трогами перевалу, щоб допомогти родичам у Хараносі.",["race:Gnome"]="Для новоприбулих гномів доправити пакунок Гендса Спрінґспрокета — практичний спосіб здобути прихильність місцевих дворфів, що тримають корчми Дун Мороґу."},sec={{t="Крізь перевал трогів",b="Зазвичай крам вільно плине між тихими навчальними угіддями Анвілмара та людними містечками Дун Мороґу. Та недавні набіги трогів перерізали Перевал Холодного Кряжа, і цивільним кур'єрам шлях закрито, доки озброєні горяни не розчистять дороги. Цей важкий ящик, спакований Гендсом Спрінґспрокетом, містить необхідні корчемні припаси, яких Таннок Фростгаммер у Хараносі тривожно чекає посеред цього безладу."}},fp="21,261,22.431.0,25.157.0,32.156.0,43.232.0,26.118.0"}
P.entries["item:crystal-kelp-frond"] = {n="Лист Кристалевої Ламінарії",s="Листи Кристалевої Ламінарії — зрізки водяної рослини, здобуті в мурлоків, що живуть на Кришталевому Озері в Лісі Елвінн. Хоч ламінарія родом з океану, мурлоки носять її листя вглиб суходолу, і так воно стає незвичним алхімічним реагентом, за яким полює Вільям Пестл у Ґолдширі.",h="Листи Кристалевої Ламінарії — зрізки водяної рослини, здобуті в мурлоків, що живуть на Кришталевому Озері в...",kw={"кристалева ламінарія","мурлоки","кришталеве озеро","вільям пестл","алхімія","реагент"},ang={["profession:Herbalism"]="На відміну від звичайних трав, що ростуть у землі, кристалева ламінарія — водяна рослина, якої не знайти у звичних місцях збору трав по Елвінну; травникам і збирачам доводиться відбирати її просто в тутешніх мурлоків, які її нагромаджують."},sec={{t="Рідкісний водяний реагент",b="Кристалева ламінарія зазвичай росте в глибинах солоних океанів, тож її поява в прісних водоймах Лісу Елвінн несподівана. Племена мурлоків, що оселилися на берегах Кришталевого Озера, збирають і зберігають це листя з власних міркувань. Алхіміки цінують листя за дивну здатність спотворювати зір, а Вільям Пестл у Ґолдширі використовує його як головний інгредієнт лікеру невидимості, створеного, щоб допомогти таємним закоханим прослизнути повз пильні очі родини."}},fp="18,258,22.511.0,39.209.0,51.183.0,43.241.1,42.204.0"}
P.entries["item:crystal-phial"] = {n="Кристалева Фіала",s="Бездоганна Кристалева Фіала, яку друїд Тенарон Стормґріп у Тінедолі довіряє молодим нічним ельфам — шукачам пригод. Нею набирають священну воду з поблизького місячного колодязя, розпочинаючи низку обрядів на честь і для живлення зростаючого Світового Дерева — Тельдрассила.",h="Бездоганна Кристалева Фіала, яку друїд Тенарон Стормґріп у Тінедолі довіряє молодим нічним ельфам — шукачам...",kw={"кристалева фіала","місячний колодязь","тенарон стормґріп","тінедол","алдрассил","тельдрассил","корона землі"},ang={["class:Druid"]="Друїди глибоко шанують місячні колодязі й черпають їхні безтурботні властивості, щоб спрямовувати природні сили й плекати нове зростання, не піддаючись спокусам таємного чаклунства.",["race:NightElf"]="Для молодих калдореїв, що роблять перші кроки за межами Алдрассила, наповнити цю фіалу — основоположний обряд посвяти, що прямо єднає їх із водами Елуни та відродженням народу після Третьої війни."},sec={{t="Посудина для священних вод",b="Ця тендітна скляна фіала, яку дають молодим нічним ельфам на верхівці Алдрассила, має важливе обрядове призначення. Тенарон Стормґріп доручає молодим захисникам віднести її до місячного колодязя одразу на північ від гілки й набрати його сяйливої води. Проста на вигляд, фіала містить воду, наснажену священним спадком Колодязя Вічності. Принесена назад Наповнена Кришталева Фіала — перший крок паломництва Корони Землі, що вчить молодих калдореїв хисткої рівноваги магії, історії та природи на їхньому новому острівному домі."}},fp="13,258,26.540.0,35.200.0,32.147.0,44.252.0,39.194.0"}
P.entries["item:darkhound-blood"] = {n="Кров Темного Гончака",s="Кров Темного Гончака — мерзенна тілесна рідина, добута із заражених псоподібних звірів, що блукають полями й лісами Галявин Тірісфалю. Зібрана на замовлення Королівського Аптекарського Товариства, вона слугує одним із перших реагентів у їхніх темних дослідах зі створення нової смертоносної чуми.",h="Кров Темного Гончака — мерзенна тілесна рідина, добута із заражених псоподібних звірів, що блукають полями й...",kw={"кров темного гончака","темні гончаки","королівське аптекарське товариство","аптекар йогаан","чума","брілл"},ang={["faction:Horde"]="Поки у Бріллі тривають темні досліди, мало хто поза внутрішнім колом Відступників цілком усвідомлює, який отруйний потенціал відкриває Королівське Аптекарське Товариство.",["race:Undead"]="Збирання реагентів на кшталт Крові Темного Гончака — важлива праця для Відступників: вона допомагає Леді Сильвані й Королівському Аптекарському Товариству кувати найвищу зброю проти Погибелі."},sec={{t="Пальне для Нової Чуми",b="За наказом Леді Сильвани Віндраннер Королівське Аптекарське Товариство прагне створити заразу, здатну стерти Артаса і його Погибель. Аптекар Йогаан, що працює у Бріллі, припускає: місцеві звірі, зіпсуті темними силами й стійкі до довколишнього розкладу, мають незвичайні біологічні властивості. Переганяючи кров диких темних гончаків, Йогаан сподівається виявити біологічні сполуки, здатні протистояти лютим некротичним штамам або розносити їх."}},fp="15,275,23.478.0,33.185.0,33.119.0,48.179.0"}
P.entries["item:devlin-s-remains"] = {n="Останки Девліна",s="Останки Девліна — зібрані кістки Девліна Аґаманда, молодшого сина заможної родини, якій належали Млини Аґаманда. Безтямним рабом Погибелі він никав дорогами біля зруйнованого родового маєтку, доки його не здолали, щоб доставити його кістки мстивому вцілілому у Бріллі.",h="Останки Девліна — зібрані кістки Девліна Аґаманда, молодшого сина заможної родини, якій належали Млини...",kw={"останки девліна","девлін аґаманд","млини аґаманда","коулмен фартінґ","помста","брілл"},ang={["race:Undead"]="Для Відступників Аґаманди — стара привілейована знать Лордерону, чиї невдачі лишили простолюд гинути й повставати чудовиськами, тож наруга над останками Девліна — акт класової відплати."},sec={{t="Гірка спадщина",b="За життя Девлін Аґаманд стояв у тіні старшого брата Турмана. Де Турман був лагідний і високий, там Девліна пам'ятали тілесно кволим і злостиво гострим на язик. Коли Чума Нежиті прокотилася північчю Галявин Тірісфалю, родина Аґамандів не зуміла захистити ні свої землі, ні робітників. Девлін упав одним із перших і був піднятий ненажерливим гулем Погибелі, чиє шалене, безумне белькотіння переслідувало узбіччя дороги до Млинів Аґаманда."},{t="Помста на каміні",b="Коулмен Фартінґ, один із Відступників, що мешкає у Бріллі, плекає глибоку й невідступну образу на весь рід Аґамандів. Вважаючи їх прямо винними в тому, що вони підвели його сім'ю, коли прийшла чума, Фартінґ доручив мандрівникам упокоїти Девліна й зібрати його останки. Фартінґ хотів виставити кістки Девліна на своєму каміні, смакуючи знання, що його колишні господарі обернулися на порох і потрощені уламки під його п'ятою."}},fp="16,290,15.464.0,23.452.0,31.284.0,42.152.0,43.245.0,31.184.0"}
P.entries["item:dolanaar-delivery"] = {n="Посилка для Доланаара",s="Посилка для Доланаара — пакунок зібраного зілля, відправлений із друїдських угідь Тінедолу до села Доланаар. Довірений молодим мандрівникам, що покидають затишну долину, він слугує простим дорученням, яке знайомить їх із Корчмарем Келдаміром далі дорогою.",h="Посилка для Доланаара — пакунок зібраного зілля, відправлений із друїдських угідь Тінедолу до села Доланаар.",kw={"посилка","доланаар","зілля","портанніус","корчмар келдамір","тінедол","корчма"},ang={["profession:Herbalism"]="Посилка показує сталий попит на рослини, зібрані довкола Алдрассила, для постачання віддалених поселень Тельдрассила.",["race:NightElf"]="Узяти пакунок — обряд посвяти для молодих калдореїв, що виходять з-під захисного віття Тінедолу в ширший світ."},sec={{t="Клунок із Тінедолу",b="Зібраний у тінистих гаях Алдрассила, цей пакунок містить свіже зілля для поселення Доланаар. Портанніус, затриманий поточними справами серед друїдів Тінедолу, покладається на молодих шукачів пригод, що прямують дорогою на південь, аби ті безпечно доправили клунок Корчмареві Келдаміру."},{t="Ласкаво просимо до вогнища",b="Доставка пакунка приводить мандрівника просто на поріг корчми Доланаара. Келдамір із вдячністю приймає товар і користається нагодою нагадати втомленим подорожнім про потребу відпочинку, душевного спокою й прихистку біля вогнища корчми, перш ніж вони заглибляться в Тельдрассил."}},fp="17,266,24.310.0,21.305.0,37.144.0,24.144.0,37.110.0,52.171.0"}
P.entries["item:durnan-s-scalding-mornbrew"] = {n="Гарячий Ранковий Узвар Дурнана",s="Гарячий Ранковий Узвар Дурнана — щойно налитий, обпікаюче гарячий дворфійський напій, призначений для Дурнана Фуркаттера в Долині Холодного Хребта. На морозному гірському повітрі питво швидко холоне, тож його треба чимдуж донести до Анвілмара, поки не вистигло.",h="Гарячий Ранковий Узвар Дурнана — щойно налитий, обпікаюче гарячий дворфійський напій, призначений для Дурнана...",kw={"ранковий узвар","дурнан фуркаттер","гарячий напій","анвілмар","долина холодного хребта","доставка","норі"},ang={["race:Dwarf"]="Для дворфа з Дун Мороґу мало образ гірших, ніж дати доброму елю чи ранковому узвару захолонути на гірському морозі."},sec={{t="Наввипередки з холодом",b="У пронизливому холоді Долини Холодного Хребта мало що зрівняється з кухлем свіжого ранкового узвару, поданого гарячим-гарячим. Коли кур'єр затримується, доставляючи порцію Ґреліну Вайтбірду, свіжий кухоль для Дурнана Фуркаттера в Анвілмарі ризикує вкритися кригою. Дурнан вимагає, щоб його узвар був саме обпікаючим, тож лишається лише кілька хвилин, аби пронести паруючий кухоль засніженою стежкою до гірської зали, поки він геть не вистиг."}},fp="26,255,23.436.0,29.112.0,48.170.0,34.152.0,42.124.0"}
P.entries["item:durotar-tiger-fur"] = {n="Хутро Тигра з Дуротара",s="Хутро Тигра з Дуротара здобувають із лютих тигрів, що блукають тропічними Островами Відлуння біля південно-східного узбережжя Дуротару. Тролі Темного Списа значною мірою покладаються на ці шкури, щоб шити ковдри на холод, міцні намети й надійні обладунки, поки їхнє населення біженців невпинно зростає.",h="Хутро Тигра з Дуротара здобувають із лютих тигрів, що блукають тропічними Островами Відлуння біля...",kw={"хутро","тигр","дуротар","острови відлуння","сен'джин","темний спис","шкура"},ang={["class:Hunter"]="Вистежування тигрів Островів Відлуння повторює класичні мисливські обряди тролів і вимагає величезного терпіння й маскування, щоб заскочити цих скрадливих острівних хижаків.",["race:Troll"]="Для Темного Списа здобуття тигрячих шкур — подвійне нагадування: про щоденну боротьбу за виживання в Селі Сен'джин і про болючу втрату законної батьківщини на Островах Відлуння."},sec={{t="Життєво важливий ресурс для Темного Списа",b="У тісному поселенні Село Сен'джин ресурсів вічно бракує. Тролі Темного Списа зважують виживання свого народу проти крихкої екології нового дому, свідомо даючи місцевим тигрячим популяціям розростатися, доки зростання потреб не вимагатиме відстрілу. Густі, міцні шкури тигрів Дуротару ретельно вичиняють на щоденні речі для виживання — від простих захисних обладунків до теплих ковдр, що вкривають плем'я, коли змінюється пора року."},{t="Полювання на Островах Відлуння",b="Щоб здобути ці шкури, треба перетнути відкриту воду до Островів Відлуння — пишного архіпелагу на південь від Дуротару, який Темний Спис колись звав домом, доки відьмак Залазан не вигнав їх звідти. Окрім небезпеки від рабів Залазана, мисливці в густих заростях мають рахуватися з терплячою хижою вдачею самих тигрів. Досвідчені тролі-мисливці на кшталт Вел'ріна Фанга розповідають, як цілими днями нерухомо лежали в джунглях заради єдиного чистого пострілу."}},fp="17,283,34.484.0,22.492.0,38.139.0,53.203.0,41.206.0"}
P.entries["item:duskbat-wing"] = {n="Крило Сутінкового Кажана",s="Крило Сутінкового Кажана — сировина, здобута зі шкірястокрилих кажанів, що снують у мороці довкола Похоронного Подзвону. У злиденному поселенні Відступників ці шкірясті крила збирають, а місцеві кравці перешивають їх на міцну саморобну броню для щойно піднятих солдатів.",h="Крило Сутінкового Кажана — сировина, здобута зі шкірястокрилих кажанів, що снують у мороці довкола...",kw={"крило сутінкового кажана","сутінкові кажани","послушниця елрет","похоронний подзвін","броня","кравецтво"},ang={["profession:Tailoring"]="Послушниця Елрет показує грубе похідне кравецтво, потрібне в Тірісфалі: міцні крила кажанів правлять за замінник шкіри й тканини.",["race:Undead"]="Для щойно пробуджених Відступників збирання цих крил — одне з найперших завдань на виживання, щоб ви не розсипалися на шматки в перших сутичках."},sec={{t="Імпровізований захист у Похоронному Подзвоні",b="Коли нові мерці видряпуються з землі Похоронного Подзвону, вони виходять майже ні з чим, окрім лахміття й крихких кісток. В оточенні безтямних решток Погибелі й ворожої живності новоявлені Відступники мусять нашкребти будь-яке захисне спорядження, яке тільки знайдуть. Послушниця Елрет, якою опікується Жрець Тіні Сарвіс, збирає Крила Сутінкових Кажанів разом із вовчими лапами, щоб зшивати й зміцнювати одяг і броню для щойно піднятих воїнів, перш ніж їх пошлють битися в хащі."}},fp="12,287,35.494.0,32.176.0,33.149.0,39.159.0,48.251.0"}
P.entries["item:embalming-ichor"] = {n="Бальзамувальний Іхор",s="Бальзамувальний Іхор — неприродна консервувальна рідина, добута з тіл гнолів Гнилошкірих на півночі Галявин Тірісфалю. Вона підтримує оживлене існування гнолів і привернула пильну увагу аптекарів Відступників, які прагнуть дослідити її властивості, щоб протистояти Погибелі.",h="Бальзамувальний Іхор — неприродна консервувальна рідина, добута з тіл гнолів Гнилошкірих на півночі Галявин...",kw={"бальзамувальний іхор","гноли гнилошкірі","лігво гаррена","магістрат севрен","аптекарі","брілл"},ang={["profession:Herbalism"]="Консервувальна рідина всередині Гнилошкірих демонструє темні алхімічні методи, що інтригують травників і хіміків, які вивчають реагенти чуми.",["race:Undead"]="Для Відступників позбавити Погибель свіжих трупів із братських могил життєво важливо: так вони захищають Тірісфаль і здобувають сировину для власного виживання."},sec={{t="Неприродне збереження",b="Гноли Гнилошкірі, що заполонили Лігво Гаррена й сусідні братські могили, — не звичайні дикі звірі, а гниючі законсервовані раби, яких Погибель посилає викопувати жертв чуми. Їхніми розкладеними жилами тече Бальзамувальний Іхор — мерзенна рідина, що штучно зберігає їхню плоть і дарує тривале нежиття. Для Магістрата Севрена у Бріллі здобуті флакони цього іхору слугують двом цілям: підтверджують знищення грабіжників могил і дають дослідникам Королівського Аптекарського Товариства свіжі зразки, щоб розтинати, вивчати й обертати на зброю проти прислужників, якими володіє Король-Ліч."}},fp="15,287,22.601.0,24.199.0,31.181.0,46.176.0,47.155.0"}
P.entries["item:emerald-dreamcatcher"] = {n="Смарагдовий Ловець Снів",s="Смарагдовий Ловець Снів — священний амулет нічних ельфів, створений, щоб черпати тонку снагу зі Смарагдового Сну. Подарований Таллонкаю Свіфтруту друїдами Курганного Лігва Бан'етіл, він лишився в Селі Зоряного Вітерця, коли фурболги Вузлошкірів піддалися скверні й заполонили поселення.",h="Смарагдовий Ловець Снів — священний амулет нічних ельфів, створений, щоб черпати тонку снагу зі Смарагдового...",kw={"смарагдовий ловець снів","амулет","таллонкай свіфтрут","ґеролас талветрен","село зоряного вітерця","смарагдовий сон","фурболги"},ang={["class:Druid"]="Амулет — прямий зв'язок зі сплячими друїдами Курганного Лігва Бан'етіл, що показує, як їхнє єднання зі Смарагдовим Сном допомагає поселенням калдореїв унизу.",["race:NightElf"]="Повернення реліквії — маленька перемога над пошестю, що поглинає Село Зоряного Вітерця й навколишнє віття Тельдрассила."},sec={{t="Дарунок із Бан'етіла",b="Створений під опікою Ґероласа Талветрена, друїдського сторожа Курганного Лігва Бан'етіл, Смарагдовий Ловець Снів — зачарована реліквія, яку дарують лише небагатьом обраним. Він має витягати розлиті сили просто зі Смарагдового Сну, благословляючи носія удачею та захистом. Коли Село Зоряного Вітерця впало під натиском знавіснілих фурболгів Вузлошкірів, амулет лишився в шухляді комода — посеред ворожої, споганеної землі."}},fp="20,300,21.470.0,38.204.0,34.143.0,59.219.0,51.201.0"}
P.entries["item:encrypted-memorandum"] = {n="Зашифрована Записка",s="Зашифрована Записка — закодоване послання, яке вручають розбійникам-новачкам, що починають шлях у Долині Холодного Хребта. Замасковане під офіційний лист, насправді це таємне запрошення від місцевого наставника розбійників, Солма Гарґріна, який закликає до єдності між пройдисвітами у вигнанні.",h="Зашифрована Записка — закодоване послання, яке вручають розбійникам-новачкам, що починають шлях у Долині...",kw={"зашифрована записка","розбійник","солм гарґрін","анвілмар","гноми","гномреґан","шифр"},ang={["class:Rogue"]="Цей закодований лист — ваш офіційний виклик у тіні Дун Мороґу, що зводить вас напряму з вашим місцевим наставником в Анвілмарі.",["race:Gnome"]="Живучи біженцями серед дворфів після падіння Гномреґану, гномські розбійники знаходять у цій записці тиху пропозицію солідарності й виживання."},sec={{t="Непомітний виклик",b="У людному дворфійському притулку Анвілмара розбійники мусять не впадати в око. Замість підходити до новобранців у всіх на виду, наставник Солм Гарґрін налагоджує зв'язок за допомогою Зашифрованої Записки. Закодований пергамент, замаскований під офіційну директиву від далекого начальства, дає новачкам-розбійникам знати, де шукати наставника, не привертаючи зайвої уваги місцевої варти чи підозріливих містян."},{t="Побратимство в Холодному Хребті",b="Під шифром ховається послання про практичне виживання. Гномреґан утрачено, переселені гноми тісняться поруч зі своїми союзниками-дворфами в засніжених поселеннях Дун Мороґу, і напруга жевріє біля самої поверхні. Солм використовує записку, щоб тихо згуртувати своїх учнів, нагадуючи: ті, хто займається їхнім ремеслом, мусять дбати одне про одного, коли через пошук цапів-відбувайлів та упередження їх ладні звинуватити в кожній зниклій дрібничці."}},fp="20,279,18.422.0,20.439.1,33.159.0,26.156.0,29.198.0,28.187.0"}
P.entries["item:encrypted-parchment"] = {n="Зашифрований Пергамент",s="Зашифрований Пергамент — шифроване послання, яке вручають майбутнім оркам-розбійникам, що навчаються в Долині Випробувань. Передане Ґорнеком, воно непомітно спрямовує здібних новобранців у тінь Лігва, до таємного наставника Рваґа.",h="Зашифрований Пергамент — шифроване послання, яке вручають майбутнім оркам-розбійникам, що навчаються в Долині...",kw={"зашифрований пергамент","розбійник","рваґ","ґорнек","лігво","долина випробувань","розтрощена рука"},ang={["class:Rogue"]="Пергамент означає ваше посвячення в таємне підпілля Орди і вказує на наставників, пов'язаних із Розтрощеною Рукою.",["race:Orc"]="Хоч орча культура зазвичай цінує відкритий, чесний бій, це послання вітає тих, чий талант — у тихіших, смертоносніших мистецтвах виживання."},sec={{t="Поклик із тіні",b="Молоді орки, що прагнуть довести свою бойову вправність у Долині Випробувань, зазвичай б'ються просто неба, під сонцем. Та ті, хто виявляє хист до скрадання, обману й роботи клинком, привертають зовсім іншу увагу. Зашифрований Пергамент Ґорнек вручає здібним оркам-розбійникам, щойно ті випробують себе на місцевій звірині. Замість відкритого оголошення послання закодоване, щоб на поклик відгукнувся лише той, хто має око на хитрощі."},{t="Зв'язок із Розтрощеною Рукою",b="Розшифрувавши пергамент, новачок прямує вглиб печери, відомої як Лігво, повз пильні погляди інших наставників клану, щоб знайти Рваґа. Там новобранець дізнається, що виклик надіслано від імені Розтрощеної Руки — ордену, який діє в таємній мережі Орди. Відповівши на пергамент, розбійник робить перший крок у світ шпигунства, тіньового ремесла та стережених таємниць."}},fp="19,237,26.478.0,26.406.0,47.146.0,31.142.0,37.203.0,40.169.0,36.151.0"}
P.entries["item:encrypted-rune"] = {n="Зашифрована Руна",s="Зашифрована Руна — закодоване послання-виклик, яке вручають перспективним новачкам-розбійникам у Долині Холодного Хребта. Передана потай, вона велить власникові розшифрувати її зміст і знайти наставника розбійників Солма Гарґріна в Анвілмарі.",h="Зашифрована Руна — закодоване послання-виклик, яке вручають перспективним новачкам-розбійникам у Долині...",kw={"зашифрована руна","розбійник","солм гарґрін","анвілмар","долина холодного хребта","шифр","скрадання"},ang={["class:Rogue"]="Ця руна — ваш перший офіційний контакт із мережею розбійників Дун Мороґу, що посвячує вас у мистецтво скрадання, швидких клинків і виживання.",["race:Dwarf"]="Передана в Долині Холодного Хребта, руна кличе ще одне дитя Айронфорджа опанувати тіні й боронити інтереси клану з-під поверхні."},sec={{t="Закодований виклик",b="У затишній засніженій улоговині Долини Холодного Хребта відкритий набір — не в стилі місцевих пройдисвітів і розвідників. Натомість послушникам, які виявляють хист до скрадання й хитрощів, непомітно підкидають Зашифровану Руну. Камінь, помічений ледь уловимими шифрами, несе непомітне запрошення від Солма Гарґріна, наставника розбійників, що квартирує в Анвілмарі. Це водночас і таємний іспит на знання злодійського жаргону, і вступ до тіньового ремесла, без якого не вижити в суворій пустці Дун Мороґу."},{t="Очі в тінях",b="Розшифрована руна приводить нових розбійників до Солма, який прагне зміцнити таємні лави долини посеред дедалі більшої місцевої напруги. Окрім основ володіння клинком і скрадання, Солм наголошує на пильності й побратимстві, нагадуючи новачкам: у цей час хиткого миру їхньому братству тим паче важливо триматися разом."}},fp="14,223,15.503.0,19.341.0,27.145.0,28.165.0,29.107.0,29.209.0"}
P.entries["item:encrypted-scroll"] = {n="Зашифрований Сувій",s="Зашифрований Сувій — непримітний пергамент, що його вручають багатонадійним щойно піднятим розбійникам у Похоронному Подзвоні. Скріплений печаткою Девіда Тріаса, він велить одержувачу з'явитися на офіційний вишкіл серед таємних оперативників Відступників.",h="Зашифрований Сувій — непримітний пергамент, що його вручають багатонадійним щойно піднятим розбійникам у...",kw={"зашифрований сувій","розбійник","девід тріас","похоронний подзвін","відступники","тіньові переслідувачі"},ang={["class:Rogue"]="Сувій знаменує початок вашого професійного навчання скритності, зламу замків і брудного бою під пильним оком розбійницького кадру Відступників.",["race:Undead"]="Для щойно піднятих у Похоронному Подзвоні цей виклик — рання нагода посісти осмислене місце в королівстві Сильвани, що тільки постає."},sec={{t="Таємний виклик",b="Коли щойно пробуджений із Відступників виявляє хист до скритності й хитрощів, непоміченим він лишається недовго. Зашифрований Сувій вручають у Похоронному Подзвоні, щойно розвідник доведе свою спроможність проти безтямної Погибелі, що блукає сусіднім цвинтарем. Скріплений особистою печаткою наставника розбійників Девіда Тріаса, сувій велить власникові розшукати його в місцевій корчмі. Це перший відбір: він скеровує оперативників-початківців до дисципліни, потрібної, щоб служити Темній Леді, а не змарнувати другий шанс на життя простими кишеньковими злодіями."},{t="Очі Тіньових Переслідувачів",b="Саме послання коротке: розбійникові належить вийти на зв'язок у Похоронному Подзвоні, перш ніж заглиблюватися в Галявини Тірісфалю. Тріас наглядає за перспективними талантами від імені Тіньових Переслідувачів — таємного крила Відступників. Щоб вижити в Лордероні, Відступники щедро покладаються на тихі клинки й хитрих розвідників: їхні вороги — Багряний Хрестовий Похід, уцілілі анклави Альянсу й недобитки Погибелі. Відгукнутися на цей шифрований виклик — перший крок до цієї таємної мережі."}},fp="16,243,16.574.0,26.501.0,44.197.0,31.145.0,53.200.0,54.114.0"}
P.entries["item:encrypted-sigil"] = {n="Зашифрований Сигіл",s="Зашифрований Сигіл — закодований знак, який вручають щойно пробудженим розбійникам — нічним ельфам у Тінедолі. Він несе приховані настанови від наставника Фрагуна Шейдвіспера й велить молодим виконавцям розпочати навчання посеред дедалі більших загроз Тельдрассилу.",h="Зашифрований Сигіл — закодований знак, який вручають щойно пробудженим розбійникам — нічним ельфам у Тінедолі.",kw={"зашифрований сигіл","розбійник","фрагун шейдвіспер","тінедол","алдрассил","тельдрассил","наставник"},ang={["class:Rogue"]="Сигіл — відправна точка шляху розбійника — нічного ельфа, що перевіряє вашу здатність розшифрувати настанови й зв'язатися зі своїм місцевим наставником.",["race:NightElf"]="Для калдореїв таємні виконавці дають життєво важливі відомості в крихку добу, коли прадавні лісові кордони зазнають нового натиску Орди."},sec={{t="Прихований виклик",b="У затишній улоговині Тінедолу з майбутніми розвідниками й лазутчиками нічних ельфів зв'язуються непомітно. Зашифрований Сигіл передає посвяченому просто в руки тихий посланець від імені Фрагуна Шейдвіспера. Ховаючи свій зміст так, як личить ремеслу, сигіл велить одержувачу з'явитися до Фрагуна біля Алдрассила. Для Шейдвіспера прочитати й доставити знак означає довести, що посвячений уміє виконувати ледь помітні вказівки й поводитися з таємними посланнями."},{t="Очі в тінях",b="Фрагун користається викликом, щоб наголосити на потребі в розбійниках у неспокійному світі. Поки між нічними ельфами й далекою Ордою тліє напруга, Шейдвіспер нагадує новобранцям: відкрита війна — не єдина небезпека для їхнього народу. Розбійники мають бути першими очима й незримими клинками калдореїв: збирати відомості по всьому Тельдрассилу й учитися бити, перш ніж загрози вкоріняться у вітті Світового Дерева."}},fp="15,259,16.498.0,19.443.0,43.205.0,30.126.0,43.195.0,45.141.0"}
P.entries["item:encrypted-tablet"] = {n="Зашифрована Табличка",s="Зашифрована Табличка — кодоване послання, яке отримують тролі-розбійники Темного Списа, що починають навчання в Долині Випробувань. Накреслене наставником розбійників Рваґом, воно кличе здібних злодюжок і розвідників до його посту в Лігві.",h="Зашифрована Табличка — кодоване послання, яке отримують тролі-розбійники Темного Списа, що починають навчання...",kw={"зашифрована табличка","розбійник","рваґ","лігво","темний спис","долина випробувань"},ang={["class:Rogue"]="Шифрована плитка означає ваше перше посвячення в офіційні лави розбійників Орди і вказує шлях до науки Рваґа в Лігві.",["race:Troll"]="Тролі Темного Списа, що навчаються в Дуроторі, отримують цю табличку як доказ, що їхня спритність і скрадливість привернули увагу наставників Долини."},sec={{t="Прихований поклик",b="Тролі-розбійники, що прибувають у Долину Випробувань, отримують Зашифровану Табличку як першу настанову. Накреслена шифрованими вказівками, плитка веде їх просто до Рваґа — орка-наставника, що мешкає в затінених печерах Лігва. Замість відкрито оголошувати справи гільдії, місцеві тіньові агенти вживають ці шифровані плитки, щоб перевірити кмітливість і непомітно взяти нові таланти під офіційну опіку."},{t="Очі Руки",b="Розшифрування таблички знайомить новобранців із ширшою тіньовою мережею Орди. Доповівши Рваґу, розвідники дізнаються, що за їхнім поступом стежать тіньові спілки на кшталт Розтрощеної Руки, які покладаються на наставників долини, аби майбутні злодюжки, шпигуни й убивці були достатньо гострі, щоб служити новій нації."}},fp="16,223,16.432.0,16.331.0,38.175.0,36.152.0,21.114.0,37.190.0"}
P.entries["item:etched-note"] = {n="Гравірована Записка",s="Гравірована Записка — офіційний виклик, який вручають перспективним молодим мисливцям-тауренам, що відпочивають у Таборі Нарачі. Написане наставницею мисливців табору, Ланкою Фаршот, послання вітає новачка в традиціях полювання й кличе його на перший урок.",h="Гравірована Записка — офіційний виклик, який вручають перспективним молодим мисливцям-тауренам, що...",kw={"гравірована записка","мисливець","ланка фаршот","табір нарачі","таурени","шу'гало"},ang={["class:Hunter"]="Записка знаменує ваше офіційне посвячення в традицію мисливців і обіцяє уроки володіння далекобійною зброєю та спілкування зі звірами рівнин.",["race:Tauren"]="Несучи сподівання старійшин і свого роду, ви отримуєте цю записку як поклик опанувати хвилясті луки Малгору, перш ніж вирушати в далекі землі."},sec={{t="Поклик до полювання",b="Табір Нарачі — безпечне місце, де молодих шу'гало рано розпізнають за природними нахилами й родинним походженням. Гравіровану Записку приносить гонець від імені Ланки Фаршот, тутешньої наставниці мисливців. Вона називає мисливця серцем племені й водночас суворо нагадує: сирий інстинкт треба гартувати суворою наукою та глибокою шаною до дикої природи Малгору."},{t="Традиції шу'гало",b="Для тауренів полювання — значно більше, ніж практичний спосіб вижити: це шанована, священна дисципліна, вплетена в життя племені. Записка велить читачеві досконало вивчити кожен клапоть Плато Червоної Хмари й довколишніх рівнин. Подавши лист Ланці, учень робить перші офіційні кроки в науці зброї, розумінні звірів і виконанні обов'язку захищати й годувати племена."}},fp="11,274,18.422.0,26.430.0,39.217.0,20.173.0,42.235.0,34.133.0"}
P.entries["item:etched-parchment"] = {n="Гравірований Пергамент",s="Гравірований Пергамент — письмовий виклик, який отримують мисливці-новачки, що навчаються в Долині Випробувань у Дуроторі. Переданий Ґорнеком, він спрямовує майбутніх слідопитів нетрів по науку до тролиці-наставниці Джен'шан.",h="Гравірований Пергамент — письмовий виклик, який отримують мисливці-новачки, що навчаються в Долині...",kw={"гравірований пергамент","мисливець","джен'шан","ґорнек","долина випробувань","дуротар"},ang={["class:Hunter"]="Це послання — найперший обряд переходу мисливця в Дуроторі, що офіційно зводить вас із Джен'шан для навчання вистежування, стрільби й виживання.",["faction:Horde"]="Кожен молодий воїн Орди має відточувати своє ремесло; для мисливців цей пергамент — перший крок до того, щоб годувати клан і стерегти кордони Дуротару."},sec={{t="Поклик на полювання",b="Молоді орки й тролі Темного Списа, що шукають своє місце в Орді, починають обряди в посушливому басейні Долини Випробувань. Поки вони випробовують себе на місцевій дрібноті, Ґорнек пильно наглядає за ними й скеровує новобранців до їхнього покликання. Тим, кому судилося володіти луком, рушницею та іклом, Ґорнек передає цей гравірований пергамент. Він несе пряме послання від Джен'шан — умілої наставниці мисливців, що шукає свіжих очей і твердих рук."},{t="Перший урок",b="Принести пергамент Джен'шан — означає по-справжньому почати мисливський вишкіл у Дуроторі. Джен'шан наголошує: йти дикою стежкою нелегко, і опанувати звірів пустелі потребує не меншої відданості, ніж маг віддає магії, а шаман — духам. Прочитати пергамент і відгукнутися на її поклик — означає долучити новачків до справжньої стрілецької майстерності й виживання в нетрях."}},fp="16,229,21.455.0,16.408.0,33.127.0,29.123.0,31.129.0,28.131.0"}
P.entries["item:etched-rune"] = {n="Гравірована Руна",s="Гравірована Руна — різьблена кам'яна табличка, яку вручають майбутнім дворфійським мисливцям у Долині Холодного Хребта. Це запрошення від наставника мисливців Торґаса Ґрімсона, що велить новачкам знайти його в Анвілмарі й розпочати офіційне навчання лісовому ремеслу.",h="Гравірована Руна — різьблена кам'яна табличка, яку вручають майбутнім дворфійським мисливцям у Долині...",kw={"гравірована руна","мисливець","торґас ґрімсон","анвілмар","долина холодного хребта","полювання","вистежування"},ang={["class:Hunter"]="Руна — ваш перший офіційний виклик до давнього ремесла дворфійського полювання, де головне — вистежування, повага до тварин-супутників і виживання в суворій пустці лише власним розумом.",["race:Dwarf"]="Різьблені камені й руни — традиційний дворфійський спосіб передавати ремісничі знання та нагальні вказівки, навіть загартованим мандрівникам серед снігів Долини Холодного Хребта."},sec={{t="Поклик дикої природи",b="Цю невелику кам'яну табличку з вирізьбленими дворфійськими рунами передають новачкам, які виявляють хист серед заметів Долини Холодного Хребта. Надіслана горянином і наставником мисливців Торґасом Ґрімсоном, руна закликає молодих слідопитів відкласти справи надворі й з'явитися до Анвілмара. Прочитання каменя — перший крок мисливця від простого виживання до глибшого розуміння ремесла дикої природи: навчитися шанувати звірів Дун Мороґу, вистежувати гірських хижаків, доглядати дальнобійну зброю й витримувати люту стихію."}},fp="11,262,16.564.0,39.231.0,34.225.0,52.230.0"}
P.entries["item:etched-sigil"] = {n="Гравірований Сигіл",s="Вирізьблений знак, який вручають майбутнім мисливцям — нічним ельфам, що пробуджуються в Тінедолі. Принесений лісовим гінцем, він несе виклик від наставниці мисливців Аянни Еверстрайд із великої гілки Алдрассила.",h="Вирізьблений знак, який вручають майбутнім мисливцям — нічним ельфам, що пробуджуються в Тінедолі.",kw={"гравірований сигіл","мисливець","аянна еверстрайд","тінедол","алдрассил","тельдрассил","лук"},ang={["class:Hunter"]="Цей вирізьблений талісман — самісінький початок шляху калдорейського мисливця до опанування лука й звичаїв звірів під проводом Аянни Еверстрайд.",["race:NightElf"]="Вручений у відлюдному шатрі Тінедолу, сигіл вшановує прадавні традиції нічноельфійських лісників, відданих захисту Тельдрассила."},sec={{t="Поклик дикого краю",b="Різьблений знаками полювання Гравірований Сигіл вручають щойно пробудженим мисливцям — нічним ельфам, щойно ті ступають у Тінедол. Знак слугує офіційним сповіщенням і вітанням від Аянни Еверстрайд, місцевої наставниці мисливців, що мешкає високо в порожнистому вітті Алдрассила. Велячи новачкові розшукати її, сигіл розпочинає довічну науку стрільби з лука, лісового вистежування й прадавнього нічноельфійського зв'язку між ловцем і звіром."}},fp="12,209,20.452.0,40.206.0,27.129.0,32.137.0,68.195.0"}
P.entries["item:fang-of-vagash"] = {n="Ікло Ваґаша",s="Ікло Ваґаша — величезний хижацький зуб, узятий у сумнозвісного звіра Ваґаша серед засніжених скель Дун Мороґу. Для місцевих тваринників це відчутний доказ того, що чудовисько, яке загрожувало їхнім цінним баранам, нарешті вбито.",h="Ікло Ваґаша — величезний хижацький зуб, узятий у сумнозвісного звіра Ваґаша серед засніжених скель Дун Мороґу.",kw={"ікло ваґаша","ваґаш","ранчо амберстілл","барани","хижак","дун мороґ","трофей"},ang={["class:Hunter"]="Вистежити такого верховного хижака, як Ваґаш, серед крижаних скель Дун Мороґу — рання перевірка вміння йти по сліду, виживати в дикій природі й убивати звірів.",["race:Dwarf"]="Ранчо Амберстілл постачає витривалих гірських баранів, без яких не обійтися ні дворфійським горянам, ні мандрівникам. Принести ікло Ваґаша — означає зберегти найцінніший верховий виводок Айронфорджа."},sec={{t="Трофей полювання",b="Високі скелі Дун Мороґу — домівка лютого холоду й лютих хижаків, та жоден не дошкуляв місцевим ранчо так, як Ваґаш. Цей дикий звір, що зачаївся на гребенях над Ранчо Амберстілл, часто спускається під покровом темряви, щоб різати цінних баранів. Війська Айронфорджа й так розтягнуті до краю, тож місцеві пастухи не можуть розраховувати на захист міської варти. Убити звіра й вирізати одне з його лютих ікол — незаперечний доказ того, що пасовиська знову в безпеці."}},fp="14,246,18.521.0,36.207.0,14.195.0,45.173.0"}
P.entries["item:feather-charm"] = {n="Талісман з Пера",s="Талісмани з Пера — грубі магічні дрібнички, які носять новачки тролів Морозогривів у засніжених низинах Долини Холодного Хребта. Хоч зроблені вони з простих матеріалів, у них живе природний чаклунський відгук, що привертає увагу місцевих наставників-чорнокнижників.",h="Талісмани з Пера — грубі магічні дрібнички, які носять новачки тролів Морозогривів у засніжених низинах...",kw={"талісман з пера","чорнокнижник","морозогриви","тролі","аламар грімм","біс","анвілмар"},ang={["class:Warlock"]="Для чорнокнижників-новачків у Дун Мороґу відібрати талісмани з пера в тролячих чаклунів — головне випробування дисципліни, перш ніж Аламар Грімм довірить їм ритуал призову біса.",["race:Gnome"]="Гномські чорнокнижники, що працюють з Анвілмара, вивчають ці примітивні тролячі фетиші, щоб розібрати сиру, невідшліфовану магію, яку спрямовують первісні чаклуни Морозогривів."},sec={{t="Тролячі дрібнички й темні студії",b="Тролі Морозогриви, що живуть у засніжених печерах на південний захід від Анвілмара, відомі здебільшого територіальною жорстокістю, але їхні новачки бавляться примітивним чаклунством. Талісмани з пера, які носять ці молоді тролі, таять слабку, але безпомильну магічну силу. В Анвілмарі наставник чорнокнижників Аламар Грімм вважає їх цікавим предметом для вивчення — несподівано для грубої тролячої роботи — і використовує як випробування для новачків-чорнокнижників, які прагнуть опанувати прив'язування свого першого біса."}},fp="13,252,31.492.0,33.119.0,32.277.0,43.250.0,29.161.0"}
P.entries["item:fel-moss"] = {n="Мох Скверни",s="Мох Скверни — споганена рослинна речовина, що розповзається лісами Тельдрассила. Він несе демонічні, руйнівні сили, його розносять ворожі ґрелли та ґреллята, і він становить підступну загрозу для звірини й корінних племен фурболгів Світового Дерева.",h="Мох Скверни — споганена рослинна речовина, що розповзається лісами Тельдрассила.",kw={"мох скверни","скверна","ґрелли","фурболги","вузлошкіри","тариндрелла","тінедол","тельдрассил"},ang={["class:Druid"]="Для друїдів Кола Кенарія Мох Скверни — тривожна пухлина, що розповзається Тельдрассилом, і доказ того, що новонароджене Світове Дерево глибоко вразливе до демонічної пошесті.",["race:NightElf"]="Нічні ельфи шанують Тельдрассил як нову батьківщину, тож присутність Моху Скверни — гнітюче знамення: мир лишається невловимим навіть на їхньому священному вітті."},sec={{t="Пошесть на Світовому Дереві",b="Тельдрассил посадили, щоб повернути нічним ельфам безсмертя й зцілити природний світ, та скверна вже прокралася в його незаймане віття. Мох Скверни — один із найпомітніших знаків цього занепаду. Він чіпляється до бісуватих ґреллів і ґреллят, що заполонили Тінедол, і мандрує разом із ними, випромінюючи неприродну, лиху магію. Захисники лісу, як-от дріада Тариндрелла, взялися збирати зразки, щоб виміряти, як глибоко це гниття проникло у священне лісове шатро."},{t="Насіння безумства",b="Небезпека Моху Скверни сягає далі простого лісового гниття: він має згубний вплив на розум живих створінь. Колись мирні фурболги з висот Тельдрассила піддалися його дотику, покинули свої споконвічні оселі й збилися у вороже плем'я Вузлошкірів. Доведені до безумства лихою силою моху під проводом ватажків на кшталт Урсала Гамаїла, ці уражені створіння виявляють дедалі більшу хворобу, що вкорінюється у великому дереві."}},fp="8,264,24.512.0,16.473.1,17.211.0,30.222.0,38.207.0,45.242.0"}
P.entries["item:felix-s-box"] = {n="Скринька Фелікса",s="Скринька Фелікса — невеликий контейнер з особистими речами Фелікса Віндлболта, біженця, що втік після падіння Гномреґану. Загублену під час панічної евакуації до Дун Мороґу скриньку розграбували місцеві тролі Морозогриви й віднесли до своїх таборів на південний захід від Анвілмара.",h="Скринька Фелікса — невеликий контейнер з особистими речами Фелікса Віндлболта, біженця, що втік після падіння...",kw={"скринька фелікса","фелікс віндлболт","гномреґан","біженець","морозогриви","тролі","анвілмар"},ang={["profession:Engineering"]="Повернуті інструменти й контейнери — рятівна нитка для винахідника, і вони підкреслюють, яких злигоднів зазнають переселені гномські ремісники, розлучені зі своїм обладнанням.",["race:Gnome"]="Для гномів-шукачів пригод, що починають шлях у Долині Холодного Хребта, повернути особисті речі Фелікса — означає напряму полегшити долю побратима-вигнанця, який потерпає від гірких наслідків евакуації Гномреґану."},sec={{t="Загублена під час утечі з Гномреґану",b="Коли Гномреґан затопила радіація під час невдалої спроби вичистити трогів, Фелікс Віндлболт приєднався до панічного виходу гномів у Долину Холодного Хребта. У відчайдушній втечі від радіоактивних випарів Фелікс загубив свої найцінніші речі й ремісниче знаряддя на засніженій дорозі. Перш ніж він устиг їх повернути, тутешні тролі Морозогриви розграбували залишки край дороги й затягли його скриньку разом зі скринею та відром болтів до своїх грубих поселень на південний захід від Анвілмара."},{t="Біда біженця",b="Незвиклий до насильства й не пристосований до суворої пустки Дун Мороґу, Фелікс був змушений просити допомоги в подорожніх шукачів пригод в Анвілмарі, щоб повернути своє майно. Повернути Скриньку Фелікса — це не просто віддати скромний контейнер: це повернути дещицю звичного життя й заробітку переселеному ремісникові, який утратив усе в катастрофі, що поглинула його підземну батьківщину."}},fp="11,281,34.514.0,20.412.0,20.154.0,49.210.0,25.174.0,32.150.0"}
P.entries["item:felix-s-bucket-of-bolts"] = {n="Відро Болтів Фелікса",s="Відро Болтів Фелікса — ємність із запасними деталями й інструментами, що належить Феліксу Віндлболту, гному-біженцю, який утік після падіння Гномреґану. Під час його втечі до Дун Мороґу відро вихопили місцеві тролі Морозогриви й затягли до своїх сусідніх таборів.",h="Відро Болтів Фелікса — ємність із запасними деталями й інструментами, що належить Феліксу Віндлболту...",kw={"відро болтів","фелікс віндлболт","гномреґан","інженерія","морозогриви","тролі","біженець"},ang={["profession:Engineering"]="Жоден майстер не працюватиме без базового кріплення, тож просте відро болтів стає цінним надбанням, коли починаєш усе спочатку серед снігів Дун Мороґу.",["race:Gnome"]="Кожне врятоване відро деталей — ще один крихітний шматочок Гномреґану, вирваний у руїни, що допомагає біженцям закріпитися в Долині Холодного Хребта."},sec={{t="Розкидане знаряддя біженця",b="Коли після катастрофи у війні з трогами Гномреґан затопила радіація, тисячі гномів утекли в крижані пустки Дун Мороґу з тим, що змогли винести. Фелікс Віндлболт зумів вибратися зі своїм найважливішим обладнанням, але в сум'ятті втечі до Анвілмара потрапив у засідку тролів Морозогривів, що мешкають у скелях на південний захід від містечка. Тролі розграбували його майно, зокрема й це відро, повне болтів і деталей, лишивши ремісника без матеріалів, конче потрібних, щоб працювати за фахом у вигнанні."}},fp="23,265,27.541.0,32.156.0,21.131.0,29.103.0,38.199.0"}
P.entries["item:felix-s-chest"] = {n="Скриня Фелікса",s="Скриня Фелікса — контейнер з особистими речами, який вигнанець-гном Фелікс Віндлболт загубив під час утечі з Гномреґану. Її віднесли тролі Морозогриви, що никають біля Долини Холодного Хребта, і тепер вона стоїть покинута в одному з їхніх примітивних гірських таборів.",h="Скриня Фелікса — контейнер з особистими речами, який вигнанець-гном Фелікс Віндлболт загубив під час утечі з...",kw={"скриня фелікса","фелікс віндлболт","гномреґан","евакуація","морозогриви","тролі","анвілмар"},ang={["race:Gnome"]="Скриня — болісне нагадування про хаотичну евакуацію Гномреґану, коли гноми-втікачі втратили майже все через дику природу та мародерів-опортуністів."},sec={{t="Утрати біженця",b="Коли підземне техномісто Гномреґан упало під натиском трогів і отруйних радіоактивних опадів, тисячі гномів кинулися на засніжену поверхню Дун Мороґу з тим майном, що змогли понести. Фелікс Віндлболт зумів вибратися з опромінених руїн, але серед паніки евакуації тутешні тролі Морозогриви нишпорили по дорогах і наздоганяли розрізнених уцілілих. Фелікс утратив основне знаряддя й пожитки, а його міцну скриню затягли до грубих таборів, які тролі тримають у скелях на південний захід від Анвілмара."}},fp="13,257,18.547.0,29.271.0,52.277.0,27.148.0"}
P.entries["item:felstalker-hoof"] = {n="Копито Переслідувача Скверни",s="Копито Переслідувача Скверни — речовий знак, здобутий із демонічних звірів, що кишать у Ковені Палаючого Клинка в Долині Випробувань у Дуроторі. Молоді шамани мають здобути ці копита як випробування готовності, перш ніж навчитися єднатися з духами стихії землі.",h="Копито Переслідувача Скверни — речовий знак, здобутий із демонічних звірів, що кишать у Ковені Палаючого...",kw={"копито","переслідувач скверни","шаман","ерткаллер","ковен","долина випробувань","тотем землі"},ang={["class:Shaman"]="Убивство демонів і збирання їхніх копит — ваш перший великий крок до єднання з духами землі, перевірка терпіння й упертої стійкості, потрібних, щоб володіти Тотемом Землі.",["faction:Horde"]="Присутність демонічних переслідувачів Скверни на тренувальних землях Дуротару — постійне нагадування про скверну Палаючого Клинка, що й досі тліє на землях Орди."},sec={{t="Випробування шамана",b="У випаленій сонцем Долині Випробувань наставник Канаґа Ерткаллер доручає шаманам-початківцям стати на герць із демонічною скверною, що загрожує Дуротару. Ковен Палаючого Клинка на півночі ховає мерзенних фамільярів і демонічних переслідувачів Скверни. Забрати копита цих бісів — не просто знищення шкідників, а суворе випробування витривалості, рішучості й духу. Лише приборкавши цих хаотичних звірів, майбутній шаман доводить, що гідний прийняти таємниці землі та приготувати обрядову сапту, потрібну для прямого єднання з духами стихій."}},fp="15,260,16.552.0,37.208.0,32.161.0,26.131.0,40.197.0"}
P.entries["item:filled-amethyst-phial"] = {n="Наповнена Аметистова Фіала",s="Наповнена Аметистова Фіала містить священну воду з прадавнього місячного колодязя під віттям Дерева Оракула. Зібрана на прохання Корітраса Мунрейджа, ця очищена вода слугує друїдам Кола Кенарія для вивчення тривожного, недосконалого зростання Тельдрассила.",h="Наповнена Аметистова Фіала містить священну воду з прадавнього місячного колодязя під віттям Дерева Оракула.",kw={"наповнена аметистова фіала","місячний колодязь","дерево оракула","корітрас мунрейдж","фандрал стаґгелм","драконячі аспекти","тельдрассил","нордрассил"},ang={["class:Druid"]="Друїди Кола Кенарія шанують місячні колодязі як провідники природи й зоряної сили і вивчають уражений живий світ Тельдрассила за допомогою очищених посудин, як-от ця фіала.",["race:NightElf"]="Для калдореїв наповнити цю фіалу означає похмуро усвідомити: їхній славний новий дім відкинули Драконячі Аспекти, а втрачене безсмертя не повернулося."},sec={{t="Вода Дерева Оракула",b="Далеко на північному заході Тельдрассила лежить Галявина Оракула, де під великим Деревом Оракула спочиває найстаріший і наймогутніший із місячних колодязів острова. Якщо менші колодязі по всьому вітті служать щоденним потребам нічних ельфів, то води цього колодязя насичені чистою сутністю ласки Елуни. Друїди, яким доручено стежити за здоров'ям Світового Дерева, набирають і зберігають цю могутню рідину в особливих аметистових фіалах для досліджень і обрядового очищення."},{t="Недосконале відродження",b="Повернення цього зразка Корітрасу Мунрейджу має скорботну мету. Попри тріумф Архідруїда Фандрала Стаґгелма, який виростив Тельдрассил на заміну полеглому Нордрассилу, Драконячі Аспекти відмовилися його освятити. Без благословення Ноздорму, яке повернуло б нічним ельфам безсмертя, і Алекстрази, яке захистило б його життєву силу, зростання Тельдрассила лишається кволим і ураженим скверною. Зразки з галявини показують: навіть найсвященніші води острова не приховають повзучої недуги, що вкорінюється у Світовому Дереві."}},fp="21,266,24.487.0,16.525.1,45.161.0,44.178.0,34.153.0,50.224.0"}
P.entries["item:filled-crystal-phial"] = {n="Наповнена Кришталева Фіала",s="Наповнена Кришталева Фіала містить священну воду з місячного колодязя одразу на північ від Алдрассила в Тінедолі. Зібрана за настановою Тенарона Стормґріпа, ця вода знайомить новачка зі священною й мінливою силою, що струменить Тельдрассилом.",h="Наповнена Кришталева Фіала містить священну воду з місячного колодязя одразу на північ від Алдрассила в...",kw={"наповнена кришталева фіала","місячний колодязь","тенарон стормґріп","тінедол","алдрассил","колодязь вічності","гора гіджал"},ang={["class:Druid"]="Друїди глибоко шанують воду місячних колодязів і її оживлювальними силами доглядають споганену рослинність і підтримують великі дерева.",["race:NightElf"]="Кожен молодий калдорей, що починає навчання під Алдрассилом, наповнює цю фіалу, згадуючи жертву Гори Гіджал і свій священний обов'язок берегти природу."},sec={{t="Води місячного колодязя",b="Щоб підготувати молодих нічних ельфів до виходу в ширший світ, Тенарон Стормґріп посилає їх набрати води з місячного колодязя, що ховається в Тінедолі. У фіалі не проста джерельна вода: Місячний Колодязь наснажений залишковими силами, що сягають прадавнього Колодязя Вічності. Вартові шанують ці місця як благословенні святині Елуни, а друїди спрямовують їхні відновлювальні властивості на догляд за природою, та давнє таємне чаклунство лишається суворо забороненим. Набрати цієї води — перший крок до розуміння жертв Гори Гіджал і хисткої рівноваги, потрібної, щоб плекати Тельдрассил."}},fp="20,265,22.622.0,40.195.0,31.165.0,43.227.0,25.253.0"}
P.entries["item:filled-jade-phial"] = {n="Наповнена Нефритова Фіала",s="Наповнена Нефритова Фіала містить священну воду з місячного колодязя біля Села Зоряного Вітерця. Принесена назад до Доланаара, вона є частиною безперервного обряду поповнення центральних вод столиці, під час якого молоді нічні ельфи пізнають історію свого народу.",h="Наповнена Нефритова Фіала містить священну воду з місячного колодязя біля Села Зоряного Вітерця.",kw={"наповнена нефритова фіала","місячний колодязь","село зоряного вітерця","корітрас мунрейдж","доланаар","нордрассил","малфуріон стормрейдж"},ang={["class:Druid"]="Догляд за місячними колодязями прямо єднає друїдів із відновлювальною магією, що живить Дарнасус, і з безперервними зусиллями Кола Кенарія плекати молоде Світове Дерево.",["race:NightElf"]="Принесена вода зміцнює священний обов'язок молодого калдорея перед Тельдрассилом і передає важливу історію про втрату безсмертя після Гори Гіджал."},sec={{t="Води Зоряного Вітерця",b="Друїди Дарнасуса покладаються на священну воду місячних колодязів з усього віття Тельдрассила, щоб поповнювати свої центральні колодязі. Особливо виготовлені посудини, як-от нефритова фіала, яку Корітрас Мунрейдж у Доланаарі довіряє молодим шукачам пригод, настроєні безпечно вміщувати ці чисті води. Вирушивши на схід до місячного колодязя за Селом Зоряного Вітерця, посвячені набирають життєдайну воду й водночас доводять відданість догляду за Світовим Деревом."},{t="Урок історії",b="Повернути Наповнену Нефритову Фіалу до Доланаара — більше ніж просте доручення: кожна поповнена посудина відкриває новий розділ усної історії калдореїв. Прийнявши повну фіалу, Корітрас Мунрейдж розповідає про відчайдушну добу після Третьої війни — спалення Нордрассила, втрату безсмертя нічних ельфів, звільнення Зрадника й раптове зникнення Шан'до Малфуріона Стормрейджа у Смарагдовому Сні."}},fp="17,256,20.463.0,19.435.0,31.151.0,35.166.0,54.214.0,55.249.0"}
P.entries["item:filled-tourmaline-phial"] = {n="Наповнена Турмалінова Фіала",s="Наповнена Турмалінова Фіала містить зачаровану воду з місячного колодязя на межі Озерець Арлітрієну в південному Тельдрассилі. Зібрана на прохання Корітраса Мунрейджа, вода є частиною зусиль стежити за здоров'ям і рівновагою зростаючого Світового Дерева.",h="Наповнена Турмалінова Фіала містить зачаровану воду з місячного колодязя на межі Озерець Арлітрієну в...",kw={"наповнена турмалінова фіала","озерця арлітрієну","місячний колодязь","корітрас мунрейдж","фандрал стаґгелм","вузлошкіри","тельдрассил"},ang={["class:Druid"]="Для друїдів несення фіали прямо торкається суперечливого спадку Архідруїда Фандрала Стаґгелма, який наполіг на посадженні Тельдрассила за незрозумілої відсутності Шан'до Стормрейджа.",["race:NightElf"]="Води місячних колодязів — неодмінна духовна жила калдореїв, тож скверна в навколишніх гаях Вузлошкірів — глибоко тривожне знамення для їхнього нового дому."},sec={{t="Води Арлітрієну",b="Турмалінова Фіала призначена саме для води з місячного колодязя на південний схід від дороги до Дарнасуса, на берегах Озерець Арлітрієну. Набирати воду з цієї святині стало небезпечно через раптову лють фурболгів Вузлошкірів — мирних сусідів, що стрімко скотилися в несамовите безумство. Корітрас Мунрейдж доручає мандрівникам пройти ворожими гаями й здобути цю воду, щоб розпізнати скверну, яка дедалі глибше збурює землю."},{t="Коріння Тельдрассила",b="Повернення фіали до Доланаара спонукає Корітраса Мунрейджа замислитися над постанням віття вгорі. Після зникнення Шан'до Малфуріона Стормрейджа у Смарагдовому Сні Архідруїд Фандрал Стаґгелм згуртував Коло Древніх за морем, на Темному Узбережжі, щоб посадити Тельдрассил у надії повернути втрачене безсмертя. Вода в самоцвітній фіалі відбиває стан того священного досліду — задуму, нині затьмареного незрозумілою хворобою, що розповзається на звірів і фурболгів."}},fp="23,279,20.507.0,23.526.1,45.246.0,55.206.0,49.247.0,26.278.0"}
P.entries["item:filled-vessel"] = {n="Наповнена Посудина",s="Наповнена Посудина містить очищену воду з різних священних місячних колодязів Тельдрассила. Довірена посланцям Корітрасом Мунрейджем у Доланаарі, вона призначена Архідруїдові Фандралу Стаґгелму в Дарнасусі на допомогу в його вивченні недуг Світового Дерева.",h="Наповнена Посудина містить очищену воду з різних священних місячних колодязів Тельдрассила.",kw={"наповнена посудина","місячні колодязі","корітрас мунрейдж","фандрал стаґгелм","дарнасус","ценаріонський анклав","тельдрассил"},ang={["class:Druid"]="Для посвячених Кола Кенарія доставка цієї посудини — перше офіційне доручення до Архідруїда Фандрала Стаґгелма, що на власні очі показує крихкість живого світу Тельдрассила.",["race:NightElf"]="Води місячних колодязів усередині — священні жили нового дому калдореїв, у яких магія Елуни змішується з непевним зростанням неблагословенного Світового Дерева."},sec={{t="Злиття священних вод",b="Тельдрассил посадили без благословення Великих Аспектів, Алекстрази й Ноздорму, і його величезне віття лишилося вразливим до несподіваної скверни, дивних звірів і знавіснілих племен фурболгів. Щоб стежити за молодим віттям і очищати його, нічноельфійських послушників посилають збирати зразки води з місячних колодязів по всьому вітті. Корітрас Мунрейдж зливає зібрані фіали в одну Наповнену Посудину й відсилає її далі, до столиці. Суміш слугує важливим зразком життєвої сили Тельдрассила для Архідруїда Фандрала Стаґгелма, який невтомно працює в Ценаріонському Анклаві, шукаючи ліки від глибинних вад Великого Дерева."}},fp="13,265,29.675.0,33.159.0,28.121.0,51.256.0,24.155.0"}
P.entries["item:fire-tar"] = {n="Вогняна Смола",s="Вогняна Смола — летка речовина, яку збирають чаклуни-шипогриви Гостроманів по всіх східних Пустках. Для шаманів Орди це ключовий обрядовий складник Вогняної Сапти, що дарує духовне єднання зі стихією вогню.",h="Вогняна Смола — летка речовина, яку збирають чаклуни-шипогриви Гостроманів по всіх східних Пустках.",kw={"вогняна смола","шипогриви","гострогриви","шаман","вогняна сапта","вогняний тотем","телф джулам"},ang={["class:Shaman"]="Збирання Вогняної Смоли — важливий обряд переходу, що вчить вас шукати відгомін стихій у широкому світі, аби зварити Вогняну Сапту й заслужити свій Вогняний Тотем.",["faction:Horde"]="Щоб здобути Вогняну Смолу, молоді шукачі пригод Орди покидають Дуротар і переходять Річку Південної Люті в Пустки, де стикаються з агресивними племенами Гостроманів."},sec={{t="Вариво Гостроманів",b="Вогняна смола — алхімічна речовина, тісно споріднена з полум'ям, і носять її майже виключно чаклуни-шипогриви Гостроманів: геоманти, містики й тернові ткачі. Поки щетинисті племена Пусток уживають її для власної жорстокої магії та обрядів, шаманські наставники бачать у ній необхідний земний реагент, здатний перекинути міст між смертними чуттями й сирою люттю стихій."},{t="Шлях до Вогняного Тотема",b="Коли молодих орків і тролів-шаманів посилають до Телфа Джулама, що вмостився високо на скелях Дуротару, їм доручають викувати свій вогняний тотем. Для Вогняної Сапти Телф вимагає два ключові складники, пов'язані з жаром і полум'ям: мішечок реагентів, відібраний у культистів Палаючого Клинка, і вогняну смолу, здобуту в Гостроманів. Випивши готове вариво, шаман пронизує завісу й бачить духів полум'я, що чекають на нього на сусідніх вершинах."}},fp="8,250,29.406.0,26.454.0,26.269.0,21.157.0,61.300.0,43.207.0"}
P.entries["item:fizzle-s-claw"] = {n="Кіготь Фіззла",s="Кіготь Фіззла — відрубана рука гобліна-чорнокнижника Фіззла Дарксторма. Здобутий у його таборі на Громовому Хребті, він слугує речовим доказом для командирів Орди в Гострому Пагорбі, що небезпечного змовника Палаючого Клинка вбито.",h="Кіготь Фіззла — відрубана рука гобліна-чорнокнижника Фіззла Дарксторма.",kw={"кіготь фіззла","дарксторм","гоблін","чорнокнижник","громовий хребет","палаючий клинок","соулскар"},ang={["class:Warlock"]="Фіззл Дарксторм уживав мистецтва Скверни на службі підривному Палаючому Клинку, обернувши свої темні таланти на пряме повстання проти Орди.",["faction:Horde"]="Піднести кіготь Фіззла в Гострому Пагорбі — означає підтвердити тривалу рішучість очистити Дуротар від тіньових культів, що загрожують крихкій безпеці молодої нації."},sec={{t="Похмурий трофей",b="Орґніл Соулскар, якому доручено викорінити тіньові культи, що загрожують батьківщині орків, визначив Фіззла Дарксторма як підбурювача, що ширить скверну на Громовому Хребті. Вимога принести кіготь Фіззла — не просто дикунство, а практична потреба: Орді потрібен беззаперечний доказ, коли знищено таємного чорнокнижника, що діяв під стягом Палаючого Клинка."},{t="Загроза на Громовому Хребті",b="Громовий Хребет і так був збурений заворушеннями стихій, тож присутність культиста Фіззла стала близькою небезпекою для довколишніх земель. Відрубавши кіготь гобліна й принісши його до Гострого Пагорба, розвідники Орди підтвердили: обряди чорнокнижника та його спроби закріпити Палаючий Клинок на цих землях зірвано."}},fp="13,242,13.376.0,27.325.0,29.127.0,44.219.0,25.135.0,43.220.0"}
P.entries["item:flatland-prowler-claw"] = {n="Кіготь Рівнинного Бродяги",s="Кіготь Рівнинного Бродяги беруть у небезпечних котячих хижаків, що скрадаються трав'янистими рівнинами Малгору. Для майбутніх мисливців збирання цих кігтів — традиційний обряд посвяти, що доводить старійшинам Тандер Блафу їхню кмітливість і бойову рішучість.",h="Кіготь Рівнинного Бродяги беруть у небезпечних котячих хижаків, що скрадаються трав'янистими рівнинами...",kw={"кіготь рівнинного бродяги","рівнинний бродяга","мисливець","скорн вайтклауд","мелор стоунгуф","тандер блаф","малгор"},ang={["class:Hunter"]="Полювання на потайних бродяг перевіряє, наскільки пильний мисливець у полі, тож ці кігті — символ заслуженої поваги серед стрільців, що збираються на Узвишші Мисливців у Тандер Блафі.",["race:Tauren"]="Для тауренів полювання — почесна духовна традиція, і подані кігті хитрого рівнинного хижака знаменують перші кроки посвяченого до служіння племені слідопитом."},sec={{t="Доказ мисливця",b="Рівнинні бродяги — одні з найхитріших і найтериторіальніших хижаків, що никають обвітреними рівнинами Малгору. Прудкі й вправні у засідках у високій траві, вони становлять справжню загрозу для подорожніх і гідне випробування для молодих мисливців. Збирати їхні гострі кігті — не просто справа виживання, а визнана традиція. Скорн Вайтклауд радить перспективним мандрівникам здобути ці трофеї й подати їх Мелору Стоунгуфу на Узвишші Мисливців у Тандер Блафі — на доказ того, що вони мають рішучість і польову майстерність, потрібні на шляху мисливця."}},fp="21,268,16.571.0,41.207.0,29.178.0,52.245.0"}
P.entries["item:foreman-s-blackjack"] = {n="Кийок Наглядача",s="Кийок Наглядача — важка, обмотана шкірою довбня, яку позичають новим новобранцям Орди в Долині Випробувань. Наглядачі передають її як буденне знаряддя дисципліни: будити заснулих пеонів і тримати виснажливий темп перших будов Дуротару.",h="Кийок Наглядача — важка, обмотана шкірою довбня, яку позичають новим новобранцям Орди в Долині Випробувань.",kw={"кийок","наглядач","тазз'ріл","пеони","робітники","долина випробувань","дуротар"},ang={["faction:Horde"]="Кийок показує невпинні практичні зусилля, потрібні, щоб приборкати Дуротар: заселення суворого краю вимагає від кожного робітника праці без перепочинку.",["race:Orc"]="Для молодих орків, що ступають у Долину Випробувань, кийок у руках — ранній урок ієрархії Орди: тих, кому бракує сили чи духу воїна, відводять до праці й тримають у покорі силою."},sec={{t="Знаряддя орчої праці",b="Щоб збудувати новий дім у суворій пустелі Дуротару, потрібні величезні запаси деревини, і ця праця цілком лягає на плечі пеонів Орди. У Долині Випробувань Наглядач Тазз'ріл покладається на Кийок Наглядача, щоб робочі бригади не спинялися. Ця майстерно обтяжена довбня не завдає смертельних ударів — вона дає струсливий побудильний сигнал робітникам, яких заскочили за дрімотою під тінистими деревами долини. Це суворе нагадування про життя пеона в новій Орді: виснажливе, невдячне й під залізною рукою."}},fp="19,261,22.544.0,41.211.0,24.159.0,48.220.0,50.174.0"}
P.entries["item:gargantuan-tumor"] = {n="Велетенська Пухлина",s="Велетенська Пухлина — величезний хворобливий наріст, вирваний зі споганеного деревляника Похмуродуба в Тельдрассилі. Це кричущий доказ неприродної хвороби, що розповзається серед створінь Озера Ал'Амет.",h="Велетенська Пухлина — величезний хворобливий наріст, вирваний зі споганеного деревляника Похмуродуба в...",kw={"велетенська пухлина","похмуродуб","деревляник","озеро ал'амет","скверна","тельдрассил","наріст"},ang={["class:Druid"]="Для друїдів, що прагнуть плекати молоде віття Тельдрассила, потворна пухлина — тривожне нагадування: природа у вітті небезпечно вразлива до скверни.",["race:NightElf"]="Бачити шанованого старійшину-деревляника, перетвореного на безумне, уражене чудовисько, — підкреслення дедалі більших негараздів довкілля, що спіткали новий дім калдореїв."},sec={{t="Пошесть над озером",b="Біля південного берега Озера Ал'Амет печера прихищає Похмуродуба — колись шляхетного старійшину деревляників, що став жертвою мерзенної недуги. Створіння було помітно отруєне величезним наростом, який спотворив його поведінку й просочував скверну в навколишню звірину. Відтяти цю потворну пухлину вкрай важливо не лише щоб покласти край мученицькому шалу звіра, а й щоб тутешні дослідники змогли оглянути пошесть і зрозуміти, як така огидна недуга вкоренилася у вітті новопосталого Світового Дерева."}},fp="16,222,20.499.0,42.141.0,48.207.0,30.152.0"}
P.entries["item:garrick-s-head"] = {n="Голова Ґарріка",s="Голова Ґарріка — відтята голова Ґаррика Педфута, сумнозвісного горлоріза, що орудував біля виноградників Долини Нортширу. Вона слугує моторошним доказом смерті, потрібним, щоб отримати винагороду, оголошену владою Абатства Нортшира.",h="Голова Ґарріка — відтята голова Ґаррика Педфута, сумнозвісного горлоріза, що орудував біля виноградників...",kw={"голова ґарріка","ґаррик педфут","бандит","винагорода","нортшир","помічник віллем"},ang={["class:Rogue"]="Усунення Педфута показує тутешнім головорізам, що на недисципліноване бандитство неодмінно відповідять смертоносніші, фаховіші клинки.",["race:Human"]="Голова Педфута — один із перших рішучих ударів, яких молодий новобранець Стормвінда завдає беззаконню, що розповзається Лісом Елвінн."},sec={{t="Кінець бандита",b="Тижнями Ґаррик Педфут і його зграя головорізів тероризували тутешніх фермерів і крамарів по всій Долині Нортширу. Скориставшись тим, що оборона Королівства Стормвінд розтягнута до межі, Ґаррик засів у халупі біля нортширських виноградників, грабуючи проїжджих торговців. Поки тутешню варту скували кобольди, що насуваються, та бандити Дефіас, Помічник Віллем оголосив винагороду за голову Педфута, шукаючи заповзятливого шукача пригод, який усуне розбійника й надасть незаперечний доказ його загибелі."}},fp="14,229,14.485.0,24.222.0,51.190.0,33.139.0,39.130.0"}
P.entries["item:gloom-weed"] = {n="Похмура Трава",s="Похмура Трава — хирлява рослина, що росте на ураженому ґрунті Галявин Тірісфалю, здебільшого на полях між Похоронним Подзвоном і Бріллом. Найбільше вона відома як не та рослина, яку збирає Ґордо — незграбна почвара Відступників, що плутає її з алхімічним реагентом, травою-згубою.",h="Похмура Трава — хирлява рослина, що росте на ураженому ґрунті Галявин Тірісфалю, здебільшого на полях між...",kw={"похмура трава","ґордо","почвара","трава-згуба","брілл","похоронний подзвін","травництво"},ang={["profession:Herbalism"]="Навчені травники відчувають цю рослину за допомогою Пошуку трав, тож помітити її в тінистому підліску Тірісфалю значно легше.",["race:Undead"]="Для нових Відступників, що покидають Похоронний Подзвін, принести Похмуру Траву — швидкий урок про вади праці почвар і їдкий норов алхіміків Андерсіті."},sec={{t="Помилковий урожай",b="Проростаючи серед мороку й розкладу Галявин Тірісфалю, Похмура Трава буяє на перелогах на захід від Брілла — там, де на обрії видніє Хутір Соллідена. Попри зловісну назву, рослина доволі нешкідлива й позбавлена потужного алхімічного ефекту, який цінує Королівське Аптекарське Товариство. Своєю славою вона завдячує почварі Ґордо, що блукає дорогою й намагається висмикувати бур'яни своїми величезними незграбними руками. Хибно зрозумівши наказ господаря, Ґордо знай збирає Похмуру Траву й підбиває довірливих мандрівників носити її оберемками майстрові Голланду на цвинтар Брілла — на превелике роздратування аптекаря."}},fp="10,278,18.640.0,28.177.0,27.164.0,38.220.0,38.181.0"}
P.entries["item:glowing-ember"] = {n="Сяйливий Жар",s="Сяйливий Жар — тліюче стихійне осердя, здобуте з переможеного Малого Прояву Вогню на скелях Дуротару. Це важливий обрядовий реагент у випробуваннях шамана, яким розпалюють жаровню в Святилищі Вічного Полум'я.",h="Сяйливий Жар — тліюче стихійне осердя, здобуте з переможеного Малого Прояву Вогню на скелях Дуротару.",kw={"сяйливий жар","вогонь","прояв вогню","шаман","святилище","смолоскип","дуротар"},ang={["class:Shaman"]="Здобуття цього палаючого осердя — визначальний обряд переходу, що змушує посвячуваного випробувати свою рішучість проти живого вогню, перш ніж наказувати його тотему."},sec={{t="Осердя полум'я",b="Коли майбутній шаман випиває вогняну сапту і стає перед вогняними духами на хребті біля Телфа Джулама, він зустрічає Малий Прояв Вогню. Після перемоги над елементалем цей тліючий залишок — усе, що лишається від його тілесної форми. Жар, що досі пульсує сирим стихійним теплом, несе живу іскру вогню, потрібну, щоб пробудити священну жаровню в Святилищі Вічного Полум'я."},{t="Запалення смолоскипа",b="Покладений у холодну чашу гірської жаровні, Сяйливий Жар спалахує раптовим білим полум'ям. Живлячись рештками переможеного елементаля, жаровня дає посвячуваному запалити Смолоскип Сплячого Полум'я, замкнувши норовливу сутність вогню в посудину, яку можна знести з гори на доказ влади над стихіями."}},fp="13,250,17.396.0,18.366.1,39.165.0,27.176.0,49.217.0,39.155.0"}
P.entries["item:glowing-fruit"] = {n="Сяйливий Плід",s="Сяйливий Плід — екзотичний світний зразок, що росте серед дивного листя на вітті Тельдрассила. Його неприродне сяйво й химерна взаємодія з ґрунтом Світового Дерева роблять його предметом нагального ботанічного вивчення для природознавців.",h="Сяйливий Плід — екзотичний світний зразок, що росте серед дивного листя на вітті Тельдрассила.",kw={"сяйливий плід","деналан","озеро ал'амет","ботаніка","тельдрассил","насіння","ґрунт"},ang={["class:Druid"]="Для друїдів, настроєних на крихку рівновагу Тельдрассила, чужа рослинність, що непередбачувано реагує на ґрунт, — можливе збурення для зростаючого Світового Дерева.",["profession:Herbalism"]="Травники одразу завважать: дивне світіння плоду вказує на екзотичну, потужну взаємодію між чужоземним насінням і зачарованим ґрунтом."},sec={{t="Цікавий зразок",b="Знайдений під незвичним листям на Тельдрассилі, цей великий круглий плід випромінює безпомильне світло. Ботанік Деналан біля Озера Ал'Амет упізнає в ньому чужинця для Світового Дерева й припускає, що його насіння прибуло з далеких земель за морем. Хай яке його походження, плід дивно реагує на багатий, зачарований ґрунт Тельдрассила і показує, наскільки молода світова гілка вразлива до чужої й непередбачуваної рослинності."}},fp="13,250,18.441.0,26.168.0,31.228.0,39.200.0"}
P.entries["item:glyph-of-azora"] = {n="Гліф Азори",s="Гліф Азори — таємний пристрій стеження, створений чарівником Теокрітусом у Вежі Азори. Прив'язані до ясновидної сили Ока Азори, ці різьблені камені дають магові змогу зазирати крізь відстані й проникати в думки своїх ворогів.",h="Гліф Азори — таємний пристрій стеження, створений чарівником Теокрітусом у Вежі Азори.",kw={"гліф азори","теокрітус","вежа азори","морґант","ясновидіння","редрідж"},ang={["class:Mage"]="Гліф Азори показує практичне таємне ворожіння, розширюючи звичайне кришталеве ясновидіння до цілеспрямованої телепатії та передачі відчуттів на відстані.",["faction:Alliance"]="Гліфи дають важливі відомості про ворожі пересування в Редріджі: вони стежать за чаклуном-відступником Морґантом і гарнізоном орків Блекрок в Кам'яній Варті."},sec={{t="Очі за кордоном",b="Зі своєї вежі в Лісі Елвінн чарівник Теокрітус невтомно стежить за ворожими силами, що загрожують королівству. Його кришталева реліквія, Око Азори, дає змогу бачити на великі відстані, та їй бракує сили проникати глибше — у розум і задуми супротивників. Щоб подолати це обмеження, Теокрітус створює мініатюрні осередки, відомі як Гліфи Азори. Прикріплений до поверхні у віддаленому місці, гліф стає якорем для його магії: він дозволяє не лише читати наміри ворога, а й переносити голос на милі, щоб говорити просто з польовими агентами."},{t="Шпигунство в Редріджі",b="Теокрітус розміщує ці гліфи просто на ворожій території в Горах Редріджу. Перший кріплять до давньої статуї лева над Вежею Ілґалара — твердинею його суперника-відступника, темного чарівника Морґанта. Проникнувши в розум Морґанта, Теокрітус виявляє несподівану сварку між магом-ренегатом і орками Блекрок, що зайняли сусідню Фортецю Кам'яної Варти. Другий гліф несуть на висоту вцілілої сторожової вежі фортеці, сховавши в покинутому глечику з-під трунку, щоб з'ясувати, чому Морґант і загарбники ворогують."}},fp="14,256,22.588.0,21.554.1,42.286.0,31.126.0,37.237.0,49.210.0,55.218.0"}
P.entries["item:glyphic-letter"] = {n="Гліфічний Лист",s="Гліфічний Лист — офіційне послання з таємним знаком Келдена Бремена, наставника магів в Абатстві Нортшира. Його вручають перспективним новачкам після перших послуг гарнізону, і він велить майбутнім магам піднятися нагору й зустрітися із суворою дійсністю вивчення таємної магії.",h="Гліфічний Лист — офіційне послання з таємним знаком Келдена Бремена, наставника магів в Абатстві Нортшира.",kw={"гліфічний лист","келден бремен","маг","абатство нортшира","таємна магія","наставник"},ang={["class:Mage"]="Це позначене послання знаменує ваше офіційне посвячення в таємні традиції Альянсу й кличе вас нагору навчатися в Келдена Бремена.",["race:Human"]="Абатство Нортшира за історію королівства прихистило багатьох учнів таємної магії, і цей виклик починає вашу службу магічним дисциплінам Стормвінда."},sec={{t="Виклик до таємної магії",b="Запечатаний особистим знаком наставника магів Келдена Бремена, Гліфічний Лист вручають учням-чарівникам, щойно вони доведуть свою дисципліну в Долині Нортширу. Лист — офіційне запрошення відійти від простих польових обов'язків і розпочати справжнє магічне навчання в абатстві. Бремен використовує цей виклик, щоб виміряти рішучість учня й пересвідчитися, що кожен, хто береться за таємну магію, цілком готовий зустріти небезпечні сили, невблаганну прискіпливість і тягар, який несе володіння сирою магічною силою."}},fp="14,294,23.545.0,27.225.0,29.220.0,35.215.0,38.253.0"}
P.entries["item:glyphic-memorandum"] = {n="Гліфічний Меморандум",s="Гліфічний Меморандум — письмове повідомлення, яке вручають магам-новачкам, що прибувають до Долини Холодного Хребта. Написаний від імені наставника магів Марріка Нуррібіта, він скеровує заклиначів-початківців під дах, щоб розпочати офіційне навчання таємним мистецтвам.",h="Гліфічний Меморандум — письмове повідомлення, яке вручають магам-новачкам, що прибувають до Долини Холодного...",kw={"гліфічний меморандум","маг","маррік нуррібіт","анвілмар","долина холодного хребта","навчання","гноми"},ang={["class:Mage"]="Для магів-початківців, що мандрують Дун Мороґом, ця записка — офіційний початок учнівства в таємних мистецтвах під проводом Марріка Нуррібіта.",["race:Gnome"]="Гномам-магам, що починають шлях у вигнанні, наставник нагадує: зосередьтеся на навчанні й тримайтеся подалі від утраченої батьківщини — Гномреґану."},sec={{t="Виклик до Анвілмара",b="Заклиначі-новачки, що вирушають у лютий мороз Долини Холодного Хребта, отримують це коротке послання, впоравшись із першими дорученнями. Меморандум, складений місцевим наставником магів Марріком Нуррібітом, кличе молодих практиків у тепло Анвілмара. Замість суворої академічної догми настанови Марріка невимушені й прямі: вчіть закляття, відкладайте монети на навчання й корчемний ель та тримайтеся якнайдалі від опроміненої руїни Гномреґану."}},fp="18,236,21.465.0,31.153.0,26.116.0,64.168.0"}
P.entries["item:glyphic-scroll"] = {n="Гліфічний Сувій",s="Гліфічний Сувій — виклик, що його вручають щойно піднятим магам Відступників у Похоронному Подзвоні. Скріплений печаткою Ізабелли, місцевої наставниці таємної магії, він кличе чародіїв-початківців до оскверненої церкви — відточувати своє ремесло в нежитті.",h="Гліфічний Сувій — виклик, що його вручають щойно піднятим магам Відступників у Похоронному Подзвоні.",kw={"гліфічний сувій","маг","ізабелла","похоронний подзвін","таємна магія","відступники"},ang={["class:Mage"]="Сувій — перший офіційний виклик, який одержує маг Відступників; він наголошує, що нежиття не звільняє чародія від згубної залежності від таємної магії.",["race:Undead"]="Для Відступників повернуте знання таємної магії — не просто наука: це неодмінна зброя, щоб відстояти свій суверенітет і проти Погибелі, і проти живих ворогів."},sec={{t="Виклик із церкви",b="Коли щойно пробуджений маг Відступників повертається з проріджування безтямної Погибелі на цвинтарі Похоронного Подзвону, на нього чекає це запечатане послання. Написаний під знаком Ізабелли, місцевої наставниці магів, сувій кличе одержувача до зруйнованого парафіяльного святилища. Для щойно піднятих магів це перше знайомство з дисципліною таємної магії під стягом Відступників — нагадування, що смерть, може, і звільнила їх від смертної слабкості, та згубні спокуси магічної сили лишаються такими ж невідступними, як і завжди."}},fp="14,233,25.552.0,27.247.0,29.195.0,51.285.0"}
P.entries["item:glyphic-tablet"] = {n="Гліфічна Табличка",s="Гліфічна Табличка — плитка з письменами, яку отримують тролі-маги Темного Списа, починаючи випробування в Дуроторі. Передана через наглядача Ґорнека, вона спрямовує чародіїв-початківців по науку до тролиці-наставниці магів Май'а.",h="Гліфічна Табличка — плитка з письменами, яку отримують тролі-маги Темного Списа, починаючи випробування в...",kw={"гліфічна табличка","маг","май'а","ґорнек","темний спис","долина випробувань","магія"},ang={["class:Mage"]="Табличка знаменує початок вашої магічної науки серед Темного Списа і несе нагадування від Май'а: згубна принадність магії — ваша найбільша небезпека.",["race:Troll"]="Як єдиний народ у Долині Випробувань, що практикує чародійство, маги Темного Списа отримують цю табличку, щоб почати свій особливий шлях поряд із традиційними шаманськими й воїнськими."},sec={{t="Перший поклик мага",b="У Долині Випробувань новим посвячуваним Темного Списа, що виявляють хист до таємної сили, вручають Гліфічну Табличку. Ґорнек передає її, поки молоді новобранці виконують перші доручення серед червоних каньйонів; табличка містить запрошення від Май'а — досвідченої тролиці-маги, що стоїть біля Лігва. Для Темного Списа, чиї магічні традиції далекі від учених академій людей чи високих ельфів, табличка — офіційний заклик до дисципліни. На зустрічі Май'а дає і магічну настанову, і суворе застереження: сира магія розбещує, обманює і значно небезпечніша для розуму чародія, ніж будь-який ворожий солдат."}},fp="14,246,22.655.0,42.171.0,29.123.0,46.233.0,42.124.0"}
P.entries["item:gnomish-tools"] = {n="Гномські Інструменти",s="Гномські Інструменти — хитромудре механічне знаряддя, підняте з потоплених бойових кораблів флоту Великого адмірала Дейліна Праудмура біля узбережжя Дуротару. Орда шукає ці врятовані пристрої, щоб вивчити інженерію Альянсу й обернути технологічну перевагу ворогів собі на користь.",h="Гномські Інструменти — хитромудре механічне знаряддя, підняте з потоплених бойових кораблів флоту Великого...",kw={"гномські інструменти","праудмур","флот","дріботливе узбережжя","ґар'ток","інженерія","дуротар"},ang={["faction:Horde"]="Повернення втраченого обладнання Альянсу дає Орді змогу вивчити ворожі конструкції, розібрати чужі механізми й захиститися від майбутніх морських вторгнень.",["profession:Engineering"]="Ці набори показують точне, хитромудре ремесло майстрів Альянсу і дають цінне розуміння годинникових механізмів та мініатюризації."},sec={{t="Потоплена здобич",b="Коли Великий адмірал Дейлін Праудмур привів сили Кул Тірасу та Альянсу до берегів Дуротару, його флот віз величезні запаси сучасного обладнання, зокрема вигадливе знаряддя, виготовлене гномськими союзниками. Після знищення флоту Праудмура вздовж Дріботливого Узбережжя, на схід від Фортеці Тіраґард, ці тонкі механічні набори пішли під воду. Нині водонепроникні скриньки з інструментами розкидані серед гнилих колод і вкритих черепашками корпусів на мілководді."},{t="Очі в Оргріммарі",b="Ґар'Ток, наглядач Гострого Пагорба, доручив розвідникам Орди дістати ці інструменти з водної могили флоту Праудмура. Орки визнають, що люди й гноми володіють передовою технічною майстерністю, надто в облогових машинах, кораблебудуванні та годинниковій механіці. Збираючи ці набори й відправляючи їх караваном до ремісників і вчених Оргріммара, Орда має намір розібрати пристрої Альянсу, навчитися протистояти його бойовим машинам і пристосувати чужі винаходи до власного виживання."}},fp="13,293,14.485.0,17.521.0,53.259.0,36.280.0,26.201.0"}
P.entries["item:gold-dust"] = {n="Золотий Пил",s="Золотий Пил — дрібні крупинки дорогоцінного металу, які просіюють і накопичують кобольди, що заполонили копальні Лісу Елвінн. Поки звичайні рудокопи шукають цілі жили руди, тутешні ділки платять добру монету кожному, хто готовий відібрати ці зібрані крупинки в шкідників.",h="Золотий Пил — дрібні крупинки дорогоцінного металу, які просіюють і накопичують кобольди, що заполонили...",kw={"золотий пил","кобольди","ремі двічі","ґолдшир","копальня","чорний ринок"},ang={["class:Rogue"]="Торгівля неочищеним, невідстежуваним пилом із такими тіньовими постатями, як Ремі «Двічі», — практичний урок того, як підпілля відмиває сире багатство подалі від очей магістратів Стормвінда.",["profession:Mining"]="Поки рудокопи шукають суцільні жили міді й олова з киркою та лотком, кобольдовий пил показує, що підземні ходи Елвінну ховають багатші поклади, ніж кажуть звичайні обстеження."},sec={{t="Кисет, повний крихт",b="Під землею Лісу Елвінн кобольди шкребуть підземні тунелі копалень Фарґодіп і Яшмової. Замість як слід очищати знайдену руду, щуроподібні створіння часто ховають грубий золотий пил просто в кишенях і кисетах. Ці дрібні блискучі крупинки — плід марудної підземної праці, яку поважні гірничі товариства легко не помічають, зате палко жадають тутешні рознощики й скупники краденого, що хочуть тихо нажитися, не сплачуючи офіційних плавильних мит."},{t="Чорний ринок Ґолдширу",b="У містечку Ґолдшир Ремі «Двічі» завзято випитує в подорожніх здобутий золотий пил. Заявляючи, що пропонує найкращу ціну в місті, Ремі від імені своїх неназваних спільників міняє монету й підозрілі жетони на кисети з сирим пилом. Використовуючи заповзятливих найманців, щоб вирвати золото просто з кобольдових лап, тіньові посередники тримають руки чистими й водночас здобувають невідстежуване багатство просто під носом у варти Стормвінда."}},fp="9,268,22.524.0,24.472.1,31.204.0,53.146.0,36.183.0,44.222.0"}
P.entries["item:grape-manifest"] = {n="Опис Винограду",s="Опис Винограду — рукописна відомість, що обліковує врожай із виноградника Міллі Осворт у Долині Нортширу. Вона засвідчує повернення свіжих плодів після того, як тутешні розбійники захопили поля, і призначена для підвалів Абатства Нортшира.",h="Опис Винограду — рукописна відомість, що обліковує врожай із виноградника Міллі Осворт у Долині Нортширу.",kw={"опис винограду","міллі осворт","брат нілз","абатство нортшира","урожай","виноградник"},ang={["profession:Cooking"]="Для кухарів опис утілює тонку рівновагу між урожаєм полів і коморами абатства, показуючи, як місцеві інгредієнти живлять цілу чернечу громаду.",["race:Human"]="Документ висвітлює ранні труднощі серця Стормвінда, де навіть чернече життя й простий урожай потребують збройного захисту від мандрівних розбійників."},sec={{t="Запис про врожай",b="Абатство Нортшира здавна живиться з місцевого господарства, зокрема з пишних виноградників, які доглядають тутешні фермери на кшталт Міллі Осворт. Коли бандити Дефіас прийшли в долину й захопили врожай, запаси свіжих плодів і сировини для бродіння в абатстві опинилися під загрозою. Опис Винограду слугує офіційним підтвердженням, що ящики повернуто з полів. Він вказує кількість урятованого винограду, щоб інтенданти абатства могли звести свої запаси й підготувати бочки для бродіння."},{t="Келар абатства",b="Брат Нілз відповідає за харчі й напої Нортширу, маючи особливу слабкість до куштування абатського вина у високій тиші дзвіниці. Для нього отримати опис — не просто паперова робота: він гарантує, що ченці й гостьові новобранці не страждатимуть від спраги. Для побожних братів абатства кожен урятований кошик — водночас і господарська перемога, і тихе благословення Святого Світла."}},fp="14,243,23.519.0,20.436.0,27.185.0,26.154.0,30.192.0,43.166.0"}
P.entries["item:gregor-s-remains"] = {n="Рештки Грегора",s="Рештки Грегора — кістки, здобуті з поневоленого Погибеллю Ґреґора Аґаманда. Колись він належав до найзаможнішої династії Галявин Тірісфалю, а тепер його останків прагне колишній робітник млина, що жадає звести давній рахунок з-за могили.",h="Рештки Грегора — кістки, здобуті з поневоленого Погибеллю Ґреґора Аґаманда.",kw={"рештки грегора","ґреґор аґаманд","млини аґаманда","коулмен фартінґ","помста","погибель"},ang={["faction:Horde"]="Очищення Млинів Аґаманда — прямий удар по недобитках Погибелі, що загрожують безпеці Галявин Тірісфалю.",["race:Undead"]="Трагедія Аґамандів віддзеркалює долю багатьох Відступників: простий люд, зраджений гордістю знаті й покинутий на жахіття Чуми."},sec={{t="Спадщина руїни",b="До Третьої війни родина Аґамандів мала величезне багатство й широкі землі на півночі Галявин Тірісфалю. Коли Погибель вторглася до Лордерону, патріархи обрали гордість замість утечі: укріпили родинні млини й переконали вірних робітників стати на відчайдушну оборону проти нежиті. Оборона провалилася цілковито. Маєток захопили, а тих, хто вистояв на місці, вирізали й підняли в нежитті. Ґреґор Аґаманд став ще одним безтямним рабом, яким володіє Король-Ліч, і тепер никає тими самими млинами, якими колись правила його родина."},{t="Ціна помсти",b="Для вцілілих, що вирвалися з лабет Короля-Ліча й приєдналися до Відступників, пам'ять про ту фатальну оборону лишається гіркою раною. Коулмен Фартінґ, колишній робітник млина, що тепер перебуває у Бріллі, звинувачує пиху Аґамандів у тому, що його душа ув'язнена у вічному гнитті. Зібрати рештки Ґреґора означає для Фартінґа міру особистої відплати — закрити розділ про господаря, який повів свій дім просто в прокляття."}},fp="16,246,16.557.0,22.424.0,23.299.0,48.276.0,33.135.0,38.148.0"}
P.entries["item:grelin-s-report"] = {n="Звіт Греліна",s="Звіт Греліна — депеша, яку Ґрелін Вайтбірд склав про становище з тролями Морозогривами в Долині Холодного Хребта. Довірена шукачеві пригод, а не недосвідченому учневі, вона є офіційною ланкою між розвідниками, що стережуть Анвілмар, і Сеніром Вайтбірдим, який служить у Хараносі.",h="Звіт Греліна — депеша, яку Ґрелін Вайтбірд склав про становище з тролями Морозогривами в Долині Холодного...",kw={"звіт греліна","ґрелін вайтбірд","сенір вайтбірдий","депеша","морозогриви","горянин талос","харанос","перевал холодного кряжа"},ang={["race:Dwarf"]="Пронести цей звіт — для дворфа перехід від безпечних навчальних угідь Холодного Хребта до оборони серця Дун Мороґу й служби Айронфорджу.",["race:Gnome"]="Доставити послання Ґреліна — нагода для гномів-біженців довести свою вартість дворфійським горянам, долаючи спільні гірські перевали Дун Мороґу."},sec={{t="Депеша повз трогів",b="Написаний після спостережень за тролями Морозогривами в Долині Холодного Хребта, Звіт Греліна робить висновок: великої загрози вони не становлять, і з ними впораються горяни, що вже стоять там, та найманці, яким заплатять із коштів Сенату. Замість довіряти такі важливі відомості своєму незграбному учневі, Ґрелін залучає здібного мандрівника, щоб той проніс документ крізь кишачий трогами Перевал Холодного Кряжа. Папір править за офіційну перепустку крізь заслін Горянина Талоса, доводячи, що власник прямує в нагальній справі на широкі засніжені простори Дун Мороґу."},{t="Переполох у Хараносі",b="Доставлений Сеніру Вайтбірдому до Ґуральні Тандербрю в Хараносі, звіт містить важливі польові відомості, призначені для Айронфорджа. Сенір з веселою покорою зауважує, що брат щедро розкидався по тексту іменем Короля Маґні Бронзбірда. Ґрелін посилається на дозвіл Короля на свої дії, і Сенір очікує, що таке звернення до королівської влади збурить декого в Сенаті Айронфорджа."}},fp="15,291,26.564.0,29.414.0,39.279.0,36.253.0,57.230.0,50.280.0"}
P.entries["item:grelin-whitebeard-s-journal"] = {n="Щоденник Греліна Вайтбірда",s="Щоденник Греліна Вайтбірда — особистий польовий записник, який дворф-розвідник Ґрелін Вайтбірд вів у Долині Холодного Хребта. Щоденник із важливими нотатками про діяльність місцевих тролів Морозогривів викрав вождь Ґрік'нір Холодний і затягнув до тролячої печери в Долині Холодного Хребта.",h="Щоденник Греліна Вайтбірда — особистий польовий записник, який дворф-розвідник Ґрелін Вайтбірд вів у Долині...",kw={"щоденник","ґрелін вайтбірд","ґрік'нір холодний","тролі","морозогриви","троляча печера","долина холодного хребта"},ang={["race:Dwarf"]="Повернути цей щоденник — означає вберегти важливі дворфійські відомості про загрозу Морозогривів, що підступає до самих воріт навчальних угідь Айронфорджа."},sec={{t="Записник розвідника",b="Спостерігаючи за агресивними пересуваннями тролів Морозогривів біля Долини Холодного Хребта, Ґрелін Вайтбірд старанно занотовував свої висновки в цьому записнику в шкіряній палітурці. У ньому — сирі польові спостереження про силу, устрій і рівень загрози від тутешніх зимових тролів. Але під час сутички чи засідки щоденник вихопив Ґрік'нір Холодний — троль-ватажок із рясним розписом на тілі, — і Ґреліну довелося залучити подорожніх шукачів пригод, щоб ті спустилися до тролячої печери й відбили записник, перш ніж він зможе завершити звіт."},{t="Депеша для Сеніра",b="Коли щоденник вирвано з лап Ґрік'ніра, нотатки в цьому пошарпаному записнику дають Ґреліну достатньо впевненості, щоб визнати тролячу загрозу в Долині Холодного Хребта тимчасово стриманою. Спираючись на повернуті записи, Ґрелін завершує письмову депешу про повстання Морозогривів, яку відтак запечатують і довіряють кур'єрам, що прямують до його брата Сеніра Вайтбірдого, який служить далі в Дун Мороґу."}},fp="27,291,16.571.0,17.417.1,38.153.0,31.175.0,44.195.1,43.195.0"}
P.entries["item:gunther-s-spellbook"] = {n="Книга Заклять Ґюнтера",s="Книга Заклять Ґюнтера — особистий том таємної магії, що належить Ґунтерові Арканусу, колишньому чарівникові Кірін-Тору, який мешкає на Галявинах Тірісфалю. Наділена чарами Бетора Айсшарда, книга слугує Ґунтерові доказом, що іншим магам також вдалося вирватися з-під влади Короля-Ліча.",h="Книга Заклять Ґюнтера — особистий том таємної магії, що належить Ґунтерові Арканусу, колишньому чарівникові...",kw={"книга заклять ґюнтера","ґунтер арканус","бетор айсшард","кірін-тор","даларан","маг"},ang={["class:Mage"]="Для тих, хто практикує таємну магію, том уособлює спільне даларанське коріння, що пов'язує нинішній магічний провід Відступників з бунтівними чародіями в глушині.",["race:Undead"]="Зачарована книга підкреслює невпинні зусилля Відступників залучати могутню незалежну нежить, що сама вирвалася з-під влади Короля-Ліча."},sec={{t="Знак давнього братства",b="До Третьої війни Ґунтер Арканус вивчав таємні мистецтва в Даларані разом із Бетором Айсшардом і Тулом Рейвенкловом як члени Кірін-Тору. Коли Чума Нежиті прокотилася Лордероном, Ґунтер загинув і був піднятий у нежитті, та зрештою зумів вирвати свій розум з-під влади Погибелі. Вважаючи себе самотнім і невпинно переслідуваним агентами, яких шле Король-Ліч, він лишався глибоко ворожим до чужинців. Коли том здобули, Бетор Айсшард наклав на його сторінки таємні чари — свідомий магічний підпис, що дає Ґунтерові змогу розпізнати присутність Бетора й зрозуміти: він не єдиний маг, який має вільну волю."}},fp="19,288,22.651.1,24.124.0,37.199.0,52.175.0,43.167.0"}
P.entries["item:gyromechanic-gear"] = {n="Гіромеханічна Деталь",s="Гіромеханічна Деталь — урятована частинка точної інженерії, знайдена серед опадів за межами Гномреґану. Гномські винахідники в Хараносі шукають саме такі деталі, щоб зібрати експериментальний пристрій, здатний повернути назад мутації прокажених гномів.",h="Гіромеханічна Деталь — урятована частинка точної інженерії, знайдена серед опадів за межами Гномреґану.",kw={"гіромеханічна деталь","рекомбобулятор","прокажені гноми","оззі тоґлвольт","раззл спрайспрокет","гномреґан","інженерія"},ang={["profession:Engineering"]="Гномська точна інженерія славиться надзвичайною філігранністю й покладається на гіромеханічні компоненти з тісними допусками, щоб регулювати нестабільну дослідну техніку.",["race:Gnome"]="Кожна врятована деталь наближає гномських майстрів на крок до можливого порятунку їхніх радіоактивних братів, що блукають снігами біля Гномреґану."},sec={{t="Деталі для рекомбобуляції",b="Коли Гномреґан затопили радіацією, щоб вичистити навалу трогів, вона обернула величезну частину вцілілих гномів на божевільних опромінених прокажених гномів. Не бажаючи кидати своїх спотворених родичів, винахідники Оззі Тоґлвольт і Раззл Спрайспрокет узялися креслити схеми Рекомбобулятора — амбітного пристрою, покликаного скасувати жахливі наслідки радіації. Для прототипу потрібні точні механізми, здатні витримати нестабільний внутрішній тиск, зокрема Гіромеханічні Деталі та доповняльні Шестерні Рестабілізації. Оскільки з падінням столиці місцеве виробництво зупинилося, дослідники змушені добувати ці тендітні деталі просто з ворожих прокажених гномів, що блукають Дун Мороґом."}},fp="17,247,30.741.0,37.221.0,31.89.0,50.284.0,40.266.0"}
P.entries["item:hallowed-letter"] = {n="Освячений Лист",s="Освячений Лист — офіційний виклик зі знаком Жриці Анетти, який вручають перспективним молодим жерцям у Долині Нортширу. Він кличе носія до Абатства Нортшира, щоб розпочати справжнє вивчення Святого Світла й навчання.",h="Освячений Лист — офіційний виклик зі знаком Жриці Анетти, який вручають перспективним молодим жерцям у Долині...",kw={"освячений лист","жриця анетта","жрець","святе світло","абатство нортшира","виклик"},ang={["class:Priest"]="Це послання знаменує ваше офіційне визнання знаряддям Святого Світла й установлює ваш зв'язок із наставниками Абатства Нортшира.",["race:Human"]="Люди-жерці служать у Долині Нортширу ще з часів до Першої війни; отримати цей лист — означає продовжити цю родову традицію святого обов'язку."},sec={{t="Поклик віри",b="Запечатаний особистим знаком Жриці Анетти, Освячений Лист вручають жерцям-початківцям після їхніх перших випробувань проти таборів кобольдів у Долині Нортширу. Анетта бачить у новачкові внутрішню іскру Святого Світла й закликає його не зволікати, а ступити в мури абатства, щоб офіційно присвятити себе служінню. Поки темні сили досі никають по Азероту після Третьої війни, жрецтво завзято збирає тих, хто здатен зцілювати, захищати й давати духовну настанову державі, яка силкується втримати лад."}},fp="15,234,15.567.0,28.160.0,21.147.0,58.242.0,42.185.0"}
P.entries["item:hallowed-rune"] = {n="Освячена Руна",s="Освячена Руна — камінь із написом, який вручають жерцям-новачкам, що розпочинають навчання в Долині Холодного Хребта. Надіслана дворфійським наставником жерців Бранстоком Калдером, вона кличе майбутніх носіїв Святого Світла до Анвілмара, щоб розпочати офіційне навчання.",h="Освячена Руна — камінь із написом, який вручають жерцям-новачкам, що розпочинають навчання в Долині Холодного...",kw={"освячена руна","жрець","брансток калдер","святе світло","анвілмар","долина холодного хребта","троги"},ang={["class:Priest"]="Освячена Руна знаменує офіційний початок наставництва жерця в Святому Світлі в Долині Холодного Хребта.",["race:Dwarf"]="Дворфійські жерці поєднують побожну шану до Світла з непохитним обов'язком перед Айронфорджем, стаючи на захист гірської батьківщини від трогів."},sec={{t="Поклик до Світла",b="Коли жрець-початківець виявляє рішучість, допомагаючи горянам і захисникам Долини Холодного Хребта, Брансток Калдер надсилає Освячену Руну. Камінь, укритий науками Святого Світла, — водночас і представлення, і запрошення. Дворфійським новачкам велять облишити дрібні сутички в снігу й з'явитися до Анвілмара, де Брансток готує їх гоїти рани й спрямовувати святу силу проти навали трогів, що загрожує Дун Мороґу."}},fp="13,255,22.484.0,26.210.0,35.205.0,51.187.0,58.173.0"}
P.entries["item:hallowed-scroll"] = {n="Освячений Сувій",s="Освячений Сувій — офіційний виклик, що його вручають щойно пробудженим жерцям Відступників у Похоронному Подзвоні. Скріплений особистою печаткою Темного Клірика Дюстена, він скеровує новачків до зруйнованої каплиці — розпочати переосмислення віри, сили волі й тіні.",h="Освячений Сувій — офіційний виклик, що його вручають щойно пробудженим жерцям Відступників у Похоронному...",kw={"освячений сувій","жрець","темний клірик дюстен","похоронний подзвін","тінь","сила волі"},ang={["class:Priest"]="Цей пергамент знаменує остаточний розрив із традиційною людською вірою: він скеровує жерців Відступників до самовладної переконаності й тіньових мистецтв, що їх практикує Культ Забутої Тіні.",["race:Undead"]="Одержати цей виклик — відчути нагальну, прагматичну мобілізацію Похоронного Подзвону, що дбає про швидкий вишкіл щойно пробуджених мерців і їхнє вливання до сил Сильвани."},sec={{t="Виклик до безвірних",b="Щойно підняті жерці Відступників виявляють, що їхній зв'язок зі світом різко змінився. Вручений серед безнастанного хаосу відвоювання Похоронного Подзвону, Освячений Сувій скеровує чародіїв-початківців шукати настанов у зруйнованій каплиці поселення. Позначений печаткою Темного Клірика Дюстена, пергамент слугує і знайомством, і наказом з'явитися на офіційний вишкіл, посвячуючи жерця в прагматичну філософію, що визначає жрецтво Відступників."},{t="Шлях самодостатності",b="Відгукнувшись на виклик сувою, жерці одразу позбуваються старих догм. Дюстен дає зрозуміти, що традиційні милиці — шанування Святого Світла, духів предків чи угоди з демонами — більше не служать нежиті. Натомість сувій відкриває внутрішню дисципліну, вкорінену суто в особистій силі волі. Учення, яке започатковує цей пергамент, наголошує на виживанні й пануванні через чисту переконаність, обертаючи релігійну відданість на знаряддя самовизначення й влади."}},fp="15,253,26.483.0,25.517.0,28.221.0,29.126.0,66.291.0"}
P.entries["item:hallowed-sigil"] = {n="Освячений Сигіл",s="Освячений Сигіл — вирізьблений знак нічних ельфів, який носять молоді посвячені в Тінедолі. Надісланий наставницею жерців Шандою, він слугує офіційним викликом, що спрямовує майбутніх служителів Елуни до прадавнього віття Алдрассила.",h="Освячений Сигіл — вирізьблений знак нічних ельфів, який носять молоді посвячені в Тінедолі.",kw={"освячений сигіл","жрець","шанда","сестринство елуни","тінедол","алдрассил","елуна"},ang={["class:Priest"]="Для жерців — нічних ельфів Освячений Сигіл — найперший виклик до офіційного навчання під проводом Сестринства Елуни.",["race:NightElf"]="Сигіл позначає початок служіння калдорейського подвижника в час, коли мандрівники Альянсу лише починають прибувати на віття Тельдрассила."},sec={{t="Поклик до жрецтва",b="Молоді жерці — нічні ельфи, ступаючи під священне шатро Тінедолу, часто дістають Освячений Сигіл від лісового посланця. Оздоблений святими знаками, він слугує особистою грамотою від Шанди, тутешньої наставниці жерців в Алдрассилі. Носити й читати сигіл означає піднятися до високої порожнини Алдрассила, офіційно познайомитися з Сестринством Елуни й розпочати духовне служіння калдореям у час, коли на Тельдрассил прибувають нові мандрівники."}},fp="14,237,27.493.0,27.173.0,29.131.0,30.203.0"}
P.entries["item:hallowed-tablet"] = {n="Освячена Табличка",s="Освячена Табличка — послання з письменами, яке отримують молоді тролі-жерці Темного Списа, що навчаються в Долині Випробувань. Надіслана духовним старійшиною Кен'джаєм, вона кличе новачків розшукати його й почати вчитися єднання з духами.",h="Освячена Табличка — послання з письменами, яке отримують молоді тролі-жерці Темного Списа, що навчаються в...",kw={"освячена табличка","жрець","кен'джай","ґорнек","темний спис","долина випробувань","духи"},ang={["class:Priest"]="Табличка знаменує початок офіційного жрецького вишколу в Дуроторі і встановлює ваш зв'язок із наставником класу Кен'джаєм.",["race:Troll"]="Для Темного Списа жрецтво — тісне єднання з духами й лоа, тож поклик, накреслений на табличці, — запрошення до духовних традицій предків."},sec={{t="Поклик від духів",b="Коли здібний троль-жрець робить перші кроки в суворих багряних каньйонах Долини Випробувань, Ґорнек вручає йому Освячену Табличку. Це не казенний припис, а особисте запрошення від Кен'джая — тутешнього наставника жерців, що мешкає біля Лігва. Кен'джай тлумачить знаки й шепоти духів і відчуває, коли до Дуротару прибувають молоді тролі Темного Списа з духовним потенціалом. Табличка велить посвячуваному прочитати її слова й з'явитися по настанови, як належно спрямовувати духовну владу."}},fp="15,241,26.555.0,28.175.0,20.166.0,41.196.0"}
P.entries["item:heartswood-core"] = {n="Осердя Серцедерева",s="Осердя Серцедерева — зачарований ритуальний осередок, вирізьблений із деревини прадавнього дерева. Його дає Ґакін Зв'язувач Темряви в Стормвінді, і воно спрямовує магію, потрібну, щоб пронизати Викривлений Нижній Світ й прикликати сукуба в таємне коло прикликання.",h="Осердя Серцедерева — зачарований ритуальний осередок, вирізьблений із деревини прадавнього дерева.",kw={"осердя серцедерева","ґакін","сукуб","чорнокнижник","прикликання","зарізане ягня"},ang={["class:Warlock"]="Осердя Серцедерева — необхідна навчальна реліквія для чорнокнижників Альянсу: знаряддя, через яке вони прикликають і підкоряють свого першого сукуба."},sec={{t="Осередок для Безодні",b="У темних криптах під таверною «Зарізане Ягня» у Кварталі магів Стормвінда чорнокнижники чинять обряди далеко від цікавих очей міської варти. Осердя Серцедерева — необхідний таємний провідник для початку ритуалу прив'язування. Виготовлене зі здобутого серцедерева, осердя містить досить залишкового магічного відлуння, щоб пронизати завісу між світами. Зосередивши свої темні мистецтва через деревину в освяченому колі прикликання, новачок може розірвати прохід до Викривленого Нижнього Світу й примусити сукуба перетнути межу між планами."},{t="Випробування прив'язування",b="Прикликати демона — лише половина боротьби; щоб ним керувати, треба довести цілковиту перевагу над його хитрою й спокусливою натурою. Ґакін довіряє Осердя Серцедерева перспективним практикам саме для того, щоб вони зустріли прикликаного демона в бою. Сукуби полюють на слабкість і легко долають кволий розум, тож ця зустріч — смертельно небезпечний обряд посвяти. Лише впокоривши нечисть і повернувши вичерпане осердя Ґакінові, майбутній чорнокнижник доводить, що його воля досить міцна, щоб назавжди прив'язати слугу."}},fp="15,258,22.573.0,20.527.1,37.232.0,33.169.0,28.151.0,42.241.0"}
P.entries["item:hildelve-s-journal"] = {n="Щоденник Гільдельве",s="Щоденник Гільдельве — останній запис дворфійського пілота Гільдельве, знайдений біля його останків у крижаній пустці Дун Мороґу. Його закривавлені сторінки оповідають про фатальну зустріч із лютим ведмедем і передають передсмертне бажання помсти.",h="Щоденник Гільдельве — останній запис дворфійського пілота Гільдельве, знайдений біля його останків у крижаній...",kw={"щоденник гільдельве","гільдельве","дробкіготь","пілот гаммерфут","облогова бригада","ведмідь","помста","дун мороґ"},ang={["faction:Alliance"]="Повернення особистих речей полеглих вояків, як-от Гільдельве, зміцнює зв'язок між Альянсом та Облоговою Бригадою Айронфорджа.",["race:Dwarf"]="Щоденник ушановує незламний дух дворфійських пілотів, які кидають виклик морозу й диким звірам, щоб утримати висоти Каз Модану."},sec={{t="Останні слова пілота",b="Коли паровий танк зламався, дворфійський пілот Гільдельве лишив свого напарника Гаммерфута з машинами й сам вирушив у засніжені скелі Дун Мороґу на пошуки чуток про хіронову руду. Як свідчать записи в його щоденнику, його кілька днів вистежував, а потім підстеріг велетенський крижанокігтий ведмідь на ім'я Дробкіготь. Хоча Гільдельве бився хоробро й зумів відігнати звіра, він лишився тяжко пошматованим і безпорадним на лютому морозі. Щоденник описує його болісні останні години й завершується єдиним ясним проханням, перш ніж хижак повернувся його добити: хай той, хто знайде його тіло, помститься за його смерть, вистеживши Дробкігтя."},{t="Повернення до Облогової Бригади",b="Знайдений щоденник — гірке завершення історії для товариша Гільдельве, Пілота Гаммерфута, що стоїть біля Застави Північної Брами на сході Дун Мороґу. Як член Облогової Бригади Айронфорджа, Гаммерфут боявся найгіршого, коли Гільдельве не повернувся з пошуків руди. Передати йому щоденник разом із відрубаною лапою звіра — доказ того, що дух Гільдельве упокоївся, а його останню волю виконано."}},fp="18,246,21.661.0,27.416.1,17.239.0,18.201.0,42.203.0,42.190.0"}
P.entries["item:huge-gnoll-claw"] = {n="Велетенський Кіготь Ґнола",s="Велетенський Кіготь Ґнола — безпомилковий трофей, здобутий у Гоґґера, велетенського гнола, що нишпорить південно-західним Лісом Елвінн. Значно більший за будь-який звичайний гнолячий пазур, він слугує офіційним доказом загибелі, якого вимагає влада Стормвінда в Ґолдширі.",h="Велетенський Кіготь Ґнола — безпомилковий трофей, здобутий у Гоґґера, велетенського гнола, що нишпорить...",kw={"велетенський кіготь","гоґґер","гнол","винагорода","маршал дуґан","ґолдшир"},ang={["class:Hunter"]="Здобути кіготь такого велетенського хижака — означає показати найвищу майстерність вистежування й полювання на звіра, що раз у раз долав озброєні загони.",["faction:Alliance"]="Здобутий кіготь звільняє серце королівства від його найсумнозвіснішого лісового жаху й доводить вашу доблесть Маршалові Дуґану та змученому гарнізону Ґолдширу."},sec={{t="Доказ мисливця за головами",b="Місяцями здоровань Гоґґер тероризував південні ліси Узлісся, відбиваючись від патрулів і зриваючи кожну спробу тутешнього гарнізону загнати чи приборкати його. Поступаючись силою й розтягнуте по всьому Елвінну, військо Стормвінда оголосило відкриту винагороду за голову тварюки. Маршал Дуґан у Ґолдширі вимагає незаперечного доказу, перш ніж видати винагороду, і величезний кіготь здорованя дає безсумнівне підтвердження, що жах лісів нарешті впав."}},fp="15,254,21.493.0,37.161.0,31.148.0,56.224.0,36.152.0"}
P.entries["item:hyacinth-mushroom"] = {n="Гіацинтовий Гриб",s="Гіацинтові Гриби — своєрідні гриби, що проростають біля коріння дерев по всьому Тінедолу на Тельдрассилі. Тутешні травники — нічні ельфи цінують їх за лікувальні властивості, а ще вони — улюблена пожива й здобич бешкетливих ґреллів і ґреллят.",h="Гіацинтові Гриби — своєрідні гриби, що проростають біля коріння дерев по всьому Тінедолу на Тельдрассилі.",kw={"гіацинтовий гриб","гриби","тінедол","ґрелли","протиотрута","травництво","алдрассил"},ang={["profession:Herbalism"]="Хоч збирання цих грибів у Тінедолі не вимагає формального навчання, будь-який травник-початківець оцінить їхню роль у знешкодженні лютих лісових отрут.",["race:NightElf"]="Для молодих нічних ельфів, що навчаються в Тінедолі, збирання дикої рослинності на кшталт Гіацинтових Грибів — ранній урок користування дарами природи задля підтримки своїх родичів."},sec={{t="Рослинність Тінедолу",b="Гіацинтові Гриби рясно ростуть по всьому Тінедолу, буяючи у вологій тіні біля підніжжя прадавніх курганів, замшілого каміння й розлогого коріння Алдрассила. Корисні в лісових ліках, вони привернули й увагу споганених ґреллів, що часто їх збирають про запас. Коли молодих вартових чи учнів — нічних ельфів уражає тутешня отруйна фауна, як-от павуки Печери Тіньової Нитки, ці гриби стають основним складником заспокійливих напоїв і протиотрут, що їх готують лісові цілителі."}},fp="17,271,19.525.0,37.198.0,33.161.0,42.154.0,44.184.0"}
P.entries["item:inscribed-bark"] = {n="Гравірована Кора",s="Гравірована Кора — живий пергамент, який прадавнє Дерево Оракула довіряє, щоб донести звістку про стан Тельдрассила Архідруїдові Фандралу Стаґгелму. Це офіційний звіт про віття Світового Дерева й незгасні загрози, що тривожать його ліси.",h="Гравірована Кора — живий пергамент, який прадавнє Дерево Оракула довіряє, щоб донести звістку про стан...",kw={"гравірована кора","дерево оракула","фандрал стаґгелм","послання","коло кенарія","дарнасус","тельдрассил"},ang={["class:Druid"]="Друїди впізнають у цій гравірованій деревині нагальне послання від прадавнього союзника, що підкреслює хистку рівновагу й тривалі недуги молодого Світового Дерева.",["race:NightElf"]="Для калдореїв послання на корі прадавніх дерев уособлюють священний зв'язок між природою та її охоронцями, з'єднуючи дикі гаї з мармуровими терасами Дарнасуса."},sec={{t="Послання від Оракула",b="Вирізана зі священної деревини Дерева Оракула, ця гравірована кора — пряме послання від прадавнього охоронця проводу Кола Кенарія в Дарнасусі. Коли шукачі пригод приборкують гарпій, що зазіхають на галявини, Дерево Оракула довіряє їм цей знак, не бажаючи ризикувати звичайними гінцями на споганених стежках віття. Вирізьблене послання сповіщає Архідруїда Фандрала Стаґгелма і про нещодавні перемоги, і про глибшу, тривожну пошесть, що й далі тримає Тельдрассил."}},fp="14,252,25.522.0,23.172.0,31.233.0,58.264.1"}
P.entries["item:invisibility-liquor"] = {n="Лікер Невидимості",s="Лікер Невидимості — міцний, алхімічно насичений напій, зварений з рідкісних листів кристалевої ламінарії, знайдених у Лісі Елвінн. Створений, щоб на коротку мить зробити того, хто його вип'є, невидимим, він стає ключем таємної змови, яка дозволяє двом молодим закоханим обійти ворожнечу своїх родин.",h="Лікер Невидимості — міцний, алхімічно насичений напій, зварений з рідкісних листів кристалевої ламінарії...",kw={"лікер невидимості","алхімія","томмі джо","мейбелл маклур","кристалева ламінарія","закохані"},ang={["class:Mage"]="Поки чарівники Кірін-Тору роками відточують ілюзії й закляття невидимості, мешканці Елвінну домагаються грубого наслідування за допомогою перебродженого спирту й намоклої ламінарії.",["race:Human"]="Цей напій показує, до яких безглуздих крайнощів доходить гірка сільська ворожнеча в Лісі Елвінн між родами Стоунфілдів і Маклурів."},sec={{t="Зілля для нещасливих закоханих",b="Тривала ворожнеча між Стоунфілдами й Маклурами робить мирні стосунки між їхніми домами майже неможливими. Коли молодий Томмі Джо Стоунфілд прагне зустрітися з Мейбелл Маклур подалі від пильних очей рідні, звичайної потайності замало. Лікер Невидимості дає дивовижний вихід: хмільний напій, що згинає зір довкола того, хто його випив, даруючи рівно стільки непомітності, щоб непоміченим перетнути спірні поля."},{t="Незвична алхімія Елвінну",b="Зварений з листів кристалевої ламінарії, здобутих у тутешніх водах, де кишать мурлоки, цей напій поєднує простий самогонний промисел із сирими магічними реагентами. Хоч трунок незаконний і, можливо, небезпечний для вживання, він виявляється достатньо сильним, щоб Мейбелл зникла з очей, щойно він торкнеться її губ, і вона змогла вислизнути в ліс на таємне побачення."}},fp="19,300,32.449.0,25.363.1,33.126.0,33.177.0,23.146.0,53.144.0"}
P.entries["item:iverron-s-antidote-item"] = {n="Протиотрута Іверрона (предмет)",s="Протиотрута Іверрона — тендітний лікувальний напій, який приготувала Діранія Сілвершайн у Тінедолі. Зварена спеціально, щоб знешкодити смертельну отруту тутешніх павуків Вебвуда, суміш дуже нестійка і швидко псується після приготування.",h="Протиотрута Іверрона — тендітний лікувальний напій, який приготувала Діранія Сілвершайн у Тінедолі.",kw={"протиотрута іверрона","протиотрута","діранія сілвершайн","іверрон","вебвуд","павуки","тінедол"},ang={["profession:Herbalism"]="Суміш показує надзвичайну мінливість тутешніх складників Тельдрассила і підкреслює, що деякі трав'яні ліки треба вживати одразу після приготування.",["race:NightElf"]="Для молодих нічних ельфів — шукачів пригод, що починають шлях у Тінедолі, поспіх із цими ліками до Іверрона показує, як громада покладається на швидкі дії та знання трав проти повзучої скверни у вітті Тельдрассила."},sec={{t="Крихкі ліки",b="Виготовлена Діранією Сілвершайн в Алдрассилі, ця протиотрута має побороти сильну отруту, що вразила молодого нічного ельфа Іверрона. Через мінливу природу складників і трав'яних каталізаторів напій зберігається надзвичайно недовго — лише п'ять хвилин після приготування. Гінці мають без зволікань мчати на північ, до печери Вебвуда, щоб доставити суміш, доки вона не перетворилася на нікчемну бовтанку."}},fp="25,241,16.463.0,36.122.0,40.199.0,23.146.0,37.151.0"}
P.entries["item:jade-phial"] = {n="Нефритова Пляшечка",s="Нефритова Пляшечка — особливо виготовлена посудина, яку дає друїд — нічний ельф Корітрас Мунрейдж у Доланаарі. Вона призначена безпечно набирати й перевозити священну воду з місячних колодязів Тельдрассила, щоб поповнювати центральний колодязь друїдів у Дарнасусі.",h="Нефритова Пляшечка — особливо виготовлена посудина, яку дає друїд — нічний ельф Корітрас Мунрейдж у Доланаарі.",kw={"нефритова пляшечка","місячний колодязь","корітрас мунрейдж","доланаар","дарнасус","село зоряного вітерця","тельдрассил"},ang={["class:Druid"]="Для молодих друїдів нести Нефритову Пляшечку — ранній урок опіки, що підкреслює: життєва сила місячних колодязів Тельдрассила потребує постійної шани й турботи.",["race:NightElf"]="Місячні колодязі уособлюють тривкий зв'язок між калдореями та Елуною; доглядати їх посудинами на кшталт Нефритової Пляшечки — священний обов'язок кожного нічного ельфа."},sec={{t="Посудина для священних вод",b="Тельдрассил усіяний місячними колодязями, що спрямовують місячні й природні сили, життєво важливі для суспільства нічних ельфів і друїдського служіння. Щоб підтримувати цю злагоду, центральний місячний колодязь, яким послуговуються друїди в Дарнасусі, треба час від часу поповнювати з віддалених колодязів великої гілки. Корітрас Мунрейдж довіряє молодим посвяченим Нефритову Пляшечку — посудину, старанно підготовлену, щоб набирати чисту воду з місячного колодязя біля Села Зоряного Вітерця, не порушуючи її тонкої духовної сили."}},fp="10,245,26.506.0,32.226.0,28.148.0,44.166.0"}
P.entries["item:jennea-s-flask"] = {n="Настоянка Дженнеа",s="Настоянка Дженнеа — порожня посудина, яку чарівниця Дженнея Кеннон у Кварталі магів Стормвінда дає майбутнім магам. Її використовують, щоб узяти пробу води з Дзеркального Озера й дослідити збурення в тутешніх силових лініях.",h="Настоянка Дженнеа — порожня посудина, яку чарівниця Дженнея Кеннон у Кварталі магів Стормвінда дає майбутнім...",kw={"настоянка дженнеа","пляшка","дженнея кеннон","дзеркальне озеро","силові лінії","проба води"},ang={["class:Mage"]="Для магів-новачків ця пляшка — одне з перших польових доручень від Святилища Чародія: доказ того, що ви здатні на тонкі таємні дослідження й стеження за стійкістю силових ліній."},sec={{t="Посудина для таємних досліджень",b="Після катастрофічних магічних потрясінь по всьому Азероту природний плин таємних течій зірвався зі своїх давніх русел. У Стормвінді Дженнея Кеннон прагне зрозуміти, як глибоко ці містичні зсуви вплинули на Ліс Елвінн. Вона дає цю просту скляну пляшку перспективним учням і посилає їх на південний захід від воріт столиці набрати свіжої води біля підніжжя водоспаду на Дзеркальному Озері. Наповнена посудина береже тендітну пробу, щоб її можна було принести до Святилища Чародія неушкодженою для таємного аналізу."},{t="На варті вод",b="Головна турбота, що стоїть за цією пляшкою, — безпека людей. Якщо хиткі силові лінії почнуть просочувати магічну скверну в Дзеркальне Озеро, довколишня природа й кожен, хто п'є з його вод, можуть зазнати дивних чи шкідливих недуг. Чиста проба в пляшці Дженнеї дає магам Стормвінда змогу виявити незримий магічний осад, перш ніж отруєні течії непомітно розповзуться околицями."}},fp="14,219,28.557.0,19.431.0,32.114.0,25.104.0,44.206.0,28.147.0"}
P.entries["item:johaan-s-special-drink"] = {n="Особливий Напій Йогаана",s="Особливий Напій Йогаана — смертельне вариво, приготоване Аптекарем Йогааном у селищі Брілл. Замаскована під звичайний трунок, суміш слугує польовим випробуванням чуми, яку розробляє Королівське Аптекарське Товариство.",h="Особливий Напій Йогаана — смертельне вариво, приготоване Аптекарем Йогааном у селищі Брілл.",kw={"особливий напій йогаана","аптекар йогаан","отрута","королівське аптекарське товариство","таверна шибеничний кінець","брілл"},ang={["race:Dwarf"]="Вариво відкриває похмуру долю дворфських розвідників, що підійшли надто близько до Галявин Тірісфалю, де бранців використовують як лабораторних піддослідних.",["race:Undead"]="Для Відступників доставка варива Йогаана — практичне служіння Королівському Аптекарському Товариству й великим задумам Леді Сильвани проти живих."},sec={{t="Отруйне вариво",b="Зварений у казанах Брілла, Особливий Напій Йогаана — геть не корчемний трунок. Аптекар Йогаан готує його, переганяючи різні отруйні складники й місцеві реагенти в один напій, призначений саме для перевірки заразності на живому організмі. Переданий нібито для того, щоб угамувати спрагу бранця, він утілює невідступне прагнення аптекарів Відступників викувати зброю, достатньо потужну, щоб здійснити задуми Сильвани Віндраннер щодо Азерота."},{t="Випробування в підвалі",b="Напій знаходить свого адресата в брудному підвалі під Таверною «Шибеничний Кінець», який Вартові Смерті використовують як тимчасову камеру для заблукалих непроханих гостей. Коли його пропонують полоненому дворфу-горянину, що знемагає в кайданах, спраглий в'язень жадібно п'є, маючи його за грубий ель. Вариво діє миттєво: дворф помирає на місці, і Королівське Аптекарське Товариство переконується, що його найновіший штам швидко гасить живих жертв."}},fp="22,224,12.487.0,16.468.1,31.220.0,26.159.0,36.143.1,43.211.0"}
P.entries["item:jordan-s-refined-ore-shipment"] = {n="Постачання Очищеної Руди Джордана",s="Постачання Очищеної Руди Джордана — ящик високоякісного металу, підготовлений спеціально для коваля Джордана Стілвелла. Здобутий у межах священних випробувань паладина, він дає необхідну сировину, щоб викувати святу зброю доброчесності.",h="Постачання Очищеної Руди Джордана — ящик високоякісного металу, підготовлений спеціально для коваля Джордана...",kw={"очищена руда","джордан стілвелл","паладин","випробування праведності","ковальство","айронфордж","самоцвіт кор"},ang={["class:Paladin"]="Здобути цю партію очищеної руди — перевірка терпіння й відданості паладина, одне з практичних випробувань на шляху до створення символічної зброї Світла.",["profession:Blacksmithing"]="Кожен ремісник розуміє: для майстерного кування потрібні бездоганні, ретельно підготовлені зливки, а не сира руда з поля."},sec={{t="Матеріали коваля",b="Коли Джордан Стілвелл узявся викувати зброю, гідну відданого паладина, звичайна сировина не годилася. Ковалеві знадобився набір рідкісних і вибагливих складників: Очищений Самоцвіт Кор, міцна дубова деревина Вайтстоуну, його власний загублений ковальський молот і особлива партія очищеної руди. Цей вантаж — металева основа для тієї священної праці, доставлена до Айронфорджа, щоб завершити Випробування праведності."}},fp="29,233,19.437.0,47.185.0,29.133.0,44.252.0"}
P.entries["item:jordan-s-smithing-hammer"] = {n="Ковальський Молот Джордана",s="Ковальський Молот Джордана — дорога родинна реліквія, яку коваль-людина Джордан Стілвелл успадкував від батька. Повернути його з проклятих зал Фортеці Шадовфенг конче потрібно, щоб викувати святу зброю, освячену Світлом.",h="Ковальський Молот Джордана — дорога родинна реліквія, яку коваль-людина Джордан Стілвелл успадкував від...",kw={"ковальський молот","джордан стілвелл","фортеця шадовфенг","срібнолісся","реліквія","паладин","ковальство"},ang={["class:Paladin"]="Повернення спадкового молота — частина тяжких випробувань праведності, яка доводить рішучість паладина вирушити в небезпечні землі по знаряддя святого ремесла.",["profession:Blacksmithing"]="Кожен коваль розуміє сентиментальний і практичний зв'язок між майстром та молотом, що перейшов до нього від предків."},sec={{t="Спадок майстра",b="Сторонньому Ковальський Молот Джордана може здатися звичайним ковальським залізом, але для Джордана Стілвелла він утілює і спадщину, і призначення. Успадкований від батька, цей інструмент — осердя Джорданової самості як майстра кузні біля Айронфорджа. Хтозна-як опинившись за покинутими кам'яними стінами Фортеці Шадовфенг у Срібноліссі, він має бути повернений, перш ніж Джордан зможе взятися за свій шедевр — священну зброю, гідну святого захисника."}},fp="24,242,20.457.0,42.205.0,51.177.0,43.177.0"}
P.entries["item:kron-s-amulet"] = {n="Амулет Крона",s="Амулет Крона — особиста пам'ятка Крона, молодого орка-мисливця з Дуротару, що зник на Річці Південної Люті.",h="Амулет Крона — особиста пам'ятка Крона, молодого орка-мисливця з Дуротару, що зник на Річці Південної Люті.",kw={"амулет крона","крон","кроколіски","південна лють","тор'крен","дуротар"},ang={["class:Hunter"]="Суворий урок для кожного майбутнього слідопита: не варто недооцінювати лютих звірів у незнайомих річкових землях.",["race:Orc"]="Доля Крона — трагічне нагадування: хоч гордість і бойова слава рухають орчою традицією, безрозсудність і зневага до мудрості старших можуть принести швидку й марну смерть."},sec={{t="Трагедія на Південній Люті",b="Крон був норовливим молодим орком із хутора на північний захід від Гострого Пагорба. Прагнучи довести свою вправність і зневажаючи небезпеку, він подався полювати на лютих кроколісків-страхопащ, що нишпорять на Річці Південної Люті вздовж кордону з Пустками. Знехтувавши застереженнями матері, Міші Тор'крен, він через уперту гордість потрапив просто в пащі річкових хижаків. Він так і не повернувся, лишивши по собі тільки цю проковтнуту дрібничку — мовчазне підтвердження, що його вбили й зжерли."}},fp="13,131,24.492.1,13.229.0,29.156.1,33.178.1"}
P.entries["item:large-candle"] = {n="Велика Свічка",s="Великі Свічки — воскові свічки, які цінують і носять кобольди, що риють копальні Лісу Елвінн. Прикріплені на маківках, ці грубі світильники дають видимість у підземних тунелях і слугують надійним джерелом сирого воску для людських аптекарів.",h="Великі Свічки — воскові свічки, які цінують і носять кобольди, що риють копальні Лісу Елвінн.",kw={"велика свічка","кобольди","віск","вільям пестл","аптекар","копальня фарґодіп"},ang={["faction:Alliance"]="Забираючи свічки в кобольдів Елвінну, шукачі пригод Альянсу водночас послаблюють шкідників, що заполонили копальні, і постачають важливі матеріали аптекарській справі Стормвінда.",["profession:Mining"]="Рудокопи, що розробляють жили у Фарґодіпі та Яшмовій копальні, раз у раз натикаються на зграї кобольдів, які жадають і золота, і мерехтливого світла цих великих свічок."},sec={{t="Підземне світло й віск",b="Кобольди, що риють тунелі під Лісом Елвінн, покладаються на полум'я свічки, щоб орієнтуватися в чорних як ніч підземних штольнях, і кріплять воскові свічки просто до голови. Кобольди-рудокопи, прохідники й геоманти люто захищають свої свічки від зайд. Попри грубе виготовлення, великі свічки, які носять глибоко в Копальні Фарґодіп і Яшмовій копальні, містять цінний віск, який наземним ремісникам нелегко виробити у великій кількості, — так буденне знаряддя чудовиськ стає алхімічним товаром."},{t="Торгівля й аптекар",b="Вільям Пестл, аптекар родом зі Стормвінда, збирає ці великі свічки в корчмі «Лев'яча Гордість» у Ґолдширі. Шукаючи витопленого воску для настоянок, бальзамів і мазей, які готує його родинна аптека, Пестл наймає перехожих шукачів пригод очистити заполонені копальні й забрати свічки в підземних загарбників."}},fp="12,253,26.490.0,24.353.0,32.240.0,33.200.0,44.203.0,22.233.0"}
P.entries["item:macgrann-s-dried-meats"] = {n="В'ялене М'ясо МакГранна",s="В'ялене М'ясо МакГранна — місячний запас солоних харчів, які мисливець Тундра МакГранн заготував, щоб пережити сувору зиму Дун Мороґу. Увесь запас, схований у посиленій торієвій м'ясній скрині, поцупив лютий єті, відомий як Старий Айсбірд.",h="В'ялене М'ясо МакГранна — місячний запас солоних харчів, які мисливець Тундра МакГранн заготував, щоб...",kw={"в'ялене м'ясо","тундра макгранн","старий айсбірд","єті","зимовий запас","торієва скриня","долина холодного вітерцю"},ang={["profession:Cooking"]="Соління й в'ялення дичини — основна кулінарна навичка виживання в Дун Мороґу, що дає мисливцям, як-от МакГранн, зберігати м'ясо місяцями, не боячись, що воно зіпсується на морозі.",["race:Dwarf"]="Дворфійські горяни добре знають: у високих горах підготовка означає виживання, а втрачений зимовий запас може стати різницею між життям і смертю."},sec={{t="Зимовий запас",b="Життя серед крижаних скель Дун Мороґу вимагає ретельного планування. Готуючись до заметілей холодної пори, дворф-мисливець Тундра МакГранн тижнями полював на дичину, солив м'ясо й ховав його до міцної скрині. Знаючи, що ведмеді-падложери та хижаки раз у раз дошкуляють його обійстю, МакГранн не ризикував і замкнув харчі в торієвій м'ясній скрині. Та навіть із цими пересторогами він не передбачив зайду, достатньо дужого, щоб понести всю скриню, замість ламати її на місці."},{t="До лігва єті",b="Поки МакГранн вистежував оленів, сумнозвісний єті Старий Айсбірд напав на табір мисливця й затягнув важку скриню до свого лігва в Долині Холодного Вітерцю. Хоч звір і не мав чим пробити суцільне торієве обшиття, через поранену ногу МакГранн не міг швидко вирушити до печери по своє добро. Без сторонньої допомоги, щоб повернути запас до настання зими, безпорадний мисливець опинився перед загрозою голоду серед гірських снігів."}},fp="22,261,14.556.0,20.457.0,32.126.0,37.208.0,26.173.0,53.164.0"}
P.entries["item:maggot-eye-s-paw"] = {n="Лапа Червивого Ока",s="Лапа Червивого Ока — моторошний трофей, здобутий із вождя гнолів Червивого Ока в Лігві Гаррена. Принесена до Брілла, вона слугує речовим доказом страти звіра за грабунок могил на користь Погибелі.",h="Лапа Червивого Ока — моторошний трофей, здобутий із вождя гнолів Червивого Ока в Лігві Гаррена.",kw={"лапа червивого ока","червиве око","гноли","лігво гаррена","екзекутор зиґанд","брілл"},ang={["race:Undead"]="Для Відступників з Брілла принести лапу Червивого Ока — прямий удар по викрадачах тіл, що постачають ненависному Королю-Лічу сировину."},sec={{t="Доказ страти",b="Червиве Око накликало на себе суворий гнів Відступників, грабуючи могили й плюндруючи околиці Лігва Гаррена: воно постачало трупи, щоб поповнювати армії, якими командує Король-Ліч. У відповідь у містечку Брілл оголосили офіційний смертний вирок і нагороду. Оскільки для військових адміністраторів на кшталт Екзекутора Зиґанда самих чуток про смерть ніколи не досить, мисливці за головами мусять відтяти лиходієві лапу й принести її до міста, щоб отримати винагороду й закрити справу."}},fp="16,220,18.480.0,47.191.0,55.190.0,26.153.0,51.210.0"}
P.entries["item:mangy-claw"] = {n="Облізла Лапа",s="Облізла Лапа — відрубана лапа великого крижанокігтого ведмедя Дробкігтя з Дун Мороґу. Це похмурий доказ того, що смертоносного звіра, який убив безпорадного дворфійського пілота, нарешті вбито.",h="Облізла Лапа — відрубана лапа великого крижанокігтого ведмедя Дробкігтя з Дун Мороґу.",kw={"облізла лапа","дробкіготь","ведмідь","гільдельве","пілот гаммерфут","облогова бригада","помста"},ang={["class:Hunter"]="Вистежити такого сумнозвісного хижака, як Дробкіготь, серед лютих гірських заметілей — перевірка вміння мисливця приборкувати небезпечних звірів, що стережуть свою територію.",["race:Dwarf"]="Для дворфів виконати передсмертну волю полеглого товариша й помститися за члена Облогової Бригади Айронфорджа — справа глибокої особистої та кланової честі."},sec={{t="Передсмертне бажання пілота",b="Коли паровий танк Пілота Гільдельве зламався серед замерзлих пагорбів Дун Мороґу, він продовжив шукати руду пішки й опинився сам на сам із гірською пусткою. Як записано в його знайденому щоденнику, Гільдельве зумів відбити перший напад велетенського крижанокігтого ведмедя на ім'я Дробкіготь, хоча звір жорстоко пошматував його в тій сутичці. Пізніше хижак повернувся добити ослаблого пілота. Останній запис Гільдельве благав про помсту хижакові — і цю справу завершено, коли з убитого ведмедя взято Облізлу Лапу."},{t="Помста за Облогову Бригаду",b="Облізла Лапа, принесена Пілотові Гаммерфуту, дарує Обложній Бригаді Айронфорджа гірке заспокоєння. Гаммерфут розсилав шукачів по заметах, сподіваючись знайти друга живим, та дізнався лише про його страшну долю. Щоденник Гільдельве разом із відрубаною лапою хижака доводить, що передсмертне прохання Гільдельве виконано: він упокоївся, а пілоти Айронфорджа вдячні."}},fp="10,211,20.540.0,31.399.1,23.160.0,25.170.0,36.239.0,36.118.0"}
P.entries["item:marshal-haggard-s-badge"] = {n="Відзнака Маршала Геггарда",s="Відзнака Маршала Геггарда — символ звання й влади, який Маршал Гаґґард носив на службі королівству Стормвінд. Викрадена хитрощами бандитом Дефіас Джеком Мертвозубом, відзнака становить небезпечну загрозу як знаряддя для видавання себе за міських урядовців.",h="Відзнака Маршала Геггарда — символ звання й влади, який Маршал Гаґґард носив на службі королівству Стормвінд.",kw={"відзнака","маршал гаґґард","джек мертвозуб","братство дефіас","маршал дуґан","обман"},ang={["class:Warrior"]="Повернення відзнаки Гаґґарда доводить вашу стійкість ветеранові війська Стормвінда, який винагороджує перспективних воїнів доглянутою зброєю зі своїх бойових днів.",["faction:Alliance"]="Повернення відзнаки береже цілісність військового командування Стормвінда й не дає Братству Дефіас підірвати місцеву оборону зсередини."},sec={{t="Викрадена відзнака",b="Хоч Маршал Гаґґард давно пішов на спочинок у свою маленьку садибу на пагорбах Лісу Елвінн, його стара відзнака маршала Стормвінда досі має офіційну вагу. Під покровом ночі розбійник Дефіас на ім'я Джек Мертвозуб надягнув стормвіндську накидку й удав із себе Маршала Дуґана, командира гарнізону Ґолдширу. Повіривши, що колишнім товаришам потрібна відзнака для службових справ, старий Гаґґард віддав її без жодної підозри. Джек утік у ліс, перш ніж відставний офіцер усвідомив обман. У руках Братства Дефіас такий знак влади Стормвінда може дозволити розбійникам проходити повз застави чи сіяти сум'яття серед тутешніх патрулів."}},fp="23,290,17.675.0,32.203.0,38.208.0,54.201.0,24.147.0"}
P.entries["item:melenas-head"] = {n="Голова Меленаса",s="Голова Меленаса — відтята здобич, узята в Лорда Меленаса, сатирського ватажка, що отаборився всередині Скелі Скверни. Принесений як беззаперечний доказ його загибелі, трофей позначає тихе усунення застарілої демонічної загрози на вітті Тельдрассила.",h="Голова Меленаса — відтята здобич, узята в Лорда Меленаса, сатирського ватажка, що отаборився всередині Скелі...",kw={"голова меленаса","лорд меленас","сатир","скеля скверни","ґрелли","тінедол","тельдрассил"},ang={["class:Warrior"]="Нести відтяту голову ворожого воєводи — безпомильний, первісний доказ того, що небезпечного супротивника та його військо ґреллів зламано.",["race:NightElf"]="Сатири — трагічне демонічне спотворення прадавнього роду нічних ельфів, тож тиха страта Лорда Меленаса — водночас необхідність і культурний сором."},sec={{t="Негласна ганьба",b="Для нічних ельфів, що охороняють Тінедол і навколишні простори Тельдрассила, сама присутність сатирів на їхньому новому Світовому Дереві — гірка ганьба. Лорд Меленас улаштував лігво в покручених печерах Скелі Скверни, одразу на північ від ельфійських поселень, і згуртував під своїм стягом напасливих воїнів-ґреллів. Оскільки калдореї цінують стриманість, коли йдеться про скверну так близько до їхнього серця, цей кривавий трофей слугує негласним доказом: його підступи придушено, перш ніж його вплив устиг розповзтися."}},fp="13,248,20.532.0,21.187.0,32.253.0,35.131.0"}
P.entries["item:milly-s-harvest"] = {n="Урожай Міллі",s="Урожай Міллі — ящики й відра щойно зібраного винограду, які Міллі Осворт назбирала на Виноградниках Нортшира. Коли бандити Дефіас захопили поля, урожай довелося покинути, і плоди ризикують бути вкраденими злодіями або розчавленими під чоботами варти абатства.",h="Урожай Міллі — ящики й відра щойно зібраного винограду, які Міллі Осворт назбирала на Виноградниках Нортшира.",kw={"урожай міллі","міллі осворт","виноград","виноградники нортшира","братство дефіас","ящики"},ang={["faction:Alliance"]="Загроза простим фермерам Нортширу показує, яким тонким став військовий гарнізон Стормвінда: звичайні громадяни залежать від перехожих шукачів пригод, щоб уберегти свій прожиток.",["race:Human"]="Для людей, що починають свій шлях у Нортширі, повернення врожаю Міллі часто стає першою прямою зустріччю з беззаконням Братства Дефіас, що повзе рідною землею."},sec={{t="Крихкий урожай",b="Родючий ґрунт Долини Нортширу родить виноград, життєво важливий для тутешніх виноробів і громади абатства. Коли настала пора збирання, Міллі Осворт працювала на лозах, збираючи свіжі плоди в відра. Її працю жорстоко перервали озброєні розбійники в червоних масках, що вдерлися на виноградники й змусили її тікати на землі абатства, покинувши врожай розкиданим між рядами."},{t="Побічні втрати",b="Хоч варта Стормвінда пильнує вхід у долину, брак людей залишив Нортшир уразливим. Гарнізон пообіцяв вигнати Дефіас, та Міллі боялася, що будь-яка затяжна сутичка між броньованою вартою й безжальними злодіями цілком знищить її працю. Повернення ящиків, перш ніж їх розтопчуть або заберуть як провіант, рятує один із небагатьох мирних урожаїв Нортширу."}},fp="15,292,15.412.0,17.448.0,24.158.0,48.177.0,56.235.0,44.145.0"}
P.entries["item:minshina-s-skull"] = {n="Череп Міншіни",s="Череп Міншіни містить ув'язнену душу троля Темного Списа Міншіни, брата Майстра Ґадріна. Полонена відступником-відьмаком Залазаном на Островах Відлуння, вона перетворила череп на моторошну посудину, що живить темні обрядові чари.",h="Череп Міншіни містить ув'язнену душу троля Темного Списа Міншіни, брата Майстра Ґадріна.",kw={"череп міншіни","міншіна","ґадрін","залазан","острови відлуння","душа","відьмак"},ang={["faction:Horde"]="Повернення черепа — ранній удар по спотвореній владі Залазана над Островами Відлуння біля самого узбережжя Дуротару.",["race:Troll"]="Для Темного Списа осквернення Міншіни Залазаном — тяжка образа традицій предків, тож повернення його черепа — справа честі племені."},sec={{t="Ув'язнений дух",b="Коли Залазан захопив владу над Островами Відлуння й вигнав плем'я Темного Списа, Міншіна був серед полонених і вбитих. Замість дати жертві відійти в смерть, зрадливий відьмак прив'язав душу Міншіни до його ж відрубаного черепа. Поставлений у мерзенне коло сили на найпівденнішому острові, череп став прив'яззю магічного поневолення. Майстер Ґадрін, якого мучать видіння брата, що кличе його уві сні, шукає відважних мандрівників, аби ті вирушили на захоплені острови, повернули реліквію й розірвали владу Залазана над духом його брата."}},fp="16,228,16.585.0,17.169.0,44.238.0,27.203.0,56.231.1"}
P.entries["item:mirror-lake-water-sample"] = {n="Зразок Води Дзеркального Озера",s="Зразок Води Дзеркального Озера — пляшка свіжої озерної води, набраної біля підніжжя водоспаду в Лісі Елвінн. Зібраний магами-новачками за дорученням Дженнеї Кеннон із Кварталу магів Стормвінда, він потрібен, щоб з'ясувати, чи не просочуються змінені таємні течії в тутешні водойми.",h="Зразок Води Дзеркального Озера — пляшка свіжої озерної води, набраної біля підніжжя водоспаду в Лісі Елвінн.",kw={"зразок води","дзеркальне озеро","дженнея кеннон","святилище чародія","силові лінії","маг"},ang={["class:Mage"]="Принести зразок — ранній обряд обов'язку для магів Альянсу, що навчаються в Святилищі Чародія: він учить стежити за силовими лініями довкілля й розпізнавати дике магічне просочування."},sec={{t="Перевірка вод Елвінну",b="Після катастрофічних світових конфліктів, що зірвали містичні русла світу з їхніх сталих шляхів, маги Святилища Чародія в Стормвінді глибоко стурбовані залишковим таємним збуренням. Дженнея Кеннон доручає перспективним учням наповнити спеціально підготовлену пляшку біля підніжжя водоспаду Дзеркального Озера, що лежить одразу на південний захід від Воріт Стормвінда. Аналізуючи цей зразок води, маги прагнуть виявити, чи не просочилися блукаючі магічні скверни в природні водойми, якими живиться довколишній люд."}},fp="24,301,28.549.0,37.189.0,46.197.0,30.130.0,60.174.0"}
P.entries["item:moonpetal-lily"] = {n="Лілея Місячна Пелюстка",s="Лілеї Місячна Пелюстка — великі світні рослини, корінні для Тельдрассила, що буяють довкола прісних озерець. Славетні потужними відновлювальними властивостями, їхні пелюстки цінують як ключові складники природних ліків і цілющих напоїв.",h="Лілеї Місячна Пелюстка — великі світні рослини, корінні для Тельдрассила, що буяють довкола прісних озерець.",kw={"лілея місячна пелюстка","лілея","протиотрута","тінедол","алдрассил","травництво","печера тіньової нитки"},ang={["profession:Herbalism"]="Хоч у нагальну хвилину їх збирають просто руками, Лілеї Місячна Пелюстка наочно показують багатий відновлювальний ботанічний потенціал Тельдрассила.",["race:NightElf"]="Для молодих калдореїв, що навчаються в Тінедолі, пізнати відновлювальні властивості корінних рослин на кшталт Лілеї Місячної Пелюстки — важливий ранній урок життя в злагоді з природою."},sec={{t="Рослинність озерець",b="Лілеї Місячна Пелюстка ростуть лише на вологих берегах прісних озерець і ставків, найохочіше — на північно-західному боці Алдрассила в Тінедолі. Як і більшість рослинності, що буяє на верхівці новопосталого Світового Дерева, вони вбирають неповторну сутність затишних гаїв Тельдрассила. Їхні широкі пелюстки ніжні й сяйливі, і їх легко помітити біля тихої води, де природна волога дає їм змогу квітнути."},{t="Природні протиотрути",b="Цілителі й травники нічних ельфів цінують Лілею Місячну Пелюстку за її надзвичайні цілющі властивості. У поєднанні з іншою лісовою рослинністю, як-от Гіацинтовими Грибами, лілея діє як потужний заспокійливий і стабілізувальний засіб. Ця відновлювальна якість робить її неодмінним складником протиотрут проти смертельних токсинів, зокрема лютої отрути павуків Вебвуда, що чигають у Печері Тіньової Нитки."}},fp="14,236,18.439.0,17.428.0,31.133.0,35.198.0,45.176.0,55.123.0"}
P.entries["item:nightsaber-fang"] = {n="Ікло Нічного Шаблезуба",s="Гострий зуб, здобутий із хижих нічних шаблезубів, що блукають диким віттям Тельдрассила. Хоч це звичний трофей полювання, ці ікла шукають і як сирі складники тутешні лісові мешканці із сумнівними намірами.",h="Гострий зуб, здобутий із хижих нічних шаблезубів, що блукають диким віттям Тельдрассила.",kw={"ікло нічного шаблезуба","нічний шаблезуб","зенн фаулгуф","сатир","доланаар","тельдрассил","трофей"},ang={["class:Hunter"]="Здолати нічного шаблезуба й узяти його ікло означає довести основне володіння дикою природою, та постачати частини звірів споганеним лісовим духам — спотворення самого духу полювання.",["race:NightElf"]="Нічні шаблезуби — улюблені супутники й символи богині Елуни, тож полювати на цих священних хижаків задля віроломного сатира — глибока ганьба."},sec={{t="Трофей полювання",b="Нічні шаблезуби — одні з найсмертоносніших природних хижаків північного Калімдору; нічні ельфи шанують їх за спритність, лютість і глибокий духовний зв'язок з Елуною. По всьому великому віттю Тельдрассила ці котячі звірі полюють у тінях під шатром. Здолавши одного, мисливець здобуває гострі ікла — незаперечний доказ своєї вправності, хоч деякі непевні постаті в лісі шукають їх для не надто шляхетних обрядових цілей."},{t="Складник для сатира",b="За поселенням Доланаар чигає Зенн Фаулгуф — облудний сатир, що полює на завзятих і недосвідчених мандрівників. Запевняючи, що потребує лісових складників, Зенн підмовляє молодих шукачів пригод здобувати ікла нічних шаблезубів разом із перами стригід і павутинним шовком. Віддати такі хижацькі складники означає прямо допомогти шахраєві, який відверто глузує з наївного героя, щойно дістане своє."}},fp="15,233,18.458.0,17.384.1,36.153.0,41.140.0,45.187.0,58.111.0"}
P.entries["item:nissa-s-remains"] = {n="Останки Нісси",s="Останки Нісси — повернуті земні рештки Нісси Аґаманд, шляхтянки колись заможної династії Аґамандів на півночі Галявин Тірісфалю. Убита й піднята безтямною служницею Погибелі під час Третьої війни, вона разом із родиною тепер стала здобиччю колишніх робітників, що прагнуть помсти.",h="Останки Нісси — повернуті земні рештки Нісси Аґаманд, шляхтянки колись заможної династії Аґамандів на півночі...",kw={"останки нісси","нісса аґаманд","аґаманди","коулмен фартінґ","помста","брілл"},ang={["faction:Horde"]="Знищення піднятих Аґамандів і очищення їхніх млинів убезпечує північ Галявин Тірісфалю від недобитків Погибелі, що загрожують Бріллу й Андерсіті.",["race:Undead"]="Для Відступників відвоювати Тірісфаль означає вичистити і колишніх гнобителів з Погибелі, і заможних аристократів, що через дурну гордість прирекли простих робітників на нежиття."},sec={{t="Спадщина гордині",b="До Третьої війни родина Аґамандів була найзаможнішою і найвпливовішою династією Галявин Тірісфалю: вона тримала процвітаючі млини на північних пагорбах. Коли Чума Нежиті підповзла до Лордерону, патріархи родини вперто відмовилися евакуюватися. Натомість вони укріпили маєтки й переконали своїх слуг і робітників стояти до кінця. Та зухвалість коштувала життя всім. Аґаманди впали перед Погибеллю й повстали не з гордою незалежністю, а шкутильгаючими безтямними рабами, прикутими до волі, що її диктує Король-Ліч."},{t="Гірка відплата",b="У містечку Брілл уцілілі, що згодом вирвалися на волю під проводом королеви Сильвани Віндраннер, не забули фатальної гордості цієї родини. Коулмен Фартінґ, колишній робітник на млинах Аґамандів, плекає гірку образу на колишніх господарів за те, що заманили своїх робітників у пащу нежиття. Він доручає шукачам пригод упокоїти піднятих Аґамандів і повернути їхні тілесні рештки — зокрема й Ніссині. Для Фартінґа й інших серед Відступників спалити чи знищити ці реліквії означає похмуре відчуття остаточного завершення й злостивої помсти."}},fp="15,298,17.567.0,18.540.0,22.260.0,47.246.0,33.194.0,49.197.0"}
P.entries["item:nondescript-letter"] = {n="Непримітний Лист",s="Непримітний Лист — запечатане послання без позначок, довірене щойно пробудженим Відступникам, що покидають Похоронний Подзвін. Вручений Келвіном Монтеґ'ю під виглядом доручення, він скеровує носія дорогою до Корчмарки Рене в Таверні «Шибеничний Кінець» у Бріллі.",h="Непримітний Лист — запечатане послання без позначок, довірене щойно пробудженим Відступникам, що покидають...",kw={"непримітний лист","келвін монтеґ'ю","корчмарка рене","таверна шибеничний кінець","похоронний подзвін","брілл"},ang={["class:Rogue"]="Слизька поведінка Келвіна Монтеґ'ю й різка зміна настрою Рене мають усі ознаки дрібної розбійницької інтриги й шифрованого спілкування злочинного світу.",["race:Undead"]="Для щойно піднятих Відступників цей лист — одна з перших спонук покинути межі Похоронного Подзвону й дослідити більші поселення Галявин Тірісфалю."},sec={{t="Доручення кур'єра",b="До щойно піднятих Відступників, що хочуть вирушити за межі Похоронного Подзвону, підходить Келвін Монтеґ'ю — слизький розбійник, що тиняється біля околиці села. Жаліючись на втому від боїв із безтямними зомбі й павуками, Келвін просить мандрівників віднести простий конверт без позначок східною дорогою до Брілла. Недбало адресований корчмарці на ім'я Рене, лист — лише привід виштовхнути мандрівників із долини в бік Таверни «Шибеничний Кінець», хоча обіцянки Келвіна про щедру винагороду від самого початку звучать порожньо."},{t="Підозріле листування",b="Коли лист доставляють до Брілла, Корчмарка Рене спершу розігрує перебільшено веселу виставу, мовляв, це напевно добрі звістки від її святої матінки з Похоронного Подзвону. Зрозумівши, що кур'єр бачить наскрізь її незграбну гру, вона миттю міняє люб'язність на гостре роздратування. Вона вихоплює лист, відмовляється сказати, хто його насправді надіслав і що в ньому, і грубо проганяє носія — хіба що той збирається заплатити за кімнату."}},fp="18,263,18.530.0,25.447.1,31.163.0,42.151.0,34.214.0,43.230.0"}
P.entries["item:nori-s-mug"] = {n="Кухоль Норі",s="Кухоль Норі — особистий посуд Норі Прайддріфта, в якому він розносить обпікаючий ранковий узвар крижаними заметами Дун Мороґу. Доставивши теплий напій, що проганяє пронизливий гірський холод, подорожні мусять повернути порожній кухоль ощадливому власникові.",h="Кухоль Норі — особистий посуд Норі Прайддріфта, в якому він розносить обпікаючий ранковий узвар крижаними...",kw={"кухоль норі","норі прайддріфт","ранковий узвар","дурнан фуркаттер","анвілмар","посуд","доставка"},ang={["race:Dwarf"]="Для дворфів, які зносять бурі Дун Мороґу, поділитися теплим напоєм — природна річ, але загубити добрий корчемний посуд у заметі — непрощенне марнотратство."},sec={{t="Повернення кур'єра",b="На морозних гірських перевалах Дун Мороґу паруючий кухоль ранкового узвару — одна з небагатьох утіх, здатних пробити лютий холод. Норі Прайддріфт довіряє свій кухоль подорожнім, які несуть свіжу, паруючу порцію Дурнану Фуркаттеру до Анвілмара. Коли його спорожнять, міцний посуд мусить вирушити назад. Як зауважує Норі, кухлі на деревах не ростуть, і пильнувати витривалий дворфійський посуд — справа першорядна там, де гостинність зустрічається із засніженою пусткою."}},fp="10,276,18.476.0,28.196.0,18.189.0,45.242.0,28.136.0"}
P.entries["item:notched-rib"] = {n="Зазубрене Ребро",s="Зазубрене Ребро — кістяний трофей, здобутий із безтямної нежиті, що блукає Галявинами Тірісфалю. Вартовий Смерті Діллінджер у Бріллі збирає ці пошрамовані рештки як доказ зусиль зламати опору Погибелі на Млинах Аґаманда.",h="Зазубрене Ребро — кістяний трофей, здобутий із безтямної нежиті, що блукає Галявинами Тірісфалю.",kw={"зазубрене ребро","скелети","вартовий смерті діллінджер","млини аґаманда","погибель","брілл"},ang={["race:Undead"]="Для Відступників збирання цих потрощених кісток — частина безнастанної війни за виживання проти безтямних прислужників Короля-Ліча, які затягли б їх назад у рабство."},sec={{t="Похмурий доказ бою",b="Сили Погибелі, що збираються на північних полях Галявин Тірісфалю, складаються з оживлених скелетів у зруйнованих обладунках. Серед них солдати Тріснутого Черепа й солдати Гримучих Кісток кидаються на кожну живу чи вільну істоту, яка трапиться їм на шляху. Клинки, що розтинають їхні крихкі кістяки, лишають на кістках вибоїни й зарубки. Щоб переконатися, що розвідники й добровольці Відступників справді проріджують цих безтямних зайд, а не просто спостерігають за ними, Вартові Смерті вимагають речових доказів. Зазубрене, позначене боєм ребро — незаперечний доказ того, що ще одного раба, якого послав Король-Ліч, розтрощено."},{t="Убезпечення млинів",b="Млини Аґаманда — ключова стратегічна позиція на північний захід від Брілла. Якби Погибель міцно закріпилася серед зруйнованих хуторів і вітряків, вона мала б прямий плацдарм для ударів углиб Тірісфалю. Вартовий Смерті Діллінджер наглядає за дорогами, що ведуть на північ, і відряджає звитяжців розчавити скелетні загони, перш ніж ті згуртуються. Купи зазубрених ребер, принесені до Брілла, доводять, що лінії Відступників тримаються й повільно перемелюють авангард Погибелі — кістка за кісткою."}},fp="11,236,20.629.0,18.542.0,22.191.0,32.141.0,22.157.0,46.196.0"}
P.entries["item:osric-s-crate"] = {n="Ящик Осріка",s="Ящик Осріка — важкий пакунок зі щойно виготовленим обладунком, відправлений зі Стормвінда знеможеним захисникам Сентінел Гілл. Перевезений на грифоні повітряною мережею королівства, він дає життєво важливе спорядження, щоб Народне Ополчення втримало Вестфол проти розбійницьких зграй.",h="Ящик Осріка — важкий пакунок зі щойно виготовленим обладунком, відправлений зі Стормвінда знеможеним...",kw={"ящик осріка","обладунок","сентінел гілл","народне ополчення","грифон","інтендант льюїс"},ang={["faction:Alliance"]="Кожна партія зброї та обладунку, що доходить до Сентінел Гілл, допомагає втримати західні кордони королівства від цілковитого падіння перед Братством Дефіас."},sec={{t="Припаси для фронту",b="Вестфол страждає від нападів Братства Дефіас і гнолів-мародерів, тоді як військо Стормвінда відсутнє. Тутешні захисники, об'єднані в Народне Ополчення на Сентінел Гілл, не мають офіційної підтримки корони й мусять покладатися на розрізнені припаси. Ящик Осріка містить свіжу партію захисного обладунку, надісланого зі столиці Інтендантові Льюїсу, щоб роздати його просто бійцям-добровольцям ополчення на місці."},{t="Крилата кур'єрська мережа",b="Везти спорядження суходолом зі Стормвінда через Ліс Елвінн і далі за кордон Вестфолу повільно й небезпечно через бандитські засідки. Щоб обминути дороги, ящик довіряють шукачеві пригод, який летить із грифонника Дунґара Лонґдрінка в Торговому Кварталі Стормвінда до Тора на Сентінел Гілл. Ця швидка доставка показує, яку важливу роль відіграють грифони в постачанні прикордонних гарнізонів під час війни."}},fp="13,284,22.458.0,22.421.0,29.192.0,13.116.0,23.148.0,38.228.0"}
P.entries["item:partially-filled-vessel"] = {n="Частково Наповнена Посудина",s="Частково Наповнена Посудина — зачарований контейнер для перевезення благословенної води місячних колодязів Тельдрассилом. Віддана молодим посвяченим — нічним ельфам Тенароном Стормґріпом в Алдрассилі, вона несе воду, набрану в Тінедолі, до поселення Доланаар.",h="Частково Наповнена Посудина — зачарований контейнер для перевезення благословенної води місячних колодязів...",kw={"частково наповнена посудина","місячний колодязь","тенарон стормґріп","корітрас мунрейдж","тінедол","доланаар","алдрассил"},ang={["class:Druid"]="Перевезення освячених вод — неодмінний обов'язок у служінні безперервним зусиллям Кола Кенарія плекати й оглядати здоров'я Світового Дерева.",["race:NightElf"]="Нести цю посудину — обряд посвяти, що виводить молодих нічних ельфів із прихистку Тінедолу до ширшої відповідальності за турботу про Тельдрассил."},sec={{t="Священна доставка",b="У вітті Алдрассила посвячені калдореї набирають благословенну воду з усамітненого місячного колодязя Тінедолу. Тенарон Стормґріп переливає цей чистий зразок у спеціальну посудину, готуючи її до подорожі Світовим Деревом. Посудина лишається наповненою лише частково, бо її шлях тільки почався: згодом треба зібрати ще священних вод з усього Тельдрассила, щоб подбати про здоров'я острова."},{t="Далі до Доланаара",b="Щоб донести посудину, треба пройти на південь крізь браму долини й рушити бруківкою на захід до Доланаара. Ця подорож позначає вихід молодого шукача пригод із захищеної колиски Тінедолу в ширші нетрі Тельдрассила. Біля центрального місячного колодязя Доланаара посудину приймає Корітрас Мунрейдж, щоб спрямувати наступний етап обряду."}},fp="23,257,17.421.0,18.376.0,26.135.0,32.190.0,29.161.0,52.216.0"}
P.entries["item:plainstrider-feather"] = {n="Перо Степовика",s="Вискубані у прудких птахів, що блукають рівнинами Малгору, пера степових довгоступів — важливий матеріал, який збирають молоді мисливці на Плато Червоної Хмари. Табір Нарачі використовує їх передусім для одягу й племінних оздоб, і таурени шанують створінь, що годують селище.",h="Вискубані у прудких птахів, що блукають рівнинами Малгору, пера степових довгоступів — важливий матеріал...",kw={"перо степовика","степовий довгоступ","пера","мисливець","табір нарачі","ґрулл гоквінд","плато червоної хмари"},ang={["class:Hunter"]="Вистежувати прудких степових довгоступів на Плато Червоної Хмари — засадниче випробування посвяченого на терпіння, слідопитство й шану до здобичі.",["race:Tauren"]="Для молодого таурена зібрати пера степового довгоступа — важливий перший урок: нічого не брати в створінь Матері-Землі як належне й використовувати кожну частину здобичі на їжу й одяг."},sec={{t="Перша пожертва мисливця",b="На Плато Червоної Хмари молоді таурени рано вчаться, що виживання залежить від гострого ока слідопита й мисливця. Степові довгоступи бігають трав'янистим плоскогір'ям, даючи і поживу, і практичні матеріали. Вискубані міцні пера дають табору змогу виготовляти традиційний одяг і спорядження. Подані Ґруллу Гоквінду разом зі свіжим м'ясом, ці пера засвідчують повагу до потреб племені й стають найпершим випробуванням на шляху до визнання Вождем Гоквіндом і гостинного прийому в Тандер Блафі."}},fp="20,300,25.496.0,40.164.0,52.172.0,33.97.0,64.234.0"}
P.entries["item:plainstrider-meat"] = {n="М'ясо Степовика",s="М'ясо Степовика — свіжа дичина, здобута з нелітаючих птахів, що блукають рівнинами Малгору. Для молодих тауренів, які входять у зрілість на Плато Червоної Хмари, збирання цієї поживи — і життєво важливі зимові припаси, і головний обряд посвяти.",h="М'ясо Степовика — свіжа дичина, здобута з нелітаючих птахів, що блукають рівнинами Малгору.",kw={"м'ясо степовика","степовий довгоступ","дичина","мисливець","табір нарачі","ґрулл гоквінд","вождь гоквінд"},ang={["class:Hunter"]="Прудкий степовий довгоступ дає мисливцям-початківцям ранню перевірку слідопитства й влучності на відкритих рівнинах Малгору.",["race:Tauren"]="Для молодих тауренів, що виходять на Плато Червоної Хмари, полювання на степових довгоступів — перший практичний крок до поваги Вождя Гоквінда й права увійти в Тандер Блаф."},sec={{t="Пожива для плато",b="Життя тауренів нерозривно пов'язане з землею й урівноважує шану до природи з практичною потребою виживати. На Плато Червоної Хмари Табір Нарачі — поселення, що значною мірою живе з дичини, вполюваної на довколишніх луках. М'ясо степових довгоступів дає селищу необхідні запаси харчів, коли комори порожніють, а оперення птахів — матеріал для одягу й церемоніальних оздоб."},{t="Випробування молодого мисливця",b="Полювання на степових довгоступів — одне з перших випробувань для молоді, що прагне здобути повагу племені. Ґрулл Гоквінд посилає мисливців-новачків вистежувати прудких птахів на плато й збирати м'ясо та пера, щоб довести свою вправність слідопита й самостійність, перш ніж стати перед його батьком, Вождем Гоквіндом."}},fp="17,257,23.401.0,22.311.0,35.162.0,23.166.0,37.138.0,64.202.0"}
P.entries["item:plainstrider-talon"] = {n="Кіготь Степового Довгоступа",s="Кіготь Степового Довгоступа — гострий кіготь, здобутий із великих нелітаючих степових довгоступів, що водяться в Малгорі. Шамани тауренів разом з іншими природними реагентами використовують ці кігті, щоб виготовляти священні очисні тотеми, коли джерела води на їхній землі осквернено.",h="Кіготь Степового Довгоступа — гострий кіготь, здобутий із великих нелітаючих степових довгоступів, що...",kw={"кіготь степового довгоступа","степовий довгоступ","тотем","малл тандергорн","водяна криниця","шамани","малгор"},ang={["class:Shaman"]="Виготовлення очисних тотемів із тілесних частин звірів, як-от кігтів, — зразок традиційної шаманської практики тауренів, що черпає силу просто з рідних духів землі.",["race:Tauren"]="Шанувати жертву звірини Малгору — осердя тауренського полювання: кожен узятий звір допомагає зцілити Матір-Землю, коли її вражає гоблінське визискування."},sec={{t="Узи рівнин",b="Великі нелітаючі степові довгоступи блукають відкритими травами Малгору, покладаючись на потужні ноги й гострі кігті, щоб відбиватися від хижаків і рити тверду землю прерій у пошуках поживи. Для тауренів Села Бладгуф кожна частина вполюваного звіра має духовний відгук. Коли гоблінські підприємства осквернили священні джерела на кшталт Водяної Криниці Вінтергуфів, шаман Малл Тандергорн зажадав кігтів степових довгоступів разом із лапами степових вовків. У ритуальному ремеслі тауренів реагенти, зібрані з тутешніх хижаків і збирачів, дають змогу спрямувати духовну сутність землі в тотеми, здатні вигнати неприродні отрути."}},fp="18,249,19.620.0,41.151.0,38.177.0,63.258.0,40.205.0"}
P.entries["item:pork-belly-pie"] = {n="Пиріг зі Свинячою Грудинкою",s="Пиріг зі Свинячою Грудинкою — сита домашня страва, яку пече «Тітонька» Берніс Стоунфілд у Лісі Елвінн. Попри гірку, давню ворожнечу між родинами Стоунфілдів і Маклурів, малий Біллі Маклур не може встояти перед куховарством Тітоньки Берніс і вимагає пиріг як хабар, щоб розповісти про загублену родинну реліквію.",h="Пиріг зі Свинячою Грудинкою — сита домашня страва, яку пече «Тітонька» Берніс Стоунфілд у Лісі Елвінн.",kw={"пиріг","свиняча грудинка","біллі маклур","тітонька берніс","кулінарія","ворожнеча"},ang={["faction:Alliance"]="Для мандрівників Альянсу, що допомагають сільському Елвінну, такі доручення, як доставка пирогів, проливають світло на дріб'язкові, та глибоко вкорінені чвари, що ділять сільське серце Стормвінда.",["profession:Cooking"]="Пиріг показує, як домашня їжа може по-справжньому впливати на місцеві суперечки, навіть якщо сам рецепт лишається ревно бережною таємницею Тітоньки Берніс."},sec={{t="Хабар між ворожими фермами",b="Родини Стоунфілдів і Маклурів роками плекають гірке суперництво, сварячись за землю й гордість у серці Лісу Елвінн. Попри цю ворожнечу, малий Біллі Маклур має очевидну слабкість: він обожнює знаменитий пиріг зі свинячою грудинкою Тітоньки Берніс. Коли зникає цінне родинне намисто, Біллі відмовляється ділитися тим, що знає, доки шукач пригод не принесе йому теплий шматок. Берніс пече його вкрай неохоче — і з промовистим побажанням, щоб жадібний хлопчисько ним удавився, — доводячи, що кулінарна слава часом долає навіть найупертішу родинну ворожнечу."}},fp="14,318,29.572.0,36.258.0,29.212.0,53.232.0,35.153.0"}
P.entries["item:powers-of-the-void"] = {n="Сили Порожнечі",s="Сили Порожнечі — рідкісний магічний фоліант, що колись зберігався в закритому крилі бібліотеки Абатства Нортшира. Після того як послушник-відступник викрав його, переходячи до Братства Дефіас, наставниця чорнокнижників Друзілла Ла Салль прагне повернути книгу, щоб поглибити власне вивчення темної магії.",h="Сили Порожнечі — рідкісний магічний фоліант, що колись зберігався в закритому крилі бібліотеки Абатства...",kw={"сили порожнечі","фоліант","друзілла ла салль","братство дефіас","абатство нортшира","чорнокнижник"},ang={["class:Warlock"]="Повернення цього викраденого гримуара — засадниче випробування для молодих людей-чорнокнижників: доказ волі, достатньої, щоб заслужити таємницю прикликання біса.",["race:Human"]="Присутність фоліанта в Нортширі показує, що Святий Орден зберігає небезпечні магічні записи поряд зі звичайними церковними текстами, ховаючи їх від очей послушників."},sec={{t="Заборонений нортширський текст",b="Архіви Абатства Нортшира зберігають значно більше, ніж святе письмо й церковні записи. У захищеному крилі бібліотеки абатства лежали «Сили Порожнечі» — науковий трактат про енергії тіні й Безодні, імовірно написаний архімагом Хадґаром. Зважаючи на небезпечну природу таких досліджень, влада абатства пильно охороняла книгу й суворо забороняла доступ до неї випадковим відвідувачам. Так вона лишалася поза досяжністю тутешньої наставниці чорнокнижників Друзілли Ла Салль, яка не могла крутитися біля заборонених полиць, не викликавши небажаних підозр жрецтва."},{t="Крадіжка Дефіас і повернення",b="Фоліант зрештою покинув мури абатства не руками Друзілли, а через зраду зсередини. Послушник, що навчався в Нортширі, зрікся обітниць, щоб пристати до Братства Дефіас, і, тікаючи в сусідні виноградники, прихопив кілька цінних томів. Скориставшись пригодою злодія, Друзілла посилає перспективних чорнокнижників-новачків просто в табір бандитів Дефіас, щоб забрати фоліант з їхніх наметів. Повернення тексту слугує подвійній меті: воно віддає темне знання в руки наставниці й перевіряє, чи має новачок досить сміливості, щоб прив'язувати потойбічних демонів."}},fp="18,280,28.591.0,25.595.0,27.203.0,47.227.0,44.200.0,51.200.0,48.190.0"}
P.entries["item:prairie-alpha-tooth"] = {n="Зуб Альфи Прерій",s="Зуб Альфи Прерій беруть у лютих ватажків зграй, що блукають рівнинами довкола Тандер Блафу. У традиції тауренів ці зуби — могутня пожертва, якою очищають і шанують дорогоцінні джерела води на їхній землі.",h="Зуб Альфи Прерій беруть у лютих ватажків зграй, що блукають рівнинами довкола Тандер Блафу.",kw={"зуб альфи прерій","степові вовки","альфа","малл тандергорн","криниця","тандер блаф","малгор"},ang={["class:Shaman"]="Духів водяних криниць треба задобрювати земною рівновагою, і пожертвувані ікла найвищого хижака закріплюють цю природну гармонію.",["race:Tauren"]="Узяти ікло альфи прерій — означає виконати священний обов'язок мисливця: брати потрібне з повагою й повертати цю первісну сутність, щоб зцілити отруєну землю."},sec={{t="Очисна пожертва",b="Водяні криниці Малгору — життєво важливі джерела для тауренів, і збереження їхньої духовної чистоти вимагає обрядів шани й жертви. Щоб очистити Водяну Криницю Вайлдмейнів, Маллу Тандергорну із Села Бладгуф потрібні зуби, зібрані в альф степових вовків, що скрадаються в тіні Тандер Блафу. Як найвищі хижаки хвилястих трав'янистих рівнин, ці альфи уособлюють первісну силу дикої природи. Пожертвувані зуби шанують рівновагу між мисливцем, здобиччю й духами землі."}},fp="19,216,20.495.0,39.142.0,34.148.0,53.212.0"}
P.entries["item:prairie-wolf-paw"] = {n="Лапа Степового Вовка",s="Лапи степових вовків здобувають із хижаків, що блукають рівнинами Малгору. Шамани, як-от Малл Тандергорн із Села Бладгуф, використовують їх як природні складники, щоб уплести силу землі в очисні тотеми.",h="Лапи степових вовків здобувають із хижаків, що блукають рівнинами Малгору.",kw={"лапа степового вовка","степовий вовк","тотем","малл тандергорн","криниця вінтергуфів","очищення","малгор"},ang={["class:Shaman"]="Виготовлення очисних тотемів із частин місцевих звірів показує засаду стихій: живою сутністю землі вигнати неприродну скверну.",["race:Tauren"]="Для тауренів здобути вовчі лапи — урочистий обов'язок дбайливого господаря: закликати рідних звірів землі, щоб зцілити прабатьківські водяні криниці, осквернені гоблінською жадобою."},sec={{t="Природні реагенти рівнин",b="Степові вовки скрадаються хвилястими травами Малгору, полюючи зграями разом зі степовими переслідувачами та своїми альфами. Хоч вони небезпечні для молодих мисливців і місцевої худоби, ці створіння глибоко вплетені в духовну рівновагу рівнин. Шамани тауренів бачать у вовчих лапах не просто трофеї, а важливі провідники вродженої життєвої сили землі."},{t="Очищення криниць",b="Коли підприємства гоблінів осквернили священні запаси води Малгору, шаман Малл Тандергорн потребував речової допомоги самої землі, щоб протидіяти забрудненню. Зв'язані разом із кігтями степових довгоступів, вовчі лапи дають первісний духовний відгук, потрібний для виготовлення очисних тотемів, і так починається життєво важлива праця з очищення Водяної Криниці Вінтергуфів."}},fp="16,244,30.370.0,19.354.0,39.166.0,28.147.0,42.251.0,44.154.0"}
P.entries["item:purified-kor-gem"] = {n="Очищений Самоцвіт Кор",s="Очищений Самоцвіт Кор — рідкісний освячений кристал, потрібний зброяреві Джордану Стілвеллу біля Айронфорджа. Колись заплямований темними енергіями, він має бути відвойований у глибинах Калімдору й очищений ельфійською магією, перш ніж його можна буде вкувати у святу зброю Світла.",h="Очищений Самоцвіт Кор — рідкісний освячений кристал, потрібний зброяреві Джордану Стілвеллу біля Айронфорджа.",kw={"самоцвіт кор","паладин","джордан стілвелл","чорноглибинні печери","тундріс віндвівер","обердайн","наґи","очищення"},ang={["class:Paladin"]="Здобути й очистити цей самоцвіт — довести відданість паладина, пройшовши шлях від глибин Калімдору назад до Дун Мороґу, щоб викувати знакову зброю Світла.",["faction:Alliance"]="Здобуття очищеного самоцвіту єднає зусилля всього Альянсу: мудрість нічних ельфів Обердайна дає силу ковалю-людині, що працює на схилах Дун Мороґу."},sec={{t="Від скверни до святості",b="Свій шлях камінь починає як Зіпсутий Самоцвіт Кор у володінні підлих наґів, що зачаїлися в Чорноглибинних Печерах глибоко під узбережжям Ашенвалю. Щоб очистити камінь від його водяної, тіньової скверни, паладин мусить знайти нічного ельфа Тундріса Віндвівера в Обердайні. Спираючись на таємні й природні мистецтва, Тундріс виганяє з каменя скверну, обертаючи його на осяйний Очищений Самоцвіт Кор. Лише в цьому бездоганному стані він годиться як провідник святої сили."},{t="Шедевр коваля",b="Біля Айронфорджа, серед засніжених скель Дун Мороґу, зброяр-людина Джордан Стілвелл потребує самоцвіт як ключовий складник для кування майстерної зброї. Давно маючи креслення озброєння, гідного Срібної Длані, Стілвелл не мав екзотичних матеріалів, щоб утілити задум. Очищений Самоцвіт Кор разом із Дубовою Деревиною Вайтстоуну та рідкісною рудою стає духовним осердям, потрібним, щоб спрямовувати праведний гнів паладина."}},fp="16,274,27.493.0,23.438.0,38.235.0,29.155.0,21.188.0,52.200.0"}
P.entries["item:putrid-claw"] = {n="Гнилий Кіготь",s="Гнилі кігті — зогнилі руки, відтяті в безтямної нежиті, що никає лісами на захід від Брілла. Вартовий Смерті Діллінджер збирає їх як остаточний доказ того, що загрозу Погибелі біля старого мосту тримають на відстані.",h="Гнилі кігті — зогнилі руки, відтяті в безтямної нежиті, що никає лісами на захід від Брілла.",kw={"гнилий кіготь","нежить","погибель","вартовий смерті діллінджер","старий міст","брілл"},ang={["race:Undead"]="Для свіжих посвячених Відступників, що покидають Похоронний Подзвін, винищення цієї безтямної Погибелі — раннє нагадування: свобода означає постійний захист від безтямних оболонок, на які вони колись самі скидалися."},sec={{t="Трофей безтямних",b="Навіть на власній батьківщині Відступники не можуть почуватися цілком безпечно: Король-Ліч і досі сягає сюди своєю рукою. Гурти безтямної Погибелі — гниючі мерці й пошматовані трупи — раз у раз переходять східні кордони на Галявини Тірісфалю, збираючись уздовж доріг і біля старого мосту на захід від Брілла. Щоб убезпечити мандрівників і лінії постачання гарнізону, Вартові Смерті призначають нагороду за цих блукаючих страховиськ. Відтятий гнилий кіготь — незаперечний речовий доказ того, що ще один шкутильгаючий труп упокоєно назавжди."}},fp="11,231,22.526.0,31.161.0,32.141.0,38.203.0,59.211.0"}
P.entries["item:rare-earth"] = {n="Рідкісноземельний Метал",s="Рідкісноземельний Метал — особливий пакунок багатого на мінерали ґрунту, здобутого в Дарнасусі для ботанічних дослідів на Тельдрассилі. Його посилають гінцем із Доланаара травникові-дослідникові Деналану в його табір на березі Озера Ал'Амет.",h="Рідкісноземельний Метал — особливий пакунок багатого на мінерали ґрунту, здобутого в Дарнасусі для ботанічних...",kw={"рідкісноземельний метал","ґрунт","деналан","сірал блейдліф","озеро ал'амет","дарнасус","доланаар"},ang={["profession:Herbalism"]="Травники оцінять копіткі зусилля дослідників на кшталт Сірал Блейдліф і Деналана, які вивчають, як особливий ґрунт може змінити ріст і властивості саджанців Тельдрассила.",["race:NightElf"]="Для нічних ельфів, що доглядають своє молоде Світове Дерево, кожен ботанічний дослід біля Озера Ал'Амет дає розуміння того, як життя пристосовується до неприборканого віття Тельдрассила."},sec={{t="Ґрунт Дарнасуса",b="Новопостала жива система Тельдрассила потребує уважного спостереження й плекання, тож травники по всьому острову вивчають, як різні рослини відгукуються на чужий чи збагачений ґрунт. Цей пакунок рідкісної землі замовив просто з Дарнасуса Деналан — дивакуватий ботанік, що облаштувався на східному березі Озера Ал'Амет. Коли пакунок застряг у дорозі й із запізненням опинився в Доланаарі, травниця Сірал Блейдліф доручає мандрівникам, що прямують на південь, доставити нетривкий ґрунт Деналану, доки його сила не вивітрилася."}},fp="10,233,17.537.0,28.252.0,36.208.0,43.244.0"}
P.entries["item:rattlecage-skull"] = {n="Череп Гримучих Кісток",s="Черепи Гримучих Кісток — потрощені рештки безтямної нежиті, що никає зруйнованими околицями Похоронного Подзвону. Чорнокнижники-новачки з Відступників мають зібрати ці скам'янілі трофеї для Вені Мартанд, щоб показати свою міцніючу волю й здобути право на темне мистецтво прикликання.",h="Черепи Гримучих Кісток — потрощені рештки безтямної нежиті, що никає зруйнованими околицями Похоронного...",kw={"череп гримучих кісток","скелети","чорнокнижник","веня мартанд","похоронний подзвін","демон"},ang={["class:Warlock"]="Для чорнокнижників Відступників збирання цих черепів — перша віха їхньої дисципліни: доказ, що вони мають холодну волю, потрібну, щоб поневолити першого демона.",["race:Undead"]="Трощення нижчих, бездумних скелетів підкреслює віру Відступників в те, що панування утверджується чистою волею, яка й відрізняє вільну нежить від безтямних рабів."},sec={{t="Випробування неофіта",b="У безсонячних межах Похоронного Подзвону щойно піднятими Відступниками, що мають хист до темної магії, опікується Веня Мартанд. Щоб довести, що початківець має досить сили духу, аби підкоряти своїй волі істот з інших планів, Веня доручає йому впокорити скелетів Гримучих Кісток, що досі блукають біля зруйнованої кузні. Знищити цих нижчих мерців і принести їхні відтяті черепи — і практичне випробування дисципліни, і ритуальне підґрунтя, перш ніж навчитися прориватися в порожнечу й поневолювати першого демонічного прислужника."}},fp="16,267,17.530.0,36.202.0,37.169.0,68.285.0,55.164.0"}
P.entries["item:raven-claw-talisman"] = {n="Талісман Воронячого Пазура",s="Талісман Воронячого Пазура — священна реліквія нічних ельфів, пов'язана з Друїдами Кігтя. Він зберігається глибоко в Курганному Лігві Бан'етіл на Тельдрассилі і є однією з чотирьох неодмінних Реліквій Пробудження, потрібних, щоб безпечно провести сплячих друїдів назад зі Смарагдового Сну.",h="Талісман Воронячого Пазура — священна реліквія нічних ельфів, пов'язана з Друїдами Кігтя.",kw={"талісман воронячого пазура","реліквії пробудження","друїди кігтя","курганне лігво бан'етіл","смарагдовий сон","атрідас бермантл","фурболги"},ang={["class:Druid"]="Талісман — емблема Друїдів Кігтя, що показує, як обрядові осередки бережуть дух друїда, поки той блукає Смарагдовим Сном.",["race:NightElf"]="Повернення цієї реліквії захищає і прадавню традицію нічних ельфів, і життя сплячих родичів, яким загрожує безумство фурболгів Вузлошкірів."},sec={{t="Ключ до пробудження",b="Талісман Воронячого Пазура зберігається в окремій скрині всередині Курганного Лігва Бан'етіл — підземного притулку, де Друїди Кігтя Тельдрассила поринули в глибокий споглядальний сон. Друїдська сплячка — тонкий духовний поріг. Якщо зв'язок друїда з явою розірвати без належного обрядового осередку, його дух ризикує навіки застрягти у Смарагдовому Сні. Разом із Чорним Пером, Сапфіром Небес і Руною Гніздування талісман потрібен Атрідасу Бермантлу в Доланаарі, щоб провести обряд пробудження й безпечно повернути сплячих."},{t="Загроза в курганному лігві",b="Коли споганені фурболги Вузлошкірів заполонили Курганне Лігво Бан'етіл, священні скрині та сплячі друїди опинилися в безпосередній небезпеці. Споганення фурболгами відрізало святилище від зовнішньої допомоги й наразило реліквії на втрату чи знищення. Атрідас Бермантл доручає захисникам Тельдрассила пройти звивистими земляними ходами лігва й здобути Талісман Воронячого Пазура, доки вигнаних друїдів не втрачено для Сну назавжди."}},fp="19,260,18.627.0,28.447.0,41.158.0,39.135.0,34.136.0,40.243.0"}
P.entries["item:reagent-pouch-shaman"] = {n="Мішечок Реагентів (шаман)",s="Мішечок реагентів, який носять культисти Палаючого Клинка, що причаїлися на скелях Дуротару. Шаман, що прагне єднання з вогнем, потребує цих зібраних чарівних складників, щоб перегнати свою першу вогняну сапту.",h="Мішечок реагентів, який носять культисти Палаючого Клинка, що причаїлися на скелях Дуротару.",kw={"мішечок реагентів","шаман","палаючий клинок","вогняна сапта","телф джулам","вогняний тотем","дуротар"},ang={["class:Shaman"]="Здобуття мішечка — поворотний обряд переходу на шляху до вашого Вогняного Тотема, який учить, що навіть осквернені стихійні посередники можна повернути на службу рівновазі.",["class:Warlock"]="Мішечки — звичайні чаклунські припаси культистів Скверни, що містять обрядові складники для демонічної піромантії, а не для єднання з природою."},sec={{t="Складники полум'я",b="Щоб приготувати вогняну сапту й налаштувати молодого шамана на духів полум'я, потрібні особливі обрядові каталізатори. Культисти Палаючого Клинка носять невеликі торбинки з реагентами для демонічних вогняних заклять. Відлюдник Телф Джулам поєднує зібрані порошки та олії з вогняною смолою шипогривів Гостроманів, щоб приготувати напій, який дарує зір у царину вогню."},{t="Нечисті джерела, чисте бачення",b="Хоч Палаючий Клинок спотворює полум'я задля руйнування й чаклунства Скверни, речовини в їхніх мішечках лишаються пов'язаними з первісною природою жару й горіння. Шаманська філософія стверджує, що всі сили стихій існують у напрузі: вогонь — і творець, і руйнівник. Забираючи вкрадені знаряддя культистів, шаман повертає стихійне середовище, щоб пробудити справжнє єднання з духами."}},fp="22,197,23.400.0,28.406.0,35.198.0,32.145.0,40.224.0"}
P.entries["item:red-burlap-bandana"] = {n="Червона Мішковинна Бандана",s="Червоні Мішковинні Бандани — грубі фарбовані маски з тканини, які носять дрібні розбійники й кишенькові злодії Братства Дефіас. У Долині Нортширу Помічник Віллем збирає ці клапті тканини як доказ убитих злодіїв, що підступають до виноградників абатства.",h="Червоні Мішковинні Бандани — грубі фарбовані маски з тканини, які носять дрібні розбійники й кишенькові...",kw={"червона бандана","мішковина","братство дефіас","помічник віллем","нортшир","розбійники"},ang={["class:Rogue"]="Для розбійника-початківця зривання червоних масок із незграбних злодюжок Нортширу — урок того, як швидко недисципліновані розбійники стають легкою мішенню для місцевих охоронців порядку.",["faction:Alliance"]="Поширення цих червоних бандан аж до порога Абатства Нортшира показує, як сильно сільські кордони королівства вислизають з-під влади Стормвінда."},sec={{t="Знак Братства",b="Червона мішковинна бандана, пов'язана на нижній частині обличчя, слугує розпізнавальним знаком рядових Братства Дефіас. Зроблена з дешевої грубої тканини й просочена червоною фарбою, вона приховує риси злодія й водночас сповіщає про вірність повстанню, що набирає сили. У Нортширі молоді новобранці й звичайні головорізи носять ці хустки в східні сади, не здогадуючись, що тутешня варта використовує яскраву червону тканину як похмурий знак для винагороди."}},fp="18,254,25.446.0,43.285.0,34.248.0,47.264.0,28.221.0"}
P.entries["item:red-linen-bandana"] = {n="Червона Лляна Бандана",s="Червона лляна бандана — характерна маска на обличчя, яку носять члени Братства Дефіас по всьому Лісі Елвінн. Окрім того, що вона приховує особу бандита, тканина виткана з якісного льону, який винахідливі мешканці часто перешивають на корисний одяг.",h="Червона лляна бандана — характерна маска на обличчя, яку носять члени Братства Дефіас по всьому Лісі Елвінн.",kw={"червона бандана","льон","братство дефіас","едвін венкліф","сара тімберлейн","тканина"},ang={["class:Rogue"]="Багряна тканина, пов'язана на нижній частині обличчя, стала знаковим обличчям розбійників і кишенькових злодіїв у лісах довкола столиці.",["profession:Tailoring"]="Бандани показують, яким цінним лишається сире ткане полотно в сільському Елвінні, де прості ткалі перешивають бандитські кольори на робочий одяг."},sec={{t="Знак Дефіас",b="Поки дрібні новачки й звичайні головорізи в Долині Нортширу вдовольняються грубими мішковинними масками, повноправні бійці Дефіас по всьому Лісі Елвінн носять ткані червоні лляні бандани. Яскраво-багряна тканина слугує водночас уніформою й заявою про вірність розбійницькому братству Едвіна Венкліфа: вона ховає обличчя й сповіщає про заколот проти корони Стормвінда."},{t="Перешита тканина",b="Попри кривавий підтекст, бандани скроєні з пристойного полотна. Практичні поселенці, як-от Сара Тімберлейн, чий дім — Лісозаготівельний Табір Східної Долини, регулярно просять подорожніх збирати їх у таборах розбійників. Трохи прання й шиття — і контрабандна тканина перетворюється на міцний одяг і бинти для робочого люду лісу."}},fp="17,253,18.390.0,16.360.0,42.167.0,54.146.0,36.169.0,39.168.0"}
P.entries["item:restabilization-cog"] = {n="Шестерня Рестабілізації",s="Шестерні Рестабілізації — точні механічні компоненти, зняті з прокажених гномів, що блукають біля опромінених руїн Гномреґану. У Хараносі гномським майстрам потрібні ці цілі деталі, щоб зібрати Рекомбобулятор — амбітну машину, покликану повернути назад мутацію прокажених.",h="Шестерні Рестабілізації — точні механічні компоненти, зняті з прокажених гномів, що блукають біля опромінених...",kw={"шестерня рестабілізації","рекомбобулятор","прокажені гноми","оззі тоґлвольт","раззл спрайспрокет","гномреґан","харанос"},ang={["profession:Engineering"]="Точні допуски Шестерень Рестабілізації — зразок класичного гномського дизайну: вони витримують нестабільне тертя й урівноважують тендітні механічні збірки, як-от Рекомбобулятор.",["race:Gnome"]="Для гномів-вигнанців у Дун Мороґу добування цих компонентів — скорботний обов'язок: знімати механізми зі спотворених братів у відчайдушній надії зібрати ліки для полеглих Гномреґану."},sec={{t="Деталі для ліків",b="Коли Гномреґан затопили радіацією в катастрофічній спробі знищити трогів-загарбників, незліченних гномів обернуло на хворих, ворожих прокажених гномів. Попри божевілля, ці уражені вигнанці досі носять на собі складну гномську механіку та придатне до використання кріплення. Майстри Оззі Тоґлвольт і Раззл Спрайспрокет вірять, що жахливе перетворення можна систематично скасувати. Щоб довершити прототип Рекомбобуляційного Пристрою, вони покладаються на шукачів пригод, які добудуть життєво важливі деталі просто з уражених біля воріт Гномреґану — зокрема цілі Шестерні Рестабілізації, щоб урівноважити внутрішні системи згоряння машини."}},fp="19,289,21.623.0,39.247.0,30.166.0,54.289.0"}
P.entries["item:rolf-and-malakai-s-medallions"] = {n="Медальйони Рольфа і Малакая",s="Медальйони Рольфа і Малакая — службові знаки двох вартових Стормвінда, що зникли, патрулюючи східний Ліс Елвінн. Позначені гербом королівства, вони потрібні Вартовому Томасу, щоб дізнатися долю зниклих товаришів.",h="Медальйони Рольфа і Малакая — службові знаки двох вартових Стормвінда, що зникли, патрулюючи східний Ліс...",kw={"медальйони","рольф","малакай","вартовий томас","мурлоки","варта"},ang={["faction:Alliance"]="Медальйони — тверезе нагадування про те, що навіть у серці Альянсу тутешні вартові стикаються зі смертельною небезпекою, охороняючи сільські торгові шляхи.",["race:Human"]="Для людей Елвінну ці знаки означають утрачених синів і захисників, чия смерть показує вразливість королівства, поки військо зайняте деінде."},sec={{t="Гірке підтвердження",b="Коли вартові Рольф і Малакай зникли на берегах річки у східному Лісі Елвінн, їхній командир, Вартовий Томас, боявся найгіршого. Знайдені особисті медальйони вартових — незаперечний доказ їхньої загибелі від рук мурлоків, що насуваються. Для гарнізону Стормвінда ці знаки — не просто дрібнички: вони уособлюють полеглих солдатів, які тримали оборону проти зростаючих загроз дикої природи, коли військо королівства було розтягнуте до відчаю."},{t="Знаки служби",b="Як і багато хто з міської варти Стормвінда та сільських патрулів, люди-вартові носять розпізнавальні медальйони, що засвідчують їхню вірність і владу під короною. Повернення цих знаків Вартовому Томасу дає йому змогу офіційно звітувати про зниклих людей, записати їхню жертву в польовому рапорті й здійняти тривогу щодо агресивних племен мурлоків, що оселяються біля торгових шляхів."}},fp="29,250,19.485.0,17.383.0,39.184.1,34.170.0,39.134.0,51.214.1"}
P.entries["item:rough-quartz"] = {n="Грубий Кварц",s="Грубий Кварц — скромний стихійний камінь, який Малий Прояв Землі дарує шаманам-новачкам. Хоч він малий і необроблений, саме він стає духовним осердям першого Тотема Землі шамана.",h="Грубий Кварц — скромний стихійний камінь, який Малий Прояв Землі дарує шаманам-новачкам.",kw={"грубий кварц","кварц","тотем землі","шаман","прояв землі","ерткаллер"},ang={["class:Shaman"]="Грубий Кварц — ваше найперше єднання зі стихією землі, що закорінює ваші закляття й позначає ваш шлях справжнього провідника духів."},sec={{t="Серце Тотема Землі",b="Невтаємниченому оку грубий кварц здається звичайним пустельним камінцем. Та для шамана, що єднається з духами в Дуроторі чи Малгорі, це дар стихій, піднесений самим Малим Проявом Землі. Камінь утілює витривалість, терпіння й непохитну силу. Коли його приносять старійшині на кшталт Канаґи Ерткаллера в Долині Випробувань, кварц вправляють у різьблене дерево Тотема Землі, і він стає духовним осердям, що єднає молодого шамана з живим ґрунтом Азероту."}},fp="12,211,24.543.0,40.192.0,31.136.0,40.127.0,38.114.0"}
P.entries["item:rumbleshot-s-ammo"] = {n="Боєприпаси Рамблшота",s="Боєприпаси Рамблшота — загублений ящик набоїв для зброяра Геґнара Рамблшота в Дун Мороґу. Важкий ящик, покинутий переляканим кур'єром, що втік від голодних вендиґо, лежить у снігу біля Сивого Лігва.",h="Боєприпаси Рамблшота — загублений ящик набоїв для зброяра Геґнара Рамблшота в Дун Мороґу.",kw={"боєприпаси","геґнар рамблшот","вендиґо","сиве лігво","зброяр","лослор","дун мороґ"},ang={["class:Hunter"]="Для стрільців, що блукають лютим холодом Дун Мороґу, сухий порох і повні запаси шроту в Геґнара означають стабільне постачання набоїв для дворфійської вогнепальної зброї.",["profession:Engineering"]="Дворфійські інженери й майстри значною мірою залежать від постійного потоку шроту й пороху, щоб випробовувати власну вогнепальну та експериментальну зброю."},sec={{t="Застрягла партія",b="Геґнар Рамблшот тримає придорожню збройну крамницю на гірській стежці, що спускається від Перевалу Холодного Кряжа до Анвілмара. Стрільці Айронфорджа, горяни й дворфійські мінометні команди невпинно вправляються на засніжених висотах, тож його запаси згоряють майже так само швидко, як спалахує порох. Цю партію шроту відправив Лослор із Хараноса, але до полиць вона не дісталася. Кур'єр, якому доручили її перевезти, розбив табір надто близько до хижих вендиґо Сивого Лігва, запанікував під час нападу й утік, рятуючи життя, покинувши важкий ящик із припасами просто посеред мисливських угідь звірів."}},fp="17,229,19.631.0,25.224.0,32.242.0,26.212.0"}
P.entries["item:rune-inscribed-parchment"] = {n="Пергамент з Рунними Письменами",s="Письмове послання, яке отримують майбутні орки-шамани в Долині Випробувань. Написане наставником Шікріком і передане Ґорнеком, воно кличе посвячуваних прийняти роль духовних провідників і посередників духів стихій.",h="Письмове послання, яке отримують майбутні орки-шамани в Долині Випробувань.",kw={"пергамент","руни","шаман","шікрік","ґорнек","долина випробувань","предки"},ang={["class:Shaman"]="Ця рунна записка — ваш найперший крок на шляху стихій, що віддає вас під науку Шікріка вчитися шанування предків і влади над стихіями.",["race:Orc"]="Відродження шаманської традиції — осердя нової Орди, і цей пергамент утілює тяглість мудрості предків у Дуроторі."},sec={{t="Поклик до духів",b="У випаленому сонцем каньйоні Долини Випробувань нові орки-шамани починають навчання під пильним оком досвідчених наглядачів. Виконуючи перші випробування для Ґорнека, посвячуваний отримує цей укритий рунами документ. Надісланий самим Шікріком, тутешнім наставником шаманів, пергамент — офіційний виклик до глибших таємниць єднання зі стихіями. Орча культура бачить у шамані не просто бойового заклинача, а неодмінного посередника між живими й предками. Цей короткий припис позначає перехід від простої грубої сили до дисциплінованого шляху шанування предків."}},fp="24,234,24.631.0,37.182.0,24.181.0,49.263.0"}
P.entries["item:rune-inscribed-tablet"] = {n="Табличка з Рунними Письменами",s="Табличка з Рунними Письменами — кам'яне послання, яке отримують молоді тролі-шамани Темного Списа в Долині Випробувань. Передана Ґорнеком, вона спрямовує здібних містиків почати офіційне єднання зі стихіями під опікою орка-наставника Шікріка.",h="Табличка з Рунними Письменами — кам'яне послання, яке отримують молоді тролі-шамани Темного Списа в Долині...",kw={"табличка","руни","шаман","шікрік","ґорнек","темний спис","стихії"},ang={["class:Shaman"]="Табличка — перший офіційний крок шамана до володіння стихіями землі, вогню, води й повітря; вона нагадує учням, що їхня сила тече від духів предків.",["race:Troll"]="Для тролів Темного Списа відгукнутися на поклик орка-наставника — означає зміцнити зв'язок і спільний духовний шлях між тролями та їхніми новими союзниками з Орди."},sec={{t="Поклик до духів",b="Вирізьблена рунами стихій, ця табличка — офіційне запрошення для тролів-шаманів-початківців, що роблять перші кроки в Дуроторі. Коли посвячуваний доводить свою вправність у Долині Випробувань, наглядач Ґорнек вручає йому камінь, надісланий тролем-шаманом Іші-йо, щоб скерувати новачка до наставника шаманів Шікріка. Для тролів Темного Списа, які мають власні глибокі духовні традиції, табличка — початок їхнього спільного шляху з орками, що єднає давню тролячу містику з відродженою шаманською спадщиною, яку обстоює Вождь Тралл."}},fp="21,253,24.578.0,43.234.0,21.237.0,25.126.0"}
P.entries["item:rune-of-nesting"] = {n="Руна Гніздування",s="Руна Гніздування — одна з чотирьох священних Реліквій Пробудження, що зберігаються в Курганному Лігві Бан'етіл на Тельдрассилі. Це неодмінна складова тонкого друїдського обряду, потрібного, щоб безпечно прикликати сплячих Друїдів Кігтя назад зі Смарагдового Сну.",h="Руна Гніздування — одна з чотирьох священних Реліквій Пробудження, що зберігаються в Курганному Лігві...",kw={"руна гніздування","реліквії пробудження","друїди кігтя","курганне лігво бан'етіл","смарагдовий сон","атрідас бермантл","скриня гніздування"},ang={["class:Druid"]="Для друїдів Руна Гніздування уособлює священні обряди Кола Кенарія й підкреслює вразливість сплячих братів, коли священні святилища зламано.",["race:NightElf"]="Споганення курганних лігв і втрата цих реліквій пробудження підкреслюють дедалі більшу скверну, що вражає звірину й фурболгів Тельдрассила."},sec={{t="Священний осередок пробудження",b="Друїди нічних ельфів поринають у глибокі циклічні сплячки в підземних курганних лігвах, щоб єднатися з природою через Смарагдовий Сон. Прокинутися з такого глибокого трансу — не просто ворухнутися: потрібен точний обряд під проводом священних знарядь. Руна Гніздування, що безпечно лежить у Скрині Гніздування глибоко в звивистих покоях Курганного Лігва Бан'етіл, закріплює цей процес. Разом із Талісманом Воронячого Пазура, Чорним Пером і Сапфіром Небес руна слугує провідником, що кличе Друїдів Кігтя назад у яву."},{t="Лихо в Бан'етілі",b="Коли споганені фурболги Вузлошкірів заполонили Курганне Лігво Бан'етіл, сплячі захисники кургану опинилися в безпосередній небезпеці. Без доступу до реліквій друїди ризикували навіки застрягти у Смарагдовому Сні, поки загарбники плюндрували їхнє святилище. Повернення Руни Гніздування та супутніх артефактів дає Атрідасу Бермантлу в Доланаарі змогу підготувати обряд, потрібний, щоб безпечно пробудити друїдів у небезпеці."}},fp="15,260,28.574.0,19.448.0,37.183.0,35.142.0,58.245.0,59.145.0"}
P.entries["item:sack-of-supplies"] = {n="Мішок Припасів",s="Ці мішки з припасами належать караванній партії, призначеній для гобліна-інженера Резлака біля Оргріммара. Товари, що їх везли через Дуротар, перехопили гарпії Пилового Вітру, які гніздяться на скелях Каньйону Гострого Вітру.",h="Ці мішки з припасами належать караванній партії, призначеній для гобліна-інженера Резлака біля Оргріммара.",kw={"мішок припасів","резлак","гарпії","каньйон гострого вітру","караван","оргріммар"},ang={["faction:Horde"]="Повернення втрачених припасів у місцевих хижаків гарантує, що прикордонне будівництво довкола молодої столиці Оргріммара триватиме без дорогих затримок."},sec={{t="Розграбований караван",b="Резлак — інженер, якого Ґазлоу найняв із Раджета, — покладається на регулярні каравани через Дуротар, щоб забезпечувати свої будівельні роботи для Орди. Та нетрі Дуротару далеко не приборкані. Коли обіцяна партія проходила біля дороги в каньйоні на південь від Оргріммара, на неї напали й розграбували її тутешні гарпії Пилового Вітру. Люті створіння затягли вантаж углиб своїх гнізд у Каньйоні Гострого Вітру, розкидавши мішки по землі та осипищах поряд із місцями гніздування гарпій."}},fp="16,228,19.496.0,34.232.0,23.133.0,14.132.0"}
P.entries["item:samuel-s-remains"] = {n="Останки Семюела",s="Останки Семюела — повернуті земні рештки Семюела Фіппса, колишнього мешканця Галявин Тірісфалю, що впав перед Погибеллю. Зібрані шукачами пригод біля Похоронного Подзвону, їх ховають поруч із його дружиною Марлою, щоб виконати її передсмертне бажання.",h="Останки Семюела — повернуті земні рештки Семюела Фіппса, колишнього мешканця Галявин Тірісфалю, що впав перед...",kw={"останки семюела","семюел фіппс","марла","поховання","послушниця елрет","похоронний подзвін"},ang={["race:Undead"]="Поховати останки Семюела — ранній урок самосвідомості Відступників: повага до трагічно загиблих позначає ключову моральну межу між вільною нежиттю й безтямними рабами Погибелі."},sec={{t="Трагічне возз'єднання",b="До того як чума нежиті прокотилася Лордероном, Семюел Фіппс мирно жив зі своєю дружиною Марлою. Коли вдарила зараза, Семюел піддався їй і був прикутий до безтямної служби Погибелі. Марла уникла нежиття лише для того, щоб загинути від руки чоловіка, якого кохала. Попри цей жорстокий кінець її останнім бажанням була не помста, а вічність удвох: вона благала поховати її поруч із Семюелом, щойно його прокляту подобу буде упокоєно. Послушниця Елрет у Похоронному Подзвоні доручає щойно пробудженим Відступникам вистежити блукаючу подобу Семюела на північний схід від поселення, зібрати його кістки й поховати їх у передньому ряду місцевого цвинтаря."}},fp="16,242,16.635.0,21.233.0,33.202.0,45.279.0"}
P.entries["item:sapphire-of-sky"] = {n="Сапфір Небес",s="Сапфір Небес — одна з чотирьох священних Реліквій Пробудження, які нічні ельфи зберігають у Курганному Лігві Бан'етіл. Це неодмінний осередок, щоб безпечно прикликати сплячих Друїдів Кігтя назад зі Смарагдового Сну.",h="Сапфір Небес — одна з чотирьох священних Реліквій Пробудження, які нічні ельфи зберігають у Курганному Лігві...",kw={"сапфір небес","реліквії пробудження","друїди кігтя","курганне лігво бан'етіл","смарагдовий сон","скриня небес","атрідас бермантл"},ang={["class:Druid"]="Сапфір — приклад обережних обрядів, потрібних, коли дух вирушає у Смарагдовий Сон, і показує, як легко єднання може стати згубним без священних якорів.",["race:NightElf"]="Збереження священних артефактів у Курганному Лігві Бан'етіл украй важливе, щоб уберегти хисткий лад Тельдрассила посеред дедалі більшої скверни."},sec={{t="Обряд пробудження",b="Глибоко в корінні Тельдрассила Друїди Кігтя єднаються з дикою природою, спочиваючи в сплячці в Курганному Лігві Бан'етіл. Пробудження з такого глибокого трансу в яву — крихкий і небезпечний процес. Щоб убезпечити перехід, друїди покладаються на чотири освячені артефакти, відомі як Реліквії Пробудження: Чорне Перо, Талісман Воронячого Пазура, Руну Гніздування й Сапфір Небес. Без цього резонансного самоцвіта злагода, потрібна, щоб покликати сплячі духи назад зі Смарагдового Сну, лишається неповною, і їм загрожує вічне ув'язнення."},{t="Загроза в Бан'етілі",b="Коли споганені фурболги Вузлошкірів заполонили курганне лігво, священні артефакти лишилися в своїх оздоблених сховищах. Сапфір Небес зберігається в Скрині Небес посеред звивистих підземних ходів. Оскільки друїди знесилені чи викрадені знавіснілими фурболгами, повернути цей самоцвіт разом із супутніми реліквіями — нагальна справа для Атрідаса Бермантла в Доланаарі, доки сплячих не втрачено назавжди."}},fp="15,218,19.602.0,23.452.0,28.211.0,34.132.0,37.303.0,23.172.0"}
P.entries["item:sara-balloo-s-plea"] = {n="Благання Сари Баллу",s="Благання Сари Баллу — рукописне послання, яке в Айронфорджі склала вбита горем удова. Не в змозі в своїй скорботі постати перед монархом особисто, вона довіряє цей лист випробуваному захисникові Альянсу, щоб той поніс його перед Короля Маґні Бронзбірда.",h="Благання Сари Баллу — рукописне послання, яке в Айронфорджі склала вбита горем удова.",kw={"благання","сара баллу","лист","удова","король маґні бронзбірд","айронфордж","високий престол"},ang={["faction:Alliance"]="Сара довіряє своє прохання лише захисникам, визнаним за службу Альянсу, покладаючись на їхню репутацію, щоб її звернення вислухали при дворі.",["race:Dwarf"]="Для дворфів донести послання Сари до Високого Престолу — акт глибокої спорідненості: навіть у горі жоден горянин чи містянин не лишиться непочутим Королем Маґні."},sec={{t="Звернення вдови",b="Написане в тіні глибокої особистої трагедії, Благання Сари Баллу — смиренне звернення просто до престолу Айронфорджа. Замість самій іти до Високого Престолу в такому горі, Сара шукає шукача пригод, який довів свою вірність і доблесть Альянсу, щоб той передав її слова. Послання просить уваги Короля Маґні Бронзбірда, звертаючи погляд володаря на приватну жалобу й жертви звичайних дворфійських родин, що служать королівству."}},fp="18,238,16.491.0,27.146.0,53.187.0,26.103.0,40.143.1"}
P.entries["item:sarkoth-s-mangled-claw"] = {n="Понівечений Кіготь Саркота",s="Понівечений Кіготь Саркота — відрубана клешня Саркота, страхітливого скорпіда, що нишпорить південними кручами Долини Випробувань. Глибоко посічений умирущим тролем Гана'зуа, цей трофей слугує і доказом загибелі звіра, і останньою втіхою для гордості пораненого мисливця.",h="Понівечений Кіготь Саркота — відрубана клешня Саркота, страхітливого скорпіда, що нишпорить південними...",kw={"кіготь саркота","саркот","скорпід","гана'зуа","долина випробувань","трофей"},ang={["faction:Horde"]="Для посвячуваних у Долині Випробувань здобуття цього трофея — одне з найперших випробувань відваги й бойової сили в суворих нетрях Дуротару.",["race:Troll"]="Принести понівечений кіготь Гана'зуа — означає подарувати вмирущому родичу з Темного Списа дещицю гідності: він знатиме, що його останній удар покалічив звіра перед кінцем."},sec={{t="Трофей помсти",b="Полюючи в Долині Випробувань, молодий троль Темного Списа на ім'я Гана'зуа зчепився з величезним скорпідом, відомим як Саркот. Перш ніж отруйне жало Саркота пронизало йому груди й лишило стікати кров'ю під сусіднім деревом, Гана'зуа завдав нищівного удару по велетенській клешні створіння. Відрубана понівечена кінцівка — незаперечний доказ, що страхітливого скорпіда вбито. Для Гана'зуа тримати понівечений кіготь означає знати: його відчайдушний удар лишив тривкий слід, і це дарує швидкоплинну іскру воїнської честі, поки отрута розтікається його жилами."}},fp="22,282,21.559.0,24.245.0,33.216.0,30.148.0"}
P.entries["item:scarlet-armband"] = {n="Багряні Наручі",s="Багряні Наручі — відзнаки, які носять члени Багряного Хрестового Походу на знак фанатичної відданості винищенню всієї нежиті. У Похоронному Подзвоні Екзекутор Аррен вимагає їх як доказ того, що новоявлені Відступники дали відсіч фанатикам, які вторгаються на їхню землю.",h="Багряні Наручі — відзнаки, які носять члени Багряного Хрестового Походу на знак фанатичної відданості...",kw={"багряні наручі","багряний хрестовий похід","фанатики","екзекутор аррен","похоронний подзвін","відступники"},ang={["race:Undead"]="Для щойно піднятих Відступників збирання цих наручів — похмуре знайомство з ненавистю світу живих: воно показує, що виживання вимагає безжального захисту від Хрестового Походу."},sec={{t="Знак фанатизму",b="Багряні Наручі, що їх носять на рукавах і Багряні Посвячені, і свіжі навернені, — безпомильний знак, який вирізняє Багряний Хрестовий Похід. Для щойно піднятих Відступників, що виходять із Похоронного Подзвону, ці смужки червоної тканини означають смертельну загрозу просто на порозі. Хрестовий Похід не розрізняє безтямних прислужників Погибелі й вільних підданих Темної Леді: в їхніх очах кожен ходячий труп має піти на вогнище. Екзекутор Аррен обертає збирання цих наручів на похмурий обряд переходу, що підтверджує загибель ворожих розвідників на південний схід від поселення й доводить, що нові Відступники здатні боронити свою молоду націю."}},fp="15,281,21.661.0,46.309.0,25.183.0,47.222.0,52.125.0"}
P.entries["item:scarlet-crusade-documents"] = {n="Документи Багряного Хрестового Походу",s="Ці перехоплені папери ніс гонець, якого Багряний Хрестовий Похід послав із Багряного Монастиря до таборів біля Похоронного Подзвону. У них — накази польовим командирам Хрестового Походу по всіх Галявинах Тірісфалю, і вони дають Відступникам саме ті військові відомості, які потрібні, щоб ударити по місцевому проводу Хрестового Походу.",h="Ці перехоплені папери ніс гонець, якого Багряний Хрестовий Похід послав із Багряного Монастиря до таборів...",kw={"документи багряного хрестового походу","накази","мевен корґал","екзекутор аррен","екзекутор зиґанд","брілл","ратуша"},ang={["race:Undead"]="Нести ці перехоплені папери — означає для пробудженого з Відступників випуск із цвинтарних випробувань Похоронного Подзвону до ширших воєнних зусиль, якими керують із Брілла."},sec={{t="Перехоплені накази",b="Відряджений просто з Багряного Монастиря, кур'єр Мевен Корґал ніс ці документи до південного табору Хрестового Походу за межами Похоронного Подзвону. Видані за наказом Верховного Лорда, директиви адресовані капітанам Тірісфальського регіонального командування: Капітан Перрін має далі укріплювати південно-західну вежу й збирати відомості про нежить у Бріллі, Капітан Вашон — придушити рух нежиті біля північної вежі, а капітан Мелроуз — пильнувати кордон із Чумними Землями. Документи розкривають імена, пости й накази польових офіцерів Багряного Хрестового Походу по всіх Галявинах Тірісфалю, обертаючи звичайний кур'єрський рейс на катастрофічний витік розвідки для фанатиків."},{t="Доставка до Брілла",b="Екзекутор Аррен швидко збагнув, що місцеві сили в Похоронному Подзвоні не зможуть скористатися всією широтою цих відомостей. Натомість захоплене досьє стає для щойно пробудженого з Відступників перепусткою з Похоронного Подзвону. Пронесені на північний схід повз Маєток Холодного Вогнища до Брілла, документи передають просто в руки Екзекутора Зиґанда перед Ратушею Брілла. Із цими наказами військовий провід Відступників планує швидкі удари по командирах Багряного Хрестового Походу, що окопалися по всіх Галявинах."}},fp="25,328,18.718.0,17.502.0,33.150.0,41.325.0,33.178.0,50.191.0"}
P.entries["item:scarlet-insignia-ring"] = {n="Перстень з Відзнакою Багряного Хрестового Походу",s="Перстень з Відзнакою Багряного Хрестового Походу — перстень-печатка; його носить кожен, кого Багряний Хрестовий Похід розквартирував на Галявинах Тірісфалю. Для захисників Брілла з Відступників ці персні — моторошний доказ того, що ще одного фанатика стерто з землі Лордерону.",h="Перстень з Відзнакою Багряного Хрестового Походу — перстень-печатка; його носить кожен, кого Багряний...",kw={"перстень з відзнакою","багряний хрестовий похід","варіматрас","вартовий смерті берджесс","брілл","андерсіті"},ang={["faction:Horde"]="Збирання цих перснів допомагає молодій Орді закріпитися у Східних Королівствах, послаблюючи фанатичних хрестоносців довкола Андерсіті.",["race:Undead"]="Для Відступників зірвати ці персні з рук мертвих хрестоносців — пряма заява, що Тірісфаль належить мертвим, і виконання наказів Темної Леді й Варіматраса."},sec={{t="Знаки фанатизму",b="Кожен боєць Багряного Хрестового Походу на Галявинах Тірісфалю — від свіжих неофітів і ревних братів-ченців до загартованих капітанів на кшталт Мелраша й Перріна — носить перстень із відзнакою. Позначені вогняним сигілом Хрестового Походу, персні дають упізнати брата й сестру в організації, яку пожирає параноя. Та для чужинців і ворогів ці дрібнички мають зовсім інше призначення: це безпомильні розпізнавальні знаки найфанатичнішого людського недобитка Лордерону."},{t="Нагорода жахолорда",b="За прямим наказом Варіматраса, жахолорда-заступника Леді Сильвани, Вартовий Смерті Берджесс у Бріллі діяльно збирає ці персні. Відступники вважають Багряний Хрестовий Похід нестерпною пошестю, що повзе їхньою щойно відвойованою батьківщиною. Для новобранців Відступників принести до Брілла купу цих перснів — незаперечний доказ загибелі ворогів і пряме підтвердження вірності престолу Андерсіті."}},fp="21,254,18.466.0,23.428.0,31.260.0,56.292.0,45.282.0,58.301.0"}
P.entries["item:scavenged-goods"] = {n="Зібрані Припаси",s="Зібрані Припаси — різноманітні уламки покинутого спорядження й запасів, спаковані в ящики довкола Похоронного Подзвону. Щойно підняті Відступники збирають їх, щоб нескінченний потік нових новобранців було чим озброїти й одягти.",h="Зібрані Припаси — різноманітні уламки покинутого спорядження й запасів, спаковані в ящики довкола Похоронного...",kw={"зібрані припаси","спорядження","вартовий смерті салтейн","похоронний подзвін","новобранці","відступники"},ang={["race:Undead"]="Для Відступників збирання покинутого спорядження — необхідність виживання, що закріплює сувору правду: живі не дадуть їм ні допомоги, ні милосердя."},sec={{t="Самі за себе",b="Коли нові Відступники вилазять із землі на цвинтарі Похоронного Подзвону, вони прокидаються майже ні з чим, окрім зотлілого поховального савана. Сусідні поселення й королівства не дають нежиті жодної допомоги, тож вона цілком залежить від того, що зуміє роздобути. Вартовий Смерті Салтейн керує збиранням покинутої зброї, знарядь і одягу, захованих у ящиках по всьому селу, і роздає їх просто наступній партії піднятих новобранців."}},fp="15,225,22.454.0,34.236.0,28.111.0,33.178.0"}
P.entries["item:scavenger-paw"] = {n="Лапа Трупоїда",s="Лапи трупоїдів — відтяті кінцівки молодих облізлих вовків, що никають пагорбами Похоронного Подзвону. Щойно пробуджені Відступники збирають їх для місцевих доглядачів, які зшивають із них грубе захисне спорядження.",h="Лапи трупоїдів — відтяті кінцівки молодих облізлих вовків, що никають пагорбами Похоронного Подзвону.",kw={"лапа трупоїда","вовки-трупоїди","послушниця елрет","похоронний подзвін","броня","кравецтво"},ang={["profession:Tailoring"]="Грубе зшивання вовчих лап і крил кажанів, яким займається Послушниця Елрет, показує, як імпровізоване кравецтво підтримує молоді поселення Відступників.",["race:Undead"]="Прокинувшись із гниючою плоттю й майже без спорядження, ви часто починаєте зі збирання частин місцевих хижаків — це перший крок до броні, достатньої, щоб витримати небезпеки Тірісфалю."},sec={{t="Збита нашвидкуруч броня в Похоронному Подзвоні",b="Для щойно повернених у Похоронному Подзвоні ресурсів обмаль. Поки Погибель і Багряний Хрестовий Похід тиснуть на Тірісфаль, кожен клапоть шкури й кожна кістка йдуть у діло. Послушниця Елрет, якій дає настанови Жрець Тіні Сарвіс, збирає лапи місцевих вовків-трупоїдів разом із крилами кажанів, щоб шити придатний одяг і броню для розгублених Відступників, які щойно вийшли з могил."}},fp="13,213,27.397.0,33.148.0,23.144.0,24.140.0"}
P.entries["item:searing-collar"] = {n="Пекучий Нашийник",s="Пекучі Нашийники — обрядові обручі, які носять члени культу Палаючого Клинка, що ховаються в Череп-скелі в Дуроторі. Розжарені, щоб палити плоть носія, вони служать культистам для налаштування на демонічні сили.",h="Пекучі Нашийники — обрядові обручі, які носять члени культу Палаючого Клинка, що ховаються в Череп-скелі в...",kw={"пекучий нашийник","палаючий клинок","череп-скеля","культ","марґоз","дуротар"},ang={["class:Warlock"]="Чорнокнижники впізнають у Пекучих Нашийниках грубі, але дієві провідники, що спрямовують скверну просто в смертну плоть.",["race:Orc"]="Для орків, які прагнуть звільнити свій народ від спадщини демонічного рабства, культисти з такими нашийниками на порозі Дуротару — похмуре нагадування, що тінь нікуди не поділася."},sec={{t="Знаряддя скверни",b="У тінистій печері Череп-скелі, одразу на схід від Оргріммара, Палаючий Клинок збирається на темні обряди. Культисти, неофіти й горлорізи культу надягають на шиї Пекучі Нашийники, добровільно піддаючи себе пекучому жару, що таврує й обпалює шкіру. Відлюдник Марґоз вивчає ці жорстокі пристрої і припускає, що відчуття опіку й темні чари, вкладені в метал, напряму налаштовують носіїв на демонічні енергії. Дослідження нашийників показує: це вагомий канал демонічної скверни, що просочується в орче суспільство просто під носом в Орди."}},fp="14,216,25.614.0,25.179.0,24.141.0,41.175.0,41.159.0"}
P.entries["item:shaman-voodoo-charm"] = {n="Шаманський Вудуйський Оберіг",s="Шаманський Вудуйський Оберіг — темна обрядова дрібничка, яку носять шамани фурболгів Вузлошкірів глибоко в Курганному Лігві Бан'етіл. Випромінюючи мерзенну ауру, цей оберіг спрямовує неприродну магію, здатну відтяти дух сплячого друїда від його тіла.",h="Шаманський Вудуйський Оберіг — темна обрядова дрібничка, яку носять шамани фурболгів Вузлошкірів глибоко в...",kw={"шаманський вудуйський оберіг","вуду","шамани","вузлошкіри","фурболги","обен рейджклов","курганне лігво бан'етіл"},ang={["class:Druid"]="Для друїда оберіг — жахливе спотворення священної сплячки: темна магія ув'язнює сновидця у Смарагдовому Сні, а його тілом орудують, мов лялькою.",["race:NightElf"]="Знахідка цих оберегів у Курганному Лігві Бан'етіл відкриває, як глибоко Вузлошкіри споганили одне з найсвятіших спільних місць спочинку калдореїв."},sec={{t="Спотворена магія",b="Плем'я Вузлошкірів на Тельдрассилі впало в безумство й скверну, та в Курганному Лігві Бан'етіл його шамани володіють силами, що сягають далеко за звичайне лісове чаклунство. Цими дивними вудуйськими оберегами шамани навчилися виривати свідомість сплячого друїда зі смертного світу й безпорадно ув'язнювати її у Смарагдовому Сні. Відтявши душу від посудини, фурболги можуть оживити порожнє тіло й обертати шанованих захисників — нічних ельфів на бездумних вартових, що вирізають кожного, хто заходить у кургани."},{t="Розплутування прокляття",b="Коли жертвою цього обряду став друїд Обен Рейджклов, його дух опинився в пастці Сну, а оживлене тіло тероризувало глибини курганів. Сягнувши крізь заслону, Обен доручив шукачам пригод перебити шаманів Вузлошкірів й здобути один з їхніх вудуйських оберегів. Дослідивши мерзенні чари, вкладені в дрібничку, Обен сподівався розгадати покручене ремесло фурболгів і знайти спосіб розірвати пута на своїй викраденій плоті."}},fp="19,260,17.570.0,20.458.1,41.215.0,25.117.0,32.213.0,34.254.0"}
P.entries["item:shimmering-frond"] = {n="Мерехтливе Листя",s="Мерехтливе Листя — зразок із дивної світної рослини, що росте на Галявині Оракула в Тельдрассилі. Його незвичне світіння й мінлива аура виказують у ньому екзотичний вид, цілком чужий для віття Світового Дерева.",h="Мерехтливе Листя — зразок із дивної світної рослини, що росте на Галявині Оракула в Тельдрассилі.",kw={"мерехтливе листя","галявина оракула","деналан","озеро ал'амет","болото скорботи","східні королівства","ботаніка"},ang={["class:Druid"]="Поява зайшлої болотяної рослини, що буяє на новонародженому вітті Тельдрассила, — цікава природна аномалія, варта уваги будь-якого друїда.",["profession:Herbalism"]="Травники, що блукають Тельдрассилом, оцінять рідкісну стійкість, потрібну рослині з Болота Скорботи, щоб перетнути океан і прижитися в чужому ґрунті."},sec={{t="Зразок здалеку",b="Блукаючи зеленими шатрами довкола Галявини Оракула, мандрівники можуть натрапити на дивну рослинність із пульсівною сяйливою аурою. Зірване з цієї рослини листя неприродно ловить просіяне лісове світло й мерехтить яскравою життєвою силою. Деналан, ботанік, що доглядає свої грядки біля Озера Ал'Амет, одразу впізнає в листі вид, корінний для далекого Болота Скорботи у Східних Королівствах. Як насіння з болота, що лежить так далеко за Великим морем, зуміло вкоренитися й розквітнути на новопосталому Тельдрассилі, лишається інтригівною загадкою, і Деналан береться проростити й вивчити зразки у власному ґрунті."}},fp="16,244,20.650.0,42.208.0,42.194.0,47.264.0,47.151.0"}
P.entries["item:shimmerweed"] = {n="Мерехтрава",s="Мерехтрава — особлива трава, яку тролі Морозогриви вирощують на Мерехтливому Хребті, серед засніжених висот Дун Мороґу. Тролі збирають її для власних племінних ритуалів, а місцеві дворфійські бровари жадають її гострого, неповторного смаку для експериментальних елів.",h="Мерехтрава — особлива трава, яку тролі Морозогриви вирощують на Мерехтливому Хребті, серед засніжених висот...",kw={"мерехтрава","трава","морозогриви","мерехтливий хребет","реджолд барліброю","село брюнолл","стаут"},ang={["profession:Herbalism"]="Хоч мерехтрава й не входить до стандартного набору польового ботаніка, вона показує, як місцеву флору часто пристосовують і до тутешніх броварських традицій, і до ритуальної алхімії.",["race:Dwarf"]="Вірно дворфійській винахідливості: якщо на сусідній скелі росте дивна рослина, хтось урешті спробує зробити з неї пиво."},sec={{t="Троляча культура",b="Високо над низинами Дун Мороґу тролі Морозогриви доглядають грядки мерехтрави вздовж крижаних скель Мерехтливого Хребта. Тролі збирають рослину й зберігають її в плетених кошиках, розкиданих по їхніх таборах, покладаючись на неї у своїх священних і загадкових ритуалах. Поза тролячим суспільством мало хто з горян зважає на це зілля, хоча його потужні властивості привернули погляд винахідливих чужинців."},{t="Таємний інгредієнт",b="У сусідньому Селі Брюнолл броварник Реджолд Барліброю зацікавився травою не на жарт. Переконаний, що броварство в нього в крові, Реджолд прагне зварити довершений дворфійський стаут і підозрює, що різкий, неповторний смак мерехтрави може виявитися тим, чого бракувало. Він раз у раз наймає відчайдушних мандрівників, щоб ті прослизнули до таборів Морозогривів, обминули ворожих тролів і притягли оберемки трави, яку він кине до своїх бродильних чанів."}},fp="11,252,15.413.0,19.442.0,28.203.0,49.250.0,44.263.0,50.237.0"}
P.entries["item:simple-memorandum"] = {n="Проста Службова Записка",s="Проста Службова Записка — офіційне повідомлення, яке вручають гномам-воїнам-новачкам, що навчаються в Долині Холодного Хребта. Написана від імені наставника воїнів Трана Кормана, вона наказує новачкам з'явитися до нього в Анвілмар, щоб удосконалити бойову дисципліну.",h="Проста Службова Записка — офіційне повідомлення, яке вручають гномам-воїнам-новачкам, що навчаються в Долині...",kw={"проста службова записка","воїн","тран корман","гноми","анвілмар","долина холодного хребта","гномреґан"},ang={["class:Warrior"]="Ця записка — перший крок воїна від простих сутичок до офіційного бойового навчання під проводом Трана Кормана в Анвілмарі.",["race:Gnome"]="Для гномів-вигнанців записка — нагадування про спільну мету: відточувати бойові навички пліч-о-пліч з дворфійськими союзниками, готуючись до майбутнього визволення Гномреґану."},sec={{t="Виклик до Анвілмара",b="Шукачам пригод-новачкам у Долині Холодного Хребта часто довіряють рекомендаційні листи, щойно вони покажуть свою вправність проти місцевої звірини й трогів. Для молодих гномів-бійців ця записка — офіційний виклик від Трана Кормана, наставника воїнів в Анвілмарі. Дворфійські ветерани визнають: хоч гноми й покладаються на розум і пристрої, повернути Гномреґан удасться лише завдяки чистій фізичній рішучості й бойовій дисципліні. Записка велить власникові відкласти попередні доручення й шукати особистих настанов у мистецтві війни."}},fp="17,254,21.599.0,30.160.0,32.151.0,49.194.0,39.260.0"}
P.entries["item:simple-rune"] = {n="Проста Руна",s="Проста Руна — кам'яний знак із написом, який вручають дворфам-воїнам-новачкам, що навчаються в Долині Холодного Хребта. Це виклик від наставника воїнів Трана Кормана, який велить новобранцям шукати настанов в Анвілмарі.",h="Проста Руна — кам'яний знак із написом, який вручають дворфам-воїнам-новачкам, що навчаються в Долині...",kw={"проста руна","воїн","тран корман","анвілмар","долина холодного хребта","дворфи","вишкіл"},ang={["class:Warrior"]="Для дворфійських воїнів цей камінь із написом — перший крок до офіційного військового вишколу під проводом досвідченого наставника Трана Кормана.",["race:Dwarf"]="Дворфи традиційно покладаються на міцні руни з написами для наказів, нагадувань і бойових викликів, а не на крихкий пергамент."},sec={{t="Заклик до зброї",b="Просту Руну з вирізьбленими базовими бойовими знаками вручають перспективним новобранцям, які почали розчищати загрози довкола Долини Холодного Хребта. Це не магічний оберіг, а офіційний камінь-виклик від Трана Кормана, наставника воїнів в Анвілмарі. Прочитавши вирізьблені настанови, молодий боєць має з'явитися просто до Трана, щоб опанувати основи бою й почути практичні поради, як вижити серед ворожих пустищ Дун Мороґу."}},fp="11,227,17.463.0,39.198.0,26.145.0,32.102.0"}
P.entries["item:simple-sigil"] = {n="Простий Сигіл",s="Простий Сигіл — скромний навчальний знак, який вручають новачкам-воїнам — нічним ельфам у Тінедолі. Принесений як виклик від наставниці воїнів Алііссії, він позначає офіційне долучення молодого бійця до збройного захисту Тельдрассила.",h="Простий Сигіл — скромний навчальний знак, який вручають новачкам-воїнам — нічним ельфам у Тінедолі.",kw={"простий сигіл","воїн","алііссія","консерватор ілталайн","тінедол","тельдрассил","фералас"},ang={["class:Warrior"]="Для калдорейських воїнів цей простий знак — ваша найперша грамота, що знайомить вас із бойовими традиціями, потрібними для захисту Тельдрассила.",["race:NightElf"]="Сигіл підкреслює нагальність становища калдореїв: наставниці на кшталт Алііссії набирають усі здатні руки, щоб спинити дедалі більшу скверну у вітті Світового Дерева."},sec={{t="Поклик до зброї",b="У затишному вітті Тінедолу молодих нічних ельфів веде до їхнього покликання Консерватор Ілталайн. Майбутнім воїнам Ілталайн вручає Простий Сигіл, надісланий гінцем від наставниці воїнів Алііссії. Із написом, що велить новобранцеві з'явитися на навчання, цей знак — початок дисциплінованого бойового вишколу в тривожний для Світового Дерева час."},{t="Тягар Захисту",b="Принесений Алііссії, сигіл відкриває розмову про нагальний стан калдореїв. Нещодавнє зростання Тельдрассила, повзуча скверна, що вражає лісових звірів, і віднайдення далеких земель на кшталт Фераласа розтягли сили захисників нічних ельфів до краю. Сигіл — не артефакт сили, а практична грамота, що приймає новобранця до лав охоронців, яким доручено затуляти свій народ від нових загроз."}},fp="12,238,17.413.0,21.439.0,25.188.0,27.178.0,25.126.0,43.102.0"}
P.entries["item:simple-tablet"] = {n="Проста Табличка",s="Проста Табличка — письмове послання, яке отримують тролі-воїни-новачки, прибувши в Долину Випробувань. Передана Ґорнеком, вона велить бійцю-початківцю з'явитися до Франґа, тутешнього наставника воїнів.",h="Проста Табличка — письмове послання, яке отримують тролі-воїни-новачки, прибувши в Долину Випробувань.",kw={"проста табличка","воїн","франґ","ґорнек","тар'сере","долина випробувань"},ang={["class:Warrior"]="Табличка — офіційне знайомство троля-воїна з Франґом, з якого починається його бойовий вишкіл в Орді.",["race:Troll"]="Для тролів Темного Списа, що виборюють своє місце поряд з орками в Дуроторі, цей виклик означає обов'язок поповнити лави на передовій."},sec={{t="Поклик до бою",b="У суворих червоних межах Долини Випробувань новобранців швидко беруть у роботу. Молодим тролям, що шукають шляху воїна, Ґорнек передає цю просту плитку чи пергамент. Написана тролем Тар'сере і адресована Франґу — майстру зброї, що відпочиває біля Лігва, — вона слугує офіційним вступом до бойового вишколу в Дуроторі. Вона закликає новобранця виступити вперед, назватися й довести готовність махати зброєю під стягом Орди."}},fp="13,219,19.491.0,26.186.0,21.147.0,27.113.0,25.118.0"}
P.entries["item:stalker-claws"] = {n="Кігті Переслідувача",s="Кігті Переслідувача — пазурі, здобуті зі степових переслідувачів, що блукають хвилястими рівнинами Малгору. Шамани тауренів використовують їх як важливі складники, вирізьблюючи традиційні очисні тотеми для очищення осквернених водяних криниць.",h="Кігті Переслідувача — пазурі, здобуті зі степових переслідувачів, що блукають хвилястими рівнинами Малгору.",kw={"кігті переслідувача","степовий переслідувач","тотем","малл тандергорн","криниця тандергорнів","гобліни","малгор"},ang={["class:Shaman"]="Кігті диких рівнинних хижаків уособлюють люту чистоту природи — неодмінний матеріал для зв'язування й наснаження очисних тотемів.",["race:Tauren"]="Збирання цих кігтів служить священному обов'язку вашого племені — відновити святі води, отруєні безоглядними промисловими зайдами."},sec={{t="Хижаки рівнин",b="Трав'янисті степи Малгору — домівка смертоносних природних хижаків, серед них і потайних степових переслідувачів. Ці звірі живуть первісним інстинктом і смертельною точністю — неодмінна рівновага в задумі Матері-Землі. Малл Тандергорн, прагнучи зцілити вражену землю, потребує цих кігтів не зі злості на звірів, а тому, що чиста природна лють, з якою вони полюють, має духовний відгук, здатний протидіяти штучній скверні."},{t="Очищення криниць",b="Коли підприємства гоблінів почали бурити й копати по всьому центральному Калімдору, хімічні отрути просочилися глибоко в підземні води, що живлять прабатьківські криниці тауренів. Особливо постраждала Водяна Криниця Тандергорнів, уражена мерзенною скверною. Зв'язавши Кігті Переслідувача й Кігті Пуми в Очисний Тотем Громорога, племінні шамани створюють духовний провідник, здатний вичистити бруд і неприродний мул із природних джерел землі."}},fp="13,218,23.477.0,19.437.0,33.127.0,43.214.0,42.165.0,42.162.0"}
P.entries["item:steelgrill-s-tools"] = {n="Інструменти Стілґрила",s="Інструменти Стілґрила — спеціалізований набір механічного знаряддя, замовлений для Белдіна Стілґрілла, головного техніка Складу Стілґрила. Белдін, відомий тим, що жене облогові машини — й власне обладнання — на межу можливостей, часто ламає інструменти й залежить від постачання з сусіднього Хараноса, щоб його майстерня працювала.",h="Інструменти Стілґрила — спеціалізований набір механічного знаряддя, замовлений для Белдіна Стілґрілла...",kw={"інструменти стілґрила","белдін стілґрілл","склад стілґрила","облогові машини","харанос","інженерія","пілот стоунґір"},ang={["profession:Engineering"]="Кожен інженер поспівчуває скруті Белдіна: ремонт важких облогових машин із великими зусиллями регулярно забирає дугові ключі й тонкі гайкові ключі.",["race:Dwarf"]="Утримувати броньовані облогові машини Альянсу — справа дворфійської гордості, і постачання Белдіна гарантує, що броньований авангард Айронфорджа лишається боєздатним."},sec={{t="Майстер із важкою рукою",b="Белдіна Стілґрілла широко вважають одним із найкращих техніків облогових машин у Дун Мороґу, але його напористий стиль ремонту сумнозвісний серед місцевих торговців. Невтомно працюючи над броньованими танками й механічними пристроями, Белдін нищить тонке обладнання майже так само швидко, як його встигають викувати. Ламаючи дугові ключі й зриваючи зубчасті тріскачки, механік без упину робить нові замовлення в Хараносі, щоб його ремонтні верстаки не порожніли."},{t="Щоб машини їхали",b="Ця партія інструментів життєво важлива, щоб бойові машини Айронфорджа лишалися на ходу. На своєму складі на північний схід від Хараноса Белдін обслуговує бойові машини для досвідчених водіїв, як-от Пілот Стоунґір. Без свіжого запасу гайкових ключів і тріскачок важливі облогові машини стояли б напівзібраними в снігу, і зупинилися б і склад, і місцева оборона."}},fp="18,328,24.468.0,27.376.0,37.220.0,52.224.0,40.154.0,25.174.0"}
P.entries["item:stormwind-armor-marker"] = {n="Талон на Обладунок Стормвінда",s="Талон на Обладунок Стормвінда — офіційний військовий реквізиційний знак, який видають шукачам пригод, що допомогли королівству. Його можна обміняти в уповноважених ремісників, як-от Сара Тімберлейн у Лісозаготівельному Таборі Східної Долини, на щойно виготовлене спорядження.",h="Талон на Обладунок Стормвінда — офіційний військовий реквізиційний знак, який видають шукачам пригод, що...",kw={"талон на обладунок","реквізиція","сара тімберлейн","східна долина","обладунок","стормвінд"},ang={["faction:Alliance"]="Талон утілює господарські зв'язки, що напряму з'єднують прикордонні поселення на кшталт Лісозаготівельного Табору Східної Долини з військовим командуванням Стормвінда."},sec={{t="Військові реквізиції",b="Підтримання закону й порядку по всьому Лісі Елвінн виснажує ресурси королівства. Замість роздавати стандартне спорядження просто з військових застав, командири часом видають офіційні знаки, відомі як талони на обладунок. Ці реквізиційні квитки засвідчують, що носій доблесно послужив Стормвінду, й уповноважують місцевих найнятих майстрів забезпечити його підігнаним обладунком."},{t="Постачання Східної Долини",b="Одне з головних місць, куди несуть ці талони, — Лісозаготівельний Табір Східної Долини на східному рубежі Елвінну. Там ремісники на кшталт Сари Тімберлейн працюють за замовленням війська Стормвінда, перетворюючи місцеві матеріали на захисний одяг із тканини й шкіри. Пред'явивши талон, новобранці отримують підігнаний захист, що допоможе їм берегти довколишні ліси."}},fp="22,251,21.397.0,21.379.0,50.208.0,23.204.0,69.259.0,47.137.0"}
P.entries["item:strigid-owl-feather"] = {n="Перо Стригідної Сови",s="Пера Стригідної Сови збирають із диких сов-стригід, що гніздяться у вітті Тельдрассила. Хоч це природне лісове пір'я, його шукають сумнівні постаті, яким потрібна сировина для таємних оборудок.",h="Пера Стригідної Сови збирають із диких сов-стригід, що гніздяться у вітті Тельдрассила.",kw={"перо стригідної сови","сова-стригіда","пір'я","зенн фаулгуф","сатир","доланаар","тельдрассил"},ang={["class:Druid"]="Друїди високо шанують крилатих мисливців Тельдрассила, тож бачити, як їхнє пір'я збирають під облудним приводом на підозрілі складники, — прикро.",["race:NightElf"]="Сов Тельдрассила мають за створіння Елуни, тож їхній визиск застарілим сатиром на кшталт Зенна Фаулгуфа — образа священному лісу."},sec={{t="Лісове пір'я й темні оборудки",b="У шатрах Тельдрассила живуть сови-стригіди й верескуни — корінні хижі птахи, що полюють по всій Короні Землі. Їхній пух і пера — звична знахідка на лісовій долівці, та часом вони привертають око тих, хто шукає живі складники. За Доланааром сатир-відступник Зенн Фаулгуф користається з недосвідчених мандрівників, що спускаються дорогою з Тінедолу, і підбурює їх здобувати пера стригід разом із павутинним шовком та іклами нічних шаблезубів для своїх тіньових справ."}},fp="19,226,32.519.1,38.139.0,31.160.0,45.165.0"}
P.entries["item:sully-balloo-s-letter"] = {n="Лист Саллі Баллу",s="Лист Саллі Баллу — розмокле, ніжне послання, знайдене біля затонулих останків дворфійського воїна під Мостом Тандол. Адресований його дружині Сарі в Айронфорджі, він утілює тихі особисті трагедії, що ховаються за великими конфліктами Каз Модану.",h="Лист Саллі Баллу — розмокле, ніжне послання, знайдене біля затонулих останків дворфійського воїна під Мостом...",kw={"лист саллі баллу","саллі баллу","сара баллу","міст тандол","удова","айронфордж","багнокрай"},ang={["faction:Alliance"]="Доставити лист — скорботна мить співчуття: останні думки полеглого воїна дійдуть до його вдови, а не будуть забуті під мостом.",["race:Dwarf"]="Для дворфів цей лист утілює болісні жертви, на які йдуть звичайні горяни й воїни, щоб стерегти високі мости й гірські перевали Каз Модану."},sec={{t="Останнє прощання під хвилями",b="Під велетенськими кам'яними опорами Мосту Тандол, що з'єднує Багнокрай з Аратійським нагір'ям, лежить скелет дворфа, придавлений глибоко під бурхливою водою. У його руці затиснутий крихкий, розмоклий конверт із цим листом. Написаний із болісною старанністю в його останні дні чи години, він починається зворушливими словами: «Моя люба Саро…». Хоч пергамент і постраждав від довгого перебування у воді, чорнило досі береже незгасну любов дворфійського захисника, який так і не повернувся додому, до міста Айронфордж."},{t="Доставка до Айронфорджа",b="Принести лист Сарі Баллу в Айронфордж — означає принести їй скорботне, спустошливе завершення. Живучи в дворфійській столиці, Сара зносить болісну невідомість, знайому багатьом, чиї рідні пішли на війну. Останні думки її чоловіка Саллі підтверджують найгірші побоювання — він загинув далеко від дому, під крижаними течіями північної переправи, — але й зберігають його відданість, що пережила смерть."}},fp="21,272,34.545.0,21.404.1,37.212.0,21.178.0,31.130.0,56.203.1"}
P.entries["item:surena-s-choker"] = {n="Намисто Сурени",s="Намисто Сурени — зачароване намисто з кровавика, яке Ґакін Зв'язувач Темряви подарував своїй колишній учениці Сурені Каледон. Після того як Сурена зрадила Ґакіна й утекла до Братства Дефіас, майстер-чорнокнижник послав послушників-початківців силою повернути прикрасу.",h="Намисто Сурени — зачароване намисто з кровавика, яке Ґакін Зв'язувач Темряви подарував своїй колишній учениці...",kw={"намисто сурени","сурена каледон","ґакін","ерлан драджмур","братство дефіас","кровавик"},ang={["class:Warlock"]="Повернення цього намиста від Сурени Каледон — засадниче випробування для чорнокнижників із людей і гномів: доказ того, що сентиментам немає місця в гонитві за демонічною силою."},sec={{t="Утрачений вклад майстра",b="Ґакін Зв'язувач Темряви, що тихо працює під «Зарізаним Ягням» у Стормвінді, узяв Сурену Каледон перспективною ученицею темних мистецтв. Зачарований її юною привабливістю й магічним хистом, Ґакін подарував їй цінне намисто з кровавика на поміч у навчанні. Та Сурена покинула навчання й утекла з Ерланом Драджмуром, розбійником, пов'язаним із Братством Дефіас. Не бажаючи лишати такий могутній артефакт у руках зрадниці, Ґакін доручає новачкам, що прагнуть влади над порожнечею, вистежити Сурену на Гарбузовій Ділянці Брекуеллів, повернути намисто й показати, де лежить справжня вірність."}},fp="15,266,26.637.0,56.237.0,22.241.0,30.146.0,50.245.0"}
P.entries["item:tainted-heart"] = {n="Опоганене Серце",s="Опоганене Серце — уражене пошестю рослинне осердя, видобуте зі споганеної рослинності Тельдрассила. Передане шукачам пригод ботаніком Деналаном, воно потребує магічного й живильного очищення, щоб позбутися залишків огидних сил.",h="Опоганене Серце — уражене пошестю рослинне осердя, видобуте зі споганеної рослинності Тельдрассила.",kw={"опоганене серце","осквернене осердя","деналан","скверна","грядка","ґрунт","тельдрассил"},ang={["class:Druid"]="Для друїдів Кола Кенарія робота над очищенням Опоганеного Серця дає пряме розуміння повзучої скверни, що загрожує здоров'ю молодого Світового Дерева.",["profession:Herbalism"]="Травники й ботаніки оцінять майстерність Деналана в змішуванні особливо збагаченого ґрунту, здатного витягати неприродну гниль із живої рослинної тканини."},sec={{t="Осквернене Осердя",b="Природна рівновага Тельдрассила потерпає від неприродної недуги, що спотворює корінні рослини й звірів. Зчистивши огидний мох, який обліпив уражений наріст, Деналан показує залишене осердя — Опоганене Серце. Хоч і звільнене від зовнішньої гнилі, воно досі просякнуте темрявою. Деналан прагне з'ясувати, чи може особливо приготована, багата на поживу земля побороти залишки скверни й повернути життя споганеному."},{t="Ліки Деналана",b="Покладене в зачаровану грядку Деналана, серце виявляє дивну, невгасиму життєву силу. Воно жадібно вривається в багатий ґрунт і вбирає цілющу поживу. За мить земля випалює скверну, і очищене серце постає живим, пульсуючи чистою силою й пориваючись захищати тих, хто його зцілив."}},fp="13,219,16.438.0,16.326.1,26.180.0,31.187.0,33.166.1,46.143.0"}
P.entries["item:tainted-letter"] = {n="Опоганений Лист",s="Опоганений Лист — потай доставлений виклик із печаткою Друзілли Ла Салль, наставниці чорнокнижників, що ховається на околиці Абатства Нортшира. Він велить майбутнім людям-практикам темних мистецтв з'явитися до неї по особливу науку подалі від пильних очей.",h="Опоганений Лист — потай доставлений виклик із печаткою Друзілли Ла Салль, наставниці чорнокнижників, що...",kw={"опоганений лист","друзілла ла салль","чорнокнижник","абатство нортшира","виклик","скверна"},ang={["class:Warlock"]="Опоганений Лист знаменує ваше офіційне знайомство з тіньовим ремеслом у Королівстві Стормвінд і встановлює, що влада над Безоднею вимагає постійної пильності й обачності.",["race:Human"]="Людське суспільство загалом сповідує Святе Світло, тож практикам темної магії доводиться проводити свої посвяти й навчання потай, на узбіччі таких місць, як Абатство Нортшира."},sec={{t="Таємний виклик",b="Поки жерці, паладини й звичайні солдати відкрито навчаються на доглянутих галявинах Абатства Нортшира, практикам магії скверни доводиться діяти значно обережніше. Цей лист, що його вручають новачкам, які повертаються з сусідніх виноградників і копалень, повних шкідників, несе особистий знак Друзілли Ла Салль. Позначене ледь відчутними слідами темного ремесла, послання велить чорнокнижникам-початківцям непомітно розшукати свою наставницю біля земель абатства, перш ніж тутешня варта й клірики запідозрять їхній заборонений шлях."},{t="Ціна амбіцій",b="Зустріч із Друзіллою пояснює потребу в такій потайності. Простий люд Елвінну дивиться на чорнокнижників із глибокою недовірою, тож наставники мусять триматися околиць і уникати цікавих вартових. Друзілла використовує доставлений лист, щоб розпочати важливий урок дисципліни: таємна магія й магія Безодні ваблять невпинне розбещення, і практикам доводиться гамувати свої бурхливі амбіції терплячим самовладанням, спілкуючись із мешканцями Викривленого Нижнього Світу."}},fp="14,279,16.546.0,21.480.0,28.139.0,37.185.0,53.234.0,55.252.0"}
P.entries["item:tainted-memorandum"] = {n="Осквернений Меморандум",s="Осквернений Меморандум — непомітна записка, яку вручають гномам-чорнокнижникам-новачкам, що починають шлях у Долині Холодного Хребта. Написана наставником чорнокнижників Аламаром Гріммом, вона закликає читача відкинути традиційні шляхи й шукати справжньої сили, яку дають темні мистецтва.",h="Осквернений Меморандум — непомітна записка, яку вручають гномам-чорнокнижникам-новачкам, що починають шлях у...",kw={"осквернений меморандум","чорнокнижник","аламар грімм","гноми","анвілмар","гномреґан","скверна"},ang={["class:Warlock"]="Записка — ваше офіційне представлення наставникові чорнокнижників Аламару Грімму, який подає темний призов як необхідне прагнення до влади й контролю.",["race:Gnome"]="Послання Грімма грає на гномському обуренні через утрату Гномреґану та їхнє становище залежних біженців на дворфійських землях."},sec={{t="Непомітний виклик",b="У холодній дворфійській заставі Анвілмар тих, хто практикує магію скверни, не вітають і не надто їм довіряють. Для молодих гномів, що бавляться забороненими мистецтвами, Осквернений Меморандум — запрошення від Аламара Грімма. Послання відкидає опору на Святе Світло чи звичайну бойову сталь, натомість вказуючи на падіння Гномреґану як доказ того, що звичні методи й винахідництво підвели їхній народ. Для Грімма покладатися на дворфійську милостиню — глухий кут: гноми мусять здобути незаперечну силу й прикликати беззаперечно покірних поплічників, якщо сподіваються забезпечити собі майбутнє."}},fp="18,257,18.580.0,33.116.0,43.208.0,44.304.0"}
P.entries["item:tallonkai-s-jewel"] = {n="Самоцвіт Таллонкая",s="Самоцвіт Таллонкая — світний смарагд, украдений із зачарованого друїдського талісмана на Тельдрассилі. Ним дорожить містик фурболгів Фероцитас, Пожирач Снів, і саме він — ключове осердя, потрібне, щоб полагодити Смарагдовий Ловець Снів.",h="Самоцвіт Таллонкая — світний смарагд, украдений із зачарованого друїдського талісмана на Тельдрассилі.",kw={"самоцвіт таллонкая","смарагд","фероцитас","пожирач снів","смарагдовий ловець снів","таллонкай свіфтрут","вузлошкіри"},ang={["class:Druid"]="Смарагд — настроєна друїдська складова, створена резонувати зі Смарагдовим Сном, тож зловживання ним споганеними фурболгами — образа рівновазі.",["race:NightElf"]="Повернення самоцвіта допомагає відновити лад на Тельдрассилі, вирвавши священний виріб із рук напосідливої Вузлошкірів."},sec={{t="Украдене осердя",b="Таллонкай Свіфтрут створив Смарагдовий Ловець Снів як могутній осередок, настроєний на природу й царство сну. Коли талісман пошкодили, центральний сяйливий смарагд вийняли й понесли в нетрі східного Тельдрассила. Самоцвіт потрапив у лапи Фероцитаса, Пожирача Снів, — споганеного ватажка Вузлошкірів, який зробив із блискучого каменя власне намисто. Хоч зелений камінь кидав моторошне світло в лісовому присмерку, його справжній гармонійний відгук був фурболгові геть ні до чого, і доки самоцвіт не повернули, він лишався простим трофеєм."}},fp="17,232,13.559.0,26.155.0,28.128.0,49.173.0,46.152.0"}
P.entries["item:taming-rod"] = {n="Жезл Приборкання",s="Жезл Приборкання — навчальне знаряддя, яке наставники довіряють мисливцям-новачкам. Наділений простою зв'язувальною магією, він дає учневі тимчасово втихомирити тутешню звірину й керувати нею, щоб опанувати основи поводження зі звірами.",h="Жезл Приборкання — навчальне знаряддя, яке наставники довіряють мисливцям-новачкам.",kw={"жезл приборкання","мисливець","приборкання","тотар","гострий пагорб","звір","улюбленець"},ang={["class:Hunter"]="Жезл Приборкання — наріжний камінь обряду переходу кожного молодого мисливця, свого роду підпірка, доки ви не матимете природженої сили волі, щоб творити довічні зв'язки з дикими звірами.",["faction:Horde"]="У Дуроторі й Малгорі наставники на кшталт Тотара вживають ці жезли, щоб перевірити, чи мають молоді новобранці дисципліну, потрібну, щоб опанувати сувору звірину Калімдору."},sec={{t="Навчальне знаряддя наставника",b="Мисливці-новачки не можуть одразу прикласти силу волі, потрібну, щоб назавжди прив'язати дике створіння. Щоб здолати цей розрив, досвідчені наставники видають особливі Жезли Приборкання. У місцях на кшталт Гострого Пагорба наставники, як-от Тотар, дають майбутнім оркам і тролям-мисливцям ці зачаровані знаряддя, щоб приборкати тутешніх хижаків — лютих плямистих вепрів чи броньованих скорпідів. Жезл тимчасово втихомирює звіра, і приборкувач може вправлятися в командах і битися пліч-о-пліч із тваринним супутником без ризику, що передчасно виникне нерозривний первісний зв'язок."},{t="Крок до майстерності",b="Влада, яку дає Жезл Приборкання, швидкоплинна: зазвичай вона тримається недовго, доки магія не згасне. Кожен жезл налаштований на певні види диких звірів і слугує сходинкою в низці випробувань. Щойно новачок доводить, що здатен керувати різними дикими вдачами — від сумирних шукачів поживи до агресивних отруйних мисливців, — жезл повертають наставнику. Довівши правильну техніку, учень нарешті опановує природжене мистецтво приборкувати, прикликати й відпускати довічних супутників без будь-якого артефакту."}},fp="10,234,28.580.0,21.545.0,30.196.0,38.275.0,39.170.0,56.214.0"}
P.entries["item:the-collector-s-schedule"] = {n="Розклад Колекціонера",s="Розклад Колекціонера — рукописний графік із датами й часом незаконних перевезень золота, видобутого в копальнях Лісу Елвінн. Здобутий у тутешніх гнолів, документ відкриває, що невловима постать, відома лише як «Колекціонер», керує цією справою з-під Гарбузової Ділянки Брекуеллів.",h="Розклад Колекціонера — рукописний графік із датами й часом незаконних перевезень золота, видобутого в...",kw={"розклад колекціонера","золото","копальні","гарбузова ділянка","маршал дуґан","дефіас"},ang={["faction:Alliance"]="Розклад оголює, якою слабкою стала хватка Стормвінда на рідній землі: несанкціоновані ділки розкрадають природні багатства королівства просто за межами столиці.",["profession:Mining"]="Документ доводить, що попри звістки про бездіяльні копальні Елвінну, багаті жили золота активно спустошують і вивозять."},sec={{t="Крадене золото й таємні перевезення",b="Розклад дає тривожний доказ організованої діяльності просто під носом у гарнізону Стормвінда. Хоч королівство місяцями офіційно не розробляє копальні Елвінну через бандитство й напади чудовиськ, руду й далі планомірно видобувають і вивозять. У записці вказано конкретні дні й години, коли хтось на прізвисько «Колекціонер» приймає вантажі, і вона вказує на табір біля Гарбузової Ділянки Брекуеллів у східному Лісі Елвінн. Побачивши документ, Маршал Дуґан упізнає ім'я Колекціонера, та справжній замовник, що платить за крадене золото, лишається в тіні."}},fp="24,319,32.610.0,33.163.0,33.189.0,21.227.0,47.261.0"}
P.entries["item:thick-bear-fur"] = {n="Густе Ведмеже Хутро",s="Густе Ведмеже Хутро — цінна шкура, зібрана із загартованих холодом ведмедів, що блукають заметами Дун Мороґу. Її цінують за те, як вона тримає тепло, і мандрівні розвідники й воїни часто роблять із неї утеплення й теплу постіль проти лютого гірського морозу.",h="Густе Ведмеже Хутро — цінна шкура, зібрана із загартованих холодом ведмедів, що блукають заметами Дун Мороґу.",kw={"густе ведмеже хутро","ведмідь","шкура","пілот беловфіз","джетстім","склад стілґрила","сиве лігво"},ang={["class:Hunter"]="Похід у холодні хащі на ведмедів Дун Мороґу вчить молодих мисливців давати раду небезпечним гірським звірам і добувати міцні матеріали з дикої природи.",["race:Gnome"]="Гномські пілоти облогових танків, що працюють біля Складу Стілґрила, мусять покладатися на практичне полювання дворфійського краю, щоб їхні машини витримували довгі високогірні розгортання."},sec={{t="Тепло проти гірського морозу",b="Ведмеді, що никають хребтами Дун Мороґу, зносять одні з найсуворіших снігових полів Східних Королівств. Їхні густі, витривалі шуби надійно захищають від заметілей, тож шкура — безцінний ресурс і для місцевих, і для мандрівників. Ці важкі шкури не викидають як непотріб: мисливці регулярно їх збирають, щоб підбивати одяг, утеплювати продувні застави й підкладати під холодні спальні згортки."},{t="Постіль для Облогової Бригади",b="Коли Пілот Беловфіз почав споряджати свій облоговий танк Джетстім на Складі Стілґрила, перед ним постала сувора перспектива провести цілий місяць у полі на довгому завданні Облогової Бригади. Холодне залізо дає мало затишку серед високогірних заметів, тож він доручив місцевим розвідникам зібрати густе ведмеже хутро на снігових полях на південь від Сивого Лігва, щоб зробити теплу постіль для своєї кабіни."}},fp="14,263,33.420.0,29.411.0,36.207.0,39.226.0,45.164.0"}
P.entries["item:thunderhorn-cleansing-totem"] = {n="Очисний Тотем Громорога",s="Очисний Тотем Громорога — освячене ритуальне знаряддя, виготовлене Маллом Тандергорном у Селі Бладгуф. Воно наснажене магією предків, щоб очистити осквернені води Водяної Криниці Тандергорнів.",h="Очисний Тотем Громорога — освячене ритуальне знаряддя, виготовлене Маллом Тандергорном у Селі Бладгуф.",kw={"очисний тотем","громоріг","тандергорн","малл тандергорн","криниця","очищення","шаман"},ang={["class:Shaman"]="Шамани знають, що очисні тотеми — провідники, які втихомирюють стривожених духів природи й відновлюють рівновагу там, де сили стихій озлобилися.",["race:Tauren"]="Для тауренів очищення прабатьківських криниць — не буденна робота, а священний обов'язок перед Матір'ю-Землею та предками клану, що пильнують Малгор."},sec={{t="Очищення криниці Тандергорнів",b="По хвилястих рівнинах Малгору життєдайну кров землі забруднює незрима скверна. Прабатьківські криниці, викопані племенами тауренів, живлять стада й мисливські угіддя, та підлі речовини отруїли воду. За дорученням старійшини Малла Тандергорна шукачі пригод несуть цей підготовлений тотем на північ від Села Бладгуф, щоб вигнати забруднення, яке осіло над священним джерелом клану Тандергорнів. Через ритуальне закликання тотем заспокоює стривожених духів води й очищає прабатьківське місце."}},fp="27,211,30.543.0,55.239.0,22.170.0,29.115.0,43.221.1"}
P.entries["item:thurman-s-remains"] = {n="Рештки Турмана",s="Рештки Турмана — тілесні останки Турмана Аґаманда, здобуті на зруйнованих родинних млинах на півночі Галявин Тірісфалю. Колись заможний власник млинів, що переконав своїх робітників стати проти Погибелі, Турман піддався Чумі й никає колишнім маєтком рабом-нежиттю.",h="Рештки Турмана — тілесні останки Турмана Аґаманда, здобуті на зруйнованих родинних млинах на півночі Галявин...",kw={"рештки турмана","турман аґаманд","млини аґаманда","коулмен фартінґ","погибель","помста"},ang={["race:Undead"]="Для Відступників повернути ці рештки — похмуре зведення рахунків з аристократами-господарями, чия пиха привела їхніх робітників просто в лабети Погибелі."},sec={{t="Спадщина руїни",b="До Третьої війни родина Аґамандів була найзаможнішими землевласниками Галявин Тірісфалю: вона тримала великі млини й наймала десятки місцевих робітників. Коли Погибель прокотилася Лордероном, Турман Аґаманд із ріднею укріпив маєток замість тікати. Переконані, що багатство й укріплені млини витримають натиск, вони вмовили вірних робітників узятися за зброю поруч із ними. Оборона провалилася дощенту. Аґамандів і їхніх робітників вирізали й перетворили на безтямних слуг, якими володіє Король-Ліч. Нині Коулмен Фартінґ — колишній працівник, що повстав одним із Відступників, — вимагає знищити своїх колишніх господарів і хоче отримати рештки Турмана як доказ того, що нерозумний патріарх заплатив за загибель свого дому."}},fp="17,299,16.762.0,24.303.0,49.262.0,49.184.0,51.164.0"}
P.entries["item:timberling-seed"] = {n="Насінина Деревляника",s="Насінини Деревляника — рослинні зерна, здобуті зі збурених рослинних елементалів, що населяють Тельдрассил. Природознавці й друїди вивчають ці насінини, щоб зрозуміти, чому лісова рослинність стала незвично напасливою.",h="Насінини Деревляника — рослинні зерна, здобуті зі збурених рослинних елементалів, що населяють Тельдрассил.",kw={"насінина деревляника","деревляник","елементалі","деналан","релліан ґрінспайр","озеро ал'амет","скверна"},ang={["class:Druid"]="Споганене насіння — ранні застережні знаки неприродної скверни, що розповзається рослинними елементалями Тельдрассила, і важлива турбота для захисників Ценаріонського Анклаву.",["profession:Herbalism"]="Для ботаніків і збирачів трав вивчення насінин показує, як сильно стан ґрунту й розлита скверна впливають на дику рослинність."},sec={{t="Насіння неспокійного лісу",b="Деревляники Тельдрассила — природні елементалі, чия вдача відбиває рівновагу Світового Дерева. Останнім часом ці створіння стали ворожими й гнівними, тривожачи нічних ельфів, що доглядають віття. Травники на кшталт Деналана біля Озера Ал'Амет гадають, що корінь лиха — у ґрунті, і збирають насінини диких деревляників у надії, що вирощені в контрольованих, очищених умовах, вони дадуть лагідне потомство."},{t="Укорінена скверна",b="Спроби виростити лагідних деревляників наштовхуються на похмуру дійсність. Коли зразки насіння оглядають учені Кола Кенарія, як-от Релліан Ґрінспайр у Дарнасусі, виринають глибші проблеми. Насіння несе скверну споганеного батьківського роду, а отже, неспокій рослинних духів Тельдрассила — не просто поганий ріст, а глибинна скверна, що охоплює живий світ усього великого дерева."}},fp="15,221,26.434.0,19.399.1,26.181.0,31.121.0,39.179.0,54.213.1"}
P.entries["item:timberling-sprout"] = {n="Паросток Деревляника",s="Паростки Деревляника — молоді, щойно народжені рослинні елементалі, що вкорінюються біля берегів Озера Ал'Амет на Тельдрассилі. Навіть у найпершому зростанні ці паростки виявляють ознаки скверни, тож наглядачі — нічні ельфи виривають їх, перш ніж вони визріють у напасливих деревляників.",h="Паростки Деревляника — молоді, щойно народжені рослинні елементалі, що вкорінюються біля берегів Озера...",kw={"паросток деревляника","деревляник","сіянці","озеро ал'амет","скверна","тельдрассил","елементалі"},ang={["class:Druid"]="Для друїдів, настроєних на рослинність та елементалів Калімдору, бачити природних лісових духів, що проростають із ґрунту вже споганеними, — похмуре знамення для майбутнього Тельдрассила.",["race:NightElf"]="Молодим нічним ельфам, що починають навчання в Тінедолі, доручають вичищати ці паростки, щоб уберегти свій новий лісовий дім."},sec={{t="Уражені сіянці",b="Деревляники — рослинні духи, тісно пов'язані з природною життєвою силою Тельдрассила, та сіянці, що проростають уздовж Озера Ал'Амет, стривожили тутешніх нічних ельфів. Замість сходити здоровими і в злагоді з дикою природою, вони проростають уже споганеними й напасливими. Оскільки ці немовлята-паростки, схоже, не піддаються ні очищенню, ні природному зціленню, доглядачі біля Озера Ал'Амет мусять збирати й знищувати їх, щоб запобігти нестримному поширенню ворожих деревляників крихким віттям новопосадженого Світового Дерева."}},fp="17,274,18.514.0,35.117.0,63.257.0,46.243.0,48.135.0"}
P.entries["item:tirisfal-pumpkin"] = {n="Гарбуз із Тірісфалу",s="Гарбузи з Тірісфалю ростуть на зораних грядках, що їх тримає Хутір Соллідена — господарство вцілілих живих людей, які силкуються вижити на уражених галявинах. Відступники регулярно вчиняють набіги на ці поля, щоб постачати Королівському Аптекарському Товариству органічну сировину для його безнастанних хімічних варив.",h="Гарбузи з Тірісфалю ростуть на зораних грядках, що їх тримає Хутір Соллідена — господарство вцілілих живих...",kw={"гарбуз із тірісфалу","хутір соллідена","фермери","вартовий смерті сіммер","аптекар йогаан","реагенти"},ang={["faction:Alliance"]="Гарбузи, вирощені на Хуторі Соллідена, — відчайдушні зусилля вцілілого люду Лордерону прогодуватися серед постійних наскоків Відступників.",["race:Undead"]="Набіг на городи Соллідена слугує двом цілям: позбавити решту живих смертних харчу й дати Аптекареві Йогаану матеріал для темних досліджень Відступників."},sec={{t="Урожай на ураженій землі",b="Попри зіпсуття, що осіло на Лордероні, на полях на захід від Брілла все ж якось сходять посіви. На Хуторі Соллідена живі фермери-люди чіпляються за свою землю й вирощують величезні помаранчеві гарбузи, а неподалік пильнує Багряний Хрестовий Похід. Для цих смертних урожай — життєво важливий харч. Для Відступників із сусіднього Брілла гарбузи — водночас і злостива ціль для саботажу, і запас сирих органічних реагентів, потрібних Аптекареві Йогаану."},{t="Реагенти для аптекаря",b="Вартовий Смерті Сіммер посилає молодих Відступників на спірні поля цупити гарбузи просто з-під носа у фермерів. Замість годувати мертвих, ці овочі потрапляють у киплячі казани Королівського Аптекарського Товариства. Аптекарі раз у раз перевіряють, як природна флора реагує на їхні чуми й дослідні суміші, обертаючи рештки землеробства Лордерону проти живих."}},fp="16,289,26.481.0,19.421.0,37.123.0,42.202.0,47.129.0,30.144.0"}
P.entries["item:torch-of-the-dormant-flame"] = {n="Смолоскип Сплячого Полум'я",s="Смолоскип Сплячого Полум'я — обрядове знаряддя, яке молоді шамани Орди несуть під час єднання з вогнем у Дуроторі. Він чекає на перемогу над проявом полум'я на вершині гори і слугує посудиною, що має вловити первісний стихійний вогонь у Святилищі Вічного Полум'я.",h="Смолоскип Сплячого Полум'я — обрядове знаряддя, яке молоді шамани Орди несуть під час єднання з вогнем у...",kw={"смолоскип","спляче полум'я","шаман","вогонь","святилище вічного полум'я","прояв вогню","дуротар"},ang={["class:Shaman"]="Сплячий смолоскип утілює ще не доведений стан посвячуваного; лише здолавши живий прояв полум'я, шаман може запалити його й заслужити право прикликати Вогняний Тотем."},sec={{t="Посудина пробудження",b="Шаману, що шукає прихильності вогню, довіряють незапалений Смолоскип Сплячого Полум'я, перш ніж він зійде на вершини над Дуротаром. Випивши вогняну сапту, що відкриває духів, шаман бачить Малий Прояв Вогню на вершині гори й кидає йому виклик. Перемога над цим духом стихії дає сяйливий жар, який кладуть у вивітрену жаровню Святилища Вічного Полум'я. Дотик головки сплячого смолоскипа до білого полум'я, що спалахує, пробуджує дерево й перетворює його на палаючий знак влади над стихіями."}},fp="26,290,19.554.0,54.251.0,30.187.0,29.134.0"}
P.entries["item:torn-murloc-fin"] = {n="Подертий Плавець Мурлока",s="Подерті Плавці Мурлоків слугують доказом виконаної роботи за постійною винагородою війська Стормвінда за ворожих земноводних у східному Лісі Елвінн. Здобуті в збирачів і причаєних на берегах річки, вони засвідчують, що тутешні водойми планомірно очищають.",h="Подерті Плавці Мурлоків слугують доказом виконаної роботи за постійною винагородою війська Стормвінда за...",kw={"плавець мурлока","мурлоки","вартовий томас","винагорода","річка","елвінн"},ang={["faction:Alliance"]="Очищення водойм східного Елвінну убезпечує життєво важливі шляхи між Ґолдширом, Лейкширом і Стормвіндом.",["race:Human"]="Тутешня людська влада дедалі більше покладається на найманців, щоб захистити садиби й береги річок від агресивних поселень мурлоків."},sec={{t="Загроза під винагородою",b="Коли кількість мурлоків на струмках і озерах східного Елвінну різко зросла, військо Стормвінда дозволило пряму винагороду, щоб прорідити їхні лави. Вартовий Томас, що стоїть на мосту через східну річку, збирає ці відтяті плавці, щоб підтвердити вбивства. Поки військо Стормвінда розтягнуте між внутрішніми заворушеннями й загрозами в краї, тутешня влада значною мірою покладається на мандрівних шукачів пригод, які приносять речові докази очищених таборів."}},fp="15,258,17.457.0,38.117.0,50.154.0,41.154.0,50.165.0"}
P.entries["item:totem-of-hawkwind"] = {n="Тотем Гоквінда",s="Тотем Гоквінда — різьблений знак, який носять молоді таурени, що покидають Табір Нарачі. Поданий Бейну Бладгуфу в Селі Бладгуф, він доводить, що його власник завершив перші випробування й готовий пройти решту Обрядів Матері-Землі.",h="Тотем Гоквінда — різьблений знак, який носять молоді таурени, що покидають Табір Нарачі.",kw={"тотем гоквінда","вождь гоквінд","бейн бладгуф","табір нарачі","обряди","малгор"},ang={["race:Tauren"]="Нести цей тотем — означає остаточно пройти обряд переходу від дитинства на Плато Червоної Хмари до ширших племінних земель Малгору."},sec={{t="Схвалення вождя",b="Вирізьблений рукою Вождя Гоквінда на Плато Червоної Хмари, цей дерев'яний тотем слугує рекомендацією й доказом пройденого шляху для молоді, що входить у зрілість. У традиції тауренів офіційні грамоти майже не вживають; натомість волю ватажка несуть значущі символи й знайоме племінне ремесло. Коли юнак, що прагне визнання, завершує попередні випробування, Табір Нарачі проводжає його в дорогу: Гоквінд вирізьблює цей знак, щоб послати його далі, у широкі простори Малгору. Прикметне різьблення засвідчує перед Бейном Бладгуфом, що його власник має дух і силу, потрібні для наступних випробувань і майбутнього благословення Тандер Блафу."}},fp="17,282,25.648.0,39.201.0,19.179.0,35.120.0,36.242.0"}
P.entries["item:tough-wolf-meat"] = {n="Жорстке М'ясо Вовка",s="Жорстке М'ясо Вовка — сира дичина, здобута з хижих лісових вовків і молодих вовків, що нишпорять Долиною Нортширу й Долиною Холодного Хребта. Хоч воно грубе й жилаве, це основний харч для голодних мешканців на кшталт Іґана Пелтскіннера в Лісі Елвінн і дворфівських постачальників у Дун Мороґу.",h="Жорстке М'ясо Вовка — сира дичина, здобута з хижих лісових вовків і молодих вовків, що нишпорять Долиною...",kw={"м'ясо вовка","вовки","іґан пелтскіннер","нортшир","долина холодного хребта","пайок"},ang={["race:Dwarf"]="Дворфи Долини Холодного Хребта часто винищують обшарпаних лісових вовків заради м'яса, щоб забезпечити тутешніх постачальників, перш ніж вирушити через Дун Мороґ.",["race:Human"]="Для новобранців у Долині Нортширу збирання вовчого м'яса для Іґана Пелтскіннера — одне з найперших завдань на виживання поза тихими стінами абатства."},sec={{t="Прикордонний пайок",b="Вовки, що блукають околицями Долини Нортширу й Дун Мороґу, становлять постійну загрозу тутешнім поселенням, та водночас дають грубе джерело харчу. Жорстке М'ясо Вовка сумнозвісно жилаве й тверде порівняно з добірною дичиною, та нужденні мешканці рубежу однаково його цінують. Біля Абатства Нортшира Іґан Пелтскіннер ненавидить цих звірів за лютість, але залюбки смажить їхнє м'ясо на сільські стейки й охоче міняє основні припаси та спорядження кожному, хто готовий проріджувати зграї."}},fp="15,293,16.506.0,37.167.0,48.198.0,43.163.0,50.192.0"}
P.entries["item:tourmaline-phial"] = {n="Турмалінова Фіала",s="Турмалінова Фіала — особлива самоцвітна посудина, яку мандрівникам у Тельдрассилі дає Корітрас Мунрейдж. Нею набирають благословенну воду з місячного колодязя біля Озерець Арлітрієну в межах тривалих обрядів нагляду за віттям Світового Дерева та його заспокоєння.",h="Турмалінова Фіала — особлива самоцвітна посудина, яку мандрівникам у Тельдрассилі дає Корітрас Мунрейдж.",kw={"турмалінова фіала","місячний колодязь","озерця арлітрієну","корітрас мунрейдж","доланаар","дарнасус","вузлошкіри"},ang={["class:Druid"]="Носити особливі самоцвітні фіали по воду місячних колодязів — неодмінний обрядовий обов'язок молодих друїдів — нічних ельфів, що вчаться доглядати крихкий живий світ Тельдрассила.",["race:NightElf"]="Вода, зібрана в посудини на кшталт Турмалінової Фіали, уособлює опору нічних ельфів на ласку Елуни й друїдську пильність, поки Тельдрассил бореться зі скверною."},sec={{t="Посудина Арлітрієну",b="Корітрас Мунрейдж дає Турмалінову Фіалу на допомогу обрядам довкола Світового Дерева. Друїди в Доланаарі послуговуються такими особливими самоцвітними посудинами, щоб безпечно збирати чисту воду місячних колодязів з усього Тельдрассила. Цю фіалу призначено для місячного колодязя на берегах Озерець Арлітрієну, на південний схід від дороги до Дарнасуса, — у місцевості, яку дедалі дужче облягають ворожі фурболги Вузлошкірів."}},fp="16,274,20.421.0,38.205.0,34.115.0,37.117.0"}
P.entries["item:trophy-swoop-quill"] = {n="Трофейне Перо Стрімкокрила",s="Трофейне Перо Стрімкокрила — цінний мисливський знак, вискубаний у великих хижих птахів, що кружляють над рівнинами Малгору. Серед тауренів зібрані пера доводять гостре око, терпіння й мисливську вправність.",h="Трофейне Перо Стрімкокрила — цінний мисливський знак, вискубаний у великих хижих птахів, що кружляють над...",kw={"трофейне перо стрімкокрила","стрімкокрил","перо","гаркен віндтотем","мисливець","село бладгуф","малгор"},ang={["class:Hunter"]="Вистежувати крилату здобич над відкритими рівнинами — перевірка основ слідопитства, терпіння й влучності.",["race:Tauren"]="Полювати на стрімкокрила й приносити додому його пера — традиційне заняття, що вимагає терпіння й кмітливості по всьому Малгору й шанує і мисливця, і клан."},sec={{t="Знак полювання",b="Стрімкокрили — хитрі пернаті хижаки, рідні для Малгору: вони ширяють на високих висхідних потоках, і вистежити їх над луками непросто. Для молодих мисливців-тауренів і мандрівників, що прагнуть довести себе в Селі Бладгуф, здобути трофейне перо цих птахів — традиційний обряд кмітливості й рішучості. Подані старійшинам на кшталт Гаркена Віндтотема, ці пера шанують клан мисливця й засвідчують, що він має гострі чуття, потрібні, щоб процвітати на рівнинах."}},fp="18,223,17.498.0,38.219.0,39.163.0,44.191.0"}
P.entries["item:ukor-s-burden"] = {n="Тягар Укора",s="Тягар Укора — важкий пакунок харчів, який добродушний орк-пеон виніс із Гострого Пагорба. Призначені голодним новачкам у Долині Випробувань, непотрібні припаси треба віднести назад, доки пустельні скорпіди та раптори не вчули запаху.",h="Тягар Укора — важкий пакунок харчів, який добродушний орк-пеон виніс із Гострого Пагорба.",kw={"тягар укора","укор","пеон","припаси","гострий пагорб","ґроск","долина випробувань"},ang={["faction:Horde"]="Це доручення показує сувору культуру виживання, яку Орда Тралла насаджує в Дуроторі: навіть проста доброта має поступитися суворим випробуванням, що гартують нових солдатів."},sec={{t="Помилка з добрими намірами",b="Орки-пеони рідко діють з власної волі, тож доручення Укора незвичайне. Навантажившись харчами з корчми в Гострому Пагорбі, він пройшов крізь червоний пил і агресивну звірину Дуротару, щоб допомогти молодим новобранцям у Долині Випробувань. На його жаль, наглядачі й наставники відіслали його геть: вони вірять, що справжніх воїнів гартують злигодні й порожні животи. Застрягши біля входу в каньйон і боячись звірів, що чигають на зворотній стежці, Укор довірив мішок перехожим мандрівникам, щоб ті повернули його Корчмарю Ґроску."}},fp="13,258,26.548.0,29.242.0,45.227.0,33.198.0"}
P.entries["item:uncloven-satyr-hoof"] = {n="Нерозколоте Копито Сатира",s="Нерозколоте Копито Сатира — набрякле, суцільне копито, здобуте із сатирів, що причаїлися в Ашенвалі. Просякнуті спотвореною магічною енергією, висмоктаною з давнього лісу, ці похмурі трофеї — потужні складники для ремесла зброярів-тролів Темного Списа.",h="Нерозколоте Копито Сатира — набрякле, суцільне копито, здобуте із сатирів, що причаїлися в Ашенвалі.",kw={"копито сатира","сатири","ашенваль","ула'елек","сен'джин","рукавиці","скверна"},ang={["class:Warrior"]="Молодих воїнів, що шукають слави, наставники Орди спрямовують замовити особливі обладунки в Селі Сен'джин, а щоб довести бойову вправність — вистежити сатирів Ашенвалю.",["race:Troll"]="Ремісники Темного Списа на кшталт Ула'елека майстерно обертають темні чи ворожі енергії на корисне спорядження, висмоктуючи силу з демонічних ворогів, а не даючи їй пропасти марно."},sec={{t="Висмоктана сила",b="Сатири блукають оскверненими гаями північно-східного Ашенвалю, живлячись просто магічною чистотою давнього лісу. Поки вони жеруть цю сутність, скверна спотворює їхню демонічну будову: копита набрякають і втрачають природну розколину. Ці суцільні, нерозколоті копита стають щільними сховищами поглинутої енергії — летючої сили, яку вмілі шамани й шкіряники можуть видобути."},{t="Виготовлення жорстоких обладунків",b="На узбережжі Дуротару, в Селі Сен'джин, троль-зброяр Ула'елек знає, як обернути демонічну скверну на силу для чемпіонів Орди. Забираючи копита цих переситених сатирів, він висмоктує з них ув'язнену лісову магію і спрямовує викрадену силу в кування жорстоких латних рукавиць, покликаних захистити молодих воїнів від суворих випробувань Калімдору."}},fp="19,252,13.428.0,25.365.0,36.241.0,41.140.0,34.140.0,34.128.0"}
P.entries["item:venomtail-antidote"] = {n="Протиотрута Отрутохвоста",s="Протиотрута Отрутохвоста — особливе вариво, створене, щоб нейтралізувати смертельні токсини отрутохвостих скорпідів Дуротару. Приготована Кор'ґаном в Оргріммарі, вона слугує невідкладними ліками для Рінаґа — ураженого троля-розвідника, що застряг біля північно-західного кордону Дуротару.",h="Протиотрута Отрутохвоста — особливе вариво, створене, щоб нейтралізувати смертельні токсини отрутохвостих...",kw={"протиотрута","отрутохвіст","скорпід","кор'ґан","рінаґ","тіньова розколина","оргріммар"},ang={["faction:Horde"]="Навіть у серці Дуротару безжальна пустеля випробовує молодих шукачів пригод Орди і вимагає швидкої злагодженості між розвідниками в нетрях і міськими аптекарями.",["race:Troll"]="Троляча гордість глибока: Рінаґ радше ризикне померти на самоті в пустці, ніж стерпить відверті глузи Села Сен'джин через те, що його здолав скорпід."},sec={{t="Перегони з отрутою",b="Посушливі простори Дуротару кишать небезпечною звіриною, та для необережних мандрівників немає нічого небезпечнішого за тутешніх скорпідів. Глибокий укол отрутохвоста впорскує заразну отруту, здатну вбити дорослого воїна за годину. Коли троль Рінаґ дістав отруту далеко від допомоги біля північно-західного кордону, його єдиним порятунком були особливі ліки від Кор'ґана — аптекаря, що усамітнився глибоко в підземній Тіньовій Розколині Оргріммара."},{t="Ліки Кор'ґана",b="Щоб дістати протиотруту, треба пройти підземеллям Оргріммара й знайти Кор'ґана. Обізнаний у пустельних токсинах і суворих ліках, Кор'ґан готує флакон, щоб вигнати отруту, доки вона не стала смертельною. Доставлене вариво зупиняє дію отрути й рятує Рінаґа від принизливої смерті в нетрях, хоча Кор'ґан вимагає від розвідника подальших випробувань і полювань, аби спокутувати необережність."}},fp="18,270,24.475.0,15.418.0,40.225.0,33.182.0,52.214.0,55.199.0"}
P.entries["item:venomtail-poison-sac"] = {n="Отруйний Мішечок Отрутохвоста",s="Отруйний Мішечок Отрутохвоста — орган, здобутий зі скорпідів, що водяться в посушливих просторах Дуротару. Хоч він містить заразний токсин, здатний знесилити необережного мисливця, це також ключовий складник дієвої протиотрути.",h="Отруйний Мішечок Отрутохвоста — орган, здобутий зі скорпідів, що водяться в посушливих просторах Дуротару.",kw={"отруйний мішечок","отрутохвіст","скорпід","отрута","рінаґ","протиотрута","дуротар"},ang={["class:Hunter"]="Біда Рінаґа — наочний урок для мисливців: переслідувати небезпечних звірів, не знаючи їхньої отрути й не маючи при собі належних ліків, може легко коштувати слідопиту життя.",["faction:Horde"]="Молоді шукачі пригод Орди, пізнаючи сувору дійсність Дуротару, швидко з'ясовують: виживання вимагає розуміння звірини, бо тутешні токсини легко вбивають тих, хто кидається в червону пустку непідготованим."},sec={{t="Смертельний токсин і ліки від нього",b="Скорпіди, що нишпорять червоними скелями Дуротару — насамперед Отрутохвостий Скорпід, а також мутовані різновиди на кшталт Спотвореного Скорпіда й горезвісного Смертоздирача, — виробляють швидкодійну знесилювальну отруту. Збережена в особливих мішечках у хвості, ця отрута без лікування може швидко здолати навіть досвідчених воїнів. За іронією, ті самі мішечки, що завдають смертельного уколу, містять головні сполуки для синтезу протиотрути. Коли мисливець Рінаґ став жертвою уколу біля Оргріммара, місцевим алхімікам знадобилося чотири свіжі отруйні мішечки, щоб приготувати ліки й нейтралізувати отруту в його жилах."}},fp="20,263,29.642.0,39.181.0,32.206.0,42.159.0"}
P.entries["item:venture-co-documents"] = {n="Документи Венчурної Компанії",s="Ці туго перев'язані папери знайдено в ящику серед решток розгромленого каравану на сході Малгору. Вони описують діяльність Венчурної Компанії й підтверджують, що хижий картель незаконно веде відкриті розробки на батьківщині тауренів.",h="Ці туго перев'язані папери знайдено в ящику серед решток розгромленого каравану на сході Малгору.",kw={"документи венчурної компанії","венчурна компанія","гобліни","морін клаудсталкер","розкопки","малгор"},ang={["profession:Mining"]="Папери знайдено разом із зразками сирих мінералів — доказ того, що передгір'я приховують багаті, ще не займані жили, готові до розробки.",["race:Tauren"]="Священну землю Матері-Землі оскверняють гоблінські машини. Доставлені папери допомагають старійшинам підтвердити розмах наруги й завдати удару у відповідь."},sec={{t="Докази визискування",b="Знайдені поверх видобутої руди й мінералів у рештках пограбованого воза, ці документи викривають розмах вторгнення Венчурної Компанії в Малгор. Відомий по всьому Калімдору безжальним вирубуванням лісів і нестримними розкопками, очолюваний гоблінами картель тихцем влаштував бурові й копальні застави у східних передгір'ях. Морін Клаудсталкер і таурени-скороходи спираються на ці захоплені реєстри, щоб оцінити загрозу своїм священним прабатьківським рівнинам і зібрати мисливців, аби вигнати зайд."}},fp="21,241,24.514.0,42.214.0,38.157.0,30.158.0,46.205.0"}
P.entries["item:verdant-note"] = {n="Зелена Записка",s="Зелена Записка — виклик, який вручають друїдам-новачкам із тауренів у Таборі Нарачі. Надіслана від імені наставника друїдів Ґарта Містраннера, вона наказує молодим посвяченим з'явитися на навчання й почати осягати обряди Матері-Землі.",h="Зелена Записка — виклик, який вручають друїдам-новачкам із тауренів у Таборі Нарачі.",kw={"зелена записка","друїд","ґарт містраннер","табір нарачі","мати-земля","таурени"},ang={["class:Druid"]="Цей пергамент знаменує ваше офіційне прийняття до друїдичної науки серед тауренів і початок довічної подорожі в єднанні з Матір'ю-Землею.",["race:Tauren"]="Для шу'гало друїдизм — прабатьківське покликання, безпосередньо пов'язане зі зціленням рівноваги їхніх священних мисливських угідь у Малгорі."},sec={{t="Поклик на шлях",b="Молоді таурени, що виявляють духовну спорідненість із природою, отримують Зелену Записку невдовзі після початку своїх випробувань на Плато Червоної Хмари. Коротке послання приносить гонець від Ґарта Містраннера, і воно велить посвяченому стати перед наставником там, де стоїть Табір Нарачі. Неспокійні духи й мінливі стихії почали тривожити Малгор, тож навчання нових друїдів стало для старійшин нагальним обов'язком."},{t="Науки Матері-Землі",b="Відгукнувшись на записку, посвячені вступають у глибші таємниці єднання з природою. Ґарт Містраннер застерігає молодих друїдів: хоч нічні ельфи поділяють той самий зв'язок із дикою природою, їхня прадавня гордість тримає їх на відстані й робить непривітними. Друїдизм тауренів зосереджений суто на шані до Матері-Землі: він учить посвячених слухати неспокійні голоси предків у землі й бути її живими знаряддями."}},fp="12,233,18.422.0,28.421.0,25.189.0,27.128.0,51.207.0,53.233.0"}
P.entries["item:verdant-sigil"] = {n="Зелений Сигіл",s="Зелений Сигіл — вирізьблений друїдський знак, який вручають молодим друїдам — нічним ельфам, що починають навчання в Тінедолі. Принесений як виклик від наставника друїдів Марданта Стронґоука, він позначає офіційний вступ новачка до науки Кола Кенарія під гілками Алдрассила.",h="Зелений Сигіл — вирізьблений друїдський знак, який вручають молодим друїдам — нічним ельфам, що починають...",kw={"зелений сигіл","друїд","мардант стронґоук","консерватор ілталайн","тінедол","алдрассил","смарагдовий сон"},ang={["class:Druid"]="Для молодих друїдів — нічних ельфів дістати Зелений Сигіл — традиційний перший обряд посвяти, що з'єднує простий догляд за лісом із дисциплінованою наукою Кола Кенарія.",["race:NightElf"]="Вручений під шатром Алдрассила, сигіл уособлює тривку традицію калдореїв настроювати свій дух на природний світ і охоронців Тельдрассила."},sec={{t="Поклик на шлях",b="У затишному вітті Тінедолу молоді нічні ельфи, що відчувають поклик дикої природи, дістають Зелений Сигіл від Консерватора Ілталайна. Надісланий посланцем від наставника Марданта Стронґоука, знак велить новачкам піднятися у віття великого дерева Алдрассил. Носити сигіл — офіційне запрошення залишити прості клопоти й розпочати серйозне навчання єднання з духами природи та глибоких таємниць Смарагдового Сну."},{t="Перший крок у Сон",b="Піднесений Мардантові Стронґоуку, сигіл посвячує молодого друїда в його довічне ремесло. Хоч новачки ще не готові ходити сонним трансом Смарагдового Сну, прийняття сигіла позначає початок їхнього наставництва. Під проводом Марданта посвячені вчаться тлумачити шепіт дикого краю й опановують перші мистецтва перевтілення й зцілення на службі Тельдрассилу."}},fp="13,283,21.462.0,29.403.0,41.250.0,32.163.0,44.161.0,61.229.0"}
P.entries["item:vile-familiar-head"] = {n="Голова Підлого Фаміліара",s="Голова Підлого Фаміліара — моторошний трофей, зібраний із диких бісівських створінь, що мешкають біля Ковену Палаючого Клинка в Долині Випробувань. Молоді чорнокнижники Орди збирають їх під проводом Рузана як доказ бойової готовності, перш ніж навчитися прив'язувати перших демонічних прислужників. Голови слугують похмурою перевіркою дисципліни і показують, що учень розуміє смертоносність істот, яких збирається прикликати.",h="Голова Підлого Фаміліара — моторошний трофей, зібраний із диких бісівських створінь, що мешкають біля Ковену...",kw={"голова фаміліара","фамільяр","біс","чорнокнижник","рузан","ковен палаючого клинка","долина випробувань"},ang={["class:Warlock"]="Збирання цих голів — найперший крок чорнокнижника до влади над Безоднею, що дає право прикликати біса й прив'язати його до служби.",["faction:Horde"]="Навіть на тренувальних землях Дуротару чорнокнижники практикують своє мистецтво на узбіччі, пам'ятаючи, що Орда стежить за їхніми демонічними пошуками з невигаслою підозрою."},sec={{t="Моторошний урок демонології",b="У випаленому сонцем каньйоні Долини Випробувань наставник чорнокнижників Рузан вимагає від новачків, що хочуть опанувати мистецтво прикликання, шість таких голів. Мерзенні фамільяри, що вештаються біля Ковену Палаючого Клинка, — злі вогняні біси, чий дрібний зріст приховує небезпечну стихійну хитрість. Рузан вимагає, щоб майбутні прикликачі зустріли цих бісів у бою й відрубали їм голови на доказ того, що здатні підкорити демонічне життя й керувати ним, а не бути подоланими. Оскільки чорнокнижників в Орді Тралла ледве терплять, вишкіл потребує надзвичайної обережності: безрозсудні новачки, що гинуть від власних заклять, лише поглиблюють ганьбу й підозру до тих, хто практикує темні мистецтва."}},fp="18,431,31.717.0,38.226.0,34.171.0,55.268.0,59.230.0"}
P.entries["item:vile-fin-scale"] = {n="Луска Темного Плавця",s="Луску Темного Плавця здобувають із племен мурлоків, що никають водними шляхами й північними берегами Галявин Тірісфалю. У Бріллі Королівське Аптекарське Товариство використовує ці витривалі біологічні зразки у своїх дослідженнях зі створення нищівної нової чуми.",h="Луску Темного Плавця здобувають із племен мурлоків, що никають водними шляхами й північними берегами Галявин...",kw={"луска темного плавця","мурлоки","королівське аптекарське товариство","аптекар йогаан","узбережжя","брілл"},ang={["faction:Horde"]="Очищення узбережжя від агресивних поселень мурлоків допомагає убезпечити околиці Галявин Тірісфалю для гінців і мандрівників Орди.",["race:Undead"]="Кожна зібрана луска темного плавця безпосередньо допомагає священному обов'язку Королівського Аптекарського Товариства — створити зброю, що забезпечить виживання Відступників проти живих і Погибелі."},sec={{t="Реагенти для аптекаря",b="Королівське Аптекарське Товариство невпинно працює над лютою пошестю, здатною винищити і живих, і Погибель. Прості отрути зварити легко, та щоб створити заразу, яка без зусиль ширитиметься серед населення, потрібні особливі алхімічні властивості. Аптекар Йогаан у Бріллі вивчає луску Темного Плавця саме для того, щоб зрозуміти, як її природна витривалість і слизові оболонки можуть допомогти стабілізувати й передавати його дослідну заразу."},{t="Загроза з узбережжя",b="Плем'я Темного Плавця заполонило північні береги й західні мілини Галявин Тірісфалю: воно загрожує мандрівникам і зазіхає на землі Відступників. Збирання їхньої луски слугує Андерсіті двом цілям: тримати здичавілих мурлоків у шорах і постачати лабораторії Йогаана свіжі органічні складники для випробувань біохімічної зброї."}},fp="14,262,19.488.0,20.357.0,45.252.0,36.168.0,60.249.0,44.132.0"}
P.entries["item:voodoo-charm"] = {n="Вудуйський Талісман",s="Вудуйський Талісман — містичний оберіг, яким у курганах Тельдрассила розривають лиховісні чари. Переданий шукачам пригод духом Обена Рейджклова, він дає змогу назавжди звільнити його споганене, кероване мов лялька тіло, щоб його душа спочила у Смарагдовому Сні.",h="Вудуйський Талісман — містичний оберіг, яким у курганах Тельдрассила розривають лиховісні чари.",kw={"вудуйський талісман","обен рейджклов","друїд пазура","вузлошкіри","фурболги","смарагдовий сон","кургани"},ang={["class:Druid"]="Для молодих друїдів, що навчаються на Тельдрассилі, вжити оберіг, щоб із милосердя вбити й звільнити брата, Друїда Пазура, — підкреслення трагічної вразливості того, хто лишає тілесну оболонку, мандруючи Смарагдовим Сном.",["race:NightElf"]="Існування цього оберега показує, як глибоко виродилися фурболги Вузлошкірів, обернувши священні курганні лігва калдореїв на місця потворного духовного ув'язнення."},sec={{t="Розрив темних пут",b="У глибинах курганних лігв Вузлошкірів на Тельдрассилі фурболги вдалися до огидної магії, щоб керувати сплячими тілами священних захисників калдореїв. Друїд Обен Рейджклов виявив, що його дух відділено від плоті, а тілесна оболонка поневолена чаклунством Вузлошкірів. Дослідивши цей зачарований оберіг, Обен розуміє: темну прив'язь, що тримає його живу посудину, не розвіяти простими традиційними молитвами. Натомість оберіг стає знаряддям остаточного звільнення: щойно його бездушне тіло буде повалене, магію оберега треба спрямувати на полеглу оболонку, щоб цілком вигнати владу фурболгів і відпустити його мандрівний дух у Смарагдовий Сон назавжди."}},fp="12,282,24.705.1,40.248.0,31.200.0,51.283.0,37.241.1"}
P.entries["item:water-of-the-seers"] = {n="Вода Провидців",s="Вода Провидців — священний напій, який дають молодим тауренам, що проходять племінні випробування в Селі Бладгуф. Випита біля племінного вогню свята вода відкриває розум світові духів і прикликає примарне Видіння Рівнин, що веде прочанина його духовною дорогою.",h="Вода Провидців — священний напій, який дають молодим тауренам, що проходять племінні випробування в Селі...",kw={"вода провидців","обряд видіння","видіння рівнин","віщун вайзраннер","село бладгуф","таурени"},ang={["class:Shaman"]="Дія цього напою дає ранній досвід спілкування зі світом духів і показує, як ритуальні речовини можуть стоншити завісу між тілесним світом і світом предків.",["race:Tauren"]="Вода Провидців — засадниче священне вариво в науці молодих шу'гало, що поєднує стародавні шаманські звичаї з племінним переходом у доросле життя."},sec={{t="Посудина для духу",b="Приготована племінними містиками, Вода Провидців — неодмінна частина стародавнього Обряду Видіння. Щоб прорвати завісу між тілесною дійсністю й настановами предків, прохач має випити святу воду перед центральним племінним вогнем у Селі Бладгуф. Могутній напій дарує духовний зір: з жарин постає примарний провідник, відомий як Видіння Рівнин, і веде до Віщуна Вайзраннера."}},fp="18,280,23.448.0,51.242.0,35.134.0,33.162.0"}
P.entries["item:water-pitcher"] = {n="Глек для Води",s="Простий посуд, у якому носять свіжу джерельну воду з місцевої криниці на Плато Червоної Хмари. Прамати Гоквінд велить молодим тауренам віднести його до Табору Нарачі, щоб прищепити їм цінності смирення, служіння й поваги до старійшин племені.",h="Простий посуд, у якому носять свіжу джерельну воду з місцевої криниці на Плато Червоної Хмари.",kw={"глек для води","прамати гоквінд","вождь гоквінд","криниця","смирення","табір нарачі"},ang={["race:Tauren"]="Для молодих тауренів, що входять у зрілість на Плато Червоної Хмари, нести глек — ранній урок: шана до старійшин і допомога громаді — справжні підвалини сили."},sec={{t="Урок смирення",b="Хоч глек для води скромний на вигляд, для молоді він — важливе знаряддя науки, і Табір Нарачі користується ним не одне покоління. Глек стоїть біля водяної криниці на рівнинах на південний схід від табору й уособлює щоденну працю, потрібну, щоб підтримувати громаду. Просячи новачка наповнити важку посудину й віднести її Вождю Гоквінду, Прамати Гоквінд випробовує його вдачу. Ця робота показує, що жоден обов'язок не нижчий за гідність захисника племені, і нагадує молодим сміливцям: дбати про щоденні потреби родичів так само важливо, як тримати зброю на полюванні."}},fp="13,240,20.548.0,35.211.0,36.150.0,40.172.0,49.162.0"}
P.entries["item:webwood-egg"] = {n="Яйце Павука Вебвуда",s="Яйце Павука Вебвуда — невилуплений зразок, зібраний із гнізд у Печері Тіньової Нитки в Тінедолі. Природознавці, що вивчають скверну на Тельдрассилі, шукають ці життєздатні яйця, щоб досліджувати щойно вилуплених павуків у безпечних умовах.",h="Яйце Павука Вебвуда — невилуплений зразок, зібраний із гнізд у Печері Тіньової Нитки в Тінедолі.",kw={"яйце павука вебвуда","вебвуд","павуки","печера тіньової нитки","ґілшалан віндвокер","тінедол","дарнасус"},ang={["class:Druid"]="Розуміння того, як розмножуються й поводяться споганені павуки Вебвуда, дає друїдам важливі підказки для зцілення порушеної природної рівноваги Тельдрассила.",["race:NightElf"]="Для молодих калдореїв, що захищають священне віття Тельдрассила, здобуття цих яєць допомагає вченим дослідити неприродну скверну, що розповзається корінною звіриною Світового Дерева."},sec={{t="Безпечний зразок",b="Приборкати чи вгамувати дорослого отруйного павука Вебвуда — небезпечна справа, непосильна для самотніх дослідників. Замість боротися зі зрілими хижаками, вчені на кшталт Ґілшалана Віндвокера покладаються на невилуплені яйця, зібрані просто з кладок у темних закутках Печери Тіньової Нитки. Здобуте невилуплене яйце дає змогу природознавцям безпечно перевезти створіння й утримати павученят, щойно ті вилупляться, — живі зразки для вивчення без зустрічі зі смертоносними іклами дорослих звірів."},{t="Призначено для Дарнасуса",b="Неприродна лють і скверна, що вразили корінну звірину Тельдрассила, стривожили вчених по всьому вітті. Зібрані яйця й здобуту отруту, щойно їх доставлять до Алдрассила, мають відправити вниз, до столиці — Дарнасуса. Дослідники сподіваються, що вирощування й вивчення павуків у контрольованих умовах дасть цінне розуміння темної недуги, що повзе віттям Світового Дерева."}},fp="11,258,20.523.0,22.438.0,29.144.0,26.150.0,49.225.0,46.195.0"}
P.entries["item:webwood-spider-silk"] = {n="Павутинний Шовк Вебвуда",s="Павутинний Шовк Вебвуда — тонка липка нитка, здобута з вебвудських чигачів, що нишпорять лісами Тельдрассила. Павутинний шовк має багато ремісничих застосувань, та саме ці клапті шукають підозрілі постаті у вітті Світового Дерева.",h="Павутинний Шовк Вебвуда — тонка липка нитка, здобута з вебвудських чигачів, що нишпорять лісами Тельдрассила.",kw={"павутинний шовк вебвуда","вебвуд","павуки","шовк","зенн фаулгуф","сатир","доланаар"},ang={["profession:Tailoring"]="Хоч прядильники часто шукають павучі нитки, саме ці клапті вплутані в темні оборудки сатира, а не у звичне ткацьке ремесло.",["race:NightElf"]="Молодих нічних ельфів, що покидають Тінедол, застерігають зважати на створінь, на яких вони полюють, — надто коли їх підбурює самотній сатир, що чигає біля самого їхнього серця."},sec={{t="Сумнівний складник",b="Спрядений величезними вебвудськими чигачами, що гніздяться довкола Доланаара, Павутинний Шовк Вебвуда легкий, напрочуд міцний і небезпечний у здобуванні. Сатир Зенн Фаулгуф, який чигає біля лісової дороги, наймає молодих шукачів пригод збирати клапті цього шовку разом з іклами нічних шаблезубів і перами стригідних сов. Запевняючи, що це просто рідкісні складники для його лісової справи, він розраховує на наївність новачків, які збиратимуть дикі складники, не ставлячи питань про його споганену природу чи справжні наміри."}},fp="19,244,17.509.0,39.163.0,20.179.0,48.144.1,50.133.0"}
P.entries["item:webwood-venom-sac"] = {n="Отруйний Мішок Павука Вебвуда",s="Отруйний Мішок Павука Вебвуда — орган, здобутий із величезних павуків, що населяють Тінедол на Тельдрассилі. Природознавці шукають ці зразки, щоб з'ясувати, як неприродне зростання нового Світового Дерева змінило тутешню звірину.",h="Отруйний Мішок Павука Вебвуда — орган, здобутий із величезних павуків, що населяють Тінедол на Тельдрассилі.",kw={"отруйний мішок павука вебвуда","вебвуд","павуки","отрута","ґілшалан віндвокер","печера тіньової нитки","тінедол"},ang={["class:Druid"]="Для друїдів, настроєних на рівновагу природи, споганена сила цих отруйних мішків — тривожний речовий доказ того, що на вітті Тельдрассила не все гаразд.",["race:NightElf"]="Молодим нічним ельфам — шукачам пригод у Тінедолі доручають збирати ці зразки на допомогу вченим, які намагаються зрозуміти дивну нову природу їхньої батьківщини на верхівці віття."},sec={{t="Симптом зростання Тельдрассила",b="Павуки Вебвуда, що мешкають довкола й усередині Печери Тіньової Нитки, — родичі значно меншої породи павуків, яка водиться деінде. Їхнє раптове збільшення й хижа лють стривожили дослідників — нічних ельфів. Природознавці на кшталт Ґілшалана Віндвокера вивчають отруту в цих мішках, щоб проаналізувати її силу й склад, сподіваючись зрозуміти, як стрімке, неблагословенне зростання Тельдрассила спотворює створінь, що живуть на його вітті."}},fp="17,226,32.467.0,35.132.0,27.168.0,37.228.0,39.218.0"}
P.entries["item:well-stone"] = {n="Камінь Криниці",s="Камені Криниці — невеликі мінеральні камінці, зібрані на берегах і довкола водяних криниць Малгору. Багаті на тонкі енергії землі, вони слугують важливим складником у приготуванні Води Провидців під час традиційних обрядів посвяти тауренів.",h="Камені Криниці — невеликі мінеральні камінці, зібрані на берегах і довкола водяних криниць Малгору.",kw={"камінь криниці","вода провидців","зарлман ту-мунс","обряд видіння","криниця","шаман","малгор"},ang={["class:Shaman"]="Шамани розуміють Камені Криниці як природні якорі магії землі й води, що стягують приховані духи в перетворювальну церемоніальну суміш.",["race:Tauren"]="Збирання Каменів Криниці — важливий крок у вияві єднання з землею, що вчить кожного молодого таурена, як тілесні стихії землі сприяють духовному просвітленню."},sec={{t="Посудина енергій землі",b="Лежачи в м'якій землі на берегах криниць Малгору, Камені Криниці вбирають духовний відгук рівнин і вод під ними. Шамани й провидці на кшталт Зарлмана Ту-Мунса бачать у цих каменях не буденну річкову гальку, а вмістилища життєвої магії. У поєднанні з бурштиновими шишками, зібраними під могутніми деревами рівнин, їхні мінеральні властивості гартують вариво, потрібне, щоб пробудити провидчий транс у молодих тауренів, які проходять священний Обряд Видіння."}},fp="10,249,26.492.0,30.200.0,28.143.0,26.132.0"}
P.entries["item:wendigo-mane"] = {n="Грива Вендіго",s="Гриви Вендиґо — густі кошлаті шуби, зняті з диких вендиґо, що блукають замерзлими скелями Дун Мороґу. Їх цінують за надійне утеплення від пронизливого гірського холоду: ці грубі шкури досить міцні, щоб устилати підлогу хатин чи залізні кабіни дворфійських бойових машин.",h="Гриви Вендиґо — густі кошлаті шуби, зняті з диких вендиґо, що блукають замерзлими скелями Дун Мороґу.",kw={"грива вендиґо","вендиґо","хутро","пілот стоунґір","сиве лігво","троллплоу","харанос"},ang={["profession:Engineering"]="Керувати дворфійською технікою в Дун Мороґу — означає миритися з крижаними металевими кабінами, тож утеплювальна підкладка з хутра вендиґо — практичне поліпшення для затишку.",["race:Dwarf"]="Полювання на вендиґо Сивого Лігва — перевірене часом випробування для молодих дворфів, які хочуть довести свою твердість ветеранам Хараноса."},sec={{t="Тепло для залізяччя",b="Гори Дун Мороґу суворі й непоступливі, тож місцеві вміють дати раду верховним звірам, що никають заметами. Грубе хутро вендиґо щільно захищає від лютих морозних протягів. Пілот Стоунґір, що стоїть біля Хараноса, посилає шукачів пригод до сусіднього Сивого Лігва по ці важкі гриви. Але ексцентричний пілот не збирається шити зимові шуби чи плащі: він має намір сплести з них пухнастий утеплювальний килим на внутрішню палубу своєї дорогоцінної дворфійської облогової машини Троллплоу."}},fp="12,286,24.529.0,36.207.0,42.256.0,57.190.0,31.221.0"}
P.entries["item:whitestone-oak-lumber"] = {n="Дубова Деревина Вайтстоуну",s="Дубова Деревина Вайтстоуну — міцна ремісницька деревина з підземних верфей під Мунбруком. Її цінують за міцність, і вона слугує важливим матеріалом для руків'їв священного озброєння, яке кують майстри-ковалі Альянсу.",h="Дубова Деревина Вайтстоуну — міцна ремісницька деревина з підземних верфей під Мунбруком.",kw={"дубова деревина вайтстоуну","деревина","мертві копальні","братство дефіас","джордан стілвелл","випробування праведності","паладин"},ang={["class:Paladin"]="Здобути цю деревину з підземних доків Дефіас — ключова вимога Випробування праведності Джордана Стілвелла, що дає священний молот, викуваний для захисників Світла.",["profession:Blacksmithing"]="У кресленнях зброї Стілвелла щільний дуб Вайтстоуну поєднано з очищеною рудою та самоцвітом, щоб урівноважити вагу, міцність і метафізичний відгук."},sec={{t="Деревина підземних доків",b="Дуб Вайтстоуну, який знаходять глибоко в заплутаних Мертвих Копальнях Вестфолу, обробляють ґоблінські різьбярі, що будують таємний бойовий флот Братства Дефіас. Щільне, пружне волокно робить його ідеальним для конструкцій, що мають витримувати навантаження й сильні удари, і це привертає увагу досвідчених зброярів, яким для церемоніального й бойового ремесла потрібне щось більше за звичайний ясен чи сосну."},{t="Священне руків'я",b="Біля Айронфорджа коваль Джордан Стілвелл вимагає Дубову Деревину Вайтстоуну, щоб створити зброю, гідну справжнього захисника Світла. Поєднана з очищеним самоцвітом Кор і очищеними металами, ця деревина дає врівноважене, непохитне руків'я, здатне витримати святі енергії, які спрямовують під час Випробування праведності."}},fp="21,227,25.381.0,13.320.1,37.168.0,21.161.0,30.158.0,48.215.0"}
P.entries["item:wildmane-cleansing-totem"] = {n="Тотем Очищення Вайлдмейн",s="Тотем Очищення Вайлдмейн — освячене ритуальне знаряддя, виготовлене, щоб очистити північну водяну криницю Малгору. Довірений молодим захисникам землі, він стає останнім знаряддям у вигнанні отруйної скверни, залишеної загарбницькими підприємствами гоблінів.",h="Тотем Очищення Вайлдмейн — освячене ритуальне знаряддя, виготовлене, щоб очистити північну водяну криницю...",kw={"тотем очищення вайлдмейн","вайлдмейн","криниця","малл тандергорн","очищення","гобліни","тандер блаф"},ang={["class:Shaman"]="Спрямовувати духовне очищення через різьблені тотеми — основа зцілення поранених духів води, осквернених безоглядною промисловістю.",["race:Tauren"]="Відновити криницю Вайлдмейнів — урочистий обов'язок перед Матір'ю-Землею: вигнати чужі промислові отрути, щоб зберегти вашу прабатьківську домівку."},sec={{t="Очищення священних криниць",b="Коли підприємства гоблінів почали труїти землю й забруднювати бідні запаси води Малгору, таурени звернулися до священного ритуалу, щоб повернути лихо назад. Очистивши водяні криниці Вінтергуфів і Тандергорнів, Малл Тандергорн виготовляє цей останній тотем, аби вигнати решту скверни з Водяної Криниці Вайлдмейнів на північ від Тандер Блафу. Наснажений духами природи, тотем очищає смердючі води, щоб чисте життя знову могло живити рівнини."}},fp="24,265,26.452.0,52.187.0,41.152.0,44.182.0,38.119.0"}
P.entries["item:william-s-shipment"] = {n="Вантаж Вільяма",s="Вантаж Вільяма — дбайливо запакована партія свічок, здобутих у клопітних кобольдів Лісу Елвінн. Спакований Вільямом Пестлом у Ґолдширі, він призначений для алхімічної справи його брата Морґана в Торговому Кварталі Стормвінда.",h="Вантаж Вільяма — дбайливо запакована партія свічок, здобутих у клопітних кобольдів Лісу Елвінн.",kw={"вантаж вільяма","свічки","вільям пестл","аптека пестлів","торговий квартал","кобольди"},ang={["faction:Alliance"]="Очищення копалень Елвінну від кобольдів служить Альянсу подвійно: захищає місцеве господарство й постачає крамницям столиці сировину для алхімії.",["race:Human"]="Ця доставка показує тісні господарські зв'язки, що єднають сільські містечка на кшталт Ґолдширу зі столицею Стормвінд."},sec={{t="Родинна торгівля",b="Брати Пестли тримають сталий торговий зв'язок між Ґолдширом і столицею. Поки Вільям працює в Лісі Елвінн, збираючи матеріали в тутешніх ділків і шукачів пригод, Морґан порядкує в родинній крамниці — Аптеці Пестлів у Торговому Кварталі Стормвінда. Оскільки Вільям не може покинути власні обов'язки й поїхати на північ, він покладається на гінців, щоб доправити цей надійно запакований пакунок воску й свічок до міста."},{t="Кобольдовий віск",b="Вміст вантажу — кобольдові свічки, зібрані в створінь, що заполонили копальні Елвінну. Поки кобольди цінують ці грубі свічки понад усе, бо вони відганяють повзучу темряву, алхіміки й аптекарі цінують витоплений лій і віск для складання реагентів і зілля. Завдяки заповзятливості Вільяма ця здобич із копалень напряму перетворюється на корисний товар для алхімічної торгівлі столиці."}},fp="18,246,16.436.0,10.432.0,34.211.0,39.126.0,44.210.0,48.195.0"}
P.entries["item:winterhoof-cleansing-totem"] = {n="Тотем Очищення Вінтергуф",s="Тотем Очищення Вінтергуф — освячене ритуальне знаряддя, виготовлене Маллом Тандергорном у Селі Бладгуф. Вирізьблений, щоб звести нанівець отруйне лихо, яке поширили зайди з Венчурної Компанії, він спрямовує силу Матері-Землі на очищення забрудненої Водяної Криниці Вінтергуфів.",h="Тотем Очищення Вінтергуф — освячене ритуальне знаряддя, виготовлене Маллом Тандергорном у Селі Бладгуф.",kw={"тотем очищення вінтергуф","вінтергуф","криниця","малл тандергорн","венчурна компанія","очищення","малгор"},ang={["class:Shaman"]="Використання очисного тотема відображає основні засади шаманізму: гармонією стихій землі й води вигнати штучну скверну.",["race:Tauren"]="Осквернення джерел прісної води б'є в саме серце зв'язку тауренів із Матір'ю-Землею, тож ритуал тотема — неодмінний захист батьківщини."},sec={{t="Очищення джерела",b="Коли гоблінські інженери Венчурної Компанії вдерлися на рівнини Малгору, їхні промислові роботи швидко отруїли дорогоцінні підземні води краю. У відповідь Малл Тандергорн підготував Тотем Очищення Вінтергуф, наснаживши різьблене дерево захисною магією, що має вимити чужі отрути. Пронесений повз ворожих гоблінських вартових до краю Водяної Криниці Вінтергуфів, тотем розсіює забруднення зосередженим ритуалом і повертає чисту питну воду мандрівним стадам і корінним племенам рівнин."}},fp="26,266,20.564.0,48.199.0,23.164.0,43.182.0,51.159.0"}
P.entries["item:zalazane-s-head"] = {n="Голова Залазана",s="Голова Залазана — похмурий трофей, який приносять Майстру Ґадріну на підтвердження загибелі зрадливого відьмака Залазана. Її здобуття — важливий крок до звільнення Островів Відлуння від темної магії, що тримає в заручниках дім племені Темного Списа.",h="Голова Залазана — похмурий трофей, який приносять Майстру Ґадріну на підтвердження загибелі зрадливого...",kw={"голова залазана","залазан","відьмак","ґадрін","острови відлуння","сен'джин","темний спис"},ang={["faction:Horde"]="Знищення Залазана убезпечує південне узбережжя Дуротару для Орди й не дає темній магії підточувати щойно засновані землі Тралла.",["race:Troll"]="Для тролів Темного Списа здобути голову Залазана — глибоко особистий акт помсти й справедливості щодо зрадника, який вигнав їхній народ і поневолив їхніх братів."},sec={{t="Доказ кінця зрадника",b="Коли відьмак Залазан зрадив плем'я Темного Списа, він удався до проклять, що поневолюють розум, аби захопити їхній острівний дім і вигнати народ Вол'джина на материкові береги Дуротару. З Островів Відлуння Залазан і далі посилав через воду зачаклованих рабів, щоб хапати нових жертв. Аби запевнити стривожених біженців у Селі Сен'джин, що панування тирана скінчилося, Майстер Ґадрін зажадав беззаперечного речового доказу його смерті. Повернення відрубаної голови не лише підтверджує поразку Залазана в бою, а й дарує вигнаному племені рідкісну дещицю спокою та надію колись повернути вкрадені острови."}},fp="15,245,26.634.0,29.171.0,26.264.0,24.152.0,46.241.0"}
P.entries["npc:alamar-grimm"] = {n="Аламар Грімм",s="Аламар Грімм — гном, наставник чорнокнижників, що служить в Анвілмарі в Долині Холодного Хребта. Озлоблений трагічною втратою Гномреґану, він не довіряє чужинцям і зосереджується на тому, щоб навчати новачків-чорнокнижників опановувати темні мистецтва й прикликати перших демонічних поплічників.",h="Аламар Грімм — гном, наставник чорнокнижників, що служить в Анвілмарі в Долині Холодного Хребта.",kw={"аламар грімм","чорнокнижник","наставник","гном","анвілмар","гномреґан","біс","талісман з пера"},ang={["class:Warlock"]="Для гномів-чорнокнижників, що починають шлях у Долині Холодного Хребта, Грімм дає ваші найперші закляття й доручає довести свою вартість, щоб здобути першого поплічника-біса.",["race:Gnome"]="Грімм утілює тиху гіркоту вигнанців, які почуваються покинутими союзниками, поки Гномреґан лишається в руках трогів."},sec={{t="Озлоблений вигнанець",b="Поки більшість гномів у Долині Холодного Хребта спрямовують сили на відновлення й винахідництво, Аламар Грімм плекає глибоку образу через падіння Гномреґану. Він цинічно дивиться на звичайних шукачів пригод і навіть на дворфів-господарів з Айронфорджа, бурчачи, що союзникам більше залежить на дипломатії з людьми, ніж на поверненні полеглого техноміста. Працюючи з Анвілмара, він шукає споріднені душі, які розуміють: безжальна сила — можливо, саме те, чого насправді потребує його народ."},{t="Майстер темних мистецтв",b="Для молодих гномів, що ступають на шлях магії скверни, Грімм — перший провідник. Коли йому показують осквернений меморандум, він виявляє рідкісну теплоту й починає навчати новобранців базових заклять. Та перш ніж дати новачкові небезпечне знання, потрібне, щоб прив'язати демонічного біса, він вимагає доказу магічної та фізичної витривалості, посилаючи їх по дивні талісмани з пера, які носять місцеві новачки тролів Морозогривів."}},fp="12,256,14.471.0,23.450.0,20.204.0,41.264.0,46.276.0"}
P.entries["npc:alyissia"] = {n="Алііссія",s="Алііссія — калдорейська наставниця воїнів, що перебуває в порожнистому вітті Алдрассила в Тінедолі. Вона навчає щойно пробуджених воїнів — нічних ельфів основ бойового мистецтва, допомагаючи їм приборкати сиру силу й дисципліну для захисту їхнього молодого світового дерева.",h="Алііссія — калдорейська наставниця воїнів, що перебуває в порожнистому вітті Алдрассила в Тінедолі.",kw={"алііссія","воїн","наставниця","алдрассил","тінедол","тельдрассил","калдореї"},ang={["class:Warrior"]="Для молодих воїнів — нічних ельфів Алііссія — найперша наставниця, що дає ранню науку стійок і бойової дисципліни, перш ніж вони заглибляться в нетрі Тельдрассила.",["race:NightElf"]="Алііссія уособлює бойову дисципліну передової калдореїв і готує захисників боронити коріння Алдрассила від скверни."},sec={{t="Бойова наставниця Тінедолу",b="У затишному прихистку Алдрассила Алііссія навчає молодих нічних ельфів, яких вабить шлях криці й щита, а не магії природи чи жрецтва. Хоч військо калдореїв здавна славиться Вартовими й потайними лучниками, небезпечне становище сьогоднішнього Калімдору потребує рішучих бійців передової. Алііссія викладає основи, щоб свіжі новобранці вміли спрямовувати бойову лють, опановували стійки й витримували натиск напасливої звірини та споганених ґреллів, що зазіхають на Тінедол."}},fp="8,270,28.560.0,16.229.0,26.131.0,32.194.0"}
P.entries["npc:apothecary-johaan"] = {n="Аптекар Йогаан",s="Аптекар Йогаан — алхімік і дослідник Королівського Аптекарського Товариства в Бріллі. За дорученням свого ордену та Леді Сильвани він проводить смертельні досліди над місцевою флорою та фауною, розробляючи нову чуму Відступників.",h="Аптекар Йогаан — алхімік і дослідник Королівського Аптекарського Товариства в Бріллі.",kw={"аптекар йогаан","алхімік","королівське аптекарське товариство","брілл","нова чума","відступники","тірісфаль"},ang={["faction:Horde"]="Хоч орки й таурени можуть сахатися алхімічних пошестей, смертоносні суміші Йогаана служать стратегічній безпеці плацдарму Орди в Східних Королівствах.",["race:Undead"]="Дослідження Йогаана — осердя справи Відступників: він розробляє саме ту зброю, що потрібна, щоб вибороти постійну батьківщину, вільну від Погибелі й загроз з боку живих."},sec={{t="Слуга Товариства",b="Відкрито працюючи в поселенні Відступників Брілл у Галявинах Тірісфалю, Аптекар Йогаан утілює наукові амбіції новоствореного Королівського Аптекарського Товариства. Як і його колеги по всьому Лордерону, Йогаан діє за прямим наказом — створювати біологічну й алхімічну зброю, здатну убезпечити хистке майбутнє Відступників і від живих, і від Погибелі."},{t="Варіння Нової Чуми",b="Йогаан керує першими польовими випробуваннями того, що Товариство називає «Новою Чумою». З сировини, зібраної з зіпсутої живності Тірісфалю та хворих посівів — як-от сутінь-зілля й отруєний ґрунт сусідніх хуторів, — він випробовує суміші отрут і оцінює їхню силу на живих піддослідних, а тоді відсилає результати на південь, у Срібнолісся."}},fp="17,233,24.383.0,22.368.1,25.193.0,35.144.0,26.159.0,40.180.0,40.144.0,40.178.0"}
P.entries["npc:aramis-hammerhand"] = {n="Араміс Гаммергенд",s="Араміс Гаммергенд — святий воїн з-поміж нежиті, що перебуває в оскверненій каплиці Похоронного Подзвону. Як наставник паладинів Відступників він навчає щойно воскреслих мерців, що прагнуть відновити свій зв'язок зі Святим Світлом. Іти цим шляхом у нежитті потребує величезної дисципліни: володіння такою променистою силою завдає їхній зотлілій плоті нестерпного болю.",h="Араміс Гаммергенд — святий воїн з-поміж нежиті, що перебуває в оскверненій каплиці Похоронного Подзвону.",kw={"араміс гаммергенд","паладин","наставник","святе світло","похоронний подзвін","відступники","нежить"},ang={["class:Paladin"]="Для паладинів Відступників Араміс — перший наставник, якого вони зустрічають; він проводить їх через муку й духовну дисципліну, потрібні, щоб володіти Святим Світлом у тілі нежиті.",["race:Undead"]="Араміс доводить, що повстати нежиттю не означає зректися гордої спадщини Лордерона — священної війни, навіть якщо це коштує величезних особистих страждань."},sec={{t="Маяк у Похоронному Подзвоні",b="Стоячи в похмурих стінах каплиці Похоронного Подзвону, Араміс Гаммергенд — виняток серед нещодавно пробуджених Відступників. За життя чимало громадян Лордерона відгукнулися на поклик Срібної Длані — і загинули, коли Погибель прокотилася північчю. Араміс пережив падіння лише для того, щоб повстати нежиттю, та він вирішив не зрікатися бойових і духовних настанов свого колишнього існування. Тепер він наставляє інших, хто відмовляється зректися своєї відданості."},{t="Мука Святого Світла",b="Для істоти з нежиті спрямовувати Святе Світло — випробування найвищої сили волі. Ця сила пече мертву плоть і будить давно вмерлі нерви нестерпним болем. Араміс навчає своїх посвячених, що триматися цієї віри означає терпіти безперервну муку. Через такі завдання, як «Важкий шлях» і «Віднайти Світло», він вимагає від молодих паладинів усвідомити тілесну й духовну ціну володіння силою, за своєю суттю ворожою їхній теперішній природі."}},fp="17,349,22.484.0,27.466.0,25.181.0,47.225.0,35.122.0,41.202.0,50.214.0,55.193.0"}
P.entries["npc:athridas-bearmantle"] = {n="Атрідас Бермантл",s="Атрідас Бермантл — друїд нічних ельфів, що мешкає в Доланаарі серед гілля Тельдрассила. Йому доручено берегти місцеве поселення, тож він посилає молодих шукачів пригод розслідувати скверну, що насувається на тутешню живність і сусідніх фурболгів-Вузлошкірів.",h="Атрідас Бермантл — друїд нічних ельфів, що мешкає в Доланаарі серед гілля Тельдрассила.",kw={"атрідас бермантл","друїд","доланаар","тельдрассил","фурболги","вузлошкіри","скверна"},ang={["class:Druid"]="Завдання Атрідаса проти зіпсутих Вузлошкірів і його турбота про давні реліквії безпосередньо торкаються рівноваги природи, яку друїди поклялися відновлювати.",["race:NightElf"]="Для молодих калдореїв, що залишають Тінедол, Атрідас — тверезе нагадування про біди Тельдрассила: вашій новій домівці вже загрожують зсередини."},sec={{t="Хранитель Доланаара",b="Атрідас Бермантл у Доланаарі — перша лінія оборони для нічних ельфів, що виходять із Тінедолу. Поки гілля новорослого Світового Дерева Тельдрассила виказує неприродні ознаки занепаду й неспокою, Атрідас невтомно керує місцевою розвідкою й захищає мирне містечко від довколишніх загроз."},{t="Недуга фурболгів",b="Чимало тривог Атрідаса пов'язано з сусіднім племенем фурболгів — Вузлошкірами. Колись мирні сусіди, Вузлошкіри піддалися божевіллю та скверні, що ширяться й отруюють їхніх шаманів і вождів, штовхаючи їх у шалену лють проти калдореїв. Атрідас гуртує охочих звитяжців, щоб стримати загрозу й викрити глибшу заразу, що пускає коріння в хащах."}},fp="19,276,20.350.0,22.391.0,27.225.0,37.121.0,36.208.0,40.190.0,50.184.0,52.196.0"}
P.entries["npc:auntie-bernice-stonefield"] = {n="\"Тітонька\" Берніс Стоунфілд",s="«Тітонька» Берніс Стоунфілд — старша в родині Стоунфілдів, що живе на їхній садибі в південно-центральній частині Лісу Елвінн. Вона овдовіла, коли її чоловік загинув у військових походах королівства, і на всю долину славиться своїми пирогами зі свинячою грудинкою. Її можна знайти біля фермерського будинку разом із Ма Стоунфілд: вона пильно стежить за околицею і глибоко не довіряє суперникам-Маклурам.",h="«Тітонька» Берніс Стоунфілд — старша в родині Стоунфілдів, що живе на їхній садибі в південно-центральній...",kw={"берніс","тітонька","стоунфілд","маклур","намисто","пиріг зі свинячою грудинкою"},sec={{t="Життя в нестатках",b="Як і багато простих людей королівства Стормвінд, Берніс сповна заплатила за нескінченну війну. Втративши чоловіка у військових походах, вона доживає вік на родинній садибі серед рідні й допомагає матріархині Ма Стоунфілд у щоденних справах ферми. Попри втрату, вона годує родину й тримає господарство на ходу, а її пироги зі свинячою грудинкою знають по всій окрузі."},{t="Ворожнеча і зникле намисто",b="Давня неприязнь між Стоунфілдами й Маклурами — невіддільна частина світу Берніс. Коли її цінне родинне намисто зникло, вона одразу запідозрила малого Біллі Маклура. Та повернути пам'ятку виявляється складніше, ніж покарати сусідського шибеника за витівку: Біллі запевняє, що впустив його, коли тікав від грізного кобольда Золотозуба біля Копальні Фарґодіп."}},fp="27,445,18.404.0,33.426.1,33.214.0,42.114.0,34.177.0,47.161.0,46.200.1,32.171.0"}
P.entries["npc:ayanna-everstride"] = {n="Аянна Еверстрайд",s="Аянна Еверстрайд — калдорейська наставниця мисливців, що перебуває в Алдрассилі, у Тінедолі на Тельдрассилі. Вона навчає молодих рейнджерів — нічних ельфів основ влучної стрільби, вистежування й виживання в дикому краю. Молоді мисливці, роблячи перші кроки під віттям Світового Дерева, шукають її проводу, щоб відточити лісову дисципліну.",h="Аянна Еверстрайд — калдорейська наставниця мисливців, що перебуває в Алдрассилі, у Тінедолі на Тельдрассилі.",kw={"аянна еверстрайд","мисливець","наставниця","алдрассил","тінедол","тельдрассил","вистежування"},ang={["class:Hunter"]="Для молодих мисливців — нічних ельфів, що починають шлях у Тінедолі, Аянна Еверстрайд — найперша наставниця з володіння зброєю, вистежування й виживання в неприборканих нетрях.",["race:NightElf"]="Перебуваючи у священних порожнинах Алдрассила, Аянна допомагає берегти молоде Світове Дерево, готуючи новобранців захищати навколишній ліс від скверни, що насувається."},sec={{t="Наставниця в Тінедолі",b="Умостившись усередині Алдрассила в самому серці Тінедолу, Аянна Еверстрайд готова навчати щойно пробуджених калдореїв звичаїв дикої природи. Для нічних ельфів мисливець — не просто ловець чи влучний стрілець, а незамінний охоронець священних лісів. Аянна дає настанови з ранніх бойових прийомів, допомагаючи новачкам опанувати дальній бій і вижити в небезпечних лісах Тельдрассила."}},fp="17,354,22.416.0,25.214.0,35.133.0,38.207.0"}
P.entries["npc:baine-bloodhoof"] = {n="Бейн Бладгуф",s="Бейн Бладгуф — син Верховного Вождя Кайрна Бладгуфа й чинний захисник Села Бладгуф у Малгорі. Поки його батько править племенами з високих плато Тандер Блафу, Бейн безпосередньо керує місцевою обороною: розслідує промислове визискування, що насувається, і боронить край від здичавілих хижаків. Він — важлива ланка між юними тауренськими хоробрими та прадавньою мудрістю свого клану.",h="Бейн Бладгуф — син Верховного Вождя Кайрна Бладгуфа й чинний захисник Села Бладгуф у Малгорі.",kw={"бейн бладгуф","таурен","село бладгуф","малгор","кайрн","захисник","кентаври"},ang={["class:Shaman"]="Бейн понад усе шанує духів: він посилає мандрівників змусити замовкнути дворфські машини й безоглядних копачів, перш ніж вирветься на волю лють земляних елементалів.",["faction:Horde"]="Бейн утілює спокійну мудрість і тиху військову силу, що закріплюють тауренів в Орді Тралла, і дає настанови тим, хто проходить через центральний Малгор.",["race:Tauren"]="Бейн утілює і почесний рід Верховного Вождя Кайрна, і живу надію молодих племен, зібраних по рівнинах Малгору."},sec={{t="Син Верховного Вождя",b="Народжений від Кайрна й покійної Тамаали, Бейн провів юність у мандрах зі своїм кочовим народом, перш ніж той здобув багаті луки Малгору. Його ранні роки позначила повсякчасна загроза від кланів кентаврів. Невдовзі після Третьої війни бойовий загін кентаврів під проводом Хіраґґа захопив юного Бейна, і Кайрн поринув у скорботне заціпеніння, яке ледь не знищило щойно засновані поселення. Лише завдяки відвазі захисника Рекссара Бейна визволили з полону. Той порятунок повернув Кайрнові дух, і таурени змогли стати поруч з Ордою Тралла проти загарбників із Кул Тірасу й закріпитися на континенті."},{t="Охоронець Села Бладгуф",b="Замість лишатися у відносному затишку столичних плато, Бейн воліє жити серед рідні в Селі Бладгуф. Що старшим стає Кайрн, то більший тягар опікунства несе Бейн, уособлюючи наступне покоління тауренського проводу. Він скеровує хоробрих і союзників, що навідуються, на боротьбу з неспокійними гнолами Блідоманами, які дошкуляють кордонам, і пильно стежить за підозрілими сторонніми впливами, що загрожують природній рівновазі Малгору. Щоразу, як Кайрн залишає столицю в державних справах, Бейн виступає чинним провідником об'єднаних племен."},{t="На захист Матері-Землі",b="Окрім прикордонних сутичок, Бейн має справу з новітніми зайдами, яким байдужа духовна рівновага. На сході гоблінська Венчурна Компанія глибоко врізається у священний край, а дворфські шукачі з Бель Модану копають прадавню землю на Розкопках Бел'дуну. Бейн обстоює тверду, але виважену відповідь: спробувати застерегти копачів і знищити їхнє руйнівне обладнання, а не кидатися в безглузде кровопролиття. Він попереджає, що жорстоке копання дворфів ранить духів землі, та копачі не бажають слухати."}},fp="15,429,25.664.0,29.574.0,26.551.0,23.242.0,35.176.0,39.276.0,53.220.0,55.239.0,44.219.0"}
P.entries["npc:balir-frosthammer"] = {n="Балір Фростгаммер",s="Балір Фростгаммер — дворфійський захисник, що служить у Долині Холодного Хребта в Дун Мороґу. Стривожений раптовими й зухвалими вторгненнями трогів Кам'янощелепів на дворфійські землі, він набирає новачків-шукачів пригод, щоб зупинити навалу, перш ніж долину буде захоплено.",h="Балір Фростгаммер — дворфійський захисник, що служить у Долині Холодного Хребта в Дун Мороґу.",kw={"балір фростгаммер","захисник","троги","скелещелепи","долина холодного хребта","таннок фростгаммер","дун мороґ"},ang={["faction:Alliance"]="Зусилля Баліра зберігають Долину Холодного Хребта безпечною — важливим плацдармом для новобранців Альянсу, які починають вишкіл у Каз Модані.",["race:Dwarf"]="Для молодих дворфів Балір Фростгаммер утілює передову оборону батьківщини, даючи їм найперші нагоди захистити Дун Мороґ від підземних загроз."},sec={{t="Утримати Долину Холодного Хребта",b="Із засніженого закутка Долини Холодного Хребта Балір Фростгаммер стежить за периметром проти небезпек, що насуваються. Долина довго була безпечним притулком і навчальним майданчиком для дворфійських і гномських новачків, але недавні заворушення під землею випустили на поверхню лютих трогів Кам'янощелепів. Балір одним із перших б'є на сполох, згуртовуючи новоприбулих новобранців, щоб вибити трогів, перш ніж ті прорвуться глибше в Дун Мороґ."},{t="Рід Фростгаммерів",b="Носячи горде прізвище Фростгаммер, Балір, можливо, споріднений із Танноком Фростгаммером із Хараноса. Їхня родина непохитно стоїть на службі Айронфорджу, пильнуючи, щоб холодні гірські перевали лишалися безпечними для подорожніх, шахтарів і горян, навіть коли загроз у краї стає дедалі більше."}},fp="17,255,24.445.0,23.286.0,25.182.0,40.203.0,39.136.0"}
P.entries["npc:beldin-steelgrill"] = {n="Белдін Стілґрілл",s="Белдін Стілґрілл — уславлений дворфійський інженер і головний технік Складу Стілґрила в Дун Мороґу. Його широко вважають одним із найкращих механіків облогових машин у Каз Модані: він наглядає за обслуговуванням важкої броні та гусеничних бойових машин війська Айронфорджа. Щоб ці велетенські пристрої працювали, потрібен нескінченний запас високоякісного спеціального інструменту.",h="Белдін Стілґрілл — уславлений дворфійський інженер і головний технік Складу Стілґрила в Дун Мороґу.",kw={"белдін стілґрілл","інженер","склад стілґрила","облогові машини","парові танки","харанос","каз модан"},ang={["profession:Engineering"]="Для інженерів Белдін — вершина дворфійської транспортної техніки, нагода зблизька побачити найгрізніші механізовані бойові засоби Альянсу.",["race:Dwarf"]="Двір Белдіна показує промислову міць Айронфорджа й доводить, що дворфійська майстерність сягає далеко за ручні молоти й сокири — аж до нищівної облогової артилерії."},sec={{t="Володар гусеничного звіра",b="Розташований трохи далі дорогою від Хараноса, Склад Стілґрила — головний полігон і станція обслуговування дворфійських парових танків та облогових машин. Белдін Стілґрілл — його головний технік, уславлений усюди неперевершеним умінням ремонтувати й налаштовувати броньовані бойові вози. Приборкувати важкий метал і гуркітливі котли — невдячна праця, і Белдін швидко зношує знаряддя. Його постійний попит на важкі гайкові ключі, різаки й точні інструменти раз у раз жене місцевих ковалів на межу, аби лише його верстак не порожнів."}},fp="17,389,27.571.0,25.207.0,35.156.0,41.252.0"}
P.entries["npc:billy-maclure"] = {n="Біллі Маклур",s="Біллі Маклур — бешкетний хлопчисько з людей, що живе на Виноградниках Маклюрів у Лісі Елвінн. Опинившись посеред запеклої ворожнечі між своєю родиною та сусідами Стоунфілдами, Біллі своїми дрібними витівками часто завдає клопоту обом фермам. Його слабкість до свіжої випічки робить його легкою здобиччю для підкупу, коли пустощі заходять надто далеко.",h="Біллі Маклур — бешкетний хлопчисько з людей, що живе на Виноградниках Маклюрів у Лісі Елвінн.",kw={"біллі маклур","хлопчик","виноградники маклюрів","стоунфілди","намисто","пиріг","ліс елвінн"},ang={["faction:Alliance"]="Для шукачів пригод Альянсу, що щойно прибули з Нортширу, допомога з дурними витівками Біллі стає знайомством із небезпеками, що чаяться в Копальні Фарґодіп.",["profession:Cooking"]="Славетний пиріг зі свинячою грудинкою тітоньки Берніс показує, як проста сільська кухня може залагодити напружені місцеві суперечки й витягти зізнання з мовчазних фермерських хлопчаків.",["race:Human"]="Біллі уособлює приземлені буденні чвари сільського Елвінну: попри політичні потрясіння Стормвінда, місцеві фермерські ворожнечі й дитячі бешкети тривають як завжди."},sec={{t="Хлопчисько з виноградників",b="Біллі Маклура зазвичай можна застати, коли він тиняється біля клуні на Виноградниках Маклюрів, неподалік від фермера Джерарда Тіллера. Вирісши серед нескінченних рядів виноградної лози, Біллі здебільшого ухиляється від хатньої роботи й носиться сільськими луками центрального Лісу Елвінн. Як і вся його рідня, він добре знає про давню ворожнечу між Маклюрами та Стоунфілдами, та для Біллі ця чвара — радше гра в витівки й дрібні крадіжки, ніж серйозний конфлікт."},{t="Украдене намисто",b="Пустощі Біллі перейшли межу, коли він поцупив дороге сімейне намисто тітоньки Берніс Стоунфілд. Бігаючи біля небезпечної Копальні Фарґодіп, наляканий хлопчисько випустив дрібничку з рук. Перш ніж він устиг її підібрати, намисто вхопив особливо здоровий і лютий кобольд на ім'я Золотозуб і зник у підземних тунелях. Боячись і підземної погані, і гніву сусідських старших, Біллі не бажає зізнаватися, доки його не підкуплять смачним хабарем — а саме гарячим пирогом зі свинячою грудинкою, спеченим самою тітонькою Берніс."}},fp="13,336,22.504.0,19.617.1,21.202.0,33.160.0,36.147.0,42.197.1,62.209.1,17.209.1"}
P.entries["npc:bink"] = {n="Бінк",s="Бінк — гномка, наставниця магів, що мешкає в Залі Таїнств у Містичному Кварталі Айронфорджа. Кмітлива й завзята, вона веде майбутніх заклиначів крізь тонкощі таємних мистецтв і зводить їх із видатними чарівниками по всьому Альянсу.",h="Бінк — гномка, наставниця магів, що мешкає в Залі Таїнств у Містичному Кварталі Айронфорджа.",kw={"бінк","маг","наставниця","гномка","зала таїнств","містичний квартал","айронфордж"},ang={["class:Mage"]="Для магів Альянсу, що гостюють чи осіли в Айронфорджі, Бінк — важлива наставниця й давачка завдань, яка відправляє учнів навчатися в могутніх наставників по всьому Азероту.",["race:Gnome"]="Бінк утілює невпинне прагнення до таємної майстерності серед гномів-вигнанців, що знайшли прихисток у великих залах своїх дворфійських союзників."},sec={{t="Маяк у Залі Таїнств",b="У Містичному Кварталі Айронфорджа Бінк стоїть серед зібраних у Залі Таїнств учених, жерців і чародіїв. Як і багато гномів, вигнаних із Гномреґану, вона пристосувалася до життя в дворфійській гірській твердині, пропонуючи свій гострий розум і знання таємного ремесла тим, хто вчиться на мага. Вона добре знайома з чарівниками по всіх Східних Королівствах і Калімдорі й регулярно скеровує перспективних учнів до визначніших наставників, як-от Верховного Чаклуна Андромата в Стормвінді чи Табети в Багні Пилоброду."}},fp="4,266,33.549.0,12.201.0,22.122.0,25.246.0,32.170.0"}
P.entries["npc:bolvar-fordragon"] = {n="Болвар Фордрагон",s="Верховний Лорд Болвар Фордрагон — регент Стормвінда й верховний командувач його збройних сил після загадкового зникнення короля Варіана Рінна. Стоячи поруч із юним королем Андуїном Рінном у Фортеці Стормвінда, він намагається втримати королівство докупи серед дедалі гірших внутрішніх негараздів. Хоч Болвар — людина незламної честі, його військові рішення часто спрямовує й гальмує королівська радниця Леді Катрана Престор.",h="Верховний Лорд Болвар Фордрагон — регент Стормвінда й верховний командувач його збройних сил після...",kw={"болвар","фордрагон","болвар фордрагон","регент","стормвінд","катрана престор"},sec={{t="Регент королівства",b="Коли король Варіан зник дорогою на мирні перемовини на Острові Терамор, Стормвінд поринув у політичний хаос. Десятирічного принца Андуїна коронували, щоб зберегти тяглість влади, але справжнє правління перейшло до Верховного Лорда Болвара Фордрагона як регента. Болвар — шанований паладин, відданий короні, та тягар на ньому величезний. Військо Стормвінда розпорошене по Вестфолу, Редріджу й Сутінколіссю. А на додачу Болвар часто прислухається до Леді Катрани Престор, чиї зневажливі поради раз у раз не дають йому послати королівські війська до віддалених містечок."},{t="Павутина обману",b="За лаштунками королівського двору руки Болвара зв'язані міцніше, ніж він здогадується. Поки міські магістрати й прикордонні маршали благають про підкріплення проти Братства Дефіас та орків Блекрок, Леді Престор непомітно перекручує королівські укази й применшує кожне донесення про небезпеку. Болвар шанує поради знаті й вагається діяти без незаперечних доказів, тим самим мимоволі паралізуючи корону. Лише коли надходять переконливі свідчення — як-от застереження з Терамора чи зниклі польові офіцери, — регент оминає звичний придворний порядок і наймає вільних шукачів пригод."}},fp="16,433,19.604.0,15.612.1,44.334.0,60.380.0,56.284.0,51.271.0"}
P.entries["npc:branstock-khalder"] = {n="Брансток Калдер",s="Брансток Калдер — наставник жерців, що служить в Анвілмарі в Долині Холодного Хребта. Привітний і приземлений, він знайомить дворфійських жерців-новачків зі Святим Світлом, водночас пильнуючи дедалі більшу загрозу трогів надворі.",h="Брансток Калдер — наставник жерців, що служить в Анвілмарі в Долині Холодного Хребта.",kw={"брансток калдер","жрець","наставник","святе світло","анвілмар","максан анвол","долина холодного хребта"},ang={["class:Priest"]="Для дворфійських жерців Брансток Калдер — найперший духовний провідник, якого ви зустрічаєте: він розтлумачує вашу першу священну руну й знайомить вас із захисними й цілющими мистецтвами Святого Світла.",["race:Dwarf"]="Брансток утілює практичну, приземлену побожність, властиву дворфам Айронфорджа, поєднуючи благоговійну віру у Світло зі здоровою стійкістю проти холоду й місцевих набігів трогів."},sec={{t="Провідна рука в Холодному Хребті",b="У людній залі Анвілмара Брансток Калдер терпляче наставляє майбутніх жерців, що вирушають у свою духовну подорож. Лагідний дворф із глибокою відданістю Світлу, він допомагає новим послушникам опанувати перші молитви й священні руни. Хоч головний його обов'язок — духовне навчання, Брансток гостро усвідомлює дедалі більші небезпеки долини, передусім зухвалу навалу трогів, що загрожує місцевим горянам. Щойно новачок достатньо опанує Світло, він скеровує його крізь Перевал Холодного Кряжа по подальші настанови до свого зверхника, Максана Анвола, в Харанос."}},fp="17,226,27.620.0,25.239.0,44.212.0,54.225.0,32.197.0"}
P.entries["npc:bromos-grummner"] = {n="Бромос Ґруммнер",s="Бромос Ґруммнер — дворфійський наставник паладинів, що служить в Анвілмарі в Долині Холодного Хребта. Він наставляє дворфійських святих воїнів-початківців, проповідуючи непохитну віру у Святе Світло та життєво важливий зв'язок між дворфами й людьми в Лицарях Срібної Длані.",h="Бромос Ґруммнер — дворфійський наставник паладинів, що служить в Анвілмарі в Долині Холодного Хребта.",kw={"бромос ґруммнер","паладин","наставник","срібна длань","святе світло","анвілмар","долина холодного хребта"},ang={["class:Paladin"]="Для дворфійських паладинів Бромос — найперший духовний наставник, який знайомить їх зі священними обов'язками Срібної Длані.",["race:Dwarf"]="Бромос утілює тривалу традицію дворфійських служителів Світла, які б'ються пліч-о-пліч зі своїми союзниками-людьми."},sec={{t="Маяк у Холодному Хребті",b="У міцній кам'яній залі Анвілмара Бромос Ґруммнер вітає дворфійських новачків, яких тягне до дисципліни Святого Світла. Упевнений і рішучий, він навчає молодих паладинів бойових обрядів і священних закликів. Окрім основ бою, Бромос наголошує на єдності, нагадуючи учням, що орден Лицарів Срібної Длані поєднує Айронфордж і людські королівства Альянсу в праведній меті."}},fp="15,260,21.450.0,23.198.0,33.169.0,32.194.0"}
P.entries["npc:brother-neals"] = {n="Брат Нілз",s="Брат Нілз — чернець, що живе в Абатстві Нортшира в Лісі Елвінн. Відповідальний за запаси харчів і напоїв абатства, він проводить більшість часу, наглядаючи за поставками й куштуючи вино з тутешнього виноградника.",h="Брат Нілз — чернець, що живе в Абатстві Нортшира в Лісі Елвінн.",kw={"брат нілз","чернець","абатство нортшира","вино","льох","припаси"},ang={["profession:Cooking"]="Брат Нілз порядкує припасами й трунками монастиря, тож він — споріднена душа для кожного, кого цікавлять кулінарне мистецтво й броварські традиції королівства."},sec={{t="Хранитель льоху",b="Усамітнившись у верхніх покоях дзвіниці Абатства Нортшира, Брат Нілз дбає про харчові припаси й запаси напоїв монастиря. Він виявляє особливий, щирий інтерес до нортширських виноградників: ретельно стежить за описами винограду й пильнує якість уславленого абатського вина, куштуючи його з відданою регулярністю. Попри мирні обов'язки обліку й догляду за льохом, він уважно стежить за поставками, що надходять з довколишніх полів долини."}},fp="13,242,20.492.0,21.163.0,33.176.0,40.195.0"}
P.entries["npc:cairne-bloodhoof"] = {n="Кайрн Бладгуф",s="Кайрн Бладгуф — поважний Верховний Вождь об'єднаних тауренських племен і правитель Тандер Блафу. Величезний воїн неосяжної мудрості, він зв'язав долю тауренів з Ордою Тралла після того, як орки допомогли його народові уникнути винищення від рук кентаврів.",h="Кайрн Бладгуф — поважний Верховний Вождь об'єднаних тауренських племен і правитель Тандер Блафу.",kw={"кайрн бладгуф","верховний вождь","таурени","тандер блаф","малгор","тралл","орда"},ang={["faction:Horde"]="Поруч із Траллом Кайрн — батько-засновник сучасної Орди на Калімдорі, опора честі, мудрості та військової сили.",["race:Tauren"]="Кайрн — рятівник вашого народу: він об'єднав розсіяні племена, відбив кентаврів і очолив будівництво Тандер Блафу."},sec={{t="Держава в Малгорі",b="Поколіннями таурени жили мандрівними кочовиками по Пустках, і дикі кентаври-грабіжники без упину полювали на них, штовхаючи до загибелі. Коли Тралл зі своїми орками прибув на береги Калімдору, Кайрн розгледів у них рідкісну шляхетність. Тралл запропонував військовий захист і провів зневірену валку Кайрна через рівнини до безпечного Малгору в обмін на дорогу до Оракула на Піку Кам'яного Кігтя. Оселившись на високих плато Тандер Блафу, Кайрн нарешті заснував постійний, єдиний дім для всіх тауренських племен."},{t="Присяга Орді",b="У боргу перед Траллом, Кайрн пішов за орками до Піку Кам'яного Кігтя й бився пліч-о-пліч з Ордою та людьми Джайни Праудмур проти Палаючого Легіону під час Третьої війни. Пізніше, коли Адмірал Делін Праудмур вторгся в Дуротар, Кайрн знову особисто взявся за прадавній рунний спис і бився поруч із Рекссаром, щойно його полоненого сина Бейна благополучно визволили. Нині Кайрн — один із найшанованіших старійшин Орди й найближчий довірений Тралла, що дає спокійну пораду проти безоглядного розпалювання війни."}},fp="16,276,19.555.0,19.525.0,24.249.0,40.274.0,25.152.0,33.211.0"}
P.entries["npc:calvin-montague"] = {n="Келвін Монтеґ'ю",s="Келвін Монтеґ'ю — спритний розбійник із Відступників, що тиняється біля вихідної брами Похоронного Подзвону на Галявинах Тірісфалю. Полюючи на щойно пробуджених мерців, які виходять із цвинтаря, він намагається обманом змусити перехожих виконувати доручення замість нього.",h="Келвін Монтеґ'ю — спритний розбійник із Відступників, що тиняється біля вихідної брами Похоронного Подзвону...",kw={"келвін монтеґ'ю","розбійник","шахрай","похоронний подзвін","лист","відступники"},ang={["class:Rogue"]="Розбійники Відступників швидко розкусять прозорі спроби Келвіна Монтеґ'ю маніпулювати й упізнають у ньому колегу-злодія, що намагається провернути дешеву оборудку з непосвяченими.",["race:Undead"]="Для щойно піднятих, що покидають Похоронний Подзвін, Келвін — ранній урок того, що не всі піддані Сильвани зацікавлені у взаємній підтримці."},sec={{t="Шахрай біля брами",b="Келвін Монтеґ'ю, що влаштувався одразу за брамою, яка веде з Похоронного Подзвону, утілює безжальний прагматизм, властивий неспокійним мертвим Лордерону. Замість займатися власним листуванням чи платити чесну ціну кур'єрам, він намагається солодкими словами підбити мандрівних шукачів пригод доставляти листи під фальшивим приводом. Поки кілька інших помітних мерців із прізвищем Монтеґ'ю керують банківськими справами в Андерсіті, Келвін обрав куди менш поважне ремесло, віддаючи перевагу дрібним оборудкам і обману."},{t="Задум розбійника",b="Пропозиція Келвіна — віднести від його імені запечатане послання, та ті, хто має гострий розум чи вишкіл злочинного світу, швидко бачать за його словами шахрайство. Навіть серед щойно піднятих, які силкуються знайти мету в похмурих руїнах Тірісфалю, Келвін нагадує новачкам, що на службі в Темної Леді довіра — рідкісний товар."}},fp="15,242,21.528.0,16.343.1,23.202.0,40.169.0,52.175.0,35.167.0"}
P.entries["npc:canaga-earthcaller"] = {n="Канаґа Ерткаллер",s="Канаґа Ерткаллер — троль-шаман із племені Темного Списа, що стоїть у випаленій сонцем Долині Випробувань. Він навчає шаманів-новачків Орди спілкуватися з духами землі й здобувати перші стихійні тотеми. Окрім настанов в обрядах, він пильнує за пораненими розвідниками та загрозами, що виникають поблизу Лігва.",h="Канаґа Ерткаллер — троль-шаман із племені Темного Списа, що стоїть у випаленій сонцем Долині Випробувань.",kw={"канаґа ерткаллер","шаман","троль","долина випробувань","тотем землі","сапта","гана'зуа"},ang={["class:Shaman"]="Канаґа — ваш найперший духовний наставник у Дуротарі: він готує Земляну Сапту, щоб ви могли поспілкуватися зі стихіями й здобути свій Тотем Землі.",["race:Orc"]="Канаґа працює пліч-о-пліч з орківськими наставниками в долині, допомагаючи молодим оркам зв'язати свій дух із суворою землею нової батьківщини.",["race:Troll"]="Як одна з помітних постатей Темного Списа в Долині Випробувань, Канаґа дбає, щоб тролі-новобранці не лишалися без догляду — зокрема й послані розвідники на кшталт Гана'зуа."},sec={{t="Голос землі",b="На червоних кручах Долини Випробувань Канаґа Ерткаллер є одним із найперших духовних провідників для тролів Темного Списа та орків, що стають на шлях шамана. Поки багато наставників дбають лише про бойову готовність, Канаґа вчить новачків утихомирити розум і прислухатися до гуркоту самого Калімдору, готуючи земляну сапту, потрібну для спілкування з духами."},{t="Перший тотем",b="Перш ніж шаман-початківець зможе по-справжньому спрямовувати стихійну лють землі, він має довести духам свою повагу й рішучість. Канаґа скеровує посвячуваних зібрати священні реагенти й вирушити до місцевого каменя духів у Дуротарі. Під його проводом новачки п'ють земляну сапту, бачать стихійних духів на власні очі й здобувають свій Тотем Землі."},{t="Клопоти в долині",b="Канаґа не живе самими лише потаємними обрядами — він уважний і до нагальних небезпек долини. Коли його друг Гана'зуа вирушає на північ долини, де полюють скорпіди, і не повертається, Канаґа посилає здібних мандрівників на його пошуки, щоб розвідників племені не кидали гинути в глушині."}},fp="18,311,17.401.0,15.357.0,21.323.0,26.194.0,37.239.0,40.225.0,50.236.0,60.221.0,38.124.0"}
P.entries["npc:captured-mountaineer"] = {n="Полонений Горянин",s="Полонений Горянин — дворф з Айронфорджа, якого тримають у підвалі Таверни «Шибеничний Кінець» у Бріллі. Зв'язаний і під охороною Відступників, він слугує мимовільним піддослідним для похмурих дослідів Королівського Аптекарського Товариства.",h="Полонений Горянин — дворф з Айронфорджа, якого тримають у підвалі Таверни «Шибеничний Кінець» у Бріллі.",kw={"полонений горянин","дворф","айронфордж","таверна шибеничний кінець","аптекар йогаан","піддослідний"},ang={["race:Dwarf"]="Бачити гордого брата з Айронфорджа в клітці під таверною Відступників, підданого жахливим алхімічним дослідам, — гірке нагадування про безжальну ворожість Відступників до живих.",["race:Undead"]="Для Відступників живі бранці з Альянсу — життєво важливий ресурс для мети Королівського Аптекарського Товариства: довершити чуму, здатну стерти і Погибель, і живих ворогів."},sec={{t="В'язень у підвалі",b="Захований під мостинами Таверни «Шибеничний Кінець» у Бріллі, цей Айронфорджський Горянин сидить у полоні далеко від безпечного Каз Модану. Поки нагорі п'ють відвідувачі, Королівське Аптекарське Товариство використовує його як мимовільного піддослідного для своїх варив. Аптекар Йогаан і його колеги перевіряють смертоносність своєї чуми на живому організмі Альянсу, вимірюючи на в'язневі, наскільки швидко й болісно їхні токсини несуть живим кінець."}},fp="20,235,24.488.0,32.148.0,55.216.0,37.220.1,38.174.0"}
P.entries["npc:captured-scarlet-zealot"] = {n="Полонений Багряний Фанатик",s="Полонений Багряний Фанатик — хрестоносець-бранець, якого тримають у підвалі Таверни «Шибеничний Кінець» у Бріллі. Під наглядом аптекарів Відступників й містян він слугує живим піддослідним для варив, які розробляє Королівське Аптекарське Товариство.",h="Полонений Багряний Фанатик — хрестоносець-бранець, якого тримають у підвалі Таверни «Шибеничний Кінець» у...",kw={"полонений багряний фанатик","багряний хрестовий похід","таверна шибеничний кінець","аптекар йогаан","рене лауер","брілл"},ang={["class:Priest"]="Багряні фанатики заявляють про виняткове право на Святе Світло, та непохитний запал цього в'язня не захищає його від похмурої дійсності полону у Відступників.",["race:Undead"]="Для Відступників з Брілла цей фанатик у кайданах утілює невпинних хрестоносців, що прагнуть їхнього винищення, — і значно кориснішу роль піддослідного кролика аптекаря."},sec={{t="Запеклий бранець у Бріллі",b="Ув'язнений під Таверною «Шибеничний Кінець», цей член ордену, що зветься Багряний Хрестовий Похід, утілює незламний фанатизм своїх побратимів. Навіть у кайданах, в оточенні нежиті, яку він має за гидоту, він не виявляє ні краплі каяття й отруйно таврує кожного, хто з ним заговорить, — як-от Рене Лауер, яку він кляне зрадницею. Для Відступників полонити живого фанатика — не акт милосердя: це цінний людський матеріал, щоб оцінити смертоносність дослідних чум і токсинів, які розробляє Аптекар Йогаан."}},fp="23,259,25.524.0,44.159.0,30.116.0,45.153.0"}
P.entries["npc:carolai-anise"] = {n="Каролай Еніс",s="Каролай Еніс — ексцентрична алхімікиня з Відступників, що мешкає в селищі Брілл на Галявинах Тірісфалю. Вона навчає алхіміків-початківців, хоча її небезпечні варива вже не раз викликали тривожне бурмотіння місцевих вартових.",h="Каролай Еніс — ексцентрична алхімікиня з Відступників, що мешкає в селищі Брілл на Галявинах Тірісфалю.",kw={"каролай еніс","алхімія","алхімікиня","брілл","реагенти","відступники"},ang={["profession:Herbalism"]="Збирачі, що добувають дику флору по всьому Тірісфалю, часто приносять Каролай мирноцвіт, срібнолист і земнокорінь, щоб вона переробила їх на потужні суміші.",["race:Undead"]="Для щойно звільнених Відступників, які вчаться працювати з реагентами, Каролай дає основи алхімічного ремесла на Галявинах Тірісфалю."},sec={{t="Вибухове ремесло",b="Працюючи у Бріллі, Каролай Еніс присвячує своє нежиття нестабільному мистецтву алхімії. Поки багато дослідників Відступників працюють під похмурим мандатом Королівського Аптекарського Товариства, Каролай вариться у власних дивних зіллях просто всередині поселення. Її непередбачувані досліди й димучі реторти настільки сумнозвісні, що Вартові Смерті, які пильнують Брілл, відверто бурчать: схоже, вона налаштована підірвати власну хату."}},fp="13,210,16.427.0,21.166.0,21.152.0,42.177.0"}
P.entries["npc:chief-hawkwind"] = {n="Вождь Гоквінд",s="Вождь Гоквінд — племінний ватажок Табору Нарачі, місця випробувань, що сховалося на Плато Червоної Хмари в Малгорі. Він наставляє молодь Шу'хало й веде новачків-шукачів пригод через традиційні обряди посвяти. Під його пильним оком юні сміливці вчаться смирення, поваги до землі та сили, потрібної, щоб захищати свій народ.",h="Вождь Гоквінд — племінний ватажок Табору Нарачі, місця випробувань, що сховалося на Плато Червоної Хмари в...",kw={"гоквінд","вождь","табір нарачі","плато червоної хмари","малгор","таурени","обряди"},ang={["faction:Horde"]="Наука Гоквінда дбає, щоб нові покоління тауренських сміливців ставали не лише вправними воїнами й заклиначами, а й непохитними та шляхетними союзниками молодої Орди.",["race:Tauren"]="Перший вождь, що веде вас у дорогу, Вождь Гоквінд закладає основи цінностей Шу'хало: шану до Земної Матері, вірність племені та смирення в силі."},sec={{t="Вождь плато",b="Стоячи в серці Табору Нарачі, Вождь Гоквінд несе урочистий обов'язок — готувати нове покоління тауренів до великого світу. Плато Червоної Хмари править за затишний прихисток, де мисливці, шамани, друїди й воїни-початківці проходять прадавні Обряди Земної Матері. Гоквінд наглядає за цими звичаями й дбає, щоб кожен юнак пізнав обов'язок і витривалість, перш ніж ступити за безпечні межі плато."},{t="Провідник обрядів",b="Уроки Гоквінда починаються зі смирення, а не з бойової слави. Він посилає посвячуваних на прості доручення — скажімо, принести чистої джерельної води, — щоб прищепити шану до природи та старших. Лише довівши смиренність серця, сміливці переходять до випробувань бойової майстерності, а вінчають їх сутички з войовничими шипогривами племені Щетиноспинних, які зазіхають на прабатьківські рівнини."},{t="Оборона Табору Нарачі",b="Окрім ролі наставника, Вождь Гоквінд мусить давати раду небезпекам, що зростають просто на порозі його табору. Плем'я Щетиноспинних дедалі зухваліше напирає на околиці Плато Червоної Хмари. Гоквінд керує обороною поселення й доручає щойно випробуваним сміливцям стримувати наскоки шипогривів, аби священні землі навчання лишалися в безпеці."}},fp="14,371,21.430.0,17.420.0,22.380.0,22.222.0,38.252.0,51.241.0,35.227.0,48.247.0,50.151.0"}
P.entries["npc:coleman-farthing"] = {n="Коулмен Фартінґ",s="Коулмен Фартінґ — озлоблений уцілілий з-поміж Відступників, що мешкає в Таверні «Шибеничний Кінець» у Бріллі. За життя він працював на заможну династію Аґамандів на їхніх великих борошняних млинах у північному Тірісфалі. Умовлений лишитися й боронити маєток від Погибелі, він загинув разом із товаришами-робітниками, а тепер присвячує своє нежиття помсті колишнім господарям.",h="Коулмен Фартінґ — озлоблений уцілілий з-поміж Відступників, що мешкає в Таверні «Шибеничний Кінець» у Бріллі.",kw={"коулмен фартінґ","помста","аґаманди","млини аґаманда","таверна шибеничний кінець","брілл","відступники"},ang={["class:Warrior"]="Коулмен указує майбутнім воїнам просто на Родинний Склеп Аґамандів і закликає їх пограбувати бойові реліквії занепалого аристократичного дому, щоб озброїтися для прийдешніх війн.",["race:Undead"]="Для Відступників Коулмен утілює спільну образу, яку чимало простолюду плекає до старого дворянства Лордерона, чия зарозумілість і гордість нерідко прискорювали загибель їхніх підданих під час чуми."},sec={{t="Озлоблений слуга",b="До Третьої війни Коулмен Фартінґ чесно заробляв на життя робітником на Млинах Аґаманда — найбільшому млинарському й сільському господарстві Галявин Тірісфалю. Коли Погибель ринула на Лордерон, аристократична родина Аґамандів відмовилася тікати зі своїх цінних земель. Натомість вони закликали челядь і робітників узятися за зброю разом із ними, обіцяючи, що хутори вдасться втримати проти орди нежиті. Коулмен і його товариші лишилися, повіривши господарям, — і це рішення коштувало життя кожному з них."},{t="Помста з могили",b="Воскреслий нежиттю лише для того, щоб вирватися на волю під прапором Відступників, Коулмен палає ненавистю до Аґамандів. Він звинувачує не тільки Погибель, а й відверту пиху та жадібність своїх наймачів, що обманом втягнули челядь у безнадійний останній бій. Тепер, тиняючись у таверні Брілла, Коулмен залучає звитяжців Орди, щоб ті вирушили до заражених млинів, порубали воскреслих родичів Аґамандів і розтрощили родинні реліквії в їхньому склепі, аби їхню спадщину було стерто дощенту."}},fp="16,371,16.546.0,24.507.0,36.109.0,49.315.0,35.254.0,44.239.0,51.293.0,47.134.0"}
P.entries["npc:corithras-moonrage"] = {n="Корітрас Мунрейдж",s="Корітрас Мунрейдж — учений нічних ельфів і давач завдань у селищі Доланаар на Тельдрассилі. Він допомагає новоприбулим шукачам пригод збагнути природу великого Світового Дерева й доручає їм дбати про його священні місячні колодязі. Його уроки розкривають і духовну вагу Тельдрассила, і дедалі важчий тягар, що лягає на калдореїв.",h="Корітрас Мунрейдж — учений нічних ельфів і давач завдань у селищі Доланаар на Тельдрассилі.",kw={"корітрас мунрейдж","доланаар","тельдрассил","місячні колодязі","світове дерево","фандрал стаґгелм","безсмертя"},ang={["class:Druid"]="Друїди відчують, що завдання Корітраса тісно пов'язані з їхнім покликанням, адже його обряди біля місячних колодязів напряму відстежують здоров'я Світового Дерева та недуги, що підкрадаються до нього.",["class:Priest"]="Жерці Елуни допомагають Корітрасу переносити благословенні води місячних колодязів, підтримуючи духовну й тілесну гармонію хащ довкола Доланаара.",["race:NightElf"]="Для нічних ельфів розмова з Корітрасом — основоположний урок про реальність після Третьої війни: ви стикаєтеся з утратою давнього безсмертя та суперечливим створенням Тельдрассила."},sec={{t="Учений Доланаара",b="Корітрас Мунрейдж мешкає в тінистому поселенні Доланаар і наставляє мандрівників, що залишають захищені межі Тінедолу. Коли молоді калдореї вирушають у ширше гілля Тельдрассила, Корітрас дбає, щоб вони розуміли історію своєї нової домівки. Він навчає, що вижити в цю мінливу добу можна лише пильністю та шаною до природного ладу."},{t="Корона Землі",b="Значна частина обов'язків Корітраса — збирати воду місячних колодязів для друїдів Дарнасуса. Він посилає шукачів пригод набирати чисту воду з місячних колодязів по всьому Тельдрассилу в особливі фіали й доправляти її Фандралу Стаґгелму. Через ці випробування він стежить за здоров'ям Світового Дерева й прагне зберегти крихку рівновагу дикої природи перед скверною, що підкрадається."},{t="Тягар калдореїв",b="За наукою Корітраса криється гірка правда про створення Тельдрассила. На відміну від прадавнього Нордрассила, це нове Світове Дерево виростили без благословення Аспектів драконів, які відмовили честолюбному задуму Фандрала Стаґгелма. Корітрас розмірковує про втрату безсмертя нічних ельфів і про крихке, непевне майбутнє, що чекає калдореїв під неблагословенним гіллям."}},fp="18,376,19.376.0,18.389.0,26.394.1,26.211.0,38.125.0,47.222.0,54.273.0,42.167.0,59.168.0"}
P.entries["npc:dark-cleric-beryl"] = {n="Темна Клірикиня Берил",s="Темна Клірикиня Берил — наставниця жерців Відступників, що перебуває в Таверні «Шибеничний Кінець» у Бріллі. Вона веде щойно пробуджених жерців-нежить, поки ті вчаться володіти магією тіні й звикають до свого нового, нечестивого існування під рукою Темної Леді.",h="Темна Клірикиня Берил — наставниця жерців Відступників, що перебуває в Таверні «Шибеничний Кінець» у Бріллі.",kw={"темна клірикиня берил","жрець","тінь","таверна шибеничний кінець","брілл","наставниця"},ang={["class:Priest"]="Для жерців Відступників, що вирушають на Галявини Тірісфалю, Берил — неодмінна наставниця у Бріллі: вона підказує, як володіти магією тіні й пережити суворий перехід до нечестивої сили.",["race:Undead"]="Берил утілює пристосування Відступників до свого проклятого стану: сліпу відданість колишнім вірам Лордерону вони проміняли на практичну, тіньову стійкість."},sec={{t="Провідниця в тінях",b="Темна Клірикиня Берил, що мешкає на горішньому поверсі Таверни «Шибеничний Кінець» у Бріллі, служить Відступникам як наставниця жерців-початківців. За життя віддані Святому Світлу, багато жерців Відступників після підняття в нежитті виявили, що їхній зв'язок зі святою магією став нестерпно болісним або й урвався зовсім. Берил допомагає цим щойно піднятим чародіям перевести увагу на тінь і темні мистецтва, провадячи їх крізь перші випробування — як-от виготовлення Шат Темряви — і доводячи їхню відданість новому шляху."}},fp="17,231,22.511.0,25.197.0,35.116.0,50.281.0,29.231.0"}
P.entries["npc:dazalar"] = {n="Дазалар",s="Дазалар — наставник мисливців, нічний ельф, що перебуває в Доланаарі на Тельдрассилі. Він веде молодих вартових і розвідників, поки ті відточують влучність і опановують священне мистецтво зріднення з дикими звірами великого віття.",h="Дазалар — наставник мисливців, нічний ельф, що перебуває в Доланаарі на Тельдрассилі.",kw={"дазалар","мисливець","наставник","доланаар","тельдрассил","приборкання звірів","тінедол"},ang={["class:Hunter"]="Дазалар — один із найперших наставників, яких зустрічає мисливець — нічний ельф; він веде вас крізь основні випробування влади над звірами й навчання улюбленця.",["race:NightElf"]="Він підтримує традиції калдорейських вартових і розвідників, навчаючи молодих нічних ельфів жити в рівновазі з лютими хижаками природи."},sec={{t="Табір у Доланаарі",b="Перебуваючи в поселенні Доланаар, Дазалар — головний наставник молодих мисливців, що виходять за межі затишної долини Тінедолу. Суспільство нічних ельфів значною мірою покладається на своїх рейнджерів і вартових, які патрулюють нетрі, і Дазалар дбає, щоб новачки мали дисципліну й терпіння, потрібні для захисту крихкого живого світу Тельдрассила."},{t="Зріднення з дикою природою",b="Ключовий обряд посвяти під проводом Дазалара — навчитися приборкувати звірів і дбати про них. Замість гнути створінь під волю мисливця грубою силою, калдорейський звичай наголошує на взаємній угоді з лісовими хижаками — нічними шаблезубами, совами й стригідними мисливцями, — і вчить їх битися пліч-о-пліч із господарями з повагою."}},fp="7,229,23.355.0,21.340.0,15.185.0,25.148.0,35.178.0,38.218.0,46.249.0,54.180.0"}
P.entries["npc:deathguard-bartholomew"] = {n="Вартовий Смерті Бартоломью",s="Вартовий Смерті Бартоломью — пильний солдат Відступників, що несе службу в містечку Брілл. Відповідаючи за безпеку на Галявинах Тірісфалю, він допомагає мандрівникам орієнтуватися в ураженому поселенні й підтримує дисципліну серед місцевих захисників.",h="Вартовий Смерті Бартоломью — пильний солдат Відступників, що несе службу в містечку Брілл.",kw={"вартовий смерті бартоломью","варта","брілл","галявини тірісфалю","відступники","дорога"},ang={["faction:Horde"]="Союзники, що прибувають із Калімдору, можуть покластися на Бартоломью, щоб зорієнтуватися на оповитих імлою вулицях Брілла.",["race:Undead"]="Для щойно звільнених Відступників, що виходять із Похоронного Подзвону, вартові на кшталт Бартоломью у Бріллі — перше організоване обличчя регулярної армії Леді Сильвани."},sec={{t="Вартовий Брілла",b="Стоячи на варті в поселенні Брілл, Вартовий Смерті Бартоломью уособлює стійкий військовий хребет Відступників. Як і його побратими Вартові Смерті по всіх Галявинах Тірісфалю, він захищає відвойовану землю від недобитків Погибелі, фанатичних багряних хрестоносців і будь-яких інших загроз володінням Леді Сильвани. Окрім варти, він підказує дорогу мандрівникам, що намагаються знайти міські служби, і допомагає підтримувати лад серед щойно піднятих."}},fp="22,253,17.495.0,30.173.0,35.236.0,43.172.0"}
P.entries["npc:deathguard-burgess"] = {n="Вартовий Смерті Берджесс",s="Вартовий Смерті Берджесс — вартовий Відступників, що несе службу в містечку Брілл на Галявинах Тірісфалю. Стоячи на сторожі поселення, він підтримує лад і скеровує мандрівників до потрібних служб селища.",h="Вартовий Смерті Берджесс — вартовий Відступників, що несе службу в містечку Брілл на Галявинах Тірісфалю.",kw={"вартовий смерті берджесс","варта","брілл","андерсіті","відступники","служби"},ang={["faction:Horde"]="Союзники з Калімдору можуть звернутися до Берджесса, щоб зорієнтуватися в незнайомому, ураженому плануванні Брілла, шукаючи торговців припасами чи відпочинку в корчмі.",["race:Undead"]="Для щойно пробуджених Відступників, що покидають Похоронний Подзвін, вартові на кшталт Берджесса у Бріллі — ваше перше знайомство з ширшою інфраструктурою Лордерону."},sec={{t="Сторож у Бріллі",b="Вартовий Смерті Берджесс, що стоїть у поселенні Брілл одразу на північ від Андерсіті, — один із міських вартових, які бережуть його від двох напастей: це Погибель і Багряний Хрестовий Похід. Як і інші Вартові Смерті по всіх Галявинах Тірісфалю, Берджесс допомагає новоприбулим Відступникам, підказуючи дорогу до місцевих ремісників, наставників класів і міських служб, щоб уразливий форпост працював без збоїв."}},fp="18,204,19.392.0,26.194.0,44.221.0,42.197.0"}
P.entries["npc:deathguard-dillinger"] = {n="Вартовий Смерті Діллінджер",s="Вартовий Смерті Діллінджер — вартівник Відступників у Бріллі, у Галявинах Тірісфалю. Пильнуючи околиці містечка, він скеровує новоприбулих мерців до потрібних служб і доручає новобранцям тримати на відстані рештки Погибелі.",h="Вартовий Смерті Діллінджер — вартівник Відступників у Бріллі, у Галявинах Тірісфалю.",kw={"вартовий смерті діллінджер","брілл","варта смерті","погибель","гулі","улаг різник","відступники"},ang={["class:Warrior"]="Майбутні воїни Відступників часто працюють безпосередньо з Діллінджером, випробовуючи бойовий гарт проти лютих гулів і кістяних страхіть, що нишпорять околицями Брілла.",["faction:Horde"]="Діллінджер утілює боротьбу Відступників за надійний плацдарм у північному Лордероні й показує союзникам з Орди невпинну загрозу безтямної Погибелі на їхньому порозі.",["race:Undead"]="Для щойно звільнених Відступників, що приходять із Похоронного Подзвону, Діллінджер часто стає першим обличчям військової влади: він скеровує їх на навчання й до перших обов'язків на службі в Сильвани."},sec={{t="Вартовий Брілла",b="Як член Варти Смерті Відступників, Діллінджер стоїть біля входу до Брілла — водночас захисник передової й провідник для подорожніх, що приходять із Похоронного Подзвону. Він підказує дорогу до корчми, ратуші й місцевих наставників, допомагаючи щойно пробудженим мерцям зорієнтуватися в новій дійсності під владою Темної Леді."},{t="Убезпечення прикордоння",b="Діллінджер активно залучає здібних шукачів пригод вичищати залишки безтямної Погибелі з сусідніх ферм і млинів. Через такі доручення, як винищення гнилих гулів і повернення заражених господарств, він прагне створити довкола Брілла смугу безпеки, щоб молоді поселення Відступників встояли перед нескінченними набігами нежиті."},{t="Стримування безтямних страхіть",b="Окрім звичайних патрулів, Діллінджер керує відсіччю невідступним загрозам Погибелі, що чаяться в руїнах довкола Брілла. Коли з сусідніх гробниць чи покинутих садиб виринають покликані страхіття на кшталт Улага Різника, Діллінджер дбає, щоб здібних бійців вислали покінчити з шаленими чудовиськами, перш ніж ті прорвуться за межі поселення."}},fp="20,251,17.361.0,24.352.0,27.354.1,38.121.0,35.205.0,43.199.0,44.153.0,54.220.0,24.189.0"}
P.entries["npc:deathguard-linnea"] = {n="Вартова Смерті Ліннея",s="Вартова Смерті Ліннея — солдатка Відступників, що несе службу на заставі Вартових Смерті на південному сході Галявин Тірісфалю. Вона допомагає убезпечити дороги між Бріллом і східними кордонами, пильнуючи дві загрози: Багряний Хрестовий Похід і недобитки Погибелі. Шукачі пригод, що проходять головними шляхами, часто допомагають її загонові з патрулюванням.",h="Вартова Смерті Ліннея — солдатка Відступників, що несе службу на заставі Вартових Смерті на південному сході...",kw={"вартова смерті ліннея","застава","патруль","дороги","магістрат севрен","галявини тірісфалю"},ang={["faction:Horde"]="Союзники Відступників, що перетинають Галявини Тірісфалю, можуть заслужити прихильність, допомагаючи Ліннеї стабілізувати віддалені дороги проти ворожих сил.",["race:Undead"]="Для Відступників, щойно піднятих у Похоронному Подзвоні, допомога Вартовій Смерті Ліннеї на заставі — один із найперших обов'язків заради убезпечення кордонів їхнього нового королівства."},sec={{t="Варта при дорозі",b="Вартова Смерті Ліннея стоїть на чатах біля невеликої укріпленої застави на південний схід від Брілла. Життя — чи то пак нежиття — в патрулі на Галявинах Тірісфалю небезпечне: Відступники мусять невсипно боронити своє молоде володіння від лазутчиків Багряного Хрестового Походу й безтямної Погибелі, що никає хащами. Разом зі своїми побратимами-вартовими Ліннея керує патрулюванням уздовж дороги й узгоджує донесення з місцевою владою, як-от Магістратом Севреном у Бріллі, щоб південний підступ до володіння лишався безпечним."}},fp="17,339,23.501.0,25.211.0,34.247.0"}
P.entries["npc:deathguard-simmer"] = {n="Вартовий Смерті Сіммер",s="Вартовий Смерті Сіммер — солдат Відступників, що несе службу одразу за межами Похоронного Подзвону на Галявинах Тірісфалю. Він придивляється до щойно піднятих Відступників й посилає їх грабувати людську гарбузову ферму на заході, яку патрулює Багряний Хрестовий Похід, по реагенти, потрібні аптекарям Брілла.",h="Вартовий Смерті Сіммер — солдат Відступників, що несе службу одразу за межами Похоронного Подзвону на...",kw={"вартовий смерті сіммер","похоронний подзвін","хутір соллідена","гарбузи","багряний хрестовий похід","аптекар йогаан"},ang={["race:Undead"]="Сіммер дає одні з перших завдань, спрямованих безпосередньо проти Багряного Хрестового Походу, і знаменує випуск шукача пригод-нежиті зі склепів Похоронного Подзвону до ширшої оборони Лордерону."},sec={{t="Охоронець за межами Похоронного Подзвону",b="Вартовий Смерті Сіммер, поставлений одразу за межами Похоронного Подзвону, уособлює військову лінію Відступників, що тримає кордон між безпечним прихистком Похоронного Подзвону й ширшими небезпеками Галявин Тірісфалю. Край кишить живими людьми — насамперед фанатиками Багряного Хрестового Походу, — які мають усю нежить за гидоту, що її належить вичистити вогнем і клинком. Сіммер випробовує молодих Відступників, посилаючи їх на захід — туди, де лежить Хутір Соллідена і де з сусідньої вежі патрулює Багряний Хрестовий Похід, — щоб украсти десять гарбузів і віднести їх Аптекареві Йогаану в Брілл."}},fp="17,264,27.543.0,25.206.0,35.126.0,42.252.0"}
P.entries["npc:denalan"] = {n="Деналан",s="Деналан — досвідчений травник і ботанік нічних ельфів, що порається на тихій ділянці біля східного берега Озера Ал'Амет. Під простим навісом він присвячує дні вивченню рослинного світу острова й пошуку ботанічних ліків від дивної скверни, що вражає Тельдрассил. Він часто залучає молодих шукачів пригод збирати зразки, вивчати розлючених деревляників і випробовувати зачаровані ґрунти.",h="Деналан — досвідчений травник і ботанік нічних ельфів, що порається на тихій ділянці біля східного берега...",kw={"деналан","травник","ботанік","озеро ал'амет","деревляники","тельдрассил","скверна"},ang={["class:Druid"]="Друїди знайдуть спільну справу в озерних дослідах Деналана, адже його праця безпосередньо допомагає Колу Кенарія вистежити й викорінити заразу, що шириться корінням Тельдрассила.",["profession:Herbalism"]="Деналан утілює калдорейську традицію ботанічних студій, показуючи, як збирання й вирощування диких рослин допомагає розпізнати глибші недуги природи.",["race:NightElf"]="Дослідження Деналана біля Озера Ал'Амет — одна з перших спроб калдореїв зрозуміти несподівані вади й хвороби росту їхньої нової домівки, Тельдрассила."},sec={{t="Ботанік біля Озера Ал'Амет",b="Поки багато калдореїв зосереджені на військовій пильності чи високих друїдських обрядах, Деналан обрав терпляче, скрупульозне ремесло травника. На тихому східному березі Озера Ал'Амет він облаштував скромний дослідницький табір: полотняний навіс, прості польові знаряддя й охайні ряди грядок у ящиках. Замість ховатися у величних курганах Дарнасуса він воліє лишатися ближче до землі й напряму вивчати незвичну флору, що проросла після насадження нового Світового Дерева."},{t="Дослідження вад Тельдрассила",b="Дослідження Деналана — далеко не академічна цікавість; воно стосується дедалі більшого неспокою серед тутешньої живності Тельдрассила. Деревляники, зазвичай лагідні лісові істоти з дерева й паростків, стали небезпечно агресивними. Деналан зачаровує особливий ґрунт, щоб вирощувати дике насіння в неволі й з'ясовувати, як злі сили просочуються в коріння. Вивчаючи дивні зразки — мерехтливе листя, сяйливі плоди, обплетені мохом пагони, — він прагне виявити ту темну заразу, що точить лісове гілля."}},fp="7,412,27.520.0,36.526.0,25.205.0,44.296.0,41.311.0,42.250.0,27.212.0,52.236.0"}
P.entries["npc:deputy-rainer"] = {n="Помічник Рейнер",s="Помічник Рейнер — офіцер війська Стормвінда, що стоїть біля Гарнізону Вестбрук на західному кордоні Лісу Елвінн. Йому доручено тримати оборону проти зграй гнолів і бандитів, що перетікають із Вестфолу, і він керує місцевою обороною, коли офіційне військове підкріплення так і не приходить.",h="Помічник Рейнер — офіцер війська Стормвінда, що стоїть біля Гарнізону Вестбрук на західному кордоні Лісу...",kw={"помічник рейнер","гарнізон вестбрук","гноли","річколапи","вестфол","кордон"},ang={["faction:Alliance"]="Помічник Рейнер утілює розтріпані краї військової досяжності Стормвінда й дає героям Альянсу змогу на власні очі побачити, як місцевим гарнізонам доводиться виживати без постійної королівської підтримки."},sec={{t="Утримання західного кордону",b="Гарнізон Вестбрук — найзахідніший бастіон Лісу Елвінн, розташований біля прикордонної дороги, що веде у Вестфол. Поки політичний параліч у Стормвінді тримає більшість війська за кордоном або в тенетах бюрократії, прикордонні пости на кшталт Вестбруку лишаються вкрай недоукомплектованими. Помічник Рейнер стоїть біля вежі, щоб організувати ту мізерну оборону, яку гарнізон здатен зібрати. Тутешнім дорогам постійно загрожують агресивні гноли Річколапи й мандрівні злодії, тож Рейнер мусить покладатися на перехожих подорожніх і найманців-шукачів пригод, а не на регулярні полки корони, щоб тримати лісові стежки безпечними."},{t="Дорога у Вестфол",b="Окрім безпосередньої загрози зграї Річколапів і застережень подорожнім щодо сумнозвісного ватажка гнолів Гоґґера, Рейнер слугує важливою ланкою зв'язку з неспокійними землями за річкою. Знаючи, що хаос на кордонах Елвінну походить із беззаконних полів на заході, він посилає здібних добровольців за поріг у Вестфол, скеровуючи їх до Ґраяна Стаутмантла й знеможеного Народного Ополчення."}},fp="13,311,26.631.0,20.452.0,21.207.0,38.263.0,41.208.0,61.201.0"}
P.entries["npc:dirania-silvershine"] = {n="Діранія Сілвершайн",s="Діранія Сілвершайн — нічна ельфійка, мешканка Тінедолу на Тельдрассилі. Глибоко віддана й спостережлива, вона наглядає за тихим гаєм і пильнує свого товариша Іверрона, коли його нерозважливі витівки доводять до біди.",h="Діранія Сілвершайн — нічна ельфійка, мешканка Тінедолу на Тельдрассилі.",kw={"діранія сілвершайн","тінедол","тельдрассил","іверрон","дружба","отрута","павуки"},ang={["race:NightElf"]="Для молодих нічних ельфів, що входять у Тінедол, Діранія — раннє нагадування про узи дружби й про небезпеки, що підкрадаються навіть до найновіших святилищ Світового Дерева."},sec={{t="Спостерігачка в Тінедолі",b="Діранія стоїть серед тихого гілля Тінедолу — відлюдної долини, де молоді нічні ельфи починають службу Калімдору й Альянсу. Поки чимало мешканців курганів і святилищ дбають про високі духовні обов'язки, Діранія пам'ятає про тих, хто поруч, і помічає тихі небезпеки, що ворушаться навіть у серці Тельдрассила."},{t="Біда друга",b="Найбільша турбота Діранії — її товариш Іверрон. Надміру запальний і необережний поруч із отруйними лісовими створіннями, що повзають долиною, Іверрон раз у раз устряє в халепи. Коли він занедужує від отруйного укусу тутешніх павуків Вебвуда, Діранія сама береться шукати охочих, щоб зібрати складники й приготувати ліки, перш ніж отрута завдасть непоправної шкоди."}},fp="19,222,23.348.0,16.388.0,27.209.0,37.119.0,42.211.0,31.194.0,51.221.0,51.217.0"}
P.entries["npc:doomsayer-wiserunner"] = {n="Віщун Вайзраннер",s="Цього шанованого старійшину тауренів знають як Віщуна Вайзраннера; він вірно служить своєму народові серед хвилястих пагорбів Малгору. З печери в пагорбах на північний захід від Села Бладгуф він допомагає молодим сміливцям-тауренам проходити традиційні обряди посвяти, що ведуть до духовної зрілості.",h="Цього шанованого старійшину тауренів знають як Віщуна Вайзраннера; він вірно служить своєму народові серед...",kw={"віщун вайзраннер","старійшина","обряди","печера","село бладгуф","малгор"},ang={["class:Shaman"]="Шамани впізнають у Вайзраннері хранителя стародавніх традицій, який розуміє послання, вплетені в землю й небо.",["race:Tauren"]="Для молодих шу'гало, що виходять за межі Плато Червоної Хмари, Віщун Вайзраннер — неодмінний наставник на прабатьківській дорозі до духовної зрілості."},sec={{t="Провідник на священному шляху",b="Віщун Вайзраннер стоїть серед лагідних круч Малгору як старійшина й містик шу'гало. Коли молоді мисливці й шамани завершують перші випробування сили й видіння, їх посилають шукати його поради під час обрядів предків. Він тлумачить видіння Матері-Землі й наставляє молодь, як шанувати пращурів, даруючи сталу мудрість, що згуртовує розкидані кочові племена в єдину громаду."}},fp="15,293,26.435.0,64.196.0,34.235.0,35.217.0"}
P.entries["npc:drusilla-la-salle"] = {n="Друзілла Ла Салль",s="Друзілла Ла Салль — людська наставниця чорнокнижників, що стоїть на затіненому цвинтарі біля Абатства Нортшира. Діючи на узбіччі Святого Ордену Нортшира, вона навчає чарівників-початківців темних мистецтв прикликання й тіні. Коли заборонене знання вислизає за мури абатства, вона без вагань удається до пригоди й темної магії, щоб заволодіти ним.",h="Друзілла Ла Салль — людська наставниця чорнокнижників, що стоїть на затіненому цвинтарі біля Абатства...",kw={"друзілла ла салль","чорнокнижник","цвинтар","абатство нортшира","сили порожнечі","наставниця"},ang={["class:Priest"]="Стоячи біля святих залів Нортширу, Друзілла втілює темну протилежність вашого покликання: вона торгує тінню й демонічними угодами просто поряд з освяченим цвинтарем.",["class:Warlock"]="Друзілла — ваша перша наставниця в темних мистецтвах: вона веде вас до практичного володіння прокляттями й прикликанням скверни, навчаючи ховати свої амбіції на видноті."},sec={{t="Тіні на святій землі",b="Поки паладини й жерці навчаються під вітражами Абатства Нортшира, Друзілла Ла Салль лишається надворі, серед надгробків цвинтаря. Демонологія й магія скверни — глибоке табу в королівстві Стормвінд, тож чорнокнижникам доводиться жити на узбіччі пристойного суспільства. Друзілла дає перші уроки чорнокнижникам-новачкам, що отримали опоганений лист, навчаючи їх опановувати силу тіні, не накликаючи негайного гніву влади абатства."},{t="Сили Порожнечі",b="Бібліотечне крило Абатства Нортшира потай зберігає кілька небезпечних і заборонених фоліантів, зокрема «Сили Порожнечі». Друзілла давно жадає цього рукопису, та чорнокнижниця, що крутиться біля охоронюваних архівів, одразу викликала б підозру. Її нагода настає, коли послушник-відступник тікає з абатства до Братства Дефіас, прихопивши текст із собою. Скориставшись крадіжкою, Друзілла посилає своїх учнів вистежити перебіжчика й принести гримуар їй у руки під виглядом повернення майна абатства."}},fp="17,364,22.500.0,18.541.1,47.274.0,39.219.0,36.166.0,47.163.0"}
P.entries["npc:durnan-furcutter"] = {n="Дурнан Фуркаттер",s="Дурнан Фуркаттер — дворфійський кравець і торговець шкірою, що працює в Анвілмарі в Долині Холодного Хребта. Стоячи просто біля місцевого шинку, він споряджає щойно вишколених дворфійських і гномських шукачів пригод легким убранням, здатним витримати пронизливий гірський холод.",h="Дурнан Фуркаттер — дворфійський кравець і торговець шкірою, що працює в Анвілмарі в Долині Холодного Хребта.",kw={"дурнан фуркаттер","кравець","торговець","шкіра","анвілмар","ранковий узвар","долина холодного хребта"},ang={["profession:Tailoring"]="Для кравців-початківців торговці на кшталт Дурнана — це базове вбрання, що зберігає життя розвідникам і учням на засніжених перевалах, доки їх не замінить майстерно виготовлена тканина.",["race:Dwarf"]="Дурнан утілює практичний бік дворфійського життя в Долині Холодного Хребта: міцне ремесло, любов до гарячого напою й дружні теревені на снігу."},sec={{t="Теплий шов на морозі",b="Анвілмар — перший полігон для молодих дворфів і гномів-вигнанців, і не кожен воїн виходить звідти закутий у важке залізо. Дурнан Фуркаттер обслуговує розвідників, розбійників і заклиначів, яким потрібні легкі, податливі шари одягу, щоб лишатися спритними й не піддатися лютим вітрам Дун Мороґу. Розташувавшись біля самого вогнища Анвілмара, він торгує повсякденним кравецтвом і шитою шкірою, запевняючи, що його крам — найкращий у всій долині."},{t="З кухлем у руці",b="Як і будь-який справжній дворф у засніжених передгір'ях, Дурнан цінує міцний трунок майже так само, як чесну торгівлю. Він частенько заходить до шинку Анвілмара й тішиться паруючим кухлем Гарячого Ранкового Узвару, щоб відігнати крижаний протяг. Шукачі пригод, що бігають на побігеньках табором, часто приносять свіжий напій просто в його гостинні руки або повертають його порожні кухлі шинкареві."}},fp="16,273,25.456.0,13.397.0,24.190.0,34.147.0,22.152.0,53.140.0"}
P.entries["npc:elder-bloodhoof"] = {n="Старійшина Бладгуф",s="Старійшина Бладгуф — дух предків, що спочиває одразу на північ від Села Бладгуф у Малгорі. Він з'являється мандрівникам під час Місячного фестивалю й стоїть як шанований дух-охоронець племені Бладгуф.",h="Старійшина Бладгуф — дух предків, що спочиває одразу на північ від Села Бладгуф у Малгорі.",kw={"старійшина бладгуф","місячний фестиваль","дух","предки","село бладгуф","малгор"},ang={["class:Shaman"]="Шамани шанують Старійшину Бладгуфа як утілення шани до предків: він показує, як духи пращурів ведуть і захищають нащадків у тілесному світі.",["race:Tauren"]="Для прочан-тауренів віддати шану Старійшині Бладгуфу — пряме єднання з родоводом племені й ушанування жертви тих, хто ходив Малгором задовго до заснування Тандер Блафу."},sec={{t="Дух предків",b="Старійшина Бладгуф уособлює глибокий духовний зв'язок тауренів зі своїм родоводом. З'являючись біля Села Бладгуф, цей примарний старійшина пильнує свій народ і винагороджує шанобливих мандрівників, що шукають мудрості під час Місячного фестивалю. Його присутність підкріплює незгасне наставництво померлих вождів і племінних пращурів, чиї духи лишаються нерозривно пов'язаними з рівнинами Малгору."}},fp="15,221,23.396.0,23.275.0,33.131.0,44.246.0"}
P.entries["npc:elder-graveborn"] = {n="Старійшина Ґрейвборн",s="Старійшина Ґрейвборн — дух предків, що з'являється одразу на південний схід від Брілла, щойно настає Місячний фестиваль. Постаючи у вигляді примарного земляного старійшини, він вшановує мандрівників і спрямовує прочан, що шукають інших давніх духів, розсіяних по півночі Лордерону.",h="Старійшина Ґрейвборн — дух предків, що з'являється одразу на південний схід від Брілла, щойно настає Місячний...",kw={"старійшина ґрейвборн","місячний фестиваль","дух предків","брілл","прочани","тірісфаль"},ang={["faction:Alliance"]="Прочани Альянсу мусять обережно оминати околиці Брілла, щоб віддати шану Ґрейвборнові, не накликавши на себе гнів міської варти й патрулів Відступників.",["race:Undead"]="Для Відступників, що ходять дорогою між Бріллом і Андерсіті, Ґрейвборн — тихе нагадування про давнє минуле Азерота, яке не тривожать ні Погибель, ні пошесть."},sec={{t="Дух у Тірісфалі",b="З'являючись одразу за містечком Відступників Брілл, Старійшина Ґрейвборн стоїть серед примарних лісів Галявин Тірісфалю як частина всесвітнього Місячного фестивалю. Попри уражені околиці й сумний стан королівства, примарний старійшина мирно вітає мандрівників, що шукають традиційних благословень свята. Окрім того, що дарує власну мудрість предків, Ґрейвборн ділиться звістками про інших старійшин поблизу — спрямовуючи прочан до духів, що перебувають в Андерсіті, Усипальниці й по всіх Чумних Землях."}},fp="15,259,20.543.0,23.194.0,29.240.0,38.230.0,41.194.0"}
P.entries["npc:elder-runetotem"] = {n="Старійшина Рунтотем",s="Старійшина Рунтотем — дух предків тауренів, що з'являється біля Гострого Пагорба в Дуроторі під час Місячного фестивалю. Одна з шанованих старійшин Орди, вона дарує мудрість і благословення мандрівникам, які розшукують її серед червоних каньйонів.",h="Старійшина Рунтотем — дух предків тауренів, що з'являється біля Гострого Пагорба в Дуроторі під час Місячного...",kw={"старійшина рунтотем","місячний фестиваль","таурени","дух","гострий пагорб","предки"},ang={["faction:Horde"]="Стоячи біля добре укріпленого поселення Гострий Пагорб, вона втілює духовний союз між орками Дуротару й тауренами Малгору.",["race:Tauren"]="Знайти поважну предкиню племені Рунтотемів так далеко від Малгору — смиренне нагадування, що духи Шу'хало пильнують своїх союзників на всіх землях."},sec={{t="Дух у Дуроторі",b="Хоч духи предків тауренів зазвичай прив'язані до трав'янистих рівнин і священних поховань Малгору, Старійшина Рунтотем затрималася далеко від пасовищ свого народу. Вона з'являється біля запорошеного поселення Гострий Пагорб у Дуроторі. Для молодих орків і мандрівних шукачів пригод її примарна присутність — місток між давніми традиціями Шу'хало та суворим новим домом, який Орда вирізьбила на берегах Великого Моря."},{t="Шана предкам",b="Під час Місячного фестивалю духи великих провідників, шаманів і героїв з'являються по всьому світу, щоб спілкуватися з живими. Старійшина Рунтотем представляє рід Рунтотемів — лінію, відому глибокою шаною до Матері-Землі та духовним єднанням. Мандрівники, що вшановують її присутність, отримують знаки предків та її духовне благословення."}},fp="15,244,19.432.0,16.352.0,23.207.0,42.296.0,53.162.0,34.163.0"}
P.entries["npc:eleanor-shackleton"] = {n="Елеанор Шеклтон",s="Елеанор Шеклтон — мандрівниця з Відступників, що отаборилася на південний захід від Брілла на Галявинах Тірісфалю. Замість сидіти в місті чи в Андерсіті, вона допомагає мандрівникам опановувати виживання в дикій природі й похідні ремесла. Її прізвище носять й інші Відступники, що вціліли в цьому краї, — натяк на зв'язки, збережені з життя до чуми.",h="Елеанор Шеклтон — мандрівниця з Відступників, що отаборилася на південний захід від Брілла на Галявинах...",kw={"елеанор шеклтон","виживання","табір","похідна кухня","брілл","тірісфаль"},ang={["profession:Cooking"]="Уроки Елеанор охоплюють розпалювання похідного багаття й приготування їжі далеко від цивілізованих вогнищ, тож її табір — важлива зупинка для мандрівних кухарів.",["race:Undead"]="Для Відступників життєво важливо вміти виживати в дикій природі без вигод живих, і Елеанор дбає, щоб щойно підняті побратими швидко звикли до суворого побуту в Тірісфалі."},sec={{t="Провідниця Галявинами",b="Поки багато щойно пробуджених Відступників прямують просто до Брілла чи спускаються в Андерсіті, Елеанор Шеклтон розбиває табір у примарних лісах на південному заході. Виживання в Тірісфалі вимагає практичної самостійності, і Елеанор навчає шукачів пригод-початківців жити з ураженої землі. У своїх польових уроках вона показує мандрівникам, як облаштовувати табір, збирати хмиз і не занедбувати ремесла далеко від кузень і кухонь цивілізації."},{t="Зв'язки з минулого життя",b="У розтрощених рештках Лордерону родинні імена часто лишаються єдиною ниткою, що пов'язує мерця з його смертним минулим. Елеанор носить прізвище Шеклтон — як і Пірс Шеклтон у Бріллі та Саманта Шеклтон деінде в Тірісфалі. Чи підтримують ці троє тісні узи, чи лише мають спільне коріння зі смертних днів, кожен із них знайшов власну роль у служінні справі Відступників по всьому ураженому королівству."}},fp="18,356,21.516.0,21.435.0,36.125.0,47.154.0,53.169.0,60.171.0"}
P.entries["npc:executor-arren"] = {n="Екзекутор Аррен",s="Екзекутор Аррен — високопоставлений офіцер Відступників в Похоронному Подзвоні. Він наглядає за безпосередньою обороною й зміцненням поселення, поки щойно пробуджені мерці виходять зі своїх могил. Аррен керує місцевою кампанією проти безтямних зомбі Погибелі, здичавілих звірів і фанатиків Багряного Хрестового Походу, що насуваються.",h="Екзекутор Аррен — високопоставлений офіцер Відступників в Похоронному Подзвоні.",kw={"екзекутор аррен","похоронний подзвін","командир","багряний хрестовий похід","погибель","відступники","тірісфаль"},ang={["faction:Horde"]="Передові накази Аррена в Похоронному Подзвоні — це перший плацдарм Орди в північному Лордероні, що забезпечує виживання серед ворожого оточення.",["race:Undead"]="Екзекутор Аррен — один із перших командирів, яких зустрічає кожен Відступник, вийшовши в Тірісфаль; він дає перший смак обов'язку на службі Темної Леді."},sec={{t="Командир Похоронного Подзвону",b="Непохитно стоячи одразу біля каплиці в Похоронному Подзвоні, Екзекутор Аррен — головний військовий голос молодих Відступників на землях їхнього пробудження. Поки доглядачі в склепах виводять щойно воскреслих мерців із заціпеніння, Аррен спрямовує їхню увагу назовні — на виживання. Під прапором Королеви Сильвани Віндраннер він організовує місцеві операції, щоб вимести безтямних зомбі, які загрожують межам села, і закріпити безпечну землю в тіні падіння Лордерона."},{t="Убезпечення прикордоння",b="Похоронний Подзвін оточують небезпеки куди смертоносніші за розгублених новачків. За наказом Аррена розвідники й посвячувані б'ють лютих павуків, що населяють Лощину Нічної Павутини, і знищують небезпечних хижаків на лісових узліссях. Вимагаючи рішучих дій від кожної здібної руки, Аррен випробовує стійкість новоприбулих, аби на службі Темної Леді лишалися тільки ті, хто здатен захистити свій другий шанс на існування."},{t="Багряна загроза",b="Найбільша стратегічна турбота Аррена — Багряний Хрестовий Похід. Фанатики вважають усю нежить чудовиськами, які належить винищити повністю, не вміючи чи не бажаючи відрізняти Погибель від вільних Відступників. Аррен організовує точкові удари по багряних патрулях, що отаборилися в нетрях Тірісфалю, перехоплює гінців і вивчає викрадені депеші, щоб уберегти Похоронний Подзвін від очищення святим вогнем."}},fp="14,332,23.510.0,24.454.0,18.435.1,22.220.0,44.211.0,49.217.0,46.218.0,27.196.0,58.189.0"}
P.entries["npc:executor-zygand"] = {n="Екзекутор Зиґанд",s="Екзекутор Зиґанд — старший командир Відступників в ратуші Брілла, що керує оборонними й військовими операціями по центральних Галявинах Тірісфалю. Підпорядкований безпосередньо верховному командуванню Андерсіті, він координує зачистку сил Багряного Хрестового Походу, що тиснуть на землі Відступників.",h="Екзекутор Зиґанд — старший командир Відступників в ратуші Брілла, що керує оборонними й військовими...",kw={"екзекутор зиґанд","брілл","ратуша","командир","багряний хрестовий похід","андерсіті","відступники"},ang={["faction:Horde"]="Мандрівники з Калімдору, що відвідують Галявини Тірісфалю, бачать у Зиґанді зібране, дисципліноване військове керівництво, що рухає боротьбу Відступників за Лордерон.",["race:Undead"]="Для Відступників, що виходять із Похоронного Подзвону, Екзекутор Зиґанд утілює ширшу військову владу Андерсіті, яка вітає нових громадян на дійсній службі проти їхніх найзапекліших ворогів."},sec={{t="Командування в Бріллі",b="З адміністративного серця Брілла Екзекутор Зиґанд координує оборону краю для Відступників після їхнього пробудження в Похоронному Подзвоні. Безпосередній начальник таких місцевих офіцерів, як Екзекутор Аррен, і польових вартівників, як Вартова Смерті Ліннея, Зиґанд зводить докупи донесення розвідки й висилає здібних новобранців боронити кордони Лордерона від зазіхань."},{t="Війна з Хрестовим Походом",b="Головна військова турбота Зиґанда — фанатична присутність Багряного Хрестового Походу, застави якого всіяли Галявини Тірісфалю. Під його орудою агентів планомірно висилають бити розвідників, табори й передові бази хрестоносців, щоб фанатики ніколи не зібрали достатньо сил загрожувати підступам до Андерсіті."}},fp="15,297,16.392.0,22.341.0,23.236.0,33.146.0,46.239.0,31.198.0,49.226.0,53.231.0"}
P.entries["npc:fandral-staghelm"] = {n="Фандрал Стаґгелм",s="Архідруїд Фандрал Стаґгелм очолює друїдів Кола Кенарія з Ценаріонського Анклаву в Дарнасусі. Прийшовши до влади після того, як Малфуріон Стормрейдж зник у Смарагдовому Сні, він став головним поборником насадження нового Світового Дерева — Тельдрассила. Гордий, різкий і невгамовно честолюбний, Фандрал обстоює рішуче відродження калдореїв, що раз у раз зіштовхує його з Верховною Жрицею Тірандою Віспервінд.",h="Архідруїд Фандрал Стаґгелм очолює друїдів Кола Кенарія з Ценаріонського Анклаву в Дарнасусі.",kw={"фандрал стаґгелм","архідруїд","тельдрассил","коло кенарія","дарнасус","валстанн","силітус","гординя"},ang={["class:Druid"]="Стаґгелм командує дарнаськими друїдами, штовхаючи Коло Кенарія до прямої влади над світом і сперечаючись із традиційним ученням сплячого Малфуріона Стормрейджа.",["faction:Alliance"]="Хоч Тельдрассил і править за бастіон Альянсу в північному Калімдорі, Стаґгелм дивиться на молодші раси з ледь прихованою зневагою й терпить їхню присутність лише з політичної доцільності.",["race:NightElf"]="Один із головних проводирів Дарнасуса, Фандрал утілює гордість і лють калдореїв: він рухає заселення Тельдрассила, навіть коли прості мешканці відчувають розкол між його анклавом і Храмом Місяця."},sec={{t="Архітектор Тельдрассила",b="Після Третьої війни й жертви Нордрассила на Горі Гіджал нічні ельфи втратили безсмертя та своє священне святилище. Поки Малфуріон Стормрейдж закликав до терпіння й застерігав від марнославства, Фандрал обстоював зухвалий задум — виростити нове Світове Дерево біля узбережжя Калімдору. Коли ж Малфуріон упав у кому в Смарагдовому Сні, Фандрал перехопив ініціативу й повів друїдів вирощувати Тельдрассил. У велетенському дереві він бачив пам'ятник витривалості калдореїв і засіб повернути втрачену велич — навіть попри те, що Аспекти драконів демонстративно відмовили несхваленому задуму в благословенні."},{t="Трагедія Рухливих Пісків",b="За тисячу років до Першої війни Фандрал був польовим командиром калдореїв у Силітусі під час Війни Рухливих Пісків. Комахоподібні кіраджі знали його як «Кар'сіса» — Руку Землі; він тримав передову пліч-о-пліч зі своїм улюбленим єдиним сином Валстанном. Скориставшись батьківською відданістю Фандрала, кіраджійський Генерал Раджакс улаштував оманливий напад на Село Південного Вітру, захопив Валстанна й безжально стратив його просто на очах у враженого жахом Архідруїда. Ця втрата зламала дух Фандрала, спричинила нищівний відступ і закарбувала в його гордовитій вдачі незгасну, гірку ненависть до рою."},{t="Суперництво й гординя",b="Серед мармурового гілля Дарнасуса Фандрал править справами калдореїв зверхньою, непоступливою рукою. На відміну від Верховної Жриці Тіранди Віспервінд, яка віддає перевагу духовному збереженню й обережній дипломатії, Фандрал уважає військове розширення та рішучу силу найголовнішими для виживання свого народу."}},fp="16,417,23.647.0,29.638.0,18.306.0,24.261.0,43.290.0,54.286.0,31.269.0,36.135.0"}
P.entries["npc:felix-whindlebolt"] = {n="Фелікс Віндлболт",s="Фелікс Віндлболт — переселений гном-біженець, що знайшов прихисток в Анвілмарі в Долині Холодного Хребта. Поспіхом утікаючи від радіації, яка затопила Гномреґан, він загубив свої пожитки, а ворожі тролі Морозогриви їх поцупили.",h="Фелікс Віндлболт — переселений гном-біженець, що знайшов прихисток в Анвілмарі в Долині Холодного Хребта.",kw={"фелікс віндлболт","гном","біженець","гномреґан","морозогриви","тролі","анвілмар"},ang={["race:Dwarf"]="Місцеві тролі Морозогриви посміливішали по всій Долині Холодного Хребта й нападають на беззахисних гномів-біженців, що блукають біля Анвілмара.",["race:Gnome"]="Фелікс утілює триваючу біду ваших переселених родичів, витіснених у безжальний холод Дун Мороґу після катастрофи в Гномреґані."},sec={{t="Переселений мандрівник",b="Після трагічного падіння Гномреґану тисячі гномів опинилися серед крижаних просторів Дун Мороґу в пошуках безпеки. Фелікс Віндлболт тікав з опроміненого міста так поспішно, що втратив усі особисті речі й інструменти. На додачу до лиха, крижані тролі Морозогриви віднесли його скриню, скриньку й відро болтів до своїх таборів на південний захід від Анвілмара, лишивши його безпорадним, без копійки й залежним від співчутливих мандрівників, які повернуть його вкрадене добро."}},fp="17,232,20.489.0,25.180.0,29.244.0,33.208.0,36.183.0"}
P.entries["npc:foreman-stonebrow"] = {n="Наглядач Стоунброу",s="Наглядач Стоунброу — дворфійський наглядач, що представляє Лігу Шахтарів у Кар'єрі Гол'Болар на сході Дун Мороґу. Коли зі скелі вирвалися люті троги й захопили розкопки, йому довелося організувати оборону й наймати шукачів пригод, щоб розчистити ями.",h="Наглядач Стоунброу — дворфійський наглядач, що представляє Лігу Шахтарів у Кар'єрі Гол'Болар на сході Дун...",kw={"наглядач стоунброу","ліга шахтарів","кар'єр гол'болар","троги","шахтарі","дун мороґ","харанос"},ang={["profession:Mining"]="Шахтарі мають професійний інтерес допомогти Стоунброу: повернути багаті поклади каменю й руди в кар'єрі життєво важливо для гільдійських робіт Каз Модану.",["race:Dwarf"]="Для дворфів навала трогів на Кар'єр Гол'Болар — прямий удар по каменярській промисловості Айронфорджа й похмуре нагадування про прадавні загрози, що чаяться під рідною землею."},sec={{t="Криза в Гол'Боларі",b="Наглядачу Стоунброу доручили керувати роботами в Кар'єрі Гол'Болар — важливих дворфійських розкопках у горах на схід від Хараноса. Коли глибоке копання пробилося до прихованих нір трогів, підземні тварюки заполонили ями й відігнали шахтарів від їхнього обладнання. Не бажаючи зовсім кидати місце, Стоунброу лишається на краю кар'єру, щоб залучити будь-яких здатних мандрівників, готових відтіснити трогів."}},fp="17,269,23.426.0,25.183.0,41.201.0,27.182.0,37.151.0"}
P.entries["npc:foreman-thazz-ril"] = {n="Наглядач Тазз'ріл",s="Наглядач Тазз'ріл — орк-наглядач за працею в Долині Випробувань у Дуроторі. Його справа — тримати пеонів у графіку й підтримувати базову інфраструктуру для молодих воїнів, і його невпинно дратують ліниві робітники та діяльність культистів поблизу.",h="Наглядач Тазз'ріл — орк-наглядач за працею в Долині Випробувань у Дуроторі.",kw={"тазз'ріл","наглядач","пеони","кирка","долина випробувань","ковен палаючого клинка","дуротар"},ang={["profession:Mining"]="Тазз'ріл цінує якісне гірниче знаряддя — досить згадати, як відчайдушно він хоче повернути свою зачаровану кирку з темних закутків Ковену Палаючого Клинка.",["race:Orc"]="Для молодих орків, що входять у дорослий вік, Тазз'ріл — ранній урок про суспільство Орди: сила на полі бою можлива лише тоді, коли її підпирає невдячна, дисциплінована праця."},sec={{t="Тримати пеонів у шорах",b="Збудувати новий дім у суворому червоному камені Дуротару — означає безкінечну фізичну працю. У Долині Випробувань Наглядач Тазз'ріл керує пеонами, що рубають ліс і збирають матеріали, потрібні і для табору, і для ширших воєнних зусиль Орди. На біду Тазз'ріла, пеони відомі схильністю байдикувати й дрімати під пустельним сонцем. Щоб будівництво не спинялося, він регулярно залучає новоприбулих новобранців добряче огріти заснулих робітників своїм надійним кийком, прищеплюючи послух тупою переконливістю."},{t="Загублена кирка в небезпечних руках",b="Обов'язки Тазз'ріла включають і розвідку мінеральних ресурсів долини, хоч саме цей обов'язок призвів до прикрої невдачі. Оглядаючи печеру, відому як Ковен Палаючого Клинка, він мусив тікати від темних культистів, що причаїлися всередині, і ненароком покинув свою дорогоцінну зачаровану кирку. Надто обережний, щоб самому забрати її серед чорнокнижників, що збираються там, і їхніх демонічних прислужників, він покладається на молодих кандидатів Орди, аби ті спустилися в глибини й повернули його знаряддя."}},fp="17,260,25.562.0,30.481.0,25.215.0,44.213.0,54.214.0,30.220.0"}
P.entries["npc:frahun-shadewhisper"] = {n="Фрагун Шейдвіспер",s="Фрагун Шейдвіспер — наставник розбійників, нічний ельф, що перебуває в Алдрассилі в Тінедолі. Він дає щойно посвяченим розвідникам і розбійникам — нічним ельфам основи скрадання, спритності й прихованих ударів. Він носить те саме родове ім'я, що й Еріон Шейдвіспер, інший наставник його ремесла в Дарнасусі.",h="Фрагун Шейдвіспер — наставник розбійників, нічний ельф, що перебуває в Алдрассилі в Тінедолі.",kw={"фрагун шейдвіспер","розбійник","наставник","алдрассил","тінедол","скрадання","еріон шейдвіспер"},ang={["class:Rogue"]="Фрагун Шейдвіспер — найперший класовий наставник розбійників — нічних ельфів, що дає початкове знайомство зі скраданням, тактикою засідок і тонкощами володіння зброєю.",["race:NightElf"]="Фрагун показує, як нічні ельфи обертають природну нічну вдачу й невловимість на смертоносні, практичні бойові навички для захисту Тельдрассила."},sec={{t="Наставник у тінях",b="У безпечному прихистку Алдрассила, в серці Тельдрассила, Фрагун Шейдвіспер навчає майбутніх розбійників тихого мистецтва маскування й володіння клинком. Хоч суспільство нічних ельфів частіше вшановує жерців, вартових і друїдів, особливе ремесло розвідників і лазутчиків лишається неодмінним для захисту віття Світового Дерева. Фрагун приймає новобранців, які приходять із зашифрованим сигілом, оцінює їхній потенціал і спрямовує їхній ранній розвиток."}},fp="19,308,23.468.0,27.178.0,39.100.0,40.173.0,49.172.0"}
P.entries["npc:furl-scornbrow"] = {n="Фурл Скорнброу",s="Фурл Скорнброу — літній орк-дозорець на сторожовій вежі на північний захід від Гострого Пагорба. Через похилі роки він уже не може битися на передовій, тож пильнує червоні каньйони Дуротару й шиє міцні торби для молодих мандрівників, що вирушають краєм.",h="Фурл Скорнброу — літній орк-дозорець на сторожовій вежі на північний захід від Гострого Пагорба.",kw={"фурл скорнброу","дозорець","сторожова вежа","гострий пагорб","торби","ветеран","дуротар"},ang={["faction:Horde"]="Розташований на хребтах за Гострим Пагорбом, Фурл утілює пильність, потрібну, щоб захистити молоді поселення Дуротару від загроз, які нікуди не поділися.",["race:Orc"]="Фурл утілює орче переконання: навіть коли вік відбирає у воїна бойову силу, гідне життя означає знайти інший спосіб служити клану й Орді."},sec={{t="Дозорець на хребті",b="Високо на дерев'яній сторожовій вежі одразу на північний захід від Гострого Пагорба Фурл Скорнброу несе тиху варту над центральними рівнинами Дуротару. У напружені перші дні після заснування Оргріммара вартові на кшталт Фурла були життєво важливі: саме вони сурмили в сигнальні роги проти ворожих шипогривів, кентаврів і зайд із Кул Тірасу. Відколи Дуротар устабілізувався, а Гострий Пагорб зміцнив кордони, тривоги стали рідшими, і у Фурла на посту вдосталь тихих годин."},{t="Корисна пара рук",b="Фурл відверто визнає, що старі кістки й згасла сила роблять його непотрібним у бою, та орк нелегко зрікається свого призначення. Замість сидіти без діла, він береться шити парусинові мішки й торби для нових новобранців, яким треба носити припаси. В обмін на грубу нитку й практичні матеріали він споряджає зелених шукачів пригод, що вирушають довести свою цінність Орді."}},fp="14,282,21.468.0,22.410.0,22.248.0,31.249.0,42.251.0"}
P.entries["npc:gaerolas-talvethren"] = {n="Ґеролас Талветрен",s="Ґеролас Талветрен — вартовий, нічний ельф, що стоїть на сторожі руїн Села Зоряного Вітерця в Тельдрассилі. Призначений захисником Сплячих друїдів, він шукає допомоги проти напасливих фурболгів і темної скверни, що збурює віття.",h="Ґеролас Талветрен — вартовий, нічний ельф, що стоїть на сторожі руїн Села Зоряного Вітерця в Тельдрассилі.",kw={"ґеролас талветрен","вартовий","сплячі друїди","село зоряного вітерця","вузлошкіри","фурболги","смарагдовий сон"},ang={["class:Druid"]="Обов'язок Ґероласа як охоронця сплячих друїдів робить допомогу йому особистою справою захисту побратимів із Кола Кенарія.",["race:NightElf"]="Для молодих нічних ельфів, що покидають Доланаар, допомога Ґероласу дає тверезий погляд на те, як глибоко скверна проникла у священне віття Тельдрассила."},sec={{t="Охоронець Сплячих",b="Посеред стривоженого поселення Зоряного Вітерця Ґеролас Талветрен несе урочистий обов'язок захищати Сплячих друїдів, що спочивають у єднанні зі Смарагдовим Сном. Його варта стала тривожною, відколи неприродна скверна повзе лісом, порушуючи рівновагу Тельдрассила."},{t="Загроза Вузлошкірів",b="Ґеролас спрямовує мандрівників дати відсіч племені фурболгів Вузлошкірів, чий розум обернувся на безумство й дикість. Досліджуючи скверну, що шириться від їхніх шаманів, і шукаючи корені їхнього лиха, він сподівається зберегти рештки святості у східному Тельдрассилі."}},fp="19,256,24.310.0,20.292.0,27.169.0,37.91.0,46.185.0,41.136.0"}
P.entries["npc:galgar"] = {n="Ґалґар",s="Ґалґар — орк-кухар у Долині Випробувань у Дуроторі. Він готує харчі для молодих новобранців, що роблять перші кроки на службі Орді. Щоб навчити новачків основ збиральництва в суворій пустелі, він доручає їм збирати дикі кактусові яблука для своєї фірмової страви.",h="Ґалґар — орк-кухар у Долині Випробувань у Дуроторі.",kw={"ґалґар","кухар","кактусове яблуко","долина випробувань","їжа","новобранці","дуротар"},ang={["profession:Cooking"]="Ґалґар утілює практичну, просту кухню Орди: він використовує мізерні природні ресурси Дуротару, щоб новобранці були нагодовані й готові до бою.",["race:Orc"]="Для молодих орків, що роблять перші кроки в Долині Випробувань, доручення Ґалґара — звичний обряд переходу перед зустріччю з лютішими загрозами нетрів."},sec={{t="Кухар у долині",b="Ґалґар, що розташувався біля кухонного вогнища Лігва в Долині Випробувань, годує молодих орків і тролів, які проходять перші обряди переходу. Дуротар — суха, безжальна червона пустка, де кожну крихту поживи треба вирвати в землі. Відправляючи воїнів-новачків збирати стиглі кактусові плоди, Ґалґар перевіряє їхню уважність і стійкість і водночас поповнює запаси своєї кухні."},{t="Сюрприз із Кактусових Яблук",b="Фірмовий рецепт Ґалґара відомий як Сюрприз із Кактусових Яблук. Хоч він відверто визнає, що пошук колючих пустельних плодів — навмисне просте завдання, аби м'яко ввести новобранців у життя шукачів пригод, кінцевий продукт лишається основним харчем для голодних учнів. Навіть найзагартованіший воїн Орди має з чогось починати, і під пильним оком Ґалґара цей шлях починається з пустельного збиральництва."}},fp="6,294,20.415.0,21.418.0,24.177.0,39.157.0,48.211.0,30.139.0"}
P.entries["npc:gar-thok"] = {n="Ґар'Ток",s="Ґар'Ток — ветеран-орк, воїн і командир застави в Гострому Пагорбі в Дуроторі. Він бився на Горі Гіджал і пережив перші висадки Кул Тірасу на узбережжі Дуротару, а нині керує місцевою обороною від людських зайд і тутешніх загроз. Він спрямовує молодих новобранців Орди, що виходять із Долини Випробувань, убезпечувати червоні пустки нової батьківщини.",h="Ґар'Ток — ветеран-орк, воїн і командир застави в Гострому Пагорбі в Дуроторі.",kw={"ґар'ток","гострий пагорб","ветеран","кул тірас","гора гіджал","командир","дуротар"},ang={["class:Warrior"]="Як командир передової, що пережив і демонічні легіони, і жорстокі морські засідки, Ґар'Ток чекає від побратимів-воїнів бойової стійкості й беззастережного послуху.",["faction:Horde"]="Ґар'Ток дбає, щоб нові новобранці всіх народів Орди розуміли хиткість своєї нової землі, і спрямовує їх відбивати рештки загарбників з Альянсу.",["race:Orc"]="Для молодих орків, що покидають Долину Випробувань, Ґар'Ток утілює сувору, непохитну дисципліну покоління ветеранів, яке стікало кров'ю на Горі Гіджал, щоб здобути Дуротар."},sec={{t="Ветеран червоних пусток",b="Перш ніж осісти в Гострому Пагорбі, Ґар'Ток боронив орчий табір під час апокаліптичної Битви за Гору Гіджал. Після Третьої війни він рушив у Дуротар під проводом Вождя Тралла і служив лейтенантом під командою Назґрела в найперші дні будівництва нової батьківщини. Коли мандрівник-мок'натал Рекссар уперше прибув у Дуротар, саме Ґар'Ток попередив його про агресивних шипогривів, що нападали на їхній периметр, і залучив володаря звірів до захисту крихкого нового поселення."},{t="Пережити вторгнення адмірала",b="Рішучість Ґар'Тока випробувало те, що флот Кул Тірасу Великого адмірала Дейліна Праудмура висадився на східних берегах Дуротару. Стоячи на віддаленому сторожовому посту, Ґар'Ток бачив, як його гарнізон здолали й жорстоко вирізали морські піхотинці. Хоч його сили було знищено, Ґар'Ток пережив той наступ. Пам'ять про раптовий напад закріпила його пильність щодо вцілілих піхотинців, які й досі тримають Фортецю Тіраґард і прибережні кораблетрощі."},{t="Оборона Гострого Пагорба",b="Нині Ґар'Ток керує військовою обороною центрального Дуротару з казарм Гострого Пагорба. Він не марнує часу на люб'язності й одразу доручає молодим воїнам, шаманам і розвідникам Орди вичищати ворожі рештки Кул Тірасу, забирати врятовані припаси й повертати військові накази, покинуті в прибережних руїнах. Для нього безпека Дуротару далеко не гарантована і потребує постійного тиску на всіх, хто ставить під сумнів право Орди на цю землю."}},fp="8,378,27.491.0,32.468.0,21.473.0,16.219.0,53.217.0,53.239.0,53.219.0,49.219.0,28.133.0"}
P.entries["npc:gart-mistrunner"] = {n="Ґарт Містраннер",s="Ґарт Містраннер — наставник друїдів, що працює в Таборі Нарачі на Плато Червоної Хмари. Він вітає новачків-тауренів, яких покликала Мати-Земля, і веде їх крізь перші обряди магії природи.",h="Ґарт Містраннер — наставник друїдів, що працює в Таборі Нарачі на Плато Червоної Хмари.",kw={"ґарт містраннер","друїд","наставник","табір нарачі","плато червоної хмари","му'ша"},ang={["class:Druid"]="Для друїдів-тауренів Ґарт Містраннер — найперший учитель, що формує їхнє єднання з дикою природою й дарами Матері-Землі.",["race:Tauren"]="Ґарт уособлює відродження стародавніх друїдичних традицій шу'гало й передає мудрість предків молоді Табору Нарачі."},sec={{t="Наставник Плато Червоної Хмари",b="Табір Нарачі — місце, де чатує Ґарт Містраннер, уособлення стародавнього друїдичного шляху, відродженого серед шу'гало. Нових друїдів-тауренів направляють просто до Ґарта, щойно вони роблять перші кроки на Плато Червоної Хмари, і часто вони несуть зелену записку, що доручає їх його опіці. Під його терплячим проводом молоді адепти вчаться єднатися зі світом природи й черпати відновлювальні сили природи та місячне сяйво Му'ші, щоб зцілювати союзників і нищити загрози землі."}},fp="15,206,28.505.0,23.168.0,48.150.0,46.160.0"}
P.entries["npc:gerard-tiller"] = {n="Джерард Тіллер",s="Джерард Тіллер — спраглий людський наймит, що працює біля клуні на Виноградниках Маклюрів у Лісі Елвінн. Доглядаючи виноградники під теплим сонцем, він завжди радий обміняти хрустке блискуче червоне яблуко на бурдюк свіжої джерельної води від будь-якого подорожнього.",h="Джерард Тіллер — спраглий людський наймит, що працює біля клуні на Виноградниках Маклюрів у Лісі Елвінн.",kw={"джерард тіллер","яблука","джерельна вода","виноградники маклюрів","наймит","ґолдшир"},ang={["profession:Cooking"]="Готовність Джерарда міняти свіжі яблука на просту джерельну воду робить його зручним джерелом фруктів для мандрівних кухарів, що шукають простих інгредієнтів."},sec={{t="Спраглий наймит",b="Джерард Тіллер проводить дні, працюючи в полі й порядкуючи біля клуні на Виноградниках Маклюрів. Виноградник одразу на південь від Ґолдширу родить один із найвідоміших сортів винограду Елвінну, та підтримувати врожай — тяжка праця. Тіллера від роботи постійно мучить спрага, тож він охоче торгується з перехожими шукачами пригод. Якщо хтось запропонує йому свіжий бурдюк прохолодної джерельної води, він радо віддячить свіжими блискучими червоними яблуками просто з тутешніх садів."}},fp="13,272,18.515.0,21.112.0,31.131.0,30.118.0,60.175.0"}
P.entries["npc:gilshalan-windwalker"] = {n="Ґілшалан Віндвокер",s="Ґілшалан Віндвокер — дослідник, нічний ельф, що відпочиває біля підніжжя великого дерева Алдрассил у Тінедолі. Стривожений раптовою скверною, що вкорінюється в Тельдрассилі, він вивчає тутешню звірину, щоб зрозуміти неприродну лють, яка вразила віття. Його дослідження павуків Вебвуда дають перші підказки про гниль, що точить Світове Дерево.",h="Ґілшалан Віндвокер — дослідник, нічний ельф, що відпочиває біля підніжжя великого дерева Алдрассил у Тінедолі.",kw={"ґілшалан віндвокер","дослідник","павуки вебвуда","алдрассил","тінедол","печера тіньової нитки","тенарон стормґріп"},ang={["class:Druid"]="Його дослідження прямо підтримують спроби Кола Кенарія розпізнати порушення природної рівноваги, що ятриться у вітті Тінедолу.",["race:NightElf"]="Ґілшалан уособлює перші зусилля вашого народу зрозуміти, чому новопостале Світове Дерево вже породжує уражену, несамовиту звірину."},sec={{t="Учений біля коріння",b="Спокійно сидячи на кам'яних сходах, що ведуть в Алдрассил, Ґілшалан Віндвокер із дедалі більшою тривогою спостерігає за тихим шатром Тінедолу. Тельдрассил посадили, щоб повернути нічним ельфам утрачений прихисток і злагоду з природою, та ознаки глибокої духовної недуги з'явилися майже одразу. Ґілшалан присвятив себе вивченню того, як ця скверна проявляється в тутешніх звірах, починаючи з отруйних павуків, що плетуть павутиння неподалік."},{t="Загроза Вебвуда",b="Головна увага Ґілшалана зосереджена на павуках Вебвуда, що чигають у Печері Тіньової Нитки на півночі. Ці створіння, колись урівноважена частина лісового живого світу, стали неприродно ворожими й споганеними. Посилаючи молодих новачків збирати отруйні мішки й цілі павучі яйця, Ґілшалан працює над аналізом зміненої сили отрути і намагається розрізнити, чи передається скверна з покоління в покоління, чи шириться ззовні, через ґрунт Тельдрассила."},{t="Звістка Архідруїдові",b="Маючи отруту і яйце, Ґілшалан вважає, що отрута павуків виявить властивості, пов'язані з нещодавнім зростанням нового Світового Дерева. Він улаштовує відправлення зразків до Дарнасуса, де продовжить свої дослідження. А ще він переказує перспективним захисникам, що Тенарон Стормґріп питав про них у найвищій кімнаті Алдрассила, звідки друїдський провід пильнує молоде Світове Дерево."}},fp="20,370,22.466.0,18.458.0,21.429.1,28.174.0,38.153.0,37.236.0,43.151.0,38.131.0,45.187.0"}
P.entries["npc:gornek"] = {n="Ґорнек",s="Ґорнек — орк-наглядач у Долині Випробувань у Дуротарі. Саме він першим приймає нових орків і тролів Темного Списа, які готуються довести свою цінність Новій Орді.",h="Ґорнек — орк-наглядач у Долині Випробувань у Дуротарі.",kw={"ґорнек","наглядач","орк","долина випробувань","новобранці","дуротар","нова орда"},ang={["race:Orc"]="Для молодих орків з'явитися до Ґорнека — найперший крок до того, щоб скинути дитинство й заслужити почесне місце в Дуротарі.",["race:Troll"]="Як союзники під захистом Тралла, тролі Темного Списа показують Ґорнекові свої вірчі знаки, щоб довести: вони — гідні рівні поруч зі своїми братами-орками."},sec={{t="Зустріч неперевірених",b="Стоячи в самому серці Долини Випробувань, Ґорнек — перше випробування дисципліни для майбутніх воїнів, розвідників і чаклунів Орди. За наказом Вождя Тралла кожен юнак і кожен новоприбулий має заслужити своє місце завзяттям і наполегливістю, а не правом народження. Ґорнек оцінює тих, хто ступає в долину, читає їхні супровідні накази й скеровує до наставників по всьому табору. Чи приніс посвячуваний зашифровану писульку, гліфічний пергамент чи просту табличку — саме Ґорнек приймає його вірчі знаки й ставить на суворий шлях виживання."},{t="Життя на службі Дуротару",b="Посушливі каньйони долини випробовують не лише бойову вправність — вони прищеплюють дух спільноти Нової Орди. Ґорнек стежить, щоб новачки не тинялися без діла, і спрямовує їх до випробувань у сусідніх норах скорпідів, лігвах диких вепрів і під пильним оком бувалих наставників. Тим, хто переживе тренувальні угіддя й знищить загрози, що чаяться в червоних скелястих балках, Ґорнек дає останнє визнання, перш ніж відіслати їх у широкий і небезпечний Дуротар."}},fp="6,204,22.613.0,28.513.0,14.190.0,24.155.0,34.221.0,34.207.0"}
P.entries["npc:gramma-stonefield"] = {n="Бабуся Стоунфілд",s="Бабуся Стоунфілд, на ім'я Мілдред, — літня матріарх родини Стоунфілдів, що живе на їхній фермі в Лісі Елвінн. На відміну від своєї сварливої рідні, вона втомилася від гіркої ворожнечі з сусідами Маклурами, що тягнеться поколіннями. Тихо діючи за спиною родини, вона робить усе можливе, щоб допомогти онукові Томмі Джо в його забороненому коханні до Мейбелл Маклур.",h="Бабуся Стоунфілд, на ім'я Мілдред, — літня матріарх родини Стоунфілдів, що живе на їхній фермі в Лісі Елвінн.",kw={"бабуся стоунфілд","мілдред","томмі джо","мейбелл маклур","ворожнеча","закохані"},ang={["faction:Alliance"]="Бабуся Стоунфілд — лагідне нагадування про те, що навіть у серці Альянсу місцеві конфлікти часто потребують тихої дипломатії й простого співчуття, а не сталі."},sec={{t="Таємна миротвориця",b="Як найстарша з живих у роді Стоунфілдів, Мілдред Стоунфілд десятиліттями спостерігала дріб'язкові чвари між своїм домом і Маклурами через дорогу. Замість роздмухувати ворожнечу, вона вважає це тривале суперництво безглуздим і руйнівним. Коли її онук Томмі Джо Стоунфілд закохується в Мейбелл Маклур, Бабуся обирає співчуття замість вірності роду. Покладаючись на давню дружбу з Вільямом Пестлом із Ґолдширу, вона потай задумує допомогти нещасливим закоханим зустрітися таємно, підриваючи вперту ворожнечу, що розділяє дві ферми."}},fp="17,404,19.576.0,25.178.0,51.211.0,41.239.0,29.226.0"}
P.entries["npc:greatmother-hawkwind"] = {n="Прамати Гоквінд",s="Прамати Гоквінд — шанована старійшина тауренів, що відпочиває біля водяної криниці на Плато Червоної Хмари. Мати ватажка Табору Нарачі, Вождя Гоквінда, вона попри поважний вік уособлює незламний дух і спільну відповідальність племені.",h="Прамати Гоквінд — шанована старійшина тауренів, що відпочиває біля водяної криниці на Плато Червоної Хмари.",kw={"прамати гоквінд","старійшина","вождь гоквінд","криниця","смирення","табір нарачі"},ang={["race:Tauren"]="Для молодих тауренів, що починають шлях на Плато Червоної Хмари, Прамати Гоквінд уособлює головні цінності Матері-Землі: шану до старійшин, єдність громади й смирення в служінні."},sec={{t="Старійшина плато",b="Прамати Гоквінд проводить дні біля криниці з прісною водою, що її має Табір Нарачі, і є духовною матріархинею для молодих тауренів, які починають обряди посвяти. Роки сповільнили її ходу, та вона не дозволяє вікові відсторонити її від обов'язку перед селищем. Вона вірить, що кожен член племені, молодий чи старий, має свою роль у підтримці громади, і часто просить молодь допомогти з простими домашніми справами — як-от принести свіжої води."},{t="Материнська настанова",b="Як мати Вождя Гоквінда, ватажка Табору Нарачі, Прамати Гоквінд дає сталу пораду й тиху гідність посеред загроз, що нависли над Плато Червоної Хмари. Поки її син збирає мисливців і воїнів проти шипогривів Щетиноспинних і місцевих хижаків, вона дбає про моральне серце поселення й нагадує щойно пробудженим: сила починається зі смирення й служіння своїм родичам."}},fp="20,247,17.476.0,19.413.0,28.203.0,23.96.0,40.205.0,39.107.0"}
P.entries["npc:grelin-whitebeard"] = {n="Ґрелін Вайтбірд",s="Ґрелін Вайтбірд — дворфський розвідник, якого королівським наказом відрядили до Долини Холодного Хребта оцінити загрозу від тролів Морозогривів. Він працює з відлюдного табору разом із недолугим учнем і покладається на молодих шукачів пригод, щоб стримувати тролів, поки увагу Айронфорджа цілком поглинула навала трогів.",h="Ґрелін Вайтбірд — дворфський розвідник, якого королівським наказом відрядили до Долини Холодного Хребта...",kw={"ґрелін вайтбірд","розвідник","долина холодного хребта","морозогриви","тролі","дун мороґ","щоденник"},ang={["faction:Alliance"]="Становище Ґреліна показує, як тонко розтягнуті сили Альянсу й Айронфорджа в Дун Мороґу: самотнім розвідникам доводиться вести тихі війни з тролячими анклавами.",["race:Dwarf"]="Служачи безпосередньо Королю Маґні, Ґрелін уособлює тиху вперту наполегливість розвідників Айронфорджа, які тримають кордони Дун Мороґу попри дедалі більші внутрішні загрози.",["race:Gnome"]="Гномські біженці, що тікають від трагедії Гномреґану через Долину Холодного Хребта, застають у віддаленому таборі Ґреліна гнома-мандрівника, який працює пліч-о-пліч з ним."},sec={{t="Королівське доручення",b="Ґреліна Вайтбірда та його брата Сеніра відрядили до Долини Холодного Хребта за прямим наказом Сенату Айронфорджа й самого Короля Маґні Бронзбірда. Завдання було чітке: оцінити й усунути загрозу від тутешніх тролів Морозогривів. Та оскільки регулярне військо Айронфорджа загрузло в боротьбі з трогами по всьому Дун Мороґу, братам дали геть мало засобів. Ґрелінові довелося розбити табір серед засніжених пагорбів і покладатися на місцевих добровольців та новачків, що проходили повз, аби виконати всю потрібну роботу."},{t="Клопоти на півдні",b="Зі свого табору Ґрелін стежить за племенем Морозогривів, що насувається з півдня Долини Холодного Хребта. Тролі стають дедалі зухвалішими й вилазять зі своїх гірських печер на все сміливіші набіги. Під час одного з них розмальований здоровань на ім'я Ґрік'нір Холодний прослизнув у покинутий без нагляду табір і поцупив польовий щоденник Ґреліна з його найважливішими спостереженнями. Не бажаючи підвести Короля, Ґрелін посилає відчайдушних мандрівників углиб печер Морозогривів, щоб повернути вкрадені записи й передати остаточний звіт Сенірові в Харанос."}},fp="17,309,15.563.0,20.567.0,46.284.0,27.207.0,24.228.0,31.146.0,56.221.0,46.184.0"}
P.entries["npc:grif-wildheart"] = {n="Ґріф Вайлдгарт",s="Ґріф Вайлдгарт — досвідчений дворфський наставник мисливців, що стоїть біля Ґуральні Тандербрю в Хараносі. Серед місцевих горян він славиться глибоким зв'язком із дикою природою і навчає молодих стрільців вистежувати здобич, влучно стріляти й приборкувати звірів. Для юних мисливців, що виходять із Долини Холодного Хребта, Ґріф — важлива ланка між першим пострілом з рушниці та вірним звіром поруч.",h="Ґріф Вайлдгарт — досвідчений дворфський наставник мисливців, що стоїть біля Ґуральні Тандербрю в Хараносі.",kw={"ґріф вайлдгарт","мисливець","наставник","приборкання звірів","харанос","дун мороґ"},ang={["class:Hunter"]="Ґріф — головний наставник, який долучає мисливців Альянсу до приборкання звірів, даючи вам важливі завдання, що дозволять зріднитися з дикими хижаками Дун Мороґу.",["faction:Alliance"]="Стоячи в Хараносі, Ґріф готує розвідників і стрільців Альянсу до виживання в суворій глушині навколо гірського королівства Айронфордж.",["race:Dwarf"]="Утілюючи традицію дворфських горян, Ґріф показує, як сувора витривалість дворфів робить їх напрочуд придатними до життя пліч-о-пліч із дикими гірськими звірами."},sec={{t="Життя серед дикої природи",b="Поки більшість дворфів Айронфорджа віддають перевагу вогняному теплу кузні чи розміреному дзенькоту кайл, Ґріф Вайлдгарт цілком присвятив своє життя морозній глушині Дун Мороґу. Місцеві горяни напівжартома кажуть, що він надто багато часу проводить із чотирилапими, але ніхто не заперечує його майстерності в дикій природі. Роками вистежуючи здобич на засніжених хребтах пліч-о-пліч із бувалими мисливськими супутниками, Ґріф досконало пізнав хижаків, які блукають тутешніми скелями."},{t="Шлях Звіра",b="Коли молоді дворфи-мисливці завершують перші випробування в Долині Холодного Хребта, їх одразу скеровують до Хараноса по настанови Ґріфа. Він вигострює їхню влучність і вчить виживати в глушині, та справжнє його покликання — ковати зв'язок між мисливцем і звіром. Через низку суворих випробувань Ґріф посилає учнів із жезлом приборкання в крижані пустки, щоб вони випробували себе на знакових хижаках Дун Мороґу: великих скельних вепрах, снігових леопардах та льодокігтих ведмедях."},{t="Шлях до Високого Престолу",b="Щойно мисливець доведе, що має волю й витримку приборкати трьох різних диких звірів, наука Ґріфа в Хараносі добігає кінця. Розуміючи, що мисливець має також навчитися годувати, виховувати й тренувати нового союзника, він відправляє випускників угору схилом до Айронфорджа. Там, під величними склепіннями дворфської столиці, мисливці-новачки звертаються до майстрів-звіролюбів, щоб опанувати глибше мистецтво догляду за своїм довічним супутником."}},fp="14,424,19.495.0,20.507.0,24.472.0,22.187.0,32.138.0,36.200.0,43.152.0,66.188.0,49.198.0"}
P.entries["npc:grull-hawkwind"] = {n="Ґрулл Гоквінд",s="Ґрулл Гоквінд — молодий сміливець-таурен, що служить у Таборі Нарачі на Плато Червоної Хмари в Малгорі. Син Вождя Гоквінда, він допомагає вести новачків-тауренів, які роблять найперші кроки у світ. Він проводить молодих мисливців і воїнів крізь найперші випробування, щоб перевірити їхню рішучість і вшанувати предків.",h="Ґрулл Гоквінд — молодий сміливець-таурен, що служить у Таборі Нарачі на Плато Червоної Хмари в Малгорі.",kw={"ґрулл гоквінд","сміливець","вождь гоквінд","табір нарачі","випробування","мисливець","малгор"},ang={["class:Hunter"]="Ґрулл дає мисливцям-новачкам засадничі перші завдання, перевіряючи їхнє терпіння й уміння на звірині Малгору.",["race:Tauren"]="Для молодих тауренів, що виходять на Плато Червоної Хмари, Ґрулл Гоквінд часто стає найпершим сміливцем, який випробовує їхню доблесть і знайомить із традиціями шу'гало."},sec={{t="Син вождя",b="Гордо стоячи поруч зі сміливцями й старійшинами, яких зібрав Табір Нарачі, Ґрулл Гоквінд несе і гордий родовід Вождя Гоквінда, і відповідальність за підготовку молоді племені. Він — перший наставник для новоприбулих на Плато Червоної Хмари, який оцінює їхню готовність служити шу'гало. Даючи випробування на витривалість, слідопитство й виживання серед місцевих звірів — степових довгоступів і гірських пум, — Ґрулл дбає, щоб молоді таурени зрозуміли: рівновага й шана до природи — підвалини життя в Малгорі."}},fp="14,320,17.542.0,22.230.0,57.194.0,42.146.0"}
P.entries["npc:guard-thomas"] = {n="Вартовий Томас",s="Вартовий Томас — відданий солдат армії Стормвінда, що стоїть біля мосту на захід від Лісозаготівельного Табору Східної Долини. Відрізаний на східному порубіжжі Лісу Елвінн, він керує обороною місцевих поселенців від хижої звірини та мурлоків, що насуваються.",h="Вартовий Томас — відданий солдат армії Стормвінда, що стоїть біля мосту на захід від Лісозаготівельного...",kw={"вартовий томас","вартовий","міст","східна долина","мурлоки","ліс елвінн","стормвінд"},ang={["class:Warrior"]="Для молодих воїнів Альянсу Томас — приклад дисципліни передової та непривабливої дійсності оборони кордонів краю.",["faction:Alliance"]="Вартовий Томас утілює перенапружений стан армії Стормвінда: він тримає важливу заставу на порубіжжі з мінімальною підтримкою від корони."},sec={{t="На східному кордоні",b="Поки увага королівства здебільшого звернена всередину, до столиці, або на захід, до Вестфолу, Вартовий Томас тримає один із найтихіших, але найхиткіших постів у Лісі Елвінн. Стоячи біля кам'яного мосту через річку в бік Лісозаготівельного Табору Східної Долини, Томас — тонка лінія оборони між простими лісорубами та войовничими створіннями, що блукають лісом. Оскільки військо Стормвінда розтягнуте до краю, вартовим на кшталт Томаса доводиться чимало покладатися на перехожих шукачів пригод, щоб підтримувати лад і передавати донесення до центрального командування."},{t="Клопоти порубіжжя",b="Східні околиці Елвінну зазнають невпинного тиску. Войовничі ведмеді та хижаки скрадаються узліссям, загрожуючи лісорубам і мандрівникам, а дивні племена мурлоків розбили табори вздовж водойм. Томас стежить за пересуванням цих водяних хижаків і призначає винагороди за їхнє винищення. Ще гірше: розвідувальні патрулі вздовж річки часом зникають безслідно, і Томасові доводиться самотужки з'ясовувати долю товаришів по варті посеред дедалі більшої нестабільності в краї."}},fp="12,261,21.542.0,17.495.1,30.142.0,45.258.0,53.251.0,43.251.0,32.275.0,75.208.0"}
P.entries["npc:gunther-arcanus"] = {n="Ґунтер Арканус",s="Ґунтер Арканус — надзвичайно могутній некромант, що живе на відлюдному острові посеред Озера Світлої Води. Убитий під час Третьої війни й воскреслий нежиттю, він зумів цілком самотужки розірвати ментальну хватку Короля-Ліча. Довго вважаючи себе єдиним мерцем із вільною волею, він боронив свій притулок від усіх чужинців, аж поки його не знайшли Відступники.",h="Ґунтер Арканус — надзвичайно могутній некромант, що живе на відлюдному острові посеред Озера Світлої Води.",kw={"ґунтер арканус","некромант","озеро світлої води","даларан","кірін-тор","бетор айсшард","король-ліч","відступники"},ang={["class:Mage"]="Навчений у Даларані, Ґунтер утілює тих чарівників Кірін-Тору, що потай бавилися забороненими некромантськими закляттями ще до вторгнення Погибелі в Лордерон.",["class:Warlock"]="Владне опанування Ґунтером темних мистецтв і воскрешення показує, як далеко могла зайти заборонена наука поза пильним оком керівництва Даларана.",["race:Undead"]="Самозвільнення Ґунтера робить його винятком серед Відступників: воно доводить, що лише напружене навчання таємним мистецтвам і залізна воля іноді могли розбити ментальне панування Короля-Ліча."},sec={{t="Учень Даларана",b="До падіння Лордерона Ґунтер був перспективним учнем Кірін-Тору в Даларані. Разом із близькими друзями Бетором Айсшардом і Тулом Рейвенкловом він вивчав таємні мистецтва й потай заглиблювався в некромантію попри сувору заборону Кірін-Тору на темну магію. На пам'ять про своє братерство троє друзів колись сплели свої учнівські жезли в єдину реліквію."},{t="Розірвані кайдани",b="Коли під час Третьої війни Погибель прокотилася північчю, Ґунтер загинув від Чуми Нежиті й був воскрешений для служби. На відміну від більшості, кому знадобилося послаблення влади Короля-Ліча або Леді Сильвана, щоб розірвати ланцюги, Ґунтер завдяки своїй могутній таємній майстерності й незламній волі сам, повністю, скинув ментальне панування Короля-Ліча. Переконаний, що кожен інший ходячий труп лишається безтямним рабом Погибелі, він усамітнився на острові в Галявинах Тірісфалю, оточив себе шкутильгаючими охоронцями й відрізав усі зв'язки і з живими, і з мертвими."},{t="Блудний ліч",b="Шукаючи могутніх союзників проти Погибелі, Відступники послали емісарів здобути книгу заклять таємничого некроманта. Вивчаючи таємничий фоліант в Андерсіті, Бетор Айсшард упізнав неповторний почерк давно втраченого товариша. Зачарувавши повернений гримуар і зажадавши знищення місцевих командирів Погибелі, Ґунтер нарешті збагнув, що не самотній у своїй свободі. Переконаний, що фракція Сильвани — справжнє повстання проти Погибелі, він уклав угоду з колишнім однокашником допомагати Відступникам."}},fp="15,371,20.392.0,21.596.0,17.549.1,23.229.0,73.258.0,42.272.0,38.213.0,31.216.1,22.198.1"}
P.entries["npc:hana-zua"] = {n="Гана'зуа",s="Гана'зуа — троль-розвідник Темного Списа в Долині Випробувань, що став жертвою отруйних звірів, які нишпорять гребенями каньйону. Уражений і поранений страхітливим скорпідом Саркотом, він лежить і чекає на допомогу молодих посвячуваних Орди, які прагнуть довести свою звитягу.",h="Гана'зуа — троль-розвідник Темного Списа в Долині Випробувань, що став жертвою отруйних звірів, які нишпорять...",kw={"гана'зуа","саркот","скорпід","троль","розвідник","долина випробувань","отрута"},ang={["faction:Horde"]="Виживання й помста Гана'зуа — одне з найперших випробувань вірності та бойової готовності для майбутніх чемпіонів Орди.",["race:Troll"]="Для посвячуваних Темного Списа, що тільки починають шлях у Дуроторі, зустріч із пораненим родичем підкреслює смертоносність тутешньої звірини й потребу захищати новознайдених союзників."},sec={{t="Розвідник, якого здолала отрута",b="Перетинаючи посушливі висоти над Долиною Випробувань, Гана'зуа натрапив на Саркота — надзвичайно лютого й отруйного скорпіда, що нишпорить скелями. Здоланий і вжалений звіром, троль ледве пережив сутичку. Не в змозі рухатися чи сам повернутися до табору, він знемагає в пилу, сподіваючись, що перехожі новобранці доб'ють створіння й передадуть звістку про його біду до Лігва."}},fp="8,277,23.422.0,16.145.0,26.178.0,33.182.0"}
P.entries["npc:hands-springsprocket"] = {n="Гендс Спрінґспрокет",s="Гендс Спрінґспрокет — працьовитий гном, що стоїть біля входу до Перевалу Холодного Кряжа в Дун Мороґу. Він узгоджує постачання між відлюдними навчальними угіддями Долини Холодного Хребта й містечком Харанос, хоча недавні набіги трогів добряче йому заважають.",h="Гендс Спрінґспрокет — працьовитий гном, що стоїть біля входу до Перевалу Холодного Кряжа в Дун Мороґу.",kw={"гендс спрінґспрокет","гном","постачання","перевал холодного кряжа","троги","харанос","долина холодного хребта"},ang={["faction:Alliance"]="Гендс підтримує рух життєво важливих внутрішніх ліній постачання між дворфійськими новобранцями в Долині Холодного Хребта й поселеннями в глибині Дун Мороґу.",["race:Gnome"]="Для гномів-біженців, переселених із Гномреґану, Гендс утілює тиху рішучість гномів, що вливаються в місцеву торгівлю й постачання Дун Мороґу пліч-о-пліч із дворфійськими союзниками."},sec={{t="Затор на перевалі",b="Біля гирла Перевалу Холодного Кряжа Гендс Спрінґспрокет бачить, що його звичні рейси з припасами геть зірвано. Зазвичай він доправляє харчі до ґуральні Тандербрю й корчми в Хараносі, але ворожі кам'янощелепі троги захопили підземний тунель, що веде з долини. Торгівля й пішохідний рух зупинилися через тварюк, тож Гендс змушений покладатися на вправних мандрівників, які пронесуть необхідні ящики небезпечним гірським коридором."}},fp="20,279,24.453.0,28.176.0,38.192.0,32.175.0"}
P.entries["npc:harb-clawhoof"] = {n="Гарб Клогуф",s="Гарб Клогуф — таурен, що розводить їздових звірів одразу за Селом Бладгуф у Малгорі. Він доглядає міцних кодо племені й віддає їх гідним вершникам-тауренам і довіреним героям Тандер Блафу.",h="Гарб Клогуф — таурен, що розводить їздових звірів одразу за Селом Бладгуф у Малгорі.",kw={"гарб клогуф","кодо","їздові звірі","село бладгуф","тандер блаф","репутація"},ang={["faction:Horde"]="Для орків, тролів і Відступників отримати кодо від Гарба — найвищий знак честі й дружби, визнаний старійшинами Тандер Блафу.",["race:Tauren"]="Гарб Клогуф дає вам найхарактернішого скакуна вашої спадщини — і практичний транспорт через Малгор, і символ ваших кочових традицій."},sec={{t="Заводчик великих кодо",b="Гарб Клогуф, що влаштувався біля загонів Села Бладгуф, цілими днями доглядає велетенських кодо — опору тауренських мандрів і праці. Створені носити величезну вагу на великі відстані, ці міцні тварини неодмінні для життя на рівнинах. Гарб дбає, щоб кожен звір був доглянутий, вишколений і дістався лише тим вершникам, яких шанує народ тауренів."},{t="Скакуни рівнин",b="Таурени природно здобувають довіру, потрібну, щоб їздити на кодо Гарба, а от чужинців перевіряють суворіше. Через величезний розмір і норов кодо нелегко слухаються тих, хто не знайомий із їхньою вдачею. Союзники не з тауренів, що хочуть поїхати на одному з цінних скакунів Гарба, мусять спершу довести свою вірність і здобути звеличену репутацію в Тандер Блафі."}},fp="13,208,25.403.0,20.360.0,31.139.0,29.141.0,35.205.0,41.221.0"}
P.entries["npc:harken-windtotem"] = {n="Гаркен Віндтотем",s="Гаркен Віндтотем — мисливець-таурен, що мешкає в Селі Бладгуф у Малгорі. Відданий традиціям свого народу, він доручає молодим мисливцям і мандрівникам довести свої вміння слідопита й збирача на золотих рівнинах.",h="Гаркен Віндтотем — мисливець-таурен, що мешкає в Селі Бладгуф у Малгорі.",kw={"гаркен віндтотем","мисливець","стрімкокрили","пера","село бладгуф","малгор"},ang={["class:Hunter"]="Для слідопитів, що проходять через Село Бладгуф, завдання Гаркена збити крилатих стрімкокрилів — важлива рання перевірка влучності й збирання здобичі.",["race:Tauren"]="Гаркен Віндтотем уособлює прабатьківську мисливську філософію тауренів: доводити дисципліну й самостійність на рівнинах, шануючи звірів Матері-Землі."},sec={{t="Мисливець Бладгуфа",b="Гаркен Віндтотем, що оселився біля самого серця Села Бладгуф, — наставник і провідник для тих, хто вчиться мисливських звичаїв тауренів. Життя на рівнинах Малгору вимагає шани до світу природи поряд із практичним умінням годувати своє плем'я. Гаркен оцінює молодих шукачів пригод, посилаючи їх полювати на тутешніх стрімкокрилів, що кружляють над плато, і збирати їхні пера — так він зважує терпіння мисливця, його влучність і вміння брати здобич без марнотратства."}},fp="16,233,21.468.0,24.194.0,36.106.0,43.155.0,37.150.0"}
P.entries["npc:hegnar-rumbleshot"] = {n="Геґнар Рамблшот",s="Геґнар Рамблшот — дворфійський зброяр, що стоїть біля засніженої дороги від Перевалу Холодного Кряжа до Хараноса. Він тримає жвавий тир і споряджає місцевих мисливців та горян вогнепальною зброєю й набоями.",h="Геґнар Рамблшот — дворфійський зброяр, що стоїть біля засніженої дороги від Перевалу Холодного Кряжа до...",kw={"геґнар рамблшот","зброяр","тир","набої","вогнепальна зброя","лослор радж","харанос"},ang={["class:Hunter"]="Для стрільців, що вирушають із Долини Холодного Хребта до ширших засніжених вершин Дун Мороґу, Геґнар постачає необхідний шріт, сумки для набоїв і запасну вогнепальну зброю.",["race:Dwarf"]="Дворфи пишаються майстерністю й влучністю, тож придорожній тир Геґнара — природне місце зустрічі для мандрівників, які хочуть перевірити свій спуск."},sec={{t="Зброяр при дорозі",b="У невеликому таборі між Перевалом Холодного Кряжа й Хараносом Геґнар Рамблшот обслуговує дворфійських стрільців, мандрівників і місцеве ополчення. У його таборі є популярний тир, де гірський люд відточує влучність проти диких звірів, що никають Дун Мороґом. Постачати стількох завзятих стрільців означає, що Геґнар жваво витрачає набої, тож він постійно залежить від свіжих партій боєприпасів від свого постачальника, дворфа-інженера Лослора Раджа."}},fp="17,225,22.470.0,25.142.0,37.168.0,42.144.0"}
P.entries["npc:henze-faulk"] = {n="Гензе Фолк",s="Гензе Фолк — дворф-шукач пригод, що лежить при смерті на кам'яному колі біля Дозору Героїв у Лісі Елвінн. Повалений Братством Дефіас, коли затуляв собою товариша, він стає ключовим випробуванням для майбутніх паладинів, що вчаться володіти даром воскресіння.",h="Гензе Фолк — дворф-шукач пригод, що лежить при смерті на кам'яному колі біля Дозору Героїв у Лісі Елвінн.",kw={"гензе фолк","дворф","дозор героїв","паладин","символ життя","воскресіння"},ang={["class:Paladin"]="Гензе Фолк — ваше перше справжнє випробування божественного милосердя. Повернути його з-за межі Символом Життя — означає зрозуміти, що Світло — не просто зброя для бою, а урочиста сила, здатна кинути виклик смерті.",["race:Dwarf"]="Бачити побратима-дворфа поваленим на людських землях — тверезе нагадування, що розбійники Дефіас смертельно небезпечні для подорожніх усіх рас, а не лише для мешканців Стормвінда."},sec={{t="Жертва біля Дозору Героїв",b="Біля давнього кам'яного кола на схід від Стормвінда лежить Дозор Героїв — місце, яке часто навідують бандити Дефіас, що нишпорять лісами Елвінну. Гензе Фолк і його друг Ґазин Тенорм потрапили тут у засідку мародерів Дефіас. Ставши під удар, щоб Ґазин вижив, Гензе впав від клинків бандитів. Його товариш уцілів і покликав на поміч із Собору Світла, а тіло Гензе лишилося на порозі між життям і смертю, чекаючи божественного втручання паладина із Символом Життя."}},fp="11,281,28.507.0,19.206.0,39.223.0,39.292.0,20.184.0"}
P.entries["npc:high-executor-derrington"] = {n="Верховний Кат Деррінґтон",s="Верховний Кат Деррінґтон командує авангардом Відступників біля Оплоту на східному кордоні Галявин Тірісфалю. Суворий військовий офіцер, він керує передовою обороною Орди від загроз Погибелі й Багряного Хрестового Походу, що сунуть із Західних Чумних Земель. З цієї укріпленої перепони він скеровує загартованих звитяжців до спірних руїн на кшталт Андоргала й Сколомансії.",h="Верховний Кат Деррінґтон командує авангардом Відступників біля Оплоту на східному кордоні Галявин Тірісфалю.",kw={"верховний кат деррінґтон","оплот","західні чумні землі","андоргал","сколомансія","орда","погибель"},ang={["class:Warrior"]="Деррінґтон утілює похмуру, практичну твердість фронтового солдата, що цінує бойову вправність і результати на полі бою понад придворні інтриги.",["faction:Horde"]="Для мандрівників Орди, що прибувають до Тірісфалю, Деррінґтон — головний військовий командир, який скеровує сили в небезпечні конфлікти Західних Чумних Земель.",["race:Undead"]="Деррінґтон утілює військовий хребет армії Відступників, зосереджений виключно на тому, щоб уберегти відвойовані землі від повернення Погибелі й багряного фанатизму."},sec={{t="Командир на порозі",b="Стоячи просто перед укріпленими барикадами Оплоту, Верховний Кат Деррінґтон — брамник між примарним спокоєм Галявин Тірісфалю й гнилими жахіттями Західних Чумних Земель. Деррінґтон не має терпіння до політичних ігор в Андерсіті: передову він бачить як горнило чистого виживання. Солдатам і найманцям Орди, що хочуть випробувати себе, Деррінґтон віддає прямі військові накази, посилаючи розвідників і ударні загони вглиб зачумленої землі, щоб притупити ворожі вторгнення, перш ніж вони прорвуться в Тірісфаль."},{t="Війна на два фронти",b="Оборонна позиція Деррінґтона в облозі з кількох боків. На сході — Погибель, що окопалася в розтрощеному містечку Андоргал і розливається околицями через зіпсутні казани. Водночас Багряний Хрестовий Похід зі своїми ревними фанатиками оспорює північні укріплення й невпинно б'ється з патрулями Відступників. Деррінґтон координує точкові контрудари, саботаж проти ліній Багряних і планомірне руйнування полів із казанами Погибелі, щоб уберегти східний кордон."}},fp="24,400,26.575.0,19.517.0,32.252.0,28.161.0,46.293.0,46.176.0,57.199.0,40.282.0"}
P.entries["npc:hogger"] = {n="Гоґґер",s="Гоґґер — лютий ватажок гнолів Річколапів, що нишпорять південно-західним Лісом Елвінн. Вищий за своїх родичів і надзвичайно агресивний, він здобув сумну славу нападами на тутешні ферми й убивствами необережних подорожніх. Його криваві безчинства заслужили офіційну винагороду від маршалів Стормвінда.",h="Гоґґер — лютий ватажок гнолів Річколапів, що нишпорять південно-західним Лісом Елвінн.",kw={"гоґґер","гноли","річколапи","винагорода","маршал дуґан","пагорб гоґґера"},ang={["faction:Alliance"]="Набіги Гоґґера показують, як розтягнуте військо Стормвінда: маршалам доводиться покладатися на мандрівних шукачів пригод, щоб підтримувати лад біля столиці.",["race:Human"]="Для молодих захисників Стормвінда зустріч із Гоґґером — раннє випробування вогнем і пряма відповідь на загрози, що розхитують серце Елвінну."},sec={{t="Жах Річколапів",b="Нишпорячи на Пагорбі Гоґґера в південно-західному Лісі Елвінн, Гоґґер командує тутешньою зграєю Річколапів із незрівнянною жорстокістю. У роки після Третьої війни набіги гнолів на місцеві садиби ставали дедалі зухвалішими й злагодженішими. За цим сплеском насильства стоїть тривожний союз: Річколапи почали змовлятися з Братством Дефіас, міняючи сиру лють на зброю, тактичні вказівки й магічну підтримку. Щоб уберегти кордони Елвінну й захистити торгові шляхи від подальшого кровопролиття, Маршал Дуґан оголосив щедру винагороду за голову Гоґґера."}},fp="6,312,22.569.0,14.234.0,32.237.0,60.218.0,32.149.0"}
P.entries["npc:holt-thunderhorn"] = {n="Голт Тандергорн",s="Голт Тандергорн — наставник мисливців із тауренів, що працює на Узвишші Мисливців у піднесеному місті Тандер Блаф. Він навчає ремесла і новачків, і бувалих майстрів сліду, дає базові бойові настанови й спрямовує змужнілих стрільців на особливі випробування в Малгорі й за його межами.",h="Голт Тандергорн — наставник мисливців із тауренів, що працює на Узвишші Мисливців у піднесеному місті Тандер...",kw={"голт тандергорн","мисливець","наставник","узвишшя мисливців","тандер блаф","малгор"},ang={["class:Hunter"]="Голт Тандергорн — головний наставник у Тандер Блафі: він навчає прийомів зі зброєю, слідопитства й направляє до приборкання звірів.",["race:Tauren"]="Голт на Узвишші Мисливців уособлює традиційну мисливську культуру тауренів, що годувала й захищала кочові племена задовго до того, як вони звели постійний дім на кручах."},sec={{t="Майстер Узвишшя",b="Голт Тандергорн, що влаштувався на Узвишші Мисливців над розлогими рівнинами Малгору, служить Орді як досвідчений наставник далекого бою, слідопитства й виживання. Як і багато старійшин свого ремесла, він веде молодих тауренів, коли ті перетворюються з мандрівних мисливців на дисциплінованих захисників своєї нової столиці."}},fp="16,288,18.313.0,36.128.0,33.187.0,43.209.0"}
P.entries["npc:ilthalaine"] = {n="Ілталайн",s="Ілталайн — охоронець, нічний ельф, що стоїть на сторожі священної долини Тінедол у Тельдрассилі. Він — перший, хто вітає й наставляє молодих нічних ельфів, що роблять найперші кроки у світ. Пильний і суголосний із дикою природою, він спрямовує новачків підтримувати хистку рівновагу природи на вітті Світового Дерева.",h="Ілталайн — охоронець, нічний ельф, що стоїть на сторожі священної долини Тінедол у Тельдрассилі.",kw={"ілталайн","консерватор","охоронець","тінедол","тельдрассил","сигіл","наставники","алдрассил"},ang={["class:Druid"]="Для майбутніх друїдів наука Ілталайна про вилов і природну рівновагу — найперші практичні уроки засад Кола Кенарія.",["faction:Alliance"]="Він уособлює спокійну, тривку пильність калдореїв і приймає нових звитяжців на службу Дарнасусу й ширшому Альянсу.",["race:NightElf"]="Ілталайн — перший наставник, якого зустрічає кожен молодий нічний ельф; він дає основоположну мудрість про опіку й священну рівновагу їхнього новознайденого дому на Тельдрассилі."},sec={{t="Охоронець долини",b="Стоячи одразу біля серця Тінедолу, Ілталайн часто перший, кого бачить молодий нічний ельф на початку своєї подорожі. Він стежить за лісовими стежками й помічає ледь відчутні зміни в лісі, невидимі для звичайного ока. Його обов'язок — вітати родичів, що повертаються, і дбати, щоб кожен щойно пробуджений захисник був укорінений у традиціях свого народу й готовий до відповідальності, що приходить із доглядом за Тельдрассилом."},{t="Рівновага природи",b="Навіть у затишному шатрі Тінедолу серед тутешніх звірів ворушиться неприродна лють. Ілталайн доручає молодим захисникам полювати на здичавілих нічних шаблезубів і вепрів, чия дедалі більша кількість і лютість загрожують перевернути злагоду гілки. Він бачить у вилові не жорстокість, а життєво важливий священний обов'язок берегти життя й гамувати невластивий неспокій, що почав просочуватися в нове Світове Дерево."},{t="Провідник до дисципліни",b="Окрім перевірки бойової вправності шукача пригод проти споганеної звірини, Ілталайн спрямовує молодих ельфів до їхніх покликань. Довіряючи кожному мандрівникові класовий сигіл, він указує їм просто на наставників у святилищі Алдрассила — чи йдуть вони шляхом воїна, друїда, розбійника, жерця чи мисливця. Через нього кожен новачок дізнається, де починається його служіння калдореям."}},fp="10,368,20.455.0,21.412.0,21.409.0,18.238.0,40.249.0,64.225.0,33.199.0,30.117.0,58.239.0"}
P.entries["npc:innkeeper-farley"] = {n="Шинкар Фарлі",s="Корчмар Фредрік Фарлі порядкує в корчмі «Лев'яча Гордість» у Ґолдширі, забезпечуючи їжею, ночівлею та каменями повернення подорожніх, що проходять Лісом Елвінн. Усіма шанований і спостережливий, він часто притримує загублену пошту й вислуховує біди шукачів пригод із дороги.",h="Корчмар Фредрік Фарлі порядкує в корчмі «Лев'яча Гордість» у Ґолдширі, забезпечуючи їжею, ночівлею та...",kw={"фарлі","корчмар","лев'яча гордість","ґолдшир","корчма","сталван містмантл"},ang={["faction:Alliance"]="Для новобранців, що вирушають із Долини Нортширу, шинквас Фарлі в «Лев'ячій Гордості» — часто найперше місце, де вони прив'язують свій камінь повернення й купують припаси."},sec={{t="Опора Ґолдширу",b="Родина Фарлі тримає корчму «Лев'яча Гордість» ще з часів правління короля Ллейна Рінна I. Разом із дружиною Веріною та донькою Анною Фредрік веде заклад гостинною рукою й гострим оком. Великими міцними руками, що добре надаються розбороняти бійки в таверні чи виставляти буйних гостей, він тримає лад на одній із найжвавіших стоянок королівства. Хоч його дні минають за наливанням елю й подаванням сиру, він носить у собі тихе горе — втрату брата Франдіса, вартового, що загинув у Лордероні під час чуми Погибелі."},{t="Покинута скриня гінця",b="Оскільки Ґолдшир лежить на перехресті між Стормвіндом, Вестфолом і Сутінколіссям, Фарлі чує чимало чуток і має справу з дивними подорожніми. Так, він якось прихистив гінця, що в жаху вибіг у ніч, покинувши свою сумку. Фарлі надійно сховав залишені послання в скрині нагорі — серед них і недоставлений лист, адресований колишньому шкільному вчителеві Сталвану Містмантлу, який згодом стає важливою зачіпкою для слідчих, що простежують шлях пропащого вчителя."}},fp="16,265,19.550.0,29.508.1,24.280.0,47.282.0,26.219.0,45.209.0"}
P.entries["npc:innkeeper-grosk"] = {n="Корчмар Ґроск",s="Корчмар Ґроск тримає корчму в Гострому Пагорбі, даючи втомленим мандрівникам їжу, питво й місце для відпочинку в центральному Дуроторі. Розташований на жвавій дорозі між Долиною Випробувань та Оргріммаром, його заклад — головний перепочинок для молодих шукачів пригод Орди, що вирушають у широкий світ.",h="Корчмар Ґроск тримає корчму в Гострому Пагорбі, даючи втомленим мандрівникам їжу, питво й місце для...",kw={"корчмар ґроск","корчма","гострий пагорб","укор","перепочинок","дуротар"},ang={["faction:Horde"]="Для орків, тролів і тауренів-гостей, що щойно пройшли бойове хрещення й мандрують на північ із Долини Випробувань чи Села Сен'джин, корчма Ґроска — перше справжнє містечко й домашнє вогнище на шляху до Оргріммара."},sec={{t="Гостинність у червоних пустках",b="Гострий Пагорб — важливе поселення на перехресті, що єднає південні тренувальні землі Дуротару з високими мурами Оргріммара. У центрі цієї станції стоїть Корчмар Ґроск — орк, якому доручено давати притулок воїнам, розвідникам і пеонам. Його корчма — перепочинок від суворої пустельної спеки, із запасом простих харчів, ситного м'яса й прохолодної води для кожного мандрівника, що проходить під її міцними сволоками."},{t="Перепочинок пеона",b="Окрім мандрівників, Ґроск допомагає й місцевим робітникам, на яких тримається Дуротар. У завданні «Тягар пеона» боязкий робітник Укор, що відніс харчі аж до Долини Випробувань і виявив, що вони там не потрібні, просить мандрівників віднести вантаж назад до корчми Ґроска в Гострому Пагорбі."}},fp="15,319,29.423.0,16.302.0,33.147.0,43.180.0,38.168.0"}
P.entries["npc:innkeeper-keldamyr"] = {n="Корчмар Келдамір",s="Корчмар Келдамір порядкує вогнищем і ночівлею в центральній корчмі Доланаара на Тельдрассилі. Він пропонує їжу, питво й місце для відпочинку молодим нічним ельфам, що вирушають із Тінедолу в ширше віття Світового Дерева.",h="Корчмар Келдамір порядкує вогнищем і ночівлею в центральній корчмі Доланаара на Тельдрассилі.",kw={"корчмар келдамір","корчма","доланаар","вогнище","тельдрассил","тінедол","відпочинок"},ang={["race:NightElf"]="Для нічних ельфів, що щойно вирушили з навчальних угідь Тінедолу, корчма Келдаміра — зазвичай найперший дім удалині від дому, де вони прив'язують свої камені повернення."},sec={{t="Вогнище Доланаара",b="Доланаар — перше село, до якого дістаються новачки, покинувши затишну долину Алдрассила. Корчмар Келдамір утримує центральний прихисток громади, пропонуючи хліб, джерельну воду й м'які ліжка під шатром Тельдрассила. Мандрівники, вартові й молоді новачки, що прямують до Дарнасуса, часто зупиняються біля його стійки, щоб перепочити духом, прив'язати камені повернення й запастися харчами на дорогу через віття."},{t="Доставки до села",b="Утримувати корчму високо в гілках означає потребувати сталого постачання з поблизьких поселень і від ремісників. Тутешніх гінців часто посилають просто до стійки Келдаміра скинути товар, і це прямо вплітає його в щоденну торгівлю й постачання, завдяки яким поселення Доланаар живе злагоджено."}},fp="18,232,18.432.0,15.310.0,36.150.0,44.187.0,39.141.0"}
P.entries["npc:iverron"] = {n="Іверрон",s="Іверрон — молодий нічний ельф, якого можна знайти в Тінедолі, захищеному стартовому гіллі Тельдрассила. Уражений отрутою дедалі неспокійніших павуків лісу, він своєю бідою рано попереджає про скверну, що росте в Світовому Дереві.",h="Іверрон — молодий нічний ельф, якого можна знайти в Тінедолі, захищеному стартовому гіллі Тельдрассила.",kw={"іверрон","тінедол","отрута","павуки","протиотрута","тельдрассил","нічний ельф"},ang={["class:Druid"]="Друїди, що навчаються в Тінедолі, бачать в отруєнні Іверрона симптом глибшої недуги, яка охопила природу й потребує ліків, зроблених просто з рослин і тварин долини.",["profession:Herbalism"]="Життя Іверрона залежить від того, як швидко зберуть тутешні рослини Тінедолу, і це підкреслює, наскільки знання трав важливе для порятунку життя.",["race:NightElf"]="Для нічних ельфів-новачків, що роблять перші кроки за межами Алдрассила, лихо Іверрона — ранній урок того, як швидко дика природа Тельдрассила втрачає рівновагу."},sec={{t="Гіркий укус",b="Блукаючи тихими кронами Тінедолу, Іверрон наразився на павуків Вебвуда, що гніздяться в долині. Отруйний укус швидко звалив молодого ельфа, і він лишився безпорадним, не здатним сам повернутися в безпечне місце. Його стан виказує раптову агресію, що охоплює створіння, які колись мирно ділили з ельфами цей гай."},{t="Відчайдушні ліки",b="Порятунок Іверрона залежить від кмітливості його товаришів і місцевих цілителів, яким потрібні сильні лісові складники — гіацинтові гриби, лілеї місячна пелюстка та іхор павуків Вебвуда, — щоб зварити протиотруту. Його зустріч зі смертю — тверезе нагадування всім молодим калдореям Тінедолу: гілля Тельдрассила аж ніяк не бездоганне святилище."}},fp="7,253,13.356.0,18.356.1,15.205.0,22.159.0,21.195.0,27.130.0,23.158.0,45.160.0"}
P.entries["npc:jannok-breezesong"] = {n="Джаннок Бризсонг",s="Джаннок Бризсонг — наставник розбійників, нічний ельф, що перебуває в селі Доланаар на Тельдрассилі. Він навчає скрадання, хитрощів і володіння клинком молодих калдорейських розбійників, що виходять у віття Світового Дерева.",h="Джаннок Бризсонг — наставник розбійників, нічний ельф, що перебуває в селі Доланаар на Тельдрассилі.",kw={"джаннок бризсонг","розбійник","наставник","доланаар","тельдрассил","скрадання","дарнасус"},ang={["class:Rogue"]="Для молодих розбійників — нічних ельфів, що починають шлях на Тельдрассилі, Джаннок — ваш головний наставник у Доланаарі, перш ніж ви рушите до столиці.",["race:NightElf"]="Хоч калдорейська культура часто наголошує на вартових і друїдизмі, наставники на кшталт Джаннока готують тих, хто надає перевагу скраданню, отрутам і кинджалам."},sec={{t="Провідник у тінях",b="Джаннок Бризсонг, якого можна застати, як він ліниво сидить під віттям Доланаара, — головний наставник розбійників-новачків серед нічних ельфів. На відміну від статечних вартових чи відлюдних друїдів Тельдрассила, Джаннок веде тих, хто тихо діє на узбіччі суспільства, і вчить їх скрадатися в тінях, бити ззаду й виживати непоміченими серед віття. Щойно розбійник переросте перші уроки в Доланаарі, Джаннок спрямовує його далі, до досвідченіших майстрів у столиці — Дарнасусі."}},fp="17,230,22.506.0,25.156.0,40.221.0,36.137.0"}
P.entries["npc:jen-shan"] = {n="Джен'шан",s="Джен'шан — тролиця з джунглів Темного Списа і наставниця мисливців у Долині Випробувань у Дуроторі. Вона веде орків і тролів-стрільців-початківців, що роблять перші кроки в нетрях Орди. Молодих мисливців спрямовують до неї вчитися основ вистежування, дальнього бою й виживання.",h="Джен'шан — тролиця з джунглів Темного Списа і наставниця мисливців у Долині Випробувань у Дуроторі.",kw={"джен'шан","мисливець","наставниця","тролиця","долина випробувань","стрільба","дуротар"},ang={["class:Hunter"]="Для молодих орків і тролів-мисливців Джен'шан — найперша наставниця, яку ви зустрічаєте: вона навчає основ дальнього бою, перш ніж ви вирушите за червоні каньйони Лігва.",["race:Troll"]="Джен'шан утілює славетну вправність племені Темного Списа у вистежуванні й розвідці і дбає, щоб молоді тролі зберегли мисливські традиції предків у новому домі на материку."},sec={{t="Наставниця червоних пісків",b="Серед вивітрених таборів Долини Випробувань Джен'шан — головна наставниця мисливців для новобранців, що доводять свою цінність Орді. Молоді орки й тролі Темного Списа приходять до неї, стискаючи таблички з письменами й пергаменти, які вказують просто на неї. Гострим оком, вигостреним роками в дикій пустці, вона передає основи стрільби з лука, вогнепальної зброї та виживання в нетрях, щоб жоден новачок не став здобиччю скорпідів і вепрів, що нишпорять дном каньйону."}},fp="8,301,23.520.0,16.198.0,29.199.0,57.280.0"}
P.entries["npc:jocaste"] = {n="Джокасте",s="Джокасте — наставниця мисливців, нічна ельфійка, що мешкає в зеленому Ценаріонському Анклаві в Дарнасусі. Працюючи пліч-о-пліч із Колом Кенарія, вона наставляє молодих стрільців і повелителів звірів — нічних ельфів, які прибувають із нетрів Тельдрассила.",h="Джокасте — наставниця мисливців, нічна ельфійка, що мешкає в зеленому Ценаріонському Анклаві в Дарнасусі.",kw={"джокасте","мисливець","наставниця","ценаріонський анклав","дарнасус","коло кенарія","тельдрассил"},ang={["class:Hunter"]="Для мисливців — нічних ельфів, що вперше входять до Дарнасуса, Джокасте — важлива вчителька, яка відточує ваші бойові прийоми й допомагає зміцнити зв'язок із тваринними супутниками.",["race:NightElf"]="Укорінена в Ценаріонському Анклаві, Джокасте відбиває тісну злагоду між мандрівниками — нічними ельфами, дикими звірами Тельдрассила й наукою Кола Кенарія."},sec={{t="Наставниця в Анклаві",b="Перебуваючи серед тихих гаїв Ценаріонського Анклаву в Дарнасусі, Джокасте навчає мисливців — нічних ельфів. Коли молоді слідопити завершують перше навчання в Тінедолі й вирушають до столиці, Джокасте допомагає їм стати досвідченими знавцями виживання. Вона викладає мистецтво влучної стрільби, виживання в дикому краю і священний зв'язок між мисливцем і дикими звірами Калімдору."}},fp="7,230,23.420.0,15.171.0,25.139.0,42.163.0,47.171.0"}
P.entries["npc:kali-remik"] = {n="Калі Ремік",s="Калі Ремік — тролиця-мисливиця Темного Списа, яка наставляє мандрівників у серці земель Орди. Обізнана зі способами вистежування й виживання в Дуроторі, вона спрямовує молодих мисливців до Тотара в Гострий Пагорб, щоб ті вчилися приборкання звірів.",h="Калі Ремік — тролиця-мисливиця Темного Списа, яка наставляє мандрівників у серці земель Орди.",kw={"калі ремік","мисливиця","тролиця","тотар","гострий пагорб","сен'джин","дуротар"},ang={["class:Hunter"]="Для молодих орків і тролів-стрільців Калі — сходинка: вона розпізнає, коли ваші вміння переростають сільські вправи, і посилає вас далі, до Тотара в Гострий Пагорб.",["race:Troll"]="Теж із племені Темного Списа, Калі пильнує своїх родичів, що відбудовують життя на узбережжі Дуротару й осідають у Долині Духів Оргріммара."},sec={{t="Провідниця полювання",b="Калі Ремік — досвідчена тролиця-слідопитка з джунглів, добре обізнана з посушливими пустками Дуротару й гамірними осередками Орди. У прибережних поселеннях на кшталт Села Сен'джин вона наглядає за молодими розвідниками, що роблять перші кроки за межами Долини Випробувань. Знаючи, коли новачок переростає місцеві тренувальні землі, вона скеровує здібних стрільців до Тотара в Гострий Пагорб, щоб ті почали шлях володарів звірів, а прикордонні лави Орди лишалися гострими й дисциплінованими."}},fp="10,259,20.489.0,18.173.0,30.78.0,40.206.0"}
P.entries["npc:kaltunk"] = {n="Калтунк",s="Калтунк — орк-наглядач у самому серці Долини Випробувань у Дуроторі. Він — найперший, кого зустрічають молоді орки, роблячи перші кроки у світ. Його обов'язок — вітати цих майбутніх чемпіонів і спрямовувати їх до перших обов'язків на службі Орді.",h="Калтунк — орк-наглядач у самому серці Долини Випробувань у Дуроторі.",kw={"калтунк","наглядач","долина випробувань","новобранці","ґорнек","дуротар"},ang={["faction:Horde"]="Калтунк допомагає підтримувати практичну дисципліну, потрібну для ладу на суворих тренувальних землях Дуротару.",["race:Orc"]="Для кожного орка, що виходить у Калімдор, грубуваті настанови Калтунка — перші слова, які він чує, починаючи здобувати свою честь."},sec={{t="Перший крок",b="Стоячи під суворим сонцем Долини Випробувань, Калтунк наглядає за новоприбулими, що прагнуть довести свою гідність Орді. Поки інші наставники й старійшини роздають виснажливі випробування й мисливські обряди, Калтунк дбає, щоб жоден новобранець не блукав безцільно в червоному пилу. Він віддає прості накази й указує новачкам просто на Ґорнека та шлях дисципліни."},{t="Хранитель долини",b="Долина Випробувань — не легке місце для гарту; її обрали саме для того, щоб кувати силу й стійкість у кожному юнакові, що ступає дном її каньйону. Калтунк утілює цю сувору практичність. Він не виголошує пишних промов і не панькається, чекаючи, що кожен орк швидко знайде своє місце у світі й тягтиме свою лямку задля вождя."}},fp="7,304,14.402.0,20.339.0,15.207.0,41.135.0,25.139.0,44.142.0"}
P.entries["npc:katie-hunter"] = {n="Кеті Гантер",s="Кеті Гантер — конярка при стайнях на сході Лісу Елвінн, де лежить Лісозаготівельний Табір Східної Долини. Вона постачає навчених верхових коней і скакунів громадянам Стормвінда й довіреним героям Альянсу. Разом із Рендалом Гантером вона дбає, щоб подорожні й солдати мали надійних верхових тварин для доріг королівства.",h="Кеті Гантер — конярка при стайнях на сході Лісу Елвінн, де лежить Лісозаготівельний Табір Східної Долини.",kw={"кеті гантер","коні","стайня","східна долина","верхова їзда","скакуни"},ang={["faction:Alliance"]="Союзні раси, що здобудуть високу повагу й шану при дворі Стормвінда, можуть заслужити привілей вести прекрасних скакунів Кеті в бій.",["race:Human"]="Для людей-мандрівників стайні Кеті — природний обряд посвяти: класичні стормвіндські коні, щойно ви опануєте основи верхової їзди."},sec={{t="Стайні Східної Долини",b="Усамітнена в тихих лісових галявинах Лісозаготівельного Табору Східної Долини, Кеті Гантер порядкує головним кінським поголів'ям королівства для майбутніх вершників Лісу Елвінн. Поки лісоруби заготовляють деревину для відбудови Стормвінда, Кеті доглядає стайню, вирощуючи різні надійні породи — пінто, кобил і прудких скакунів. Її поголів'я втілює класичну кінну традицію королівства: вірні супутники, здатні долати небезпечні дороги південного Азероту."}},fp="12,339,19.503.0,20.150.0,30.159.0,35.158.0,26.191.0"}
P.entries["npc:khelden-bremen"] = {n="Келден Бремен",s="Келден Бремен — людський маг і наставник на верхньому поверсі Абатства Нортшира в Лісі Елвінн. Він наглядає за найпершим навчанням чарівників-новачків, що беруться за таємні мистецтва на службі Стормвінду.",h="Келден Бремен — людський маг і наставник на верхньому поверсі Абатства Нортшира в Лісі Елвінн.",kw={"келден бремен","маг","наставник","абатство нортшира","таємна магія","нортшир"},ang={["class:Mage"]="Для людей-магів Келден Бремен — перший офіційний крок у таємну науку перед поглибленим навчанням у вежах Стормвінда."},sec={{t="Учитель таємної магії",b="У спокійних кам'яних стінах Абатства Нортшира Келден Бремен — головний наставник людей-магів-початківців. Поки духівництво й захисники внизу дбають про військові й духовні справи, Бремен тримає тихий кабінет нагорі. Тут він знайомить новачків із дисципліною, зосередженістю й основними прийомами, потрібними, щоб безпечно ткати сиру магічну енергію, перш ніж вони вирушать у Ліс Елвінн і далі — до Кварталу магів Стормвінда."}},fp="14,225,19.459.0,22.172.0,32.134.0,43.205.0"}
P.entries["npc:kor-ghan"] = {n="Кор'ґан",s="Кор'ґан — троль із джунглів Темного Списа, якого можна знайти в похмурих печерах Тіньової Розколини в Оргріммарі. Стоячи просто біля «Отрут Реккула», він шукає помічників для приготування ліків проти отруйних хижаків нетрів.",h="Кор'ґан — троль із джунглів Темного Списа, якого можна знайти в похмурих печерах Тіньової Розколини в...",kw={"кор'ґан","тіньова розколина","оргріммар","отрути","реккул","протиотрута","троль"},ang={["class:Rogue"]="Кор'ґан, що стоїть просто біля «Отрут Реккула» в Тіньовій Розколині, — звична постать для розбійників, які навідуються в підземелля Оргріммара по реагенти й отрути.",["race:Troll"]="Як і багато родичів із Темного Списа, що покинули Село Сен'джин, Кор'ґан застосовує практичні знання про дикі небезпеки Дуротару в укріпленій столиці Орди."},sec={{t="Троль у тіні",b="Стоячи перед «Отрутами Реккула» в печерних глибинах Тіньової Розколини, Кор'ґан пильно стежить і за ліками, і за отрутами. Зі столиці він посилає шукачів пригод через червоні каньйони збирати отруйні складники зі скорпідів Дуротару, щоб готувати життєво важливі протиотрути."}},fp="8,246,22.296.0,16.113.0,26.125.0,34.138.0,35.197.0"}
P.entries["npc:kzan-thornslash"] = {n="Кзан Торнслеш",s="Кзан Торнслеш — орк-торговець зброєю в Долині Випробувань у Дуроторі. Він постачає найнеобхіднішу початкову зброю та припаси новобранцям, що починають вишкіл в Орді.",h="Кзан Торнслеш — орк-торговець зброєю в Долині Випробувань у Дуроторі.",kw={"кзан торнслеш","зброя","торговець","долина випробувань","новобранці","дуротар"},ang={["class:Warrior"]="Для молодих воїнів, що починають зі щербатих клинків, Кзан пропонує добірку дробильної та клинкової зброї під різні бойові стилі.",["faction:Horde"]="Постачання молодих армій Тралла починається з самих низів, де торговці на кшталт Кзана дбають, щоб кожна здатна рука мала сталь для Орди."},sec={{t="Бронник для новобранців",b="Розташований у запорошеному червоному каньйоні Долини Випробувань, Кзан Торнслеш — головний продавець зброї для молодих орків і тролів Темного Списа, що роблять перші кроки як воїни Орди. Пропонуючи добірку простого озброєння — від грубих ручних сокир і коротких мечів до кийків і метальних ножів, — Кзан дбає, щоб новопробуджені кандидати були достатньо озброєні проти тутешньої звірини й місцевих небезпек."}},fp="15,199,23.433.0,23.172.0,33.161.0,38.192.0"}
P.entries["npc:lanka-farshot"] = {n="Ланка Фаршот",s="Ланка Фаршот — наставник мисливців із тауренів, що працює в Таборі Нарачі на Плато Червоної Хмари. Він веде мисливців-новачків із тауренів, коли ті роблять перші кроки у слідопитстві, влучній стрільбі й виживанні на рівнинах Малгору.",h="Ланка Фаршот — наставник мисливців із тауренів, що працює в Таборі Нарачі на Плато Червоної Хмари.",kw={"ланка фаршот","мисливець","наставник","табір нарачі","плато червоної хмари","малгор"},ang={["class:Hunter"]="Для мисливців-тауренів, що починають навчання в Малгорі, Ланка Фаршот — найперший наставник, який навчає основ влучної стрільби й виживання в дикій природі.",["race:Tauren"]="Ланка уособлює традиційну мисливську філософію тауренів, у якій влучність і слідопитство — життєво важливі обов'язки для захисту племені й життя в рівновазі з рівнинами."},sec={{t="Наставник Плато Червоної Хмари",b="Табір Нарачі — місце, де чатує Ланка Фаршот і вітає нових тауренів, покликаних на шлях мисливця. Свіжі новобранці приходять із гравірованою запискою, що велить їм шукати його поради. Під його твердим оком підмайстри вивчають основи далекого бою, вистежування здобичі й шани до диких звірів, що блукають трав'янистими рівнинами Малгору. Його наука дбає, щоб кожен молодий мисливець став умілим розвідником і годувальником племені."}},fp="13,220,28.441.0,21.186.0,37.182.0,42.113.0"}
P.entries["npc:lar-prowltusk"] = {n="Лар Праултаск",s="Лар Праултаск — троль-вартовий Темного Списа на посту на південний захід від Села Сен'джин у Дуроторі. Зі свого прикордонного посту він пильнує загрози, що насуваються на молоде троляче поселення, і спрямовує шукачів пригод стримувати наступ ворогів поблизу.",h="Лар Праултаск — троль-вартовий Темного Списа на посту на південний захід від Села Сен'джин у Дуроторі.",kw={"лар праултаск","вартовий","сен'джин","кентаври","колкар","дуротар","темний спис"},ang={["faction:Horde"]="Лар Праултаск утілює боротьбу Орди за кордони Дуротару проти зовнішніх загроз просто на задвірках її молодої столиці.",["race:Troll"]="Для Темного Списа розвідники на кшталт Лара Праултаска життєво важливі, щоб уберегти крихкий новий дім племені в Дуроторі від агресивних кланів кентаврів і людських військ, що насуваються."},sec={{t="Вартовий на узбережжі",b="Лар Праултаск, що стоїть на південний захід від Села Сен'джин на суворому узбережжі Дуротару, — один із передових вартових племені Темного Списа. Поки тролі ще намагаються облаштувати постійний дім після втечі зі своїх затонулих островів, Село Сен'джин потерпає від постійних наскоків ворожих сусідів. Лар координує розвідників і воїнів, щоб стежити за рухом на узбережжі й стримувати агресію ворожих сил — надто кентаврів Колкар, — аби крихке поселення мало змогу перевести подих."}},fp="13,259,20.505.0,21.249.0,41.136.0,33.94.0"}
P.entries["npc:laurna-morninglight"] = {n="Лаурна Морнінґлайт",s="Лаурна Морнінґлайт — наставниця жерців нічних ельфів, що мешкає в тихому поселенні Доланаар на Тельдрассилі. Віддана Сестринству Елуни, вона веде послушників-початківців, що приходять із Тінедолу, через духовні обряди й цілющі дари Богині Місяця. Її наука готує молодих жерців нічних ельфів до загроз, що насуваються на гілля Світового Дерева.",h="Лаурна Морнінґлайт — наставниця жерців нічних ельфів, що мешкає в тихому поселенні Доланаар на Тельдрассилі.",kw={"лаурна морнінґлайт","жриця","наставниця","елуна","доланаар","тельдрассил","богиня місяця"},ang={["class:Priest"]="Для жерців нічних ельфів, що прибувають із Тінедолу, Лаурна Морнінґлайт — ваша перша велика наставниця за межами стартової долини: вона навчає основних заклять і скеровує вашу ранню відданість Елуні.",["race:NightElf"]="Лаурна втілює традиційну відданість калдореїв Богині Місяця й нагадує шукачам пригод, що жрецтво на Тельдрассилі черпає силу від Елуни, а не від Святого Світла."},sec={{t="Провідниця в Доланаарі",b="Серед гілля Доланаара Лаурна Морнінґлайт — одна з головних наставниць молодих жерців, що пройшли перші обряди в Тінедолі. Коли нові посвячені виходять у ширші простори Тельдрассила, вона вчить їх поглиблювати єднання з Елуною, урівноважуючи світло зцілення з оборонними обрядами, без яких не вижити в дедалі ворожіших хащах."},{t="Відданість Богині Місяця",b="Жрецтво калдореїв глибоко переплетене з поклонінням Елуні, а не абстрактному Святому Світлу, яке шанують люди та дворфи. Лаурна доручає учням духовні праці — отримати священні шати, зцілити поранену Вартову. Через ці традиції послушники пізнають, що їхні сили — прямий дар Матері-Місяця, призначений берегти й зцілювати народ калдореїв."}},fp="19,383,19.397.0,28.400.0,37.141.0,33.165.0,35.158.0,27.162.0,46.168.0,52.66.0"}
P.entries["npc:lorekeeper-raintotem"] = {n="Хранитель Знань Рейнтотем",s="Хранитель Знань Рейнтотем — старійшина тауренів, що перебуває на півночі Малгору, одразу на південь від Червоних Скель. Він доглядає священні поховання й просить шукачів пригод прогнати шипогривів Щетиноспинних, які їх тривожать.",h="Хранитель Знань Рейнтотем — старійшина тауренів, що перебуває на півночі Малгору, одразу на південь від...",kw={"хранитель знань рейнтотем","червоні скелі","поховання","щетиноспинні","шипогриви","предки","малгор"},ang={["class:Shaman"]="Пильність Рейнтотема над неспокійними мертвими біля Червоних Скель прямо стосується шаманського обов'язку: дбати, щоб духи предків мали належний спокій і шану.",["race:Tauren"]="Допомогти Рейнтотему захистити Червоні Скелі — означає вшанувати предків і зберегти поховальні традиції вашого народу."},sec={{t="Сторож Червоних Скель",b="Хранитель Знань Рейнтотем, що стоїть біля священних круч Червоних Скель у Малгорі, дбає про духовні обов'язки свого народу. Він просить шукачів пригод прогнати зайд Щетиноспинних із поховань і повернути спокій місцю спочинку предків."},{t="Захисник прабатьківських земель",b="Окрім випробування героїв-початківців, Хранитель Знань Рейнтотем пильнує освячені поховання біля Червоних Скель. Коли зайди з шипогривів Щетиноспинних тривожать святі місця спочинку померлих вождів і шаманів тауренів, Рейнтотем залучає мандрівників, щоб повернути гідність і втихомирити стривожених мертвих."}},fp="20,207,20.255.0,29.302.0,38.141.0,53.133.0,42.213.0"}
P.entries["npc:loslor-rudge"] = {n="Лослор Радж",s="Лослор Радж — заповзятливий дворфійський постачальник інженерного краму на Складі Стілґрила в Дун Мороґу. Він забезпечує механічними деталями, інструментами й боєприпасами майстрів по всіх засніжених гірських хребтах, підтримуючи важливі зв'язки зі зброярами на кшталт Геґнара Рамблшота.",h="Лослор Радж — заповзятливий дворфійський постачальник інженерного краму на Складі Стілґрила в Дун Мороґу.",kw={"лослор радж","постачальник","інженерія","склад стілґрила","геґнар рамблшот","вендиґо","боєприпаси"},ang={["profession:Engineering"]="Лослор тримає важливі початкові ремісничі припаси — флюси, вибуховий порох, трубки й набори майстра, — тож його пост на складі зручна зупинка для будь-якого інженера-початківця, що мандрує Дун Мороґом.",["race:Dwarf"]="Як і в багатьох ремісників Дун Мороґу, заробіток Лослора залежить від надійних в'ючних маршрутів між розкиданими дворфійськими таборами — і це показує, як навіть місцеві хижаки на кшталт вендиґо можуть зірвати гірську торгівлю."},sec={{t="Постачальник у снігах",b="Працюючи зі Складу Стілґрила трохи далі дорогою від Хараноса, Лослор Радж тримає сталий запас інженерних необхідностей — від мідних модуляторів і бронзових трубок до вибухового пороху й гайкових ключів. Сувора погода Дун Мороґу й розлогі майстерські роботи означають, що практичні деталі завжди в попиті, і Лослор пишається тим, що місцевим механікам усього вистачає. Проте пустка між заставами підступна: коли кур'єра, що зрізав шлях біля Сивого Лігва, прогнали вендиґо, важлива партія боєприпасів для його цінного клієнта, зброяра Геґнара Рамблшота, лишилася в снігу."}},fp="12,278,22.653.0,20.204.0,40.304.0,28.141.0,25.162.0"}
